// Central in-memory state for customized role permissions
let customizedRolePermissions: Record<string, PermissionKey[]> = {};

async function loadRolePermissionsFromDb() {
  if (!mongoService.isConnected()) return;
  try {
    const docs = await RolePermissionModel.find({}).lean();
    docs.forEach((doc: any) => {
      if (doc.role && Array.isArray(doc.permissions)) {
        customizedRolePermissions[doc.role] = doc.permissions;
      }
    });
    console.log(`[RBAC] Loaded ${docs.length} customized role permission template(s) from MongoDB Atlas.`);
  } catch (err: any) {
    console.warn('[RBAC] Could not load customized role permissions from MongoDB:', err?.message);
  }
}

