// ==========================================
// Central Live Data Synchronization (SSE + Polling Buffer)
// ==========================================
interface SseClient {
  id: string;
  res: Response;
  userId?: string;
  role?: string;
  connectedAt: number;
}

const sseClients = new Map<string, SseClient>();
const recentEventsBuffer: RealtimeEvent[] = [];

export function broadcastRealtimeEvent(
  entity: RealtimeEntityType,
  action: RealtimeAction,
  data?: any,
  meta?: {
    studentId?: string;
    classId?: string;
    section?: string;
    targetRole?: string;
    academicSession?: string;
    description?: string;
  }
): RealtimeEvent {
  // Realtime events reach every connected client, including signed-out visitors, and the
  // last 250 are replayed by /api/realtime/poll. Only school-level data may travel in them.
  // For personal records (students, fees, attendance, marks, staff, payroll...) the event
  // is just a "changed" signal; each client refetches with its own token and server-side scope.
  const safe = toBroadcastSafePayload(entity, action, data, meta?.description);
  const event: RealtimeEvent = {
    id: `evt_${Date.now()}_${Math.random().toString(36).substring(2, 9)}`,
    entity,
    action,
    data: safe.data,
    studentId: meta?.studentId,
    classId: meta?.classId,
    section: meta?.section,
    targetRole: meta?.targetRole || 'ALL',
    academicSession: meta?.academicSession || schoolSettings.currentAcademicSession,
    timestamp: new Date().toISOString(),
    description: safe.description,
  };

  recentEventsBuffer.push(event);
  if (recentEventsBuffer.length > 250) {
    recentEventsBuffer.shift();
  }

  const payload = `data: ${JSON.stringify(event)}\n\n`;
  for (const [clientId, client] of sseClients.entries()) {
    try {
      client.res.write(payload);
    } catch {
      sseClients.delete(clientId);
    }
  }

  return event;
}

// Heartbeat interval to keep SSE connections alive across reverse proxies
setInterval(() => {
  for (const [clientId, client] of sseClients.entries()) {
    try {
      client.res.write(': heartbeat\n\n');
    } catch {
      sseClients.delete(clientId);
    }
  }
}, 15000);

