export function normalizePhone(p?: string): string {
  if (!p) return '';
  const digits = String(p).replace(/\D/g, '');
  return digits.length > 10 ? digits.slice(-10) : digits;
}

export function parseAndValidateDob(dobStr: string): { valid: boolean; isoDate?: string; displayDate?: string; error?: string } {
  if (!dobStr || typeof dobStr !== 'string') {
    return { valid: false, error: 'Date of Birth is required in DD-MM-YYYY format (e.g., 20-04-2015).' };
  }

  const trimmed = dobStr.trim();
  let day: number;
  let month: number;
  let year: number;

  // Check YYYY-MM-DD or YYYY/MM/DD
  const isoMatch = trimmed.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})$/);
  // Check DD-MM-YYYY or DD/MM/YYYY
  const dmyMatch = trimmed.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{4})$/);

  if (isoMatch) {
    year = parseInt(isoMatch[1], 10);
    month = parseInt(isoMatch[2], 10);
    day = parseInt(isoMatch[3], 10);
  } else if (dmyMatch) {
    day = parseInt(dmyMatch[1], 10);
    month = parseInt(dmyMatch[2], 10);
    year = parseInt(dmyMatch[3], 10);
  } else {
    return { valid: false, error: 'Invalid Date of Birth format. Please enter in DD-MM-YYYY format (e.g., 20-04-2015).' };
  }

  const currentYear = new Date().getFullYear();
  if (year < 1920 || year > currentYear) {
    return { valid: false, error: `Invalid year in Date of Birth. Year must be between 1920 and ${currentYear}.` };
  }

  if (month < 1 || month > 12) {
    return { valid: false, error: 'Invalid month in Date of Birth. Month must be between 01 and 12.' };
  }

  const isLeapYear = (year % 4 === 0 && year % 100 !== 0) || (year % 400 === 0);
  const daysInMonth = [31, isLeapYear ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

  const maxDay = daysInMonth[month - 1];
  if (day < 1 || day > maxDay) {
    if (month === 2 && day === 29 && !isLeapYear) {
      return { valid: false, error: `Invalid date: ${year} is not a leap year, so February has only 28 days.` };
    }
    return { valid: false, error: `Invalid day for month ${String(month).padStart(2, '0')}. Must be between 01 and ${maxDay}.` };
  }

  const isoDate = `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
  const displayDate = `${String(day).padStart(2, '0')}-${String(month).padStart(2, '0')}-${year}`;
  return { valid: true, isoDate, displayDate };
}

export function normalizeDobToIso(d?: string): string {
  if (!d) return '';
  const parsed = parseAndValidateDob(d);
  if (parsed.valid && parsed.isoDate) return parsed.isoDate;
  const m = String(d).trim().match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})$/);
  if (m) return `${m[1]}-${String(m[2]).padStart(2, '0')}-${String(m[3]).padStart(2, '0')}`;
  return String(d).trim();
}

