  // Authentication Context Helper & Middlewares
  function getAuthContext(req: Request): { user: User | null; session: ServerSession | null; match: AuthEntityMatch | null } {
    const authHeader = req.headers.authorization || '';
    let token = authHeader.replace(/^Bearer\s+/i, '').trim() || ((req.headers['x-auth-token'] as string) || '').trim();

    if (!token || token === 'undefined' || token === 'null') {
      return { user: null, session: null, match: null };
    }

    if (revokedTokens.has(token)) {
      return { user: null, session: null, match: null };
    }

    let session = activeSessions.get(token);
    if (session) {
      if (Date.now() > session.expiresAt) {
        activeSessions.delete(token);
        session = undefined;
      }
    }

    if (!session) {
      try {
        const decoded = jwt.verify(token, JWT_SECRET) as any;
        if (decoded && decoded.userId && decoded.role) {
          session = {
            token,
            userId: decoded.userId,
            role: decoded.role,
            employeeId: decoded.employeeId,
            studentId: decoded.studentId,
            activeStudentId: decoded.activeStudentId,
            linkedStudentIds: decoded.linkedStudentIds,
            expiresAt: decoded.exp ? decoded.exp * 1000 : Date.now() + 24 * 60 * 60 * 1000,
            rememberMe: true,
            issuedAt: typeof decoded.iat === 'number' ? decoded.iat : undefined,
          };
          activeSessions.set(token, session);
        }
      } catch {
        // Strict verification failure: Reject invalid, tampered, or expired tokens
        return { user: null, session: null, match: null };
      }
    }

    if (!session) return { user: null, session: null, match: null };
    // Support staff have no app login: a token carrying that role is never accepted.
    if (isNoLoginStaffRole(session.role)) {
      activeSessions.delete(token);
      return { user: null, session: null, match: null };
    }

    if (session.issuedAt === undefined) {
      const decodedIat = (jwt.decode(token) as any)?.iat;
      if (typeof decodedIat === 'number') session.issuedAt = decodedIat;
    }
    if (isSessionRevoked(session)) {
      activeSessions.delete(token);
      return { user: null, session: null, match: null };
    }

    if (session.user && session.authMatch) {
      if (isAuthEntityDisabled(session.authMatch)) {
        activeSessions.delete(token);
        return { user: null, session: null, match: null };
      }
      return { user: session.user, session, match: session.authMatch };
    }

    let match = findAuthEntityById(session.userId, session.role, session.employeeId);
    if (!match && session.userId && session.role) {
      const isStaffOrAdmin = ['SUPER_ADMIN', 'SCHOOL_ADMIN', 'ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'ACADEMIC_COORDINATOR', 'ACCOUNTANT', 'TEACHER', 'HOSTEL_WARDEN', 'TRANSPORT_MANAGER', 'HR_STAFF'].includes(session.role);
      const fallbackEntity: any = {
        id: session.userId,
        name: session.role === 'SUPER_ADMIN' ? 'Super Administrator' : (session.role === 'SCHOOL_ADMIN' ? 'School Administrator' : session.role.replace(/_/g, ' ')),
        username: session.userId,
        role: session.role,
        status: 'ACTIVE',
        employeeId: session.employeeId,
      };
      match = {
        type: isStaffOrAdmin ? ((session.role as any) === 'SUPER_ADMIN' || (session.role as any) === 'SCHOOL_ADMIN' || (session.role as any) === 'ADMIN' ? 'ADMIN' : 'STAFF') : (session.role === 'STUDENT' ? 'STUDENT' : 'PARENT'),
        entity: fallbackEntity,
        role: session.role as UserRole,
      };
    }
    if (!match) return { user: null, session: null, match: null };
    if (isAuthEntityDisabled(match)) {
      activeSessions.delete(token);
      return { user: null, session: null, match: null };
    }

    const user = buildSafeUser(match, session);
    session.user = user;
    session.authMatch = match;
    return { user, session, match };
  }

  // Mirrors the login checks: an account that cannot sign in must not keep using an older session.
  // Reads the live record (not the copy cached on the session) so deactivation applies immediately.
  const BLOCKED_STAFF_ACCOUNT_STATUSES = ['INACTIVE', 'SUSPENDED', 'LEFT_SCHOOL', 'RESIGNED', 'TERMINATED'];
  function isAuthEntityDisabled(match: AuthEntityMatch): boolean {
    const cached: any = match.entity;
    if (!cached || !cached.id) return false;
    if (match.type === 'STAFF') {
      const live: any = staff.find((s) => s.id === cached.id) || null;
      if (!live) return false;
      if (live.loginEnabled === false) return true;
      if (isNoLoginStaffRole(live.portalRole || live.systemRole || live.role)) return true;
      const st = String(live.accountStatus || '').toUpperCase();
      const st2 = String(live.status || '').toUpperCase();
      return BLOCKED_STAFF_ACCOUNT_STATUSES.includes(st) || BLOCKED_STAFF_ACCOUNT_STATUSES.includes(st2);
    }
    if (match.type === 'ADMIN') {
      const live: any = adminAccounts.find((a) => a.id === cached.id) || null;
      if (!live) return false;
      return live.loginEnabled === false || ['INACTIVE', 'SUSPENDED'].includes(String(live.status || '').toUpperCase());
    }
    if (match.type === 'STUDENT') {
      const live: any = students.find((s) => s.id === cached.id) || null;
      if (!live) return false;
      const st = String(live.accountStatus || live.status || 'ACTIVE').toUpperCase();
      return live.loginEnabled === false || st === 'INACTIVE' || st === 'SUSPENDED';
    }
    return false;
  }

  // --- Staff data disclosure controls ---
  // Secret fields are never returned to any caller. Financial fields only to payroll roles.
  // Non-admin staff see only the directory projection for colleagues, and their own full record.
  const STAFF_SECRET_FIELDS = [
    'passwordHash', 'initialPassword', 'passwordResetToken', 'passwordResetTokenHash',
    'passwordResetExpires', 'passwordResetEmail', 'lockoutUntil', 'failedLoginAttempts', '__v',
  ];
  const STAFF_FINANCIAL_FIELDS = [
    'salary', 'monthlySalary', 'salaryStartDate', 'payrollHistory', 'bankAccountNo', 'bankName', 'bankBranch',
    'ifscCode', 'panNumber', 'uanNumber',
  ];
  const STAFF_DIRECTORY_FIELDS = [
    'id', 'employeeId', 'name', 'designation', 'department', 'classTeacherOf',
    'photo', 'photoFileKey', 'status', 'subjectExpertise',
  ];
  const STAFF_ADMIN_TIER = [
    'SUPER_ADMIN', 'SCHOOL_ADMIN', 'ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL',
    'HR_STAFF', 'ACADEMIC_COORDINATOR', 'ACCOUNTANT',
  ];
  const STAFF_PAYROLL_TIER = ['SUPER_ADMIN', 'SCHOOL_ADMIN', 'ADMIN', 'HR_STAFF', 'ACCOUNTANT'];
  function isStaffAdminTier(role?: string): boolean {
    return STAFF_ADMIN_TIER.includes(String(role || '').toUpperCase());
  }
  function isStaffPayrollTier(role?: string): boolean {
    return STAFF_PAYROLL_TIER.includes(String(role || '').toUpperCase());
  }
  function sanitizeStaffRecord(record: any, opts: { includeFinancial: boolean }): any {
    if (!record || typeof record !== 'object') return record;
    const out: Record<string, any> = { ...record };
    for (const key of STAFF_SECRET_FIELDS) delete out[key];
    if (!opts.includeFinancial) {
      for (const key of STAFF_FINANCIAL_FIELDS) delete out[key];
    }
    return out;
  }
  function sanitizeStaffDirectoryEntry(record: any): any {
    if (!record || typeof record !== 'object') return {};
    const out: Record<string, any> = {};
    for (const key of STAFF_DIRECTORY_FIELDS) {
      if (record[key] !== undefined) out[key] = record[key];
    }
    return out;
  }

  function requireAuth(req: Request, res: Response, next: any) {
    const { user, session, match } = getAuthContext(req);
    if (!user || !session || !match) {
      return res.status(401).json({ success: false, error: 'Unauthorized: Session expired or invalid token' });
    }
    (req as any).currentUser = user;
    (req as any).currentSession = session;
    (req as any).authMatch = match;
    next();
  }

  function requireRole(allowedRoles: (UserRole | string)[]) {
    return (req: Request, res: Response, next: any) => {
      if (!(req as any).currentUser) {
        const { user, session, match } = getAuthContext(req);
        if (!user || !session || !match) {
          return res.status(401).json({ success: false, error: 'Unauthorized: Session expired or invalid token' });
        }
        (req as any).currentUser = user;
        (req as any).currentSession = session;
        (req as any).authMatch = match;
      }
      const user = (req as any).currentUser as User;
      const role = String(user?.role || '').trim().toUpperCase();
      const normalizedAllowed = allowedRoles.map((r) => String(r).toUpperCase());
      const isAllowed =
        user &&
        (normalizedAllowed.includes(role) ||
          role === 'SUPER_ADMIN' ||
          (role === 'ADMIN' && (normalizedAllowed.includes('SCHOOL_ADMIN') || normalizedAllowed.includes('SUPER_ADMIN'))));
      if (!isAllowed) {
        return res.status(403).json({ success: false, error: 'Forbidden: Insufficient privileges for this operation' });
      }
      next();
    };
  }

  function requirePermission(requiredPermission: PermissionKey | string | (PermissionKey | string)[]) {
    return (req: Request, res: Response, next: any) => {
      if (!(req as any).currentUser) {
        const { user, session, match } = getAuthContext(req);
        if (!user || !session || !match) {
          return res.status(401).json({ success: false, error: 'Unauthorized: Session expired or invalid token' });
        }
        (req as any).currentUser = user;
        (req as any).currentSession = session;
        (req as any).authMatch = match;
      }
      const user = (req as any).currentUser as User;
      if (!user) {
        return res.status(401).json({ success: false, error: 'Unauthorized: No active session' });
      }

      if (user.role === 'SUPER_ADMIN' || user.role === 'SCHOOL_ADMIN' || (user.role as any) === 'ADMIN') {
        return next();
      }

      const perms = Array.isArray(requiredPermission) ? requiredPermission : [requiredPermission];
      const isGranted = perms.some((p) => hasPermission(user, p));

      if (!isGranted) {
        return res.status(403).json({
          success: false,
          error: `Forbidden: Missing required permission [${perms.join(' or ')}]`,
          requiredPermissions: perms,
          userRole: user.role,
        });
      }
      next();
    };
  }

  // --- AUTHENTICATION ENDPOINTS ---

  // Auth: Login - Authenticates directly against integrated domain entities (Admin, TeacherStaff, Student, Parent)
  app.post('/api/auth/login', loginThrottleGuard, async (req: Request, res: Response) => {
    try {
      // Fail securely if database is unavailable
      if (!mongoService.isConnected() || (mongoose.connection && mongoose.connection.readyState !== 1)) {
        return res.status(503).json({
          success: false,
          error: 'Database unavailable. Authentication service is temporarily offline.',
        });
      }

    const { password, dob, loginType, rememberMe } = req.body;
    const identifier = req.body.identifier || req.body.username || req.body.email || '';

    if (!identifier) {
      return res.status(400).json({ success: false, error: 'Login identifier is required.' });
    }

    const rawId = String(identifier).trim();
    const cleanId = rawId.toLowerCase();
    const cleanPhone = normalizePhone(rawId);

    // ==========================================
    // 1. STUDENT LOGIN
    // ==========================================
    if (loginType === 'STUDENT') {
      const enteredCred = String(dob || password || '').trim();
      if (!enteredCred) {
        return res.status(400).json({
          success: false,
          error: 'Password or Date of Birth (DD-MM-YYYY) is required for student login.',
        });
      }

      let student = students.find(
        (s) =>
          s.admissionNumber.toLowerCase() === cleanId ||
          s.registrationNumber.toLowerCase() === cleanId ||
          (s.email && s.email.toLowerCase() === cleanId)
      ) as any;

      if (mongoService.isConnected() && mongoose.connection.readyState === 1) {
        try {
          const dbStudent = await StudentModel.findOne({
            $or: [
              { admissionNumber: cleanId.toUpperCase() },
              { admissionNumber: cleanId },
              { registrationNumber: cleanId.toUpperCase() },
              { registrationNumber: cleanId },
              { email: cleanId },
              { id: cleanId },
            ],
          }).lean();
          if (dbStudent) {
            if (student) {
              Object.assign(student, dbStudent);
            } else {
              student = dbStudent as any;
              students.push(student);
            }
          }
        } catch (_) {}
      }

      // Roll number sign-in: roll numbers repeat across classes, so it only works together with the
      // date of birth and only when exactly one student matches both. Otherwise the admission number is needed.
      if (!student && cleanId) {
        const dobCheck = parseAndValidateDob(enteredCred);
        if (dobCheck.valid) {
          const byRoll = students.filter(
            (s: any) =>
              String(s.rollNumber || '').trim().toLowerCase() === cleanId &&
              (s.accountStatus || s.status || 'ACTIVE') === 'ACTIVE' &&
              (normalizeDobToIso(s.dob) === dobCheck.isoDate || s.dob === dobCheck.isoDate)
          );
          if (byRoll.length === 1) student = byRoll[0] as any;
          else if (byRoll.length > 1) {
            return res.status(401).json({
              success: false,
              error: 'More than one student has this roll number and date of birth. Please sign in with your Admission Number.',
            });
          }
        }
      }

      if (!student) {
        return res.status(401).json({
          success: false,
          error: 'Invalid login ID or password',
        });
      }

      // Check lockout
      if (student.lockoutUntil && Date.now() < student.lockoutUntil) {
        const minutesLeft = Math.ceil((student.lockoutUntil - Date.now()) / 60000);
        return res.status(429).json({
          success: false,
          error: `Account temporarily locked due to multiple failed login attempts. Please try again in ${minutesLeft} minute(s).`,
        });
      }

      // Check portal permissions & active status
      if (student.loginEnabled === false) {
        logAudit(student.name, 'STUDENT', 'LOGIN_BLOCKED', 'Student', student.id, 'Portal access is disabled for this student');
        return res.status(403).json({
          success: false,
          error: 'Account inactive',
        });
      }

      const accountStatus = student.accountStatus || student.status || 'ACTIVE';
      if (accountStatus === 'INACTIVE' || accountStatus === 'SUSPENDED') {
        logAudit(student.name, 'STUDENT', 'LOGIN_BLOCKED', 'Student', student.id, `Blocked login for ${accountStatus} student`);
        return res.status(403).json({
          success: false,
          error: 'Account inactive',
        });
      }

      // Check credential: match custom password hash (if set/reset) OR match DOB
      let isCredentialValid = false;
      if (student.passwordHash && bcrypt.compareSync(enteredCred, student.passwordHash)) {
        isCredentialValid = true;
      } else {
        const dobValidation = parseAndValidateDob(enteredCred);
        if (dobValidation.valid) {
          const normStuDob = normalizeDobToIso(student.dob);
          if (normStuDob === dobValidation.isoDate || student.dob === dobValidation.isoDate) {
            isCredentialValid = true;
          }
        }
      }

      if (!isCredentialValid) {
        student.failedLoginAttempts = (student.failedLoginAttempts || 0) + 1;
        if (student.failedLoginAttempts >= 5) {
          student.lockoutUntil = Date.now() + 15 * 60 * 1000;
        }
        logAudit(student.name, 'STUDENT', 'LOGIN_FAILED', 'Student', student.id, `Failed credential attempt for student ${student.admissionNumber}`);
        return res.status(401).json({
          success: false,
          error: 'Invalid login ID or password',
        });
      }

      // Success
      student.failedLoginAttempts = 0;
      student.lockoutUntil = undefined;
      student.lastLoginAt = new Date().toISOString();

      const { token, expiresAt } = createAuthToken(
        {
          userId: student.id,
          role: 'STUDENT',
          studentId: student.id,
        },
        !!rememberMe
      );

      const authMatch: AuthEntityMatch = { type: 'STUDENT', entity: student, role: 'STUDENT' };
      const safeUser = buildSafeUser(authMatch);

      const session: ServerSession = {
        token,
        userId: student.id,
        role: 'STUDENT',
        studentId: student.id,
        expiresAt,
        rememberMe: !!rememberMe,
        user: safeUser,
        authMatch,
      };
      activeSessions.set(token, session);

      logAudit(safeUser.name, 'STUDENT', 'USER_LOGIN', 'Student', student.id, `Student logged in via ${student.admissionNumber}`);

      return res.json({
        success: true,
        token,
        user: safeUser,
        expiresAt,
        school: {
          name: schoolSettings.schoolName,
          code: schoolSettings.schoolCode,
          session: schoolSettings.currentAcademicSession,
        },
      });
    }

    // ==========================================
    // 2. PARENT LOGIN
    // ==========================================
    if (loginType === 'PARENT') {
      const enteredCredential = String(dob || password || '').trim();
      if (!enteredCredential) {
        return res.status(400).json({
          success: false,
          error: 'Parent password or Child Date of Birth (DD-MM-YYYY) is required.',
        });
      }

      if (!cleanPhone || cleanPhone.length < 10) {
        return res.status(400).json({
          success: false,
          error: 'Please enter a valid 10-digit registered parent mobile number.',
        });
      }

      // Fetch fresh linked students directly from MongoDB Atlas (single production source of truth)
      if (mongoService.isConnected()) {
        try {
          const phoneRegex = new RegExp(cleanPhone + '$');
          const dbStudents = await StudentModel.find({
            $or: [
              { parentPhone: cleanPhone },
              { fatherMobile: cleanPhone },
              { motherMobile: cleanPhone },
              { guardianMobile: cleanPhone },
              { mobile: cleanPhone },
              { parentPhone: phoneRegex },
              { fatherMobile: phoneRegex },
              { motherMobile: phoneRegex },
              { guardianMobile: phoneRegex },
              { mobile: phoneRegex },
            ],
          }).lean();
          if (Array.isArray(dbStudents) && dbStudents.length > 0) {
            dbStudents.forEach((stu: any) => {
              const { _id, ...clean } = stu;
              const idx = students.findIndex((s) => s.id === clean.id);
              if (idx !== -1) {
                students[idx] = clean as Student;
              } else {
                students.push(clean as Student);
              }
            });
          }
        } catch (e) {
          console.warn('[Server] Error fetching linked students from MongoDB:', e);
        }
      }

      syncParentAccounts();

      // Find all students linked to this parent mobile number
      const linkedStudents = students.filter((s) => {
        return (
          normalizePhone(s.parentPhone) === cleanPhone ||
          normalizePhone(s.fatherMobile) === cleanPhone ||
          normalizePhone(s.motherMobile) === cleanPhone ||
          normalizePhone(s.guardianMobile) === cleanPhone ||
          normalizePhone(s.mobile) === cleanPhone
        );
      });

      // Check authoritative UserModel in MongoDB Atlas for persistent parent credentials
      let parentUserDoc: any = null;
      if (mongoService.isConnected()) {
        try {
          parentUserDoc = await UserModel.findOne({
            $or: [
              { phone: cleanPhone },
              { username: cleanPhone },
              { id: `parent-${cleanPhone}` },
            ],
            userType: 'PARENT',
          }).lean();
        } catch (e) {
          console.warn('[Server] Error querying parent UserModel in MongoDB:', e);
        }
      }

      // Also ensure any student IDs explicitly linked in parentUserDoc are present in linkedStudents
      if (parentUserDoc?.studentIds?.length || parentUserDoc?.linkedStudentIds?.length) {
        const docStudentIds: string[] = [...(parentUserDoc.studentIds || []), ...(parentUserDoc.linkedStudentIds || [])];
        for (const sid of docStudentIds) {
          if (!linkedStudents.some((st) => st.id === sid)) {
            const existingSt = students.find((st) => st.id === sid);
            if (existingSt) {
              linkedStudents.push(existingSt);
            } else if (mongoService.isConnected()) {
              try {
                const dbStu = await StudentModel.findOne({ id: sid }).lean();
                if (dbStu) {
                  const { _id, ...clean } = dbStu as any;
                  students.push(clean as Student);
                  linkedStudents.push(clean as Student);
                }
              } catch (_) {}
            }
          }
        }
      }

      let parent = parentAccounts.get(cleanPhone);
      if (!parent && linkedStudents.length > 0) {
        syncParentAccounts();
        parent = parentAccounts.get(cleanPhone);
      }

      if (linkedStudents.length === 0) {
        return res.status(401).json({
          success: false,
          error: 'No registered student found under this parent mobile number. If your number changed, please log in with your updated mobile number.',
        });
      }

      const activeLockout = parentUserDoc?.lockoutUntil
        ? new Date(parentUserDoc.lockoutUntil).getTime()
        : parent?.lockoutUntil;
      if (activeLockout && Date.now() < activeLockout) {
        const minutesLeft = Math.ceil((activeLockout - Date.now()) / 60000);
        return res.status(429).json({
          success: false,
          error: `Account temporarily locked due to multiple failed login attempts. Please try again in ${minutesLeft} minute(s).`,
        });
      }

      if (parentUserDoc?.loginEnabled === false || parent?.loginEnabled === false) {
        logAudit(parentUserDoc?.name || parent?.parentName || cleanPhone, 'PARENT', 'LOGIN_BLOCKED', 'Parent', parentUserDoc?.id || parent?.id || cleanPhone, 'Parent portal access disabled');
        return res.status(403).json({
          success: false,
          error: 'Account inactive',
        });
      }

      const statusVal = parentUserDoc?.status || parent?.accountStatus || 'ACTIVE';
      if (statusVal === 'INACTIVE' || statusVal === 'SUSPENDED') {
        logAudit(parentUserDoc?.name || parent?.parentName || cleanPhone, 'PARENT', 'LOGIN_BLOCKED', 'Parent', parentUserDoc?.id || parent?.id || cleanPhone, `Blocked login for ${statusVal} parent`);
        return res.status(403).json({
          success: false,
          error: 'Account inactive',
        });
      }

      // Check if password matches (authoritative MongoDB hash, custom parent account hash, default CPS123, or child DOB)
      const effectiveHash = parentUserDoc?.passwordHash || parent?.passwordHash;
      const isCustomPasswordMatch = !!(effectiveHash && (effectiveHash.startsWith('$2b$') || effectiveHash.startsWith('$2a$')) && bcrypt.compareSync(enteredCredential, effectiveHash));
      let isInitialDefaultPassword = false;
      if (isCustomPasswordMatch) {
        isInitialDefaultPassword = true;
      } else if (!effectiveHash || (!effectiveHash.startsWith('$2b$') && !effectiveHash.startsWith('$2a$'))) {
        if (enteredCredential.toUpperCase() === 'CPS123') {
          isInitialDefaultPassword = true;
        }
      }

      let matchingChild: any = null;
      if (isInitialDefaultPassword) {
        matchingChild = linkedStudents[0] || (parent?.studentIds ? students.find((s) => parent?.studentIds?.includes(s.id)) : null);
      } else {
        const dobValidation = parseAndValidateDob(enteredCredential);
        if (dobValidation.valid) {
          matchingChild = linkedStudents.find((s) => {
            const norm = normalizeDobToIso(s.dob);
            return norm === dobValidation.isoDate || s.dob === dobValidation.isoDate;
          });
        }
      }

      if (!matchingChild && !isCustomPasswordMatch) {
        if (parentUserDoc && mongoService.isConnected()) {
          const failCount = (parentUserDoc.failedLoginAttempts || 0) + 1;
          const lockoutTime = failCount >= 5 ? new Date(Date.now() + 15 * 60 * 1000) : null;
          await UserModel.updateOne(
            { id: parentUserDoc.id },
            { $set: { failedLoginAttempts: failCount, ...(lockoutTime ? { lockoutUntil: lockoutTime } : {}) } }
          ).catch(() => {});
        }
        if (parent) {
          parent.failedLoginAttempts = (parent.failedLoginAttempts || 0) + 1;
          if (parent.failedLoginAttempts >= 5) {
            parent.lockoutUntil = Date.now() + 15 * 60 * 1000;
          }
        }
        logAudit(parentUserDoc?.name || parent?.parentName || cleanPhone, 'PARENT', 'LOGIN_FAILED', 'Parent', parentUserDoc?.id || parent?.id || cleanPhone, `Credential mismatch for parent mobile ${cleanPhone}`);
        return res.status(401).json({
          success: false,
          error: 'Invalid login ID or password',
        });
      }

      // Reset failed attempts on success
      if (parentUserDoc && mongoService.isConnected()) {
        await UserModel.updateOne(
          { id: parentUserDoc.id },
          { $set: { failedLoginAttempts: 0, lockoutUntil: null, lastLoginAt: new Date() } }
        ).catch(() => {});
      }
      if (parent) {
        parent.failedLoginAttempts = 0;
        parent.lockoutUntil = undefined;
      }

      const activeStudentId = matchingChild?.id || linkedStudents[0]?.id || parent?.studentIds?.[0];
      const linkedStudentIds = linkedStudents.map((s) => s.id);

      // Ensure persistent UserModel exists in MongoDB Atlas for this parent
      if (!parentUserDoc && mongoService.isConnected() && linkedStudents.length > 0) {
        try {
          const firstChild = matchingChild || linkedStudents[0];
          parentUserDoc = await UserModel.findOneAndUpdate(
            { $or: [{ phone: cleanPhone }, { id: `parent-${cleanPhone}` }], userType: 'PARENT' },
            {
              $setOnInsert: {
                id: `parent-${cleanPhone}`,
                username: cleanPhone,
                name: firstChild.parentName || firstChild.fatherName || 'Parent / Guardian',
                phone: cleanPhone,
                email: firstChild.parentEmail || firstChild.fatherEmail || '',
                role: 'PARENT',
                userType: 'PARENT',
                passwordHash: bcrypt.hashSync('CPS123', 10),
                linkedStudentIds,
                activeStudentId,
                address: firstChild.address || '',
                city: firstChild.city || 'Sheohar',
                state: firstChild.state || 'Bihar',
                pincode: firstChild.pincode || '843329',
                fatherName: firstChild.fatherName || '',
                occupation: firstChild.parentOccupation || firstChild.fatherOccupation || '',
                status: 'ACTIVE',
                accountStatus: 'ACTIVE',
                loginEnabled: true,
                failedLoginAttempts: 0,
                lastLoginAt: new Date(),
              },
            },
            { upsert: true, new: true }
          ).lean();
        } catch (e) {
          console.warn('[Server] Error upserting parent UserModel in MongoDB:', e);
        }
      }

      const parentUserId = parentUserDoc?.id || parent?.id || `parent-${cleanPhone}`;

      const { token, expiresAt } = createAuthToken(
        {
          userId: parentUserId,
          role: 'PARENT',
          studentId: activeStudentId,
          activeStudentId,
          linkedStudentIds,
        },
        !!rememberMe
      );

      const parentEntity: InternalParentAccount = parent || {
        id: parentUserId,
        parentName: parentUserDoc?.name || matchingChild?.parentName || matchingChild?.fatherName || 'Parent / Guardian',
        phone: cleanPhone,
        email: parentUserDoc?.email || matchingChild?.parentEmail || matchingChild?.email,
        studentIds: linkedStudentIds,
        loginEnabled: true,
        accountStatus: 'ACTIVE',
        passwordHash: effectiveHash || DEFAULT_STAFF_PASSWORD_HASH,
        failedLoginAttempts: 0,
      };

      const authMatch: AuthEntityMatch = { type: 'PARENT', entity: parentEntity, role: 'PARENT' };
      const safeUser = buildSafeUser(authMatch);
      safeUser.id = parentUserId;
      safeUser.name = parentUserDoc?.name || parentEntity.parentName;
      safeUser.email = parentUserDoc?.email || parentEntity.email || safeUser.email;
      safeUser.phone = cleanPhone;
      safeUser.linkedStudentIds = linkedStudentIds;
      safeUser.activeStudentId = activeStudentId;
      safeUser.studentId = activeStudentId;

      const session: ServerSession = {
        token,
        userId: parentUserId,
        role: 'PARENT',
        studentId: activeStudentId,
        activeStudentId,
        linkedStudentIds,
        expiresAt,
        rememberMe: !!rememberMe,
        user: safeUser,
        authMatch,
      };
      activeSessions.set(token, session);

      logAudit(safeUser.name, 'PARENT', 'USER_LOGIN', 'Parent', parentEntity.id, `Parent logged in for child ${matchingChild?.name || ''}`);

      return res.json({
        success: true,
        token,
        user: safeUser,
        expiresAt,
        school: {
          name: schoolSettings.schoolName,
          code: schoolSettings.schoolCode,
          session: schoolSettings.currentAcademicSession,
        },
      });
    }

    // ==========================================
    // 3. COMMON STAFF / ADMIN LOGIN — ONE SINGLE COMMON LOGIN EXPERIENCE
    // Supports all 10 staff and admin roles:
    // SUPER_ADMIN, SCHOOL_ADMIN, PRINCIPAL, TEACHER, ACCOUNTANT,
    // HR_STAFF, HOSTEL_WARDEN, TRANSPORT_MANAGER, ACADEMIC_COORDINATOR, VICE_PRINCIPAL
    // Role is determined securely by MongoDB UserModel after authentication.
    // Frontend does NOT choose or submit a role.
    // ==========================================
    if (loginType === 'STAFF_ADMIN' || loginType === 'STAFF' || loginType === 'ADMIN' || (!loginType && loginType !== 'STUDENT' && loginType !== 'PARENT')) {
      const rawPass = String(password || '').trim();
      if (!rawPass) {
        return res.status(400).json({ success: false, error: 'Password is required for Staff & Administrator sign in.' });
      }

      const upperId = cleanId.toUpperCase();

      // Query MongoDB UserModel as the ONLY authoritative credentials source
      const queryFilters: any[] = [
        { username: cleanId },
        { email: cleanId },
        { employeeId: upperId },
        { employeeId: cleanId },
        { employeeId: rawId },
        { id: cleanId },
      ];
      if (cleanPhone.length >= 10) {
        queryFilters.push({ phone: cleanPhone });
      }

      // Several accounts can share an email or mobile (e.g. the school email on many staff records). Exact login
      // ids win; a shared email / mobile is used only when it belongs to one account, or when the password fits
      // exactly one of them. Otherwise the person is asked for their Employee ID (never someone else's account).
      const candidates: any[] = await UserModel.find({
        $or: queryFilters,
        userType: { $in: ['ADMIN', 'STAFF'] },
      })
        .limit(20)
        .lean();
      const lowerId = cleanId.toLowerCase();
      let userDoc: any = pickByPriority(
        candidates,
        [
          (u) => String(u.username || '').toLowerCase() === lowerId,
          (u) => String(u.employeeId || '').toUpperCase() === upperId,
          (u) => u.id === cleanId,
        ],
        [(u) => !!u.email && String(u.email).toLowerCase() === lowerId, (u) => cleanPhone.length >= 10 && normalizePhone(u.phone) === cleanPhone]
      );
      if (!userDoc && candidates.length > 1) {
        const fits = candidates.filter((u) => u.passwordHash && bcrypt.compareSync(rawPass, u.passwordHash));
        if (fits.length === 1) userDoc = fits[0];
        else if (fits.length > 1) {
          return res.status(409).json({
            success: false,
            code: 'AMBIGUOUS_LOGIN',
            error: 'This email / mobile number is used by more than one staff account. Please sign in with your Employee ID (e.g. CPS0012).',
          });
        }
      }
      if (!userDoc && candidates.length === 1) userDoc = candidates[0];

      if (!userDoc) {
        // Helpful check: if student or parent tried to log in via staff portal
        const isStudentOrParent = students.some(
          (s) =>
            (s.admissionNumber && s.admissionNumber.toLowerCase() === cleanId) ||
            (s.registrationNumber && s.registrationNumber.toLowerCase() === cleanId) ||
            (s.email && s.email.toLowerCase() === cleanId) ||
            (cleanPhone.length >= 10 && (normalizePhone(s.mobile) === cleanPhone || normalizePhone(s.parentPhone) === cleanPhone))
        );
        if (isStudentOrParent) {
          return res.status(401).json({
            success: false,
            error: 'This portal is for Staff and Administrators. Students and parents please use your designated login portal.',
          });
        }
        return res.status(401).json({ success: false, error: 'Invalid login ID or password. Please verify your credentials.' });
      }

      const lockoutVal = userDoc.lockoutUntil;
      if (lockoutVal && Date.now() < (typeof lockoutVal === 'number' ? lockoutVal : new Date(lockoutVal).getTime())) {
        const lockoutTime = typeof lockoutVal === 'number' ? lockoutVal : new Date(lockoutVal).getTime();
        const minutesLeft = Math.ceil((lockoutTime - Date.now()) / 60000);
        return res.status(429).json({
          success: false,
          error: `Account temporarily locked due to multiple failed login attempts. Please try again in ${minutesLeft} minute(s).`,
        });
      }

      if (userDoc.loginEnabled === false || isNoLoginStaffRole(userDoc.role)) {
        logAudit(userDoc.name, userDoc.role, 'LOGIN_BLOCKED', userDoc.userType === 'ADMIN' ? 'Admin' : 'Staff', userDoc.id, 'Portal access disabled');
        return res.status(403).json({
          success: false,
          error: 'Account inactive',
        });
      }

      const accountStatus = userDoc.status || (userDoc as any).accountStatus || 'ACTIVE';
      if (accountStatus === 'INACTIVE' || accountStatus === 'SUSPENDED' || accountStatus === 'LEFT_SCHOOL' || accountStatus === 'RESIGNED') {
        logAudit(userDoc.name, userDoc.role, 'LOGIN_BLOCKED', userDoc.userType === 'ADMIN' ? 'Admin' : 'Staff', userDoc.id, `Blocked login for ${accountStatus} account`);
        return res.status(403).json({
          success: false,
          error: 'Account inactive',
        });
      }

      if (!userDoc.passwordHash) {
        return res.status(401).json({ success: false, error: 'Invalid login ID or password. Please verify your credentials.' });
      }

      const isPasswordValid = bcrypt.compareSync(rawPass, userDoc.passwordHash);

      if (!isPasswordValid) {
        const newFailed = (userDoc.failedLoginAttempts || 0) + 1;
        const isLocked = newFailed >= 5;
        const lockoutUntil = isLocked ? new Date(Date.now() + 15 * 60 * 1000) : null;
        await UserModel.updateOne(
          { _id: userDoc._id },
          {
            $inc: { failedLoginAttempts: 1 },
            ...(isLocked ? { $set: { lockoutUntil } } : {}),
          }
        ).catch(() => {});

        logAudit(userDoc.name, userDoc.role, 'LOGIN_FAILED', userDoc.userType === 'ADMIN' ? 'Admin' : 'Staff', userDoc.id, `Failed password attempt for ${cleanId}`);
        return res.status(401).json({ success: false, error: 'Invalid login ID or password. Please verify your credentials.' });
      }

      // Successful authentication: Reset failed login attempts & lockout
      await UserModel.updateOne(
        { _id: userDoc._id },
        { $set: { failedLoginAttempts: 0, lockoutUntil: null, lastLoginAt: new Date().toISOString() } }
      ).catch(() => {});

      const role: UserRole = userDoc.role as UserRole;
      const isMatchedAdmin = userDoc.userType === 'ADMIN';

      // Resolve full profile entity from runtime arrays / models
      let entity: any = null;
      if (isMatchedAdmin) {
        let matchedAdmin = adminAccounts.find(
          (a) =>
            a.id === userDoc.id ||
            a.id === userDoc.id.replace(/^user-admin-/, '') ||
            `user-admin-${a.id}` === userDoc.id ||
            a.username.toLowerCase() === (userDoc.username || '').toLowerCase() ||
            (userDoc.email && a.email.toLowerCase() === userDoc.email.toLowerCase())
        );
        if (!matchedAdmin) {
          matchedAdmin = {
            id: userDoc.id,
            name: userDoc.name,
            username: userDoc.username || INITIAL_ADMIN_USERNAME,
            email: userDoc.email || '',
            phone: userDoc.phone || '',
            role: (role === 'SUPER_ADMIN' ? 'SUPER_ADMIN' : 'SCHOOL_ADMIN') as any,
            status: 'ACTIVE',
            passwordHash: userDoc.passwordHash,
            failedLoginAttempts: 0,
            createdAt: userDoc.createdAt ? new Date(userDoc.createdAt).toISOString() : new Date().toISOString(),
          } as any;
          adminAccounts.push(matchedAdmin);
        } else {
          matchedAdmin.passwordHash = userDoc.passwordHash;
        }
        entity = matchedAdmin;
      } else {
        const strippedId = userDoc.id ? userDoc.id.replace(/^user-staff-/, '') : '';
        let matchedStaff = pickByPriority(
          staff,
          [
            (s) => !!userDoc.employeeId && !!s.employeeId && s.employeeId.toUpperCase() === String(userDoc.employeeId).toUpperCase(),
            (s) => s.id === userDoc.id || (!!strippedId && s.id === strippedId) || `user-staff-${s.id}` === userDoc.id,
          ],
          [(s) => !!userDoc.email && !!s.email && s.email.toLowerCase() === String(userDoc.email).toLowerCase()]
        );
        if (!matchedStaff) {
          matchedStaff = {
            id: userDoc.id,
            name: userDoc.name,
            employeeId: userDoc.employeeId || cleanId.toUpperCase(),
            email: userDoc.email || '',
            phone: userDoc.phone || '',
            systemRole: role,
            role,
            designation: role === 'PRINCIPAL' ? 'Principal' : (role === 'ACCOUNTANT' ? 'Chief Accounts Officer' : (role === 'SUPER_ADMIN' ? 'Super Administrator' : 'Faculty Member')),
            status: 'ACTIVE',
            accountStatus: 'ACTIVE',
            loginEnabled: true,
            photo: userDoc.avatar || userDoc.photo || '',
            photoFileKey: userDoc.photoFileKey || '',
          } as any;
          staff.unshift(matchedStaff);
        }
        // Update in-memory staff passwordHash so it mirrors the authoritative UserModel hash
        if (matchedStaff && matchedStaff.passwordHash !== userDoc.passwordHash) {
          matchedStaff.passwordHash = userDoc.passwordHash;
        }
        entity = matchedStaff;
      }

      const { token, expiresAt } = createAuthToken(
        {
          userId: entity.id,
          role,
          employeeId: entity.employeeId || userDoc.employeeId,
        },
        !!rememberMe
      );

      const authMatch: AuthEntityMatch = { type: isMatchedAdmin ? 'ADMIN' : 'STAFF', entity, role };
      const safeUser = buildSafeUser(authMatch);

      const session: ServerSession = {
        token,
        userId: entity.id,
        role,
        employeeId: entity.employeeId || userDoc.employeeId,
        expiresAt,
        rememberMe: !!rememberMe,
        user: safeUser,
        authMatch,
      };
      activeSessions.set(token, session);

      logAudit(safeUser.name, role, 'USER_LOGIN', isMatchedAdmin ? 'Admin' : 'Staff', entity.id, `Staff/Admin logged in via ${cleanId} (${role})`);

      return res.json({
        success: true,
        token,
        user: safeUser,
        expiresAt,
        school: {
          name: schoolSettings.schoolName,
          code: schoolSettings.schoolCode,
          session: schoolSettings.currentAcademicSession,
        },
      });
    }

    // Default secure rejection - no static or in-memory fallback permitted
    return res.status(401).json({ success: false, error: 'Invalid login ID or password. Please verify your credentials.' });
    } catch (loginErr: any) {
      console.error('[Server] /api/auth/login error:', loginErr);
      return res.status(500).json({ success: false, error: 'Internal authentication service error' });
    }
  });

  // Auth: Get Current Authenticated User (Session Verification)
  app.get('/api/auth/me', requireAuth, (req: Request, res: Response) => {
    const user = (req as any).currentUser as User;
    res.json({
      success: true,
      user,
      school: {
        name: schoolSettings.schoolName,
        code: schoolSettings.schoolCode,
        session: schoolSettings.currentAcademicSession,
      },
    });
  });

  // Auth: Logout
  app.post('/api/auth/logout', (req: Request, res: Response) => {
    const { user, session } = getAuthContext(req);
    if (session) {
      revokeToken(session.token, session.expiresAt);
    }
    if (user) {
      logAudit(user.name, user.role, 'USER_LOGOUT', 'Session', user.id, 'User logged out');
    }
    res.json({ success: true, message: 'Logged out successfully' });
  });

  // Auth: Parent Active Child Switching (Strictly verified against linked children)
  app.post('/api/auth/switch-child', requireAuth, async (req: Request, res: Response) => {
    const session = (req as any).currentSession as ServerSession;
    const user = (req as any).currentUser as User;
    const { studentId } = req.body;

    if (session.role !== 'PARENT' || !session.linkedStudentIds) {
      return res.status(403).json({ success: false, error: 'Only parent accounts can switch children' });
    }

    // Resolve student from runtime array or MongoDB directly
    let targetStudent = students.find((s) => s.id === studentId || s.admissionNumber === studentId);
    if (!targetStudent && mongoService.isConnected()) {
      try {
        const dbStudent = await mongoService.getStudentById(studentId);
        if (dbStudent) {
          targetStudent = dbStudent;
          const idx = students.findIndex((s) => s.id === dbStudent.id);
          if (idx === -1) students.push(dbStudent);
          else students[idx] = dbStudent;
        }
      } catch (e) {}
    }

    const resolvedId = targetStudent ? targetStudent.id : studentId;

    if (!session.linkedStudentIds.includes(resolvedId) && (!targetStudent?.admissionNumber || !session.linkedStudentIds.includes(targetStudent.admissionNumber))) {
      return res.status(403).json({ success: false, error: 'Access denied: That student is not linked to your parent account' });
    }

    session.activeStudentId = resolvedId;
    session.studentId = resolvedId;
    user.activeStudentId = resolvedId;
    user.studentId = resolvedId;

    if (targetStudent && (targetStudent.photo || targetStudent.photoFileKey)) {
      user.avatar = targetStudent.photo || targetStudent.photoFileKey;
      session.user!.avatar = user.avatar;
    }

    if (mongoService.isConnected()) {
      UserModel.updateOne(
        { $or: [{ id: user.id }, { phone: user.phone }], userType: 'PARENT' },
        { $set: { activeStudentId: resolvedId } }
      ).catch(() => {});
    }

    logAudit(user.name, 'PARENT', 'SWITCH_CHILD', 'Student', resolvedId, `Switched active portal view to child ${resolvedId}`);

    res.json({
      success: true,
      user,
      activeStudentId: resolvedId,
    });
  });

  // Auth: Role switching is strictly prohibited
  app.post('/api/auth/switch-role', (req: Request, res: Response) => {
    return res.status(403).json({ success: false, error: 'Forbidden: Role switching has been disabled.' });
  });

  // User Profile: Fetch current user profile details dynamically from MongoDB
  app.get('/api/auth/profile', requireAuth, async (req: Request, res: Response) => {
    try {
      const user = (req as any).currentUser as User;
      const session = (req as any).currentSession as ServerSession;

      let profileData: any = null;
      let userDoc: any = null;

      // 1. Authoritative UserModel lookup in MongoDB
      if (mongoService.isConnected()) {
        try {
          // Several accounts can share an email: exact id / employee ID / username first, email only if unique.
          const userCandidates: any[] = await UserModel.find({
            $or: [
              { id: user.id },
              ...(user.employeeId ? [{ employeeId: user.employeeId.toUpperCase() }, { employeeId: user.employeeId }] : []),
              ...(user.username ? [{ username: user.username.toLowerCase() }] : []),
              ...(user.email ? [{ email: user.email.toLowerCase() }] : []),
            ],
          })
            .limit(20)
            .lean();
          userDoc = pickByPriority(
            userCandidates,
            [
              (u) => u.id === user.id,
              (u) => !!user.employeeId && String(u.employeeId || '').toUpperCase() === user.employeeId.toUpperCase(),
              (u) => !!user.username && String(u.username || '').toLowerCase() === user.username.toLowerCase(),
            ],
            [(u) => !!user.email && String(u.email || '').toLowerCase() === user.email.toLowerCase()]
          ) || null;
        } catch (dbErr) {
          console.warn('[Profile] Error querying UserModel from MongoDB:', dbErr);
        }
      }

      const isStaffRole = [
        'TEACHER',
        'PRINCIPAL',
        'ACCOUNTANT',
        'HOSTEL_WARDEN',
        'TRANSPORT_MANAGER',
        'HR_STAFF',
        'ACADEMIC_COORDINATOR',
        'VICE_PRINCIPAL',
      ].includes(session.role) || !!user.employeeId;

      const isAdminRole = session.role === 'SUPER_ADMIN' || session.role === 'SCHOOL_ADMIN';

      // 2. Authoritative StaffModel lookup in MongoDB
      let staffDoc: any = null;
      if (mongoService.isConnected()) {
        try {
          const staffQueryFilters: any[] = [];
          if (user.employeeId) {
            staffQueryFilters.push({ employeeId: user.employeeId.toUpperCase() });
            staffQueryFilters.push({ employeeId: user.employeeId });
          }
          if (user.id) {
            staffQueryFilters.push({ id: user.id });
            const stripped = user.id.replace(/^user-staff-/, '');
            if (stripped) staffQueryFilters.push({ id: stripped });
          }
          if (user.email) {
            staffQueryFilters.push({ email: user.email.toLowerCase() });
          }
          if (user.phone) {
            staffQueryFilters.push({ phone: user.phone });
          }
          if (staffQueryFilters.length > 0) {
            const stripped = String(user.id || '').replace(/^user-staff-/, '');
            const staffCandidates: any[] = await StaffModel.find({ $or: staffQueryFilters }).limit(20).lean();
            // The signed-in person's own record only: id / employee ID first; email / phone only when unique.
            staffDoc = pickByPriority(
              staffCandidates,
              [
                (x) => x.id === user.id || (!!stripped && x.id === stripped),
                (x) => !!user.employeeId && String(x.employeeId || '').toUpperCase() === user.employeeId.toUpperCase(),
              ],
              [(x) => !!user.email && String(x.email || '').toLowerCase() === user.email.toLowerCase(), (x) => !!user.phone && x.phone === user.phone]
            ) || null;
          }
        } catch (dbErr) {
          console.warn('[Profile] Error querying StaffModel from MongoDB:', dbErr);
        }
      }

      if (staffDoc) {
        // Synchronize in-memory staff record with latest MongoDB staff doc
        // Merge into the SAME person's in-memory record (id / employee ID), never a record that only shares an email.
        const existingIdx = staff.findIndex(
          (s) => s.id === staffDoc.id || (!!staffDoc.employeeId && s.employeeId?.toUpperCase() === staffDoc.employeeId.toUpperCase())
        );
        if (existingIdx !== -1) {
          staff[existingIdx] = { ...staff[existingIdx], ...staffDoc };
        } else {
          staff.unshift(staffDoc);
        }
        profileData = { ...staffDoc };
        profileData.role = staffDoc.role || staffDoc.systemRole || staffDoc.portalRole || user.role || session.role;
        profileData.systemRole = staffDoc.systemRole || profileData.role;
        profileData.portalRole = staffDoc.portalRole || profileData.role;
        profileData.documents = Array.isArray(staffDoc.documents) ? staffDoc.documents : [];
        profileData.department = staffDoc.department || (['ACCOUNTANT'].includes(staffDoc.systemRole) ? 'Accounts & Finance' : ['HR_STAFF'].includes(staffDoc.systemRole) ? 'Human Resources' : ['HOSTEL_WARDEN'].includes(staffDoc.systemRole) ? 'Hostel' : ['TRANSPORT_MANAGER'].includes(staffDoc.systemRole) ? 'Transport' : 'ACADEMICS');
      } else if (isStaffRole) {
        // Fallback to in-memory staff array
        const found = findStaffForUser(user, session);
        if (found) {
          profileData = { ...found };
          profileData.role = found.role || found.systemRole || found.portalRole || user.role || session.role;
          profileData.systemRole = found.systemRole || profileData.role;
          profileData.portalRole = found.portalRole || profileData.role;
          profileData.documents = Array.isArray(found.documents) ? found.documents : [];
          profileData.department = found.department || 'ACADEMICS';
        }
      } else if (session.role === 'STUDENT') {
        if (mongoService.isConnected()) {
          try {
            const studentDoc = await StudentModel.findOne({
              $or: [{ id: user.studentId || user.id }, ...(user.username ? [{ admissionNumber: user.username.toUpperCase() }] : [])],
            }).lean();
            if (studentDoc) profileData = studentDoc;
          } catch (e) {}
        }
        if (!profileData) {
          profileData = students.find((s) => s.id === user.studentId || s.id === user.id);
        }
      } else if (session.role === 'PARENT') {
        let parentDoc: any = null;
        if (mongoService.isConnected()) {
          try {
            parentDoc = await UserModel.findOne({
              $or: [
                { id: user.id },
                { username: user.username },
                { phone: user.phone },
                { id: `parent-${user.phone}` },
              ],
              userType: 'PARENT',
            }).lean();
          } catch (dbErr) {
            console.warn('[Profile] Error querying parent UserModel from MongoDB:', dbErr);
          }
        }

        // Fetch parent's linked children directly from MongoDB Atlas
        let linkedChildren: Student[] = [];
        if (mongoService.isConnected()) {
          try {
            const childQuery: any[] = [];
            const linkedIds = session.linkedStudentIds || user.linkedStudentIds || parentDoc?.linkedStudentIds || [];
            if (linkedIds.length > 0) {
              childQuery.push({ id: { $in: linkedIds } });
            }
            if (user.phone) {
              const cleanP = normalizePhone(user.phone);
              childQuery.push({ parentPhone: cleanP });
              childQuery.push({ fatherMobile: cleanP });
              childQuery.push({ motherMobile: cleanP });
              childQuery.push({ guardianMobile: cleanP });
              childQuery.push({ mobile: cleanP });
            }
            if (childQuery.length > 0) {
              const dbChildren = await StudentModel.find({ $or: childQuery }).lean();
              if (Array.isArray(dbChildren) && dbChildren.length > 0) {
                linkedChildren = dbChildren.map((d: any) => {
                  const { _id, ...clean } = d;
                  return clean as Student;
                });
              }
            }
          } catch (dbErr) {
            console.warn('[Profile] Error querying linked children from MongoDB:', dbErr);
          }
        }

        if (linkedChildren.length === 0) {
          const linkedIds = session.linkedStudentIds || user.linkedStudentIds || parentDoc?.linkedStudentIds || [];
          linkedChildren = students.filter(
            (s) =>
              linkedIds.includes(s.id) ||
              (user.phone &&
                (normalizePhone(s.parentPhone) === user.phone ||
                  normalizePhone(s.fatherMobile) === user.phone ||
                  normalizePhone(s.mobile) === user.phone))
          );
        }

        // Deduplicate children by ID
        const seenIds = new Set<string>();
        const dedupedChildren: Student[] = [];
        for (const ch of linkedChildren) {
          if (!seenIds.has(ch.id)) {
            seenIds.add(ch.id);
            dedupedChildren.push(ch);
          }
        }

        const effectiveLinkedIds = dedupedChildren.map((c) => c.id);
        const effectiveActiveChildId = session.activeStudentId || user.activeStudentId || effectiveLinkedIds[0] || '';
        const activeChild = dedupedChildren.find((c) => c.id === effectiveActiveChildId) || dedupedChildren[0];

        profileData = {
          id: parentDoc?.id || user.id || `parent-${user.phone}`,
          name: parentDoc?.name || user.name || activeChild?.parentName || activeChild?.fatherName || 'Parent / Guardian',
          username: parentDoc?.username || user.username || user.phone,
          role: 'PARENT',
          systemRole: 'PARENT',
          portalRole: 'PARENT',
          phone: parentDoc?.phone || user.phone || activeChild?.parentPhone || '',
          email: parentDoc?.email || user.email || activeChild?.parentEmail || '',
          alternatePhone: parentDoc?.alternatePhone || '',
          emergencyContact: parentDoc?.emergencyContact || activeChild?.emergencyContact || '',
          address: parentDoc?.address || parentDoc?.permanentAddress || activeChild?.address || '',
          permanentAddress: parentDoc?.permanentAddress || parentDoc?.address || activeChild?.address || '',
          currentAddress: parentDoc?.currentAddress || parentDoc?.address || activeChild?.address || '',
          city: parentDoc?.city || activeChild?.city || 'Sheohar',
          state: parentDoc?.state || activeChild?.state || 'Bihar',
          pincode: parentDoc?.pincode || activeChild?.pincode || '843329',
          occupation: parentDoc?.occupation || activeChild?.parentOccupation || activeChild?.fatherOccupation || '',
          relationship: parentDoc?.relationship || activeChild?.guardianRelationship || 'Parent / Guardian',
          photo: parentDoc?.avatar || parentDoc?.photo || user.avatar || activeChild?.photo || '',
          photoFileKey: parentDoc?.photoFileKey || '',
          status: parentDoc?.status || 'ACTIVE',
          accountStatus: parentDoc?.accountStatus || 'ACTIVE',
          loginEnabled: parentDoc?.loginEnabled !== false,
          lastLoginAt: parentDoc?.lastLoginAt || '',
          linkedStudentIds: effectiveLinkedIds,
          activeStudentId: effectiveActiveChildId,
          children: dedupedChildren.map((child) => ({
            id: child.id,
            name: child.name,
            admissionNumber: child.admissionNumber,
            className: child.className,
            section: child.section,
            rollNumber: child.rollNumber || 'N/A',
            academicSession: child.academicSession || schoolSettings.currentAcademicSession,
            photo: child.photo || '',
            photoFileKey: child.photoFileKey || '',
            dob: child.dob || '',
            gender: child.gender || '',
            bloodGroup: child.bloodGroup || '',
            status: child.status || 'ACTIVE',
          })),
        };
      }

      // If no Staff record found for administrative role, build complete admin profile from UserModel/adminAccounts
      if (!profileData && isAdminRole) {
        const adminAccount = adminAccounts.find(
          (a) => a.id === user.id || a.username.toLowerCase() === user.username.toLowerCase()
        );
        profileData = {
          id: userDoc?.id || adminAccount?.id || user.id,
          employeeId: userDoc?.employeeId || user.employeeId || 'ADMIN-01',
          name: userDoc?.name || adminAccount?.name || user.name,
          username: userDoc?.username || adminAccount?.username || user.username,
          email: userDoc?.email || adminAccount?.email || user.email || '',
          phone: userDoc?.phone || adminAccount?.phone || user.phone || '',
          alternatePhone: userDoc?.alternatePhone || (adminAccount as any)?.alternatePhone || '',
          emergencyContact: userDoc?.emergencyContact || (adminAccount as any)?.emergencyContact || '',
          bloodGroup: userDoc?.bloodGroup || (adminAccount as any)?.bloodGroup || '',
          dob: userDoc?.dob || (adminAccount as any)?.dob || '',
          gender: userDoc?.gender || (adminAccount as any)?.gender || 'MALE',
          fatherOrMotherName: userDoc?.fatherOrMotherName || userDoc?.fatherName || (adminAccount as any)?.fatherOrMotherName || '',
          address: userDoc?.permanentAddress || userDoc?.address || adminAccount?.address || (user as any).address || '',
          permanentAddress: userDoc?.permanentAddress || userDoc?.address || adminAccount?.address || '',
          currentAddress: userDoc?.currentAddress || userDoc?.permanentAddress || userDoc?.address || adminAccount?.address || '',
          city: userDoc?.permanentCity || userDoc?.city || (adminAccount as any)?.city || 'Sheohar',
          permanentCity: userDoc?.permanentCity || userDoc?.city || (adminAccount as any)?.permanentCity || 'Sheohar',
          currentCity: userDoc?.currentCity || userDoc?.permanentCity || userDoc?.city || (adminAccount as any)?.currentCity || 'Sheohar',
          state: userDoc?.permanentState || userDoc?.state || (adminAccount as any)?.state || 'Bihar',
          permanentState: userDoc?.permanentState || userDoc?.state || (adminAccount as any)?.permanentState || 'Bihar',
          currentState: userDoc?.currentState || userDoc?.permanentState || userDoc?.state || (adminAccount as any)?.currentState || 'Bihar',
          pincode: userDoc?.permanentPincode || userDoc?.pincode || (adminAccount as any)?.pincode || '843329',
          permanentPincode: userDoc?.permanentPincode || userDoc?.pincode || (adminAccount as any)?.permanentPincode || '843329',
          currentPincode: userDoc?.currentPincode || userDoc?.permanentPincode || userDoc?.pincode || (adminAccount as any)?.currentPincode || '843329',
          sameAsPermanentAddress: userDoc?.sameAsPermanentAddress !== undefined ? userDoc.sameAsPermanentAddress : true,
          role: session.role,
          systemRole: session.role,
          portalRole: session.role,
          designation: userDoc?.designation || (adminAccount as any)?.designation || (session.role === 'SUPER_ADMIN' ? 'Super Administrator' : 'School Administrator'),
          department: userDoc?.department || (adminAccount as any)?.department || 'Executive Administration & Management',
          customDepartment: userDoc?.customDepartment || (adminAccount as any)?.customDepartment || '',
          qualification: userDoc?.qualification || (adminAccount as any)?.qualification || 'Post Graduate / Institutional Administration',
          customQualification: userDoc?.customQualification || '',
          totalExperience: userDoc?.totalExperience || (userDoc?.experienceYears ? `${userDoc.experienceYears} Years` : '10+ Years Administrative Experience'),
          experienceYears: userDoc?.experienceYears !== undefined ? userDoc.experienceYears : 10,
          employmentType: userDoc?.employmentType || (adminAccount as any)?.employmentType || 'Permanent / Full Time',
          joiningDate: userDoc?.joiningDate || (adminAccount as any)?.joiningDate || '2026-01-05',
          status: userDoc?.status || adminAccount?.status || 'ACTIVE',
          accountStatus: userDoc?.accountStatus || 'ACTIVE',
          loginEnabled: true,
          photo: userDoc?.avatar || userDoc?.photo || adminAccount?.avatar || user.avatar || '',
          photoFileKey: userDoc?.photoFileKey || '',
          documents: Array.isArray(userDoc?.documents) ? userDoc.documents : [],
          teachingWorkload: userDoc?.teachingWorkload || 0,
          classTeacherOf: userDoc?.classTeacherOf || '',
          assignedPrimarySubject: userDoc?.assignedPrimarySubject || '',
          houseClubResponsibility: userDoc?.houseClubResponsibility || '',
          certifications: userDoc?.certifications || '',
          bankAccountNo: userDoc?.bankAccountNo || '',
          bankName: userDoc?.bankName || '',
          bankBranch: userDoc?.bankBranch || '',
          ifscCode: userDoc?.ifscCode || '',
          panNumber: userDoc?.panNumber || '',
          uanNumber: userDoc?.uanNumber || '',
        };
      }

      // Incorporate latest login time, avatar, and active status from userDoc
      if (profileData && userDoc) {
        profileData.lastLoginAt = userDoc.lastLoginAt ? new Date(userDoc.lastLoginAt).toISOString() : profileData.lastLoginAt;
        profileData.status = userDoc.status || profileData.status || 'ACTIVE';
        profileData.accountStatus = userDoc.accountStatus || profileData.accountStatus || 'ACTIVE';
        profileData.loginEnabled = userDoc.loginEnabled !== undefined ? userDoc.loginEnabled : (profileData.loginEnabled !== false);
        if (userDoc.avatar && !profileData.photo) {
          profileData.photo = userDoc.avatar;
        }
      }

      if (profileData) {
        profileData.role = profileData.role || profileData.systemRole || profileData.portalRole || session.role || user.role;
        profileData.systemRole = profileData.systemRole || profileData.role || session.role;
        profileData.portalRole = profileData.portalRole || profileData.role || session.role;
        profileData.documents = Array.isArray(profileData.documents) ? profileData.documents : [];
      }

      // Format safeUser
      const safeUser = {
        ...user,
        name: profileData?.name || user.name,
        email: profileData?.email || user.email,
        phone: profileData?.phone || profileData?.mobile || user.phone,
        avatar: profileData?.photo || profileData?.photoFileKey || user.avatar,
        status: profileData?.status || user.status || 'ACTIVE',
      };

      res.json({
        success: true,
        user: safeUser,
        // Own record (salary / bank details are the person's own), never the password hash or reset tokens.
        profile: profileData ? sanitizeStaffRecord(profileData, { includeFinancial: true }) : safeUser,
        role: session.role,
      });
    } catch (err: any) {
      console.error('[Server] /api/auth/profile error:', err);
      res.status(500).json({ success: false, error: 'Internal server error fetching profile' });
    }
  });

  // User Profile: Update permitted personal information based on role
  /** Self-service profile edits: format checks for the fields staff may change themselves. */
  function validateSelfProfileUpdate(u: any): string | null {
    const str = (v: unknown) => (v === undefined || v === null ? undefined : String(v).trim());
    const phone = str(u.phone ?? u.mobile);
    if (phone !== undefined && phone !== '' && !/^(\+?91[\s-]?)?[6-9]\d{9}$/.test(phone.replace(/[\s-]/g, ''))) return 'Enter a valid 10-digit mobile number.';
    const alt = str(u.alternatePhone);
    if (alt !== undefined && alt !== '' && !/^\+?[\d\s-]{7,15}$/.test(alt)) return 'Enter a valid alternate phone number.';
    const email = str(u.email);
    if (email !== undefined && email !== '' && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return 'Enter a valid email address.';
    const pin = str(u.pincode ?? u.permanentPincode ?? u.currentPincode);
    if (pin !== undefined && pin !== '' && !/^\d{6}$/.test(pin)) return 'PIN code must be 6 digits.';
    for (const k of ['address', 'permanentAddress', 'currentAddress', 'city', 'state', 'emergencyContact', 'fatherName', 'motherName', 'qualification', 'customQualification']) {
      const v = str(u[k]);
      if (v !== undefined && v.length > 300) return 'One of the fields is too long.';
    }
    return null;
  }

  /** Keeps existing documents (with their verification status) and accepts only new ones, marked PENDING. */
  function mergeSelfUploadedDocuments(existing: any[], incoming: unknown): any[] {
    if (!Array.isArray(incoming)) return existing;
    const byKey = new Map(existing.map((d: any) => [String(d?.id || d?.fileKey || d?.url || ''), d]));
    const out = [...existing];
    for (const d of incoming.slice(0, 50)) {
      const key = String((d as any)?.id || (d as any)?.fileKey || (d as any)?.url || '');
      if (!key || byKey.has(key)) continue;
      out.push({ ...(d as any), status: 'PENDING', verifiedBy: undefined, verifiedAt: undefined });
    }
    return out;
  }

  app.put(['/api/auth/profile', '/api/profile'], requireAuth, async (req: Request, res: Response) => {
    try {
      const user = (req as any).currentUser as User;
      const session = (req as any).currentSession as ServerSession;
      const updates = req.body || {};

      const isStaffRole = [
        'TEACHER',
        'PRINCIPAL',
        'ACCOUNTANT',
        'HOSTEL_WARDEN',
        'TRANSPORT_MANAGER',
        'HR_STAFF',
        'ACADEMIC_COORDINATOR',
        'VICE_PRINCIPAL',
      ].includes(session.role) || !!user.employeeId;

      const isAdminRole = session.role === 'SUPER_ADMIN' || session.role === 'SCHOOL_ADMIN';

      // 1. Authoritative lookup in MongoDB StaffModel first, then in-memory staff array
      let staffDoc: any = null;
      const staffQueryFilters: any[] = [];
      if (user.employeeId) {
        staffQueryFilters.push({ employeeId: user.employeeId.toUpperCase() });
        staffQueryFilters.push({ employeeId: user.employeeId });
      }
      if (user.id) {
        staffQueryFilters.push({ id: user.id });
        const stripped = user.id.replace(/^user-staff-/, '');
        if (stripped) staffQueryFilters.push({ id: stripped });
      }
      if (user.email) {
        staffQueryFilters.push({ email: user.email.toLowerCase() });
      }
      if (user.phone) {
        staffQueryFilters.push({ phone: user.phone });
      }

      if (mongoService.isConnected() && staffQueryFilters.length > 0) {
        try {
          staffDoc = await StaffModel.findOne({ $or: staffQueryFilters }).lean();
        } catch (dbErr) {
          console.warn('[Profile Update] Error querying StaffModel:', dbErr);
        }
      }

      let staffIndex = staff.findIndex(
        (s) =>
          (user.employeeId && s.employeeId && s.employeeId.toUpperCase() === user.employeeId.toUpperCase()) ||
          s.id === user.id ||
          `user-staff-${s.id}` === user.id ||
          (s.email && user.email && s.email.toLowerCase() === user.email.toLowerCase())
      );

      // If found in MongoDB but not in memory, sync to in-memory staff array
      if (staffDoc && staffIndex === -1) {
        staff.unshift(staffDoc);
        staffIndex = 0;
      }

      // ==========================================
      // A. STAFF / FACULTY UPDATE FLOW
      // ==========================================
      if (staffDoc || staffIndex !== -1 || isStaffRole) {
        const currentStaff = staffIndex !== -1 ? staff[staffIndex] : staffDoc;
        if (!currentStaff && !isAdminRole) {
          return res.status(404).json({ success: false, error: 'Staff profile record not found in Faculty & Staff directory' });
        }

        if (currentStaff) {
          const newPhoto = updates.photo || updates.avatar || updates.photoFileKey || currentStaff.photo;
          let updatedStaff: TeacherStaff;

          if (isAdminRole) {
            // SUPER_ADMIN / SCHOOL_ADMIN can edit all permitted fields
            updatedStaff = {
              ...currentStaff,
              name: updates.name !== undefined ? String(updates.name).trim() : currentStaff.name,
              phone: updates.phone !== undefined ? String(updates.phone).trim() : (updates.mobile !== undefined ? String(updates.mobile).trim() : currentStaff.phone),
              alternatePhone: updates.alternatePhone !== undefined ? String(updates.alternatePhone).trim() : currentStaff.alternatePhone,
              email: updates.email !== undefined ? String(updates.email).trim() : currentStaff.email,
              photo: newPhoto,
              photoFileKey: updates.photoFileKey || (newPhoto && !newPhoto.startsWith('http') ? newPhoto : currentStaff.photoFileKey),
              address: updates.address !== undefined ? String(updates.address).trim() : currentStaff.address,
              permanentAddress: updates.permanentAddress !== undefined ? String(updates.permanentAddress).trim() : (updates.address !== undefined ? String(updates.address).trim() : currentStaff.permanentAddress),
              currentAddress: updates.currentAddress !== undefined ? String(updates.currentAddress).trim() : currentStaff.currentAddress,
              city: updates.city !== undefined ? String(updates.city).trim() : currentStaff.city,
              permanentCity: updates.permanentCity !== undefined ? String(updates.permanentCity).trim() : (updates.city !== undefined ? String(updates.city).trim() : currentStaff.permanentCity),
              currentCity: updates.currentCity !== undefined ? String(updates.currentCity).trim() : currentStaff.currentCity,
              state: updates.state !== undefined ? String(updates.state).trim() : currentStaff.state,
              permanentState: updates.permanentState !== undefined ? String(updates.permanentState).trim() : (updates.state !== undefined ? String(updates.state).trim() : currentStaff.permanentState),
              currentState: updates.currentState !== undefined ? String(updates.currentState).trim() : currentStaff.currentState,
              pincode: updates.pincode !== undefined ? String(updates.pincode).trim() : currentStaff.pincode,
              permanentPincode: updates.permanentPincode !== undefined ? String(updates.permanentPincode).trim() : (updates.pincode !== undefined ? String(updates.pincode).trim() : currentStaff.permanentPincode),
              currentPincode: updates.currentPincode !== undefined ? String(updates.currentPincode).trim() : currentStaff.currentPincode,
              sameAsPermanentAddress: updates.sameAsPermanentAddress !== undefined ? !!updates.sameAsPermanentAddress : currentStaff.sameAsPermanentAddress,
              emergencyContact: updates.emergencyContact !== undefined ? String(updates.emergencyContact).trim() : currentStaff.emergencyContact,
              bloodGroup: updates.bloodGroup !== undefined ? String(updates.bloodGroup).trim() : currentStaff.bloodGroup,
              dob: updates.dob !== undefined ? String(updates.dob).trim() : currentStaff.dob,
              gender: updates.gender ? (String(updates.gender).trim().toUpperCase() as 'MALE' | 'FEMALE' | 'OTHER') : currentStaff.gender,
              fatherName: updates.fatherName !== undefined ? String(updates.fatherName).trim() : (updates.fatherOrMotherName !== undefined ? String(updates.fatherOrMotherName).trim() : currentStaff.fatherName),
              motherName: updates.motherName !== undefined ? String(updates.motherName).trim() : currentStaff.motherName,
              fatherOrMotherName: updates.fatherOrMotherName !== undefined ? String(updates.fatherOrMotherName).trim() : currentStaff.fatherOrMotherName,
              qualification: updates.qualification !== undefined ? String(updates.qualification).trim() : currentStaff.qualification,
              customQualification: updates.customQualification !== undefined ? String(updates.customQualification).trim() : currentStaff.customQualification,
              designation: updates.designation !== undefined ? String(updates.designation).trim() : currentStaff.designation,
              department: updates.department !== undefined ? String(updates.department).trim() : currentStaff.department,
              customDepartment: updates.customDepartment !== undefined ? String(updates.customDepartment).trim() : currentStaff.customDepartment,
              employmentType: updates.employmentType !== undefined ? String(updates.employmentType).trim() : currentStaff.employmentType,
              experienceYears: updates.experienceYears !== undefined ? Number(updates.experienceYears) : currentStaff.experienceYears,
              totalExperience: updates.totalExperience !== undefined ? String(updates.totalExperience).trim() : currentStaff.totalExperience,
              certifications: updates.certifications !== undefined ? String(updates.certifications).trim() : currentStaff.certifications,
              certificationsList: Array.isArray(updates.certificationsList) ? updates.certificationsList : currentStaff.certificationsList,
              customCertification: updates.customCertification !== undefined ? String(updates.customCertification).trim() : currentStaff.customCertification,
              subjectExpertise: Array.isArray(updates.subjectExpertise) ? updates.subjectExpertise : currentStaff.subjectExpertise,
              specializationSubjects: Array.isArray(updates.specializationSubjects) ? updates.specializationSubjects : currentStaff.specializationSubjects,
              classesQualifiedToTeach: updates.classesQualifiedToTeach !== undefined ? String(updates.classesQualifiedToTeach).trim() : currentStaff.classesQualifiedToTeach,
              qualifiedClasses: Array.isArray(updates.qualifiedClasses)
                ? updates.qualifiedClasses
                : (Array.isArray(updates.classesQualifiedToTeach)
                  ? updates.classesQualifiedToTeach
                  : (typeof updates.classesQualifiedToTeach === 'string' && updates.classesQualifiedToTeach.trim()
                    ? updates.classesQualifiedToTeach.split(',').map((s: string) => s.trim()).filter(Boolean)
                    : currentStaff.qualifiedClasses)),
              teachingProfile: updates.teachingProfile !== undefined ? updates.teachingProfile : currentStaff.teachingProfile,
              teachingWorkload: updates.teachingWorkload !== undefined ? Number(updates.teachingWorkload) : currentStaff.teachingWorkload,
              assignedClasses: Array.isArray(updates.assignedClasses) ? updates.assignedClasses : currentStaff.assignedClasses,
              assignedSubjects: Array.isArray(updates.assignedSubjects) ? updates.assignedSubjects : currentStaff.assignedSubjects,
              assignedPrimarySubject: updates.assignedPrimarySubject !== undefined ? String(updates.assignedPrimarySubject).trim() : currentStaff.assignedPrimarySubject,
              classTeacherOf: updates.classTeacherOf !== undefined ? String(updates.classTeacherOf).trim() : currentStaff.classTeacherOf,
              houseClubResponsibility: updates.houseClubResponsibility !== undefined ? String(updates.houseClubResponsibility).trim() : currentStaff.houseClubResponsibility,
              houseClubResponsibilities: Array.isArray(updates.houseClubResponsibilities) ? updates.houseClubResponsibilities : currentStaff.houseClubResponsibilities,
              customHouseClub: updates.customHouseClub !== undefined ? String(updates.customHouseClub).trim() : currentStaff.customHouseClub,
              documents: Array.isArray(updates.documents) ? updates.documents : (currentStaff.documents || []),
              bankAccountNo: updates.bankAccountNo !== undefined ? String(updates.bankAccountNo).trim() : currentStaff.bankAccountNo,
              bankName: updates.bankName !== undefined ? String(updates.bankName).trim() : currentStaff.bankName,
              bankBranch: updates.bankBranch !== undefined ? String(updates.bankBranch).trim() : currentStaff.bankBranch,
              ifscCode: updates.ifscCode !== undefined ? String(updates.ifscCode).trim() : currentStaff.ifscCode,
              panNumber: updates.panNumber !== undefined ? String(updates.panNumber).trim() : currentStaff.panNumber,
              uanNumber: updates.uanNumber !== undefined ? String(updates.uanNumber).trim() : currentStaff.uanNumber,
              salary: updates.salary !== undefined ? updates.salary : currentStaff.salary,
            };
          } else {
            // Validate the self-editable contact fields before anything is saved.
            const selfEditError = validateSelfProfileUpdate(updates);
            if (selfEditError) {
              return res.status(400).json({ success: false, error: selfEditError });
            }
            // Other roles can edit ONLY their allowed personal/contact fields:
            // email, phone, alternatePhone, address, permanentAddress, currentAddress, city, state, pincode, emergencyContact, bloodGroup, qualification, photo, documents
            // Protected fields (role, employeeId, designation, department, salary, status, login permissions) CANNOT be changed
            updatedStaff = {
              ...currentStaff,
              role: currentStaff.role || currentStaff.systemRole || currentStaff.portalRole || user.role || session.role,
              systemRole: currentStaff.systemRole || currentStaff.role || session.role,
              portalRole: currentStaff.portalRole || currentStaff.role || session.role,
              phone: updates.phone !== undefined ? String(updates.phone).trim() : (updates.mobile !== undefined ? String(updates.mobile).trim() : currentStaff.phone),
              alternatePhone: updates.alternatePhone !== undefined ? String(updates.alternatePhone).trim() : currentStaff.alternatePhone,
              email: updates.email !== undefined ? String(updates.email).trim() : currentStaff.email,
              photo: newPhoto,
              photoFileKey: updates.photoFileKey || (newPhoto && !newPhoto.startsWith('http') ? newPhoto : currentStaff.photoFileKey),
              address: updates.address !== undefined ? String(updates.address).trim() : currentStaff.address,
              permanentAddress: updates.permanentAddress !== undefined ? String(updates.permanentAddress).trim() : (updates.address !== undefined ? String(updates.address).trim() : currentStaff.permanentAddress),
              currentAddress: updates.currentAddress !== undefined ? String(updates.currentAddress).trim() : currentStaff.currentAddress,
              city: updates.city !== undefined ? String(updates.city).trim() : currentStaff.city,
              permanentCity: updates.permanentCity !== undefined ? String(updates.permanentCity).trim() : (updates.city !== undefined ? String(updates.city).trim() : currentStaff.permanentCity),
              currentCity: updates.currentCity !== undefined ? String(updates.currentCity).trim() : currentStaff.currentCity,
              state: updates.state !== undefined ? String(updates.state).trim() : currentStaff.state,
              permanentState: updates.permanentState !== undefined ? String(updates.permanentState).trim() : (updates.state !== undefined ? String(updates.state).trim() : currentStaff.permanentState),
              currentState: updates.currentState !== undefined ? String(updates.currentState).trim() : currentStaff.currentState,
              pincode: updates.pincode !== undefined ? String(updates.pincode).trim() : currentStaff.pincode,
              permanentPincode: updates.permanentPincode !== undefined ? String(updates.permanentPincode).trim() : (updates.pincode !== undefined ? String(updates.pincode).trim() : currentStaff.permanentPincode),
              currentPincode: updates.currentPincode !== undefined ? String(updates.currentPincode).trim() : currentStaff.currentPincode,
              sameAsPermanentAddress: updates.sameAsPermanentAddress !== undefined ? !!updates.sameAsPermanentAddress : currentStaff.sameAsPermanentAddress,
              emergencyContact: updates.emergencyContact !== undefined ? String(updates.emergencyContact).trim() : currentStaff.emergencyContact,
              bloodGroup: updates.bloodGroup !== undefined ? String(updates.bloodGroup).trim() : currentStaff.bloodGroup,
              fatherName: updates.fatherName !== undefined ? String(updates.fatherName).trim() : currentStaff.fatherName,
              motherName: updates.motherName !== undefined ? String(updates.motherName).trim() : currentStaff.motherName,
              qualification: updates.qualification !== undefined ? String(updates.qualification).trim() : currentStaff.qualification,
              customQualification: updates.customQualification !== undefined ? String(updates.customQualification).trim() : currentStaff.customQualification,
              // Staff may add documents, but cannot change the verification status of any document.
              documents: mergeSelfUploadedDocuments(currentStaff.documents || [], updates.documents),
            };
          }

          // Authoritative write to StaffModel in MongoDB
          if (mongoService.isConnected()) {
            const { _id, ...cleanStaffUpdate } = updatedStaff as any;
            await StaffModel.updateOne(
              {
                $or: [
                  { id: updatedStaff.id },
                  ...(updatedStaff.employeeId ? [{ employeeId: updatedStaff.employeeId.toUpperCase() }, { employeeId: updatedStaff.employeeId }] : []),
                  ...(user.id ? [{ id: user.id }] : []),
                ],
              },
              { $set: cleanStaffUpdate },
              { upsert: false }
            );

            // Also synchronize UserModel in MongoDB
            await UserModel.updateOne(
              {
                $or: [
                  { id: user.id },
                  { id: updatedStaff.id },
                  { id: `user-staff-${updatedStaff.id}` },
                  ...(updatedStaff.employeeId ? [{ employeeId: updatedStaff.employeeId.toUpperCase() }, { employeeId: updatedStaff.employeeId }] : []),
                ],
              },
              {
                $set: {
                  name: updatedStaff.name,
                  email: updatedStaff.email || '',
                  phone: updatedStaff.phone || '',
                  alternatePhone: updatedStaff.alternatePhone || '',
                  emergencyContact: updatedStaff.emergencyContact || '',
                  bloodGroup: updatedStaff.bloodGroup || '',
                  avatar: updatedStaff.photo || '',
                  address: updatedStaff.address || '',
                  permanentAddress: updatedStaff.permanentAddress || '',
                  currentAddress: updatedStaff.currentAddress || '',
                  city: updatedStaff.city || '',
                  state: updatedStaff.state || '',
                  pincode: updatedStaff.pincode || '',
                  qualification: updatedStaff.qualification || '',
                },
              }
            );
          }

          // Keep in-memory cache and local disk synchronized
          if (staffIndex !== -1) {
            staff[staffIndex] = updatedStaff;
          } else {
            staff.unshift(updatedStaff);
          }
          persistentStorage.saveStaffToDisk(staff);

          user.name = updatedStaff.name || user.name;
          user.email = updatedStaff.email || user.email;
          user.phone = updatedStaff.phone || user.phone;
          user.avatar = updatedStaff.photo || user.avatar;
          if (session.user) {
            session.user.name = user.name;
            session.user.email = user.email;
            session.user.phone = user.phone;
            session.user.avatar = user.avatar;
          }

          logAudit(user.name, user.role, 'PROFILE_UPDATE', 'TeacherStaff', updatedStaff.id, `Updated own profile fields: ${Object.keys(updates || {}).filter((k) => !['documents'].includes(k)).slice(0, 20).join(', ') || 'none'}`);
          broadcastRealtimeEvent('TEACHER', 'UPDATE', updatedStaff, { description: `Updated staff profile for ${updatedStaff.name}` });

          return res.json({
            success: true,
            user,
            profile: updatedStaff,
            message: 'Profile updated successfully in database',
          });
        }
      }

      // ==========================================
      // B. STUDENT UPDATE FLOW
      // ==========================================
      if (session.role === 'STUDENT') {
        const studentIndex = students.findIndex((s) => s.id === user.studentId || s.id === user.id);
        if (studentIndex === -1) {
          return res.status(404).json({ success: false, error: 'Student record not found' });
        }

        const currentStudent = students[studentIndex];
        const studentMobile = updates.mobile !== undefined ? String(updates.mobile).trim() : (updates.phone !== undefined ? String(updates.phone).trim() : currentStudent.mobile);
        const newPhoto = updates.photo || updates.avatar || currentStudent.photo;
        const updatedStudent: Student = {
          ...currentStudent,
          mobile: studentMobile,
          email: updates.email !== undefined ? String(updates.email).trim() : currentStudent.email,
          bloodGroup: updates.bloodGroup !== undefined ? updates.bloodGroup : currentStudent.bloodGroup,
          address: updates.address !== undefined ? updates.address : currentStudent.address,
          emergencyContact: updates.emergencyContact !== undefined ? updates.emergencyContact : currentStudent.emergencyContact,
          photo: newPhoto,
          photoFileKey: updates.photoFileKey || (newPhoto && !newPhoto.startsWith('http') ? newPhoto : currentStudent.photoFileKey),
        };

        students[studentIndex] = updatedStudent;
        persistentStorage.saveStudentsToDisk(students);
        if (mongoService.isConnected()) {
          await mongoService.updateStudent(updatedStudent.id, updatedStudent);
          await UserModel.updateOne(
            { id: user.id },
            {
              $set: {
                email: updatedStudent.email || '',
                phone: updatedStudent.mobile || '',
                avatar: updatedStudent.photo,
                address: updatedStudent.address || '',
              },
            }
          );
        }

        user.email = updatedStudent.email || user.email;
        user.phone = updatedStudent.mobile || user.phone;
        user.avatar = updatedStudent.photo || user.avatar;
        if (session.user) {
          session.user.email = user.email;
          session.user.phone = user.phone;
          session.user.avatar = user.avatar;
        }

        logAudit(user.name, user.role, 'PROFILE_UPDATE', 'Student', updatedStudent.id, 'Updated student personal profile');
        broadcastRealtimeEvent('STUDENT', 'UPDATE', updatedStudent, {
          studentId: updatedStudent.id,
          classId: updatedStudent.classId,
          section: updatedStudent.section,
          description: `Updated student profile for ${updatedStudent.name}`,
        });

        return res.json({ success: true, user, profile: updatedStudent, message: 'Student profile updated successfully in database' });
      }

      // ==========================================
      // C. PURE ADMINISTRATOR UPDATE FLOW (No Staff record)
      // ==========================================
      if (isAdminRole) {
        const adminIndex = adminAccounts.findIndex((a) => a.id === user.id || a.username.toLowerCase() === user.username.toLowerCase());
        const currentAdmin = adminIndex !== -1 ? adminAccounts[adminIndex] : null;

        const newName = updates.name !== undefined ? String(updates.name).trim() : user.name;
        const newEmail = updates.email !== undefined ? String(updates.email).trim() : user.email;
        const newPhone = updates.phone !== undefined ? String(updates.phone).trim() : user.phone;
        const newAddress = updates.address !== undefined ? String(updates.address).trim() : (updates.permanentAddress !== undefined ? String(updates.permanentAddress).trim() : (currentAdmin?.address || ''));
        const newAvatar = updates.avatar || updates.photo || updates.photoFileKey || user.avatar;

        const adminUpdatesPayload: Record<string, any> = {
          name: newName,
          email: newEmail,
          phone: newPhone,
          avatar: newAvatar,
          address: newAddress,
          permanentAddress: updates.permanentAddress !== undefined ? String(updates.permanentAddress).trim() : newAddress,
          currentAddress: updates.currentAddress !== undefined ? String(updates.currentAddress).trim() : newAddress,
          city: updates.city !== undefined ? String(updates.city).trim() : ((currentAdmin as any)?.city || 'Sheohar'),
          permanentCity: updates.permanentCity !== undefined ? String(updates.permanentCity).trim() : (updates.city !== undefined ? String(updates.city).trim() : 'Sheohar'),
          currentCity: updates.currentCity !== undefined ? String(updates.currentCity).trim() : (updates.city !== undefined ? String(updates.city).trim() : 'Sheohar'),
          state: updates.state !== undefined ? String(updates.state).trim() : ((currentAdmin as any)?.state || 'Bihar'),
          permanentState: updates.permanentState !== undefined ? String(updates.permanentState).trim() : (updates.state !== undefined ? String(updates.state).trim() : 'Bihar'),
          currentState: updates.currentState !== undefined ? String(updates.currentState).trim() : (updates.state !== undefined ? String(updates.state).trim() : 'Bihar'),
          pincode: updates.pincode !== undefined ? String(updates.pincode).trim() : ((currentAdmin as any)?.pincode || '843329'),
          permanentPincode: updates.permanentPincode !== undefined ? String(updates.permanentPincode).trim() : (updates.pincode !== undefined ? String(updates.pincode).trim() : '843329'),
          currentPincode: updates.currentPincode !== undefined ? String(updates.currentPincode).trim() : (updates.pincode !== undefined ? String(updates.pincode).trim() : '843329'),
          sameAsPermanentAddress: updates.sameAsPermanentAddress !== undefined ? !!updates.sameAsPermanentAddress : true,
          alternatePhone: updates.alternatePhone !== undefined ? String(updates.alternatePhone).trim() : '',
          emergencyContact: updates.emergencyContact !== undefined ? String(updates.emergencyContact).trim() : '',
          bloodGroup: updates.bloodGroup !== undefined ? String(updates.bloodGroup).trim() : '',
          dob: updates.dob !== undefined ? String(updates.dob).trim() : '',
          gender: updates.gender !== undefined ? String(updates.gender).trim() : 'MALE',
          fatherName: updates.fatherName !== undefined ? String(updates.fatherName).trim() : (updates.fatherOrMotherName !== undefined ? String(updates.fatherOrMotherName).trim() : ''),
          fatherOrMotherName: updates.fatherOrMotherName !== undefined ? String(updates.fatherOrMotherName).trim() : '',
          qualification: updates.qualification !== undefined ? String(updates.qualification).trim() : 'Post Graduate / Institutional Administration',
          customQualification: updates.customQualification !== undefined ? String(updates.customQualification).trim() : '',
          designation: updates.designation !== undefined ? String(updates.designation).trim() : (session.role === 'SUPER_ADMIN' ? 'Super Administrator' : 'School Administrator'),
          department: updates.department !== undefined ? String(updates.department).trim() : 'Executive Administration & Management',
          customDepartment: updates.customDepartment !== undefined ? String(updates.customDepartment).trim() : '',
          employmentType: updates.employmentType !== undefined ? String(updates.employmentType).trim() : 'Permanent / Full Time',
          totalExperience: updates.totalExperience !== undefined ? String(updates.totalExperience).trim() : '',
          experienceYears: updates.experienceYears !== undefined ? Number(updates.experienceYears) : 10,
          teachingWorkload: updates.teachingWorkload !== undefined ? Number(updates.teachingWorkload) : 0,
          classTeacherOf: updates.classTeacherOf !== undefined ? String(updates.classTeacherOf).trim() : '',
          assignedPrimarySubject: updates.assignedPrimarySubject !== undefined ? String(updates.assignedPrimarySubject).trim() : '',
          houseClubResponsibility: updates.houseClubResponsibility !== undefined ? String(updates.houseClubResponsibility).trim() : '',
          certifications: updates.certifications !== undefined ? String(updates.certifications).trim() : '',
          documents: Array.isArray(updates.documents) ? updates.documents : [],
          bankAccountNo: updates.bankAccountNo !== undefined ? String(updates.bankAccountNo).trim() : '',
          bankName: updates.bankName !== undefined ? String(updates.bankName).trim() : '',
          bankBranch: updates.bankBranch !== undefined ? String(updates.bankBranch).trim() : '',
          ifscCode: updates.ifscCode !== undefined ? String(updates.ifscCode).trim() : '',
          panNumber: updates.panNumber !== undefined ? String(updates.panNumber).trim() : '',
          uanNumber: updates.uanNumber !== undefined ? String(updates.uanNumber).trim() : '',
        };

        if (currentAdmin) {
          Object.assign(currentAdmin, adminUpdatesPayload);
          persistentStorage.saveAdminAccountsToDisk(adminAccounts);
        }

        if (mongoService.isConnected()) {
          await UserModel.updateOne(
            { $or: [{ id: user.id }, { username: user.username.toLowerCase() }] },
            { $set: adminUpdatesPayload },
            { upsert: false }
          );
        }

        user.name = newName;
        user.email = newEmail;
        user.phone = newPhone;
        user.avatar = newAvatar;
        (user as any).address = newAddress;
        if (session.user) {
          session.user.name = user.name;
          session.user.email = user.email;
          session.user.phone = user.phone;
          session.user.avatar = user.avatar;
          (session.user as any).address = newAddress;
        }

        const freshAdminProfile = {
          id: user.id,
          employeeId: user.employeeId || 'ADMIN-01',
          name: newName,
          username: user.username,
          email: newEmail,
          phone: newPhone,
          role: session.role,
          systemRole: session.role,
          portalRole: session.role,
          status: 'ACTIVE',
          accountStatus: 'ACTIVE',
          loginEnabled: true,
          photo: newAvatar,
          ...adminUpdatesPayload,
        };

        logAudit(user.name, user.role, 'PROFILE_UPDATE', 'AdminAccount', user.id, `Updated ${user.role} profile in database`);
        return res.json({
          success: true,
          user,
          profile: freshAdminProfile,
          message: `${user.role === 'SUPER_ADMIN' ? 'Super Admin' : 'School Admin'} profile updated successfully in database`,
        });
      }

      // ==========================================
      // D. PARENT UPDATE FLOW
      // ==========================================
      if (session.role === 'PARENT') {
        const cleanPhone = normalizePhone(user.phone || updates.phone || '');
        const currentParent = parentAccounts.get(cleanPhone) || null;

        const newEmail = updates.email !== undefined ? String(updates.email).trim() : (user.email || '');
        const newPhone = updates.phone !== undefined ? normalizePhone(String(updates.phone).trim()) : cleanPhone;
        const newAlternatePhone = updates.alternatePhone !== undefined ? String(updates.alternatePhone).trim() : (updates.secondaryPhone || '');
        const newEmergencyContact = updates.emergencyContact !== undefined ? String(updates.emergencyContact).trim() : '';
        const newAddress = updates.address !== undefined ? String(updates.address).trim() : (updates.permanentAddress !== undefined ? String(updates.permanentAddress).trim() : ((user as any).address || ''));
        const newCity = updates.city !== undefined ? String(updates.city).trim() : ((user as any).city || 'Sheohar');
        const newState = updates.state !== undefined ? String(updates.state).trim() : ((user as any).state || 'Bihar');
        const newPincode = updates.pincode !== undefined ? String(updates.pincode).trim() : ((user as any).pincode || '843329');
        const newOccupation = updates.occupation !== undefined ? String(updates.occupation).trim() : ((user as any).occupation || '');
        const newAvatar = updates.avatar || updates.photo || updates.photoFileKey || user.avatar;

        const parentUpdatesPayload: Record<string, any> = {
          email: newEmail,
          phone: newPhone,
          alternatePhone: newAlternatePhone,
          emergencyContact: newEmergencyContact,
          address: newAddress,
          permanentAddress: newAddress,
          currentAddress: newAddress,
          city: newCity,
          state: newState,
          pincode: newPincode,
          occupation: newOccupation,
          avatar: newAvatar,
        };

        // Note: Protected institutional fields (id, role, userType, username, status, accountStatus, loginEnabled, linkedStudentIds, activeStudentId) are kept immutable

        if (mongoService.isConnected()) {
          await UserModel.updateOne(
            {
              $or: [
                { id: user.id },
                { phone: cleanPhone },
                { username: cleanPhone },
                { id: `parent-${cleanPhone}` },
              ],
              userType: 'PARENT',
            },
            { $set: parentUpdatesPayload },
            { upsert: true }
          );

          // Synchronize contact info to linked students in MongoDB
          if (session.linkedStudentIds && session.linkedStudentIds.length > 0) {
            await StudentModel.updateMany(
              { id: { $in: session.linkedStudentIds } },
              {
                $set: {
                  parentPhone: newPhone,
                  parentEmail: newEmail,
                  parentOccupation: newOccupation,
                  address: newAddress,
                },
              }
            );
          }
        }

        // Update in-memory parent account
        if (currentParent) {
          currentParent.email = newEmail;
          currentParent.phone = newPhone;
          if (newAvatar) (currentParent as any).avatar = newAvatar;
          persistentStorage.saveParentAccountsToDisk(Array.from(parentAccounts.values()));
        }

        // Update in-memory students linked to this parent
        students.forEach((s) => {
          if (session.linkedStudentIds?.includes(s.id) || normalizePhone(s.parentPhone) === cleanPhone) {
            s.parentPhone = newPhone;
            if (newEmail) s.parentEmail = newEmail;
            if (newOccupation) s.parentOccupation = newOccupation;
            if (newAddress) s.address = newAddress;
          }
        });

        user.email = newEmail;
        user.phone = newPhone;
        user.avatar = newAvatar;
        (user as any).address = newAddress;
        (user as any).city = newCity;
        (user as any).state = newState;
        (user as any).pincode = newPincode;
        (user as any).occupation = newOccupation;

        if (session.user) {
          session.user.email = newEmail;
          session.user.phone = newPhone;
          session.user.avatar = newAvatar;
          (session.user as any).address = newAddress;
          (session.user as any).city = newCity;
          (session.user as any).state = newState;
          (session.user as any).pincode = newPincode;
          (session.user as any).occupation = newOccupation;
        }

        const freshParentProfile = {
          id: user.id,
          name: user.name,
          username: user.username || user.phone,
          role: 'PARENT',
          systemRole: 'PARENT',
          portalRole: 'PARENT',
          status: 'ACTIVE',
          accountStatus: 'ACTIVE',
          loginEnabled: true,
          ...parentUpdatesPayload,
          linkedStudentIds: session.linkedStudentIds || [],
          activeStudentId: session.activeStudentId || '',
        };

        logAudit(user.name, 'PARENT', 'PROFILE_UPDATE', 'ParentAccount', user.id, 'Updated parent contact details in database');
        return res.json({
          success: true,
          user,
          profile: freshParentProfile,
          message: 'Parent contact profile updated successfully in database',
        });
      }

      // Default fallback
      return res.status(400).json({ success: false, error: 'Unrecognized user account profile type for update.' });
    } catch (err: any) {
      console.error('[Profile] Error updating profile:', err);
      res.status(500).json({ success: false, error: err.message || 'Failed to update profile in database' });
    }
  });

  // Auth: Forgot Password Request (Generate Secure Reset Link via Email - NO OTP)
  const forgotPasswordRateLimits = new Map<string, { count: number; firstAttempt: number }>();
  // At most 20 reset requests per IP per hour, whatever the account typed.
  const forgotPasswordIpLimiter = new AttemptLimiter(20, 60 * 60 * 1000);
  // Wrong current-password attempts on change-password: 5 per 15 minutes per account.
  const changePasswordLimiter = new AttemptLimiter(5, 15 * 60 * 1000);
  // Reset-token submissions per IP (guessing protection): 30 per 15 minutes.
  const resetPasswordIpLimiter = new AttemptLimiter(30, 15 * 60 * 1000);
  const inFlightPasswordResets = new Set<string>();

  app.post('/api/auth/forgot-password', async (req: Request, res: Response) => {
    const rawInput = (req.body.email || req.body.identifier || req.body.username || req.body.emailOrUsername || '').trim();
    if (!rawInput) {
      return res.status(400).json({ success: false, error: 'Please enter your registered email address or account username.' });
    }

    const cleanInput = rawInput.toLowerCase();
    const isEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(cleanInput);

    // Prevent duplicate in-flight requests while one email is actively being sent (Requirement 10)
    if (inFlightPasswordResets.has(cleanInput)) {
      return res.status(429).json({
        success: false,
        error: 'A password reset email is already being sent for this account. Please wait a moment and check your inbox.',
      });
    }

    const clientIp = String((req.headers['x-forwarded-for'] as string) || req.socket.remoteAddress || 'ip').split(',')[0].trim();
    const rateLimitKey = `${clientIp}_${cleanInput}`;
    const ipWait = forgotPasswordIpLimiter.blockedFor(clientIp);
    if (ipWait > 0) {
      return res.status(429).json({ success: false, error: `Too many requests. Please try again in ${Math.ceil(ipWait / 60)} minute(s).` });
    }
    forgotPasswordIpLimiter.hit(clientIp);
    const now = Date.now();
    const existingLimit = forgotPasswordRateLimits.get(rateLimitKey);

    if (existingLimit) {
      if (now - existingLimit.firstAttempt < 15 * 60 * 1000) {
        if (existingLimit.count >= 5) {
          return res.status(429).json({
            success: false,
            error: 'Too many password reset requests. Please wait 15 minutes before trying again.',
          });
        }
        existingLimit.count += 1;
      } else {
        forgotPasswordRateLimits.set(rateLimitKey, { count: 1, firstAttempt: now });
      }
    } else {
      forgotPasswordRateLimits.set(rateLimitKey, { count: 1, firstAttempt: now });
    }

    inFlightPasswordResets.add(cleanInput);

    try {
      let matchedUserDocs: any[] = [];
      let matchedStudentDoc: any = null;
      let match: AuthEntityMatch | null = null;

      // 1. Authoritative check in MongoDB Atlas UserModel first (Requirement 7)
      if (mongoose.connection && mongoose.connection.readyState === 1) {
        try {
          const uFilters: any[] = [
            { email: cleanInput },
            { username: cleanInput },
            { id: cleanInput },
            { employeeId: cleanInput.toUpperCase() },
            { employeeId: cleanInput },
          ];
          const cleanPhone = normalizePhone(cleanInput);
          if (cleanPhone && cleanPhone.length >= 10) {
            uFilters.push({ phone: cleanPhone });
          }
          matchedUserDocs = await UserModel.find({ $or: uFilters }).lean();

          if (!matchedUserDocs || matchedUserDocs.length === 0) {
            const stuFilters: any[] = [
              { email: cleanInput },
              { admissionNumber: cleanInput.toUpperCase() },
              { registrationNumber: cleanInput.toUpperCase() },
              { id: cleanInput },
            ];
            if (cleanPhone && cleanPhone.length >= 10) {
              stuFilters.push({ mobile: cleanPhone });
              stuFilters.push({ parentPhone: cleanPhone });
            }
            matchedStudentDoc = await StudentModel.findOne({ $or: stuFilters }).lean();
          }
        } catch (dbErr: any) {
          console.warn('[ForgotPassword] Notice querying MongoDB Atlas:', dbErr?.message);
        }
      }

      if (matchedUserDocs && matchedUserDocs.length > 0) {
        const primary = matchedUserDocs[0];
        if (primary.userType === 'ADMIN') {
          let adm = adminAccounts.find((a) => a.id === primary.id || a.username?.toLowerCase() === (primary.username || '').toLowerCase());
          if (!adm) {
            adm = { ...primary, role: primary.role } as any;
            adminAccounts.push(adm);
          }
          match = { type: 'ADMIN', entity: adm, role: primary.role as UserRole };
        } else if (primary.userType === 'STAFF') {
          let st = staff.find((s) => s.id === primary.id || (primary.employeeId && s.employeeId?.toUpperCase() === primary.employeeId.toUpperCase()));
          if (!st) {
            st = { ...primary, role: primary.role } as any;
            staff.push(st as any);
          }
          match = { type: 'STAFF', entity: st as any, role: (primary.role || 'TEACHER') as UserRole };
        } else if (primary.userType === 'PARENT') {
          syncParentAccounts();
          const p = primary.phone ? parentAccounts.get(normalizePhone(primary.phone)) : null;
          match = { type: 'PARENT', entity: p || primary, role: 'PARENT' };
        } else {
          match = { type: 'STAFF', entity: primary, role: (primary.role || 'TEACHER') as UserRole };
        }
      } else if (matchedStudentDoc) {
        let memStu = students.find((s) => s.id === matchedStudentDoc.id || s.admissionNumber === matchedStudentDoc.admissionNumber);
        if (!memStu) {
          memStu = matchedStudentDoc as any;
          students.push(memStu as any);
        }
        match = { type: 'STUDENT', entity: memStu as any, role: 'STUDENT' };
      }

      // 2. Fallback to in-memory lookup if not matched via MongoDB Atlas
      if (!match) {
        match = findAuthEntityByEmail(cleanInput) || findAuthEntityByIdentifier(cleanInput);
      }

      if (!match) {
        // Same answer whether or not the account exists, so the form cannot be used to discover accounts.
        console.log('[Server] Password reset requested for unknown identifier (answer concealed).');
        return res.json({ success: true, message: 'If an account matches these details, a password reset link has been sent to its registered email. If you do not receive it, contact the school office.' });
      }

      const entity = match.entity as any;

      // Determine target recipient email address
      let targetEmail: string | undefined;
      if (isEmail) {
        targetEmail = cleanInput;
      } else {
        targetEmail = entity.email || (matchedUserDocs[0]?.email) || entity.parentEmail || entity.fatherEmail;
      }

      // Requirement 5: Do not expose whether an account has a registered email
      if (!targetEmail || !targetEmail.includes('@')) {
        console.log(`[Server] Password reset requested for account without valid email (concealing account presence for security)`);
        return res.json({
          success: true,
          message: 'If an account matches these details, a password reset link has been sent to its registered email. If you do not receive it, contact the school office.',
        });
      }

      // Generate cryptographically secure, single-use, time-limited token (Requirement 5 & 11)
      const resetToken = crypto.randomBytes(32).toString('hex');
      const tokenHash = crypto.createHash('sha256').update(resetToken).digest('hex');
      const expiresAtMs = Date.now() + 15 * 60 * 1000; // 15 mins expiry
      const expiresAtDate = new Date(expiresAtMs);

      entity.passwordResetToken = tokenHash;
      entity.passwordResetTokenHash = tokenHash;
      entity.passwordResetExpires = expiresAtMs;
      entity.passwordResetEmail = targetEmail;
      delete entity.passwordResetLinkToken;
      delete entity.passwordResetOtp;

      // 1. Authoritative persistence directly to MongoDB Atlas via Mongoose (AWAITED) (Requirements 1, 5, 7)
      if (mongoose.connection && mongoose.connection.readyState === 1) {
        try {
          if (matchedUserDocs.length > 0) {
            await UserModel.updateMany(
              { _id: { $in: matchedUserDocs.map((u: any) => u._id) } },
              {
                $set: {
                  passwordResetToken: tokenHash,
                  passwordResetTokenHash: tokenHash,
                  passwordResetExpires: expiresAtDate,
                },
              }
            );

            for (const u of matchedUserDocs) {
              if (u.userType === 'STAFF') {
                await StaffModel.updateMany(
                  { $or: [{ id: u.id }, ...(u.employeeId ? [{ employeeId: u.employeeId }] : [])] },
                  {
                    $set: {
                      passwordResetToken: tokenHash,
                      passwordResetTokenHash: tokenHash,
                      passwordResetExpires: expiresAtDate,
                    },
                  }
                ).catch(() => {});
              }
            }
          } else if (matchedStudentDoc) {
            await StudentModel.updateOne(
              { _id: matchedStudentDoc._id },
              {
                $set: {
                  passwordResetToken: tokenHash,
                  passwordResetTokenHash: tokenHash,
                  passwordResetExpires: expiresAtDate,
                },
              }
            );
          } else {
            // General Mongoose fallback matching by exact entity id / username
            const fallbackFilters: any[] = [];
            if (entity.id) {
              fallbackFilters.push({ id: entity.id });
              fallbackFilters.push({ id: `user-staff-${entity.id}` });
              fallbackFilters.push({ id: `user-admin-${entity.id}` });
            }
            if (entity.username) fallbackFilters.push({ username: entity.username.toLowerCase() });
            if (entity.employeeId) fallbackFilters.push({ employeeId: entity.employeeId.toUpperCase() }, { employeeId: entity.employeeId });

            if (fallbackFilters.length > 0) {
              await UserModel.updateMany(
                { $or: fallbackFilters },
                {
                  $set: {
                    passwordResetToken: tokenHash,
                    passwordResetTokenHash: tokenHash,
                    passwordResetExpires: expiresAtDate,
                  },
                }
              ).catch(() => {});
            }
          }
        } catch (dbErr: any) {
          console.warn('[ForgotPassword] Notice updating MongoDB with reset token:', dbErr?.message);
        }
      }

      // Persist token to disk and native mongoService
      if (match.type === 'STAFF') {
        persistentStorage.saveStaffToDisk(staff);
        if (mongoService.isConnected()) {
          await mongoService.updateStaff(entity.id, {
            passwordResetToken: tokenHash,
            passwordResetTokenHash: tokenHash,
            passwordResetExpires: expiresAtMs,
          }).catch(() => {});
        }
      } else if (match.type === 'STUDENT') {
        persistentStorage.saveStudentsToDisk(students);
        if (mongoService.isConnected()) {
          await mongoService.updateStudent(entity.id, {
            passwordResetToken: tokenHash,
            passwordResetTokenHash: tokenHash,
            passwordResetExpires: expiresAtMs,
          }).catch(() => {});
        }
      } else if (match.type === 'PARENT') {
        persistentStorage.saveParentAccountsToDisk(Array.from(parentAccounts.values()));
      } else if (match.type === 'ADMIN') {
        await persistentStorage.saveAdminAccounts(adminAccounts).catch(() => {});
      }

      // Determine production portal URL - matches caller's active deployed environment (Requirement 11)
      const portalBaseUrl = resolveProductionFrontendUrl(req);
      const resetUrl = `${portalBaseUrl}/reset-password?token=${resetToken}`;
      const userName = entity.name || entity.parentName || entity.username || 'User';

      console.log(`[Server] [PASSWORD RESET DISPATCH] Sending reset email to ${targetEmail} for user ${userName} (Portal: ${portalBaseUrl})`);

      let emailRes: any = { success: false, error: 'Email service uninitialized' };
      try {
        emailRes = await emailService.sendPasswordResetEmail({
          to: targetEmail,
          userName,
          resetUrl,
          schoolName: schoolSettings.schoolName || 'CHANAKYA PUBLIC SCHOOL & COACHING CENTRE',
          expiresInMinutes: 15,
        });
      } catch (sendErr: any) {
        console.error(`[Server] Email dispatch error to ${targetEmail}:`, sendErr?.message || sendErr);
        emailRes = { success: false, error: sendErr?.message || 'Email delivery failed' };
      }

      if (emailRes.success) {
        logAudit(
          userName,
          match.role,
          'PASSWORD_RESET_LINK_SENT',
          match.type,
          entity.id,
          `Password reset link delivered to ${targetEmail} via Brevo (Message ID: ${emailRes.messageId || 'N/A'})`
        );
        console.log(`[Server] [PASSWORD RESET SUCCESS] Email successfully delivered to ${targetEmail} for user ${userName} via Brevo (Message ID: ${emailRes.messageId})`);

        return res.json({
          success: true,
          message: 'If an account matches these details, a password reset link has been sent to its registered email. If you do not receive it, contact the school office.',
        });
      }

      // If Brevo rejected the request, return failure instead of showing false success (Requirement 6)
      console.error(
        `[Server] [EMAIL DELIVERY FAILURE] Failed to deliver password reset email to ${targetEmail} for user ${userName}:`,
        {
          provider: emailRes.provider,
          error: emailRes.error,
        }
      );
      // The link itself is never logged: it carries a live reset token.

      logAudit(
        userName,
        match.role,
        'PASSWORD_RESET_LINK_FAILED',
        match.type,
        entity.id,
        `Password reset link failed for ${targetEmail}. Brevo error: ${emailRes.error || 'Failed'}. Reset token valid for 15m.`
      );

      // The failure is logged for the school; the requester gets the same answer as always.
      return res.json({ success: true, message: 'If an account matches these details, a password reset link has been sent to its registered email. If you do not receive it, contact the school office.' });
    } finally {
      inFlightPasswordResets.delete(cleanInput);
    }
  });

  // Auth: Verify Reset Token (Accepts GET query and POST body)
  app.all('/api/auth/verify-reset-token', async (req: Request, res: Response) => {
    const rawToken = req.query.token || req.body?.token;
    const cleanToken = String(rawToken || '').trim();

    if (!cleanToken) {
      return res.status(400).json({ valid: false, error: 'This password reset link is invalid or has expired. Please request a new reset link.' });
    }

    const resolved = await findAuthEntityByResetTokenAsync(cleanToken);
    if (!resolved) {
      return res.status(400).json({ valid: false, error: 'This password reset link is invalid or has expired. Please request a new reset link.' });
    }

    const { match, userDoc, studentDoc } = resolved;
    const entity = match.entity as any;

    const expiryTime = userDoc?.passwordResetExpires
      ? new Date(userDoc.passwordResetExpires).getTime()
      : studentDoc?.passwordResetExpires
      ? new Date(studentDoc.passwordResetExpires).getTime()
      : entity.passwordResetExpires;

    if (!expiryTime || Date.now() > expiryTime) {
      if (mongoose.connection && mongoose.connection.readyState === 1) {
        if (userDoc?._id) {
          await UserModel.updateOne(
            { _id: userDoc._id },
            { $unset: { passwordResetToken: 1, passwordResetTokenHash: 1, passwordResetExpires: 1 } }
          ).catch(() => {});
        }
        if (studentDoc?._id) {
          await StudentModel.updateOne(
            { _id: studentDoc._id },
            { $unset: { passwordResetToken: 1, passwordResetTokenHash: 1, passwordResetExpires: 1 } }
          ).catch(() => {});
        }
      }
      entity.passwordResetToken = undefined;
      entity.passwordResetTokenHash = undefined;
      entity.passwordResetExpires = undefined;
      return res.status(400).json({ valid: false, error: 'This password reset link is invalid or has expired. Please request a new reset link.' });
    }

    res.json({
      valid: true,
      userName: entity.name || userDoc?.name || entity.parentName || entity.username || 'User',
      role: match.role,
    });
  });

  // Auth: Reset Password with Token (NO OTP)
  app.post('/api/auth/reset-password', async (req: Request, res: Response) => {
    const { token, newPassword } = req.body;
    const cleanToken = String(token || '').trim();
    const cleanPassword = String(newPassword || '').trim();

    if (!cleanToken || !cleanPassword) {
      return res.status(400).json({ success: false, error: 'Reset token and new password are required.' });
    }

    const resetIp = String((req.headers['x-forwarded-for'] as string) || req.socket.remoteAddress || 'ip').split(',')[0].trim();
    if (resetPasswordIpLimiter.blockedFor(resetIp) > 0) {
      return res.status(429).json({ success: false, error: 'Too many attempts. Please wait a few minutes and try again.' });
    }
    resetPasswordIpLimiter.hit(resetIp);

    const resetPolicyError = validateNewPassword(String(newPassword || ''));
    if (resetPolicyError) {
      return res.status(400).json({ success: false, error: resetPolicyError });
    }

    // Authoritative lookup via MongoDB Atlas and in-memory
    const resolved = await findAuthEntityByResetTokenAsync(cleanToken);
    if (!resolved) {
      return res.status(400).json({
        success: false,
        error: 'This password reset link is invalid or has expired. Please request a new reset link.',
      });
    }

    const { match, userDoc, studentDoc } = resolved;
    const entity = match.entity as any;

    const expiryTime = userDoc?.passwordResetExpires
      ? new Date(userDoc.passwordResetExpires).getTime()
      : studentDoc?.passwordResetExpires
      ? new Date(studentDoc.passwordResetExpires).getTime()
      : entity.passwordResetExpires;

    if (!expiryTime || Date.now() > expiryTime) {
      if (mongoose.connection && mongoose.connection.readyState === 1) {
        if (userDoc?._id) {
          await UserModel.updateOne(
            { _id: userDoc._id },
            { $unset: { passwordResetToken: 1, passwordResetTokenHash: 1, passwordResetExpires: 1 } }
          ).catch(() => {});
        }
        if (studentDoc?._id) {
          await StudentModel.updateOne(
            { _id: studentDoc._id },
            { $unset: { passwordResetToken: 1, passwordResetTokenHash: 1, passwordResetExpires: 1 } }
          ).catch(() => {});
        }
      }
      entity.passwordResetToken = undefined;
      entity.passwordResetTokenHash = undefined;
      entity.passwordResetExpires = undefined;
      return res.status(400).json({
        success: false,
        error: 'This password reset link is invalid or has expired. Please request a new reset link.',
      });
    }

    // 1. Compute authoritative bcrypt hash (Requirement 1 & 8)
    const newPasswordHash = bcrypt.hashSync(cleanPassword, 10);
    const tokenHash = crypto.createHash('sha256').update(cleanToken).digest('hex');

    // 2. CRITICAL: Persist directly and authoritatively to MongoDB Atlas (AWAITED) (Requirements 1, 5, 7)
    let matchedUserDocs: any[] = [];
    let matchedStudentDocs: any[] = [];

    if (mongoose.connection && mongoose.connection.readyState === 1) {
      matchedUserDocs = await UserModel.find({
        $or: [
          { passwordResetToken: tokenHash },
          { passwordResetToken: cleanToken },
          { passwordResetTokenHash: tokenHash },
          { passwordResetTokenHash: cleanToken },
          ...(userDoc?._id ? [{ _id: userDoc._id }] : []),
          ...(entity.id ? [{ id: entity.id }, { id: `user-staff-${entity.id}` }, { id: `user-admin-${entity.id}` }] : []),
        ],
      }).lean();

      matchedStudentDocs = await StudentModel.find({
        $or: [
          { passwordResetToken: tokenHash },
          { passwordResetToken: cleanToken },
          { passwordResetTokenHash: tokenHash },
          { passwordResetTokenHash: cleanToken },
          ...(studentDoc?._id ? [{ _id: studentDoc._id }] : []),
          ...(match.type === 'STUDENT' && entity.id ? [{ id: entity.id }] : []),
        ],
      }).lean();

      if (matchedUserDocs.length > 0) {
        const targetUserIds = matchedUserDocs.map((u: any) => u._id);
        const updateResult = await UserModel.updateMany(
          { _id: { $in: targetUserIds } },
          {
            $set: {
              passwordHash: newPasswordHash,
              failedLoginAttempts: 0,
              lockoutUntil: null,
              updatedAt: new Date(),
            },
            $unset: {
              passwordResetToken: 1,
              passwordResetTokenHash: 1,
              passwordResetExpires: 1,
              passwordResetLinkToken: 1,
              passwordResetOtp: 1,
            },
          }
        );
        console.log(`[ResetPassword] Updated ${updateResult.modifiedCount} UserModel record(s) in MongoDB Atlas with new bcrypt hash.`);

        // Also update StaffModel for any staff accounts
        for (const u of matchedUserDocs) {
          if (u.userType === 'STAFF') {
            await StaffModel.updateMany(
              {
                $or: [
                  { id: u.id },
                  ...(u.employeeId ? [{ employeeId: u.employeeId.toUpperCase() }, { employeeId: u.employeeId }] : []),
                ],
              },
              {
                $set: {
                  passwordHash: newPasswordHash,
                  failedLoginAttempts: 0,
                  lockoutUntil: null,
                  updatedAt: new Date().toISOString(),
                },
                $unset: {
                  passwordResetToken: 1,
                  passwordResetTokenHash: 1,
                  passwordResetExpires: 1,
                },
              }
            ).catch(() => {});
          }
        }
      }

      if (matchedStudentDocs.length > 0) {
        const targetStudentIds = matchedStudentDocs.map((s: any) => s._id);
        await StudentModel.updateMany(
          { _id: { $in: targetStudentIds } },
          {
            $set: {
              passwordHash: newPasswordHash,
              failedLoginAttempts: 0,
              lockoutUntil: null,
              updatedAt: new Date().toISOString(),
            },
            $unset: {
              passwordResetToken: 1,
              passwordResetTokenHash: 1,
              passwordResetExpires: 1,
            },
          }
        ).catch(() => {});
      }
    }

    // 3. Invalidate reset token immediately (single-use enforcement) (Requirement 11)
    entity.passwordHash = newPasswordHash;
    entity.passwordResetToken = undefined;
    entity.passwordResetTokenHash = undefined;
    entity.passwordResetExpires = undefined;
    delete entity.passwordResetLinkToken;
    delete entity.passwordResetOtp;
    entity.failedLoginAttempts = 0;
    entity.lockoutUntil = undefined;

    // 4. Update runtime in-memory stores & disk backups (Requirement 6)
    for (const u of matchedUserDocs) {
      if (u.userType === 'STAFF') {
        const staffIdx = staff.findIndex(
          (s) => s.id === u.id || (u.employeeId && s.employeeId?.toUpperCase() === u.employeeId.toUpperCase())
        );
        if (staffIdx !== -1) {
          staff[staffIdx].passwordHash = newPasswordHash;
          staff[staffIdx].failedLoginAttempts = 0;
          delete (staff[staffIdx] as any).passwordResetToken;
          delete (staff[staffIdx] as any).passwordResetTokenHash;
          delete (staff[staffIdx] as any).passwordResetExpires;
          staff[staffIdx].lockoutUntil = undefined;
        }
      } else if (u.userType === 'ADMIN') {
        const adminIdx = adminAccounts.findIndex(
          (a) => a.id === u.id || a.username?.toLowerCase() === (u.username || '').toLowerCase()
        );
        if (adminIdx !== -1) {
          adminAccounts[adminIdx].passwordHash = newPasswordHash;
          adminAccounts[adminIdx].failedLoginAttempts = 0;
          delete (adminAccounts[adminIdx] as any).passwordResetToken;
          delete (adminAccounts[adminIdx] as any).passwordResetTokenHash;
          delete (adminAccounts[adminIdx] as any).passwordResetExpires;
          adminAccounts[adminIdx].lockoutUntil = undefined;
        }
      } else if (u.userType === 'PARENT') {
        const cleanPhone = normalizePhone(u.phone || u.username);
        if (cleanPhone) {
          const p = parentAccounts.get(cleanPhone);
          if (p) {
            p.passwordHash = newPasswordHash;
            delete (p as any).passwordResetToken;
            delete (p as any).passwordResetTokenHash;
            delete (p as any).passwordResetExpires;
            p.failedLoginAttempts = 0;
          }
        }
      }
    }

    if (match.type === 'STAFF') {
      const staffIdx = staff.findIndex(
        (s) => s.id === entity.id || (entity.employeeId && s.employeeId?.toUpperCase() === entity.employeeId.toUpperCase())
      );
      if (staffIdx !== -1) {
        staff[staffIdx].passwordHash = newPasswordHash;
        delete (staff[staffIdx] as any).passwordResetToken;
        delete (staff[staffIdx] as any).passwordResetTokenHash;
        delete (staff[staffIdx] as any).passwordResetExpires;
        staff[staffIdx].failedLoginAttempts = 0;
      }
      persistentStorage.saveJsonData('staff.json', staff);
    } else if (match.type === 'ADMIN') {
      const adminIdx = adminAccounts.findIndex(
        (a) => a.id === entity.id || (entity.username && a.username.toLowerCase() === entity.username.toLowerCase())
      );
      if (adminIdx !== -1) {
        adminAccounts[adminIdx].passwordHash = newPasswordHash;
        delete (adminAccounts[adminIdx] as any).passwordResetToken;
        delete (adminAccounts[adminIdx] as any).passwordResetTokenHash;
        delete (adminAccounts[adminIdx] as any).passwordResetExpires;
        adminAccounts[adminIdx].failedLoginAttempts = 0;
      }
      persistentStorage.saveJsonData('adminAccounts.json', adminAccounts);
    } else if (match.type === 'STUDENT') {
      const stuIdx = students.findIndex((s) => s.id === entity.id);
      if (stuIdx !== -1) {
        (students[stuIdx] as any).passwordHash = newPasswordHash;
        delete (students[stuIdx] as any).passwordResetToken;
        delete (students[stuIdx] as any).passwordResetTokenHash;
        delete (students[stuIdx] as any).passwordResetExpires;
      }
      persistentStorage.saveJsonData('students.json', students);
    } else if (match.type === 'PARENT') {
      syncParentAccounts();
      const cleanPhone = normalizePhone(entity.phone);
      if (cleanPhone) {
        const p = parentAccounts.get(cleanPhone);
        if (p) {
          p.passwordHash = newPasswordHash;
          delete (p as any).passwordResetToken;
          delete (p as any).passwordResetTokenHash;
          delete (p as any).passwordResetExpires;
        }
      }
      persistentStorage.saveJsonData('parentAccounts.json', Array.from(parentAccounts.values()));
    }

    // 5. Revoke active sessions (Requirement 12)
    revokeUserSessions(entity.id);
    if (entity.employeeId) revokeUserSessions(entity.employeeId);
    if (entity.admissionNumber) revokeUserSessions(entity.admissionNumber);
    if (entity.username) revokeUserSessions(entity.username);
    for (const u of matchedUserDocs) {
      if (u.id) revokeUserSessions(u.id);
      if (u.username) revokeUserSessions(u.username);
      if (u.employeeId) revokeUserSessions(u.employeeId);
    }
    for (const s of matchedStudentDocs) {
      if (s.id) revokeUserSessions(s.id);
      if (s.admissionNumber) revokeUserSessions(s.admissionNumber);
    }

    // 6. Safe verification of persistence (Requirement 15)
    if (mongoose.connection && mongoose.connection.readyState === 1) {
      if (matchedUserDocs.length > 0) {
        for (const u of matchedUserDocs) {
          const verifyDoc = await UserModel.findById(u._id).lean();
          if (!verifyDoc || verifyDoc.passwordHash !== newPasswordHash) {
            console.error(`[ResetPassword] Verification anomaly for ${u.username || u.id}: MongoDB hash does not match newly saved hash!`);
          } else {
            console.log(`[ResetPassword] Verified: MongoDB Atlas UserModel (${u.username || u.id}) contains updated bcrypt hash.`);
          }
        }
      } else if (userDoc?._id) {
        const verifyDoc = await UserModel.findById(userDoc._id).lean();
        if (verifyDoc && verifyDoc.passwordHash === newPasswordHash) {
          console.log(`[ResetPassword] Verified: MongoDB Atlas UserModel contains updated bcrypt hash.`);
        }
      }
    }

    // 7. Send confirmation email
    let recipientEmail = entity.passwordResetEmail || entity.email || userDoc?.email || (entity as any).parentEmail || (entity as any).fatherEmail;
    delete entity.passwordResetEmail;

    if (recipientEmail) {
      emailService
        .sendPasswordChangedConfirmation({
          to: recipientEmail,
          userName: entity.name || userDoc?.name || entity.parentName || entity.username || 'User',
          identifier: entity.username || entity.employeeId || entity.admissionNumber || entity.email || 'Account',
          schoolName: schoolSettings.schoolName || 'CHANAKYA PUBLIC SCHOOL & COACHING CENTRE',
          portalUrl: resolveProductionFrontendUrl(req),
        })
        .then((res) => {
          console.log(`[Server] Password update confirmation email dispatched to ${recipientEmail} (Success: ${res.success})`);
        })
        .catch((err) => {
          console.warn(`[Server] Failed to send password changed confirmation to ${recipientEmail}:`, err);
        });
    }

    logAudit(
      entity.name || userDoc?.name || entity.username || 'User',
      match.role,
      'PASSWORD_RESET_COMPLETED',
      match.type,
      entity.id,
      'Successfully reset password and persisted to authoritative MongoDB Atlas database'
    );

    res.json({
      success: true,
      message: 'Password updated successfully. You can now log in with your new password.',
    });
  });

  // Auth: Email Service & Diagnostic Endpoint (Brevo Transactional Email Audit)
  const handleEmailDiagnostic = async (req: Request, res: Response) => {
    try {
      const envAudit = emailService.getEnvironmentAudit();
      const verification = await emailService.verifyActiveTransporter();

      let testDispatch: any = null;
      const shouldSend = req.method === 'POST' || req.query.sendTest === 'true';

      if (shouldSend) {
        const targetTo = String(req.body?.to || req.query.to || process.env.BREVO_SENDER_EMAIL || process.env.INITIAL_ADMIN_EMAIL || '').trim();
        const startSend = Date.now();
        const sendResult = await emailService.sendEmail({
          to: targetTo,
          subject: 'Email Service Diagnostic Verification - Chanakya Public School & Coaching Centre',
          html: `
            <div style="font-family: Arial, sans-serif; padding: 20px; color: #1e293b;">
              <h2 style="color: #1e3a8a;">Brevo Email Service Diagnostic Test</h2>
              <p>This is a real diagnostic email dispatched from the production backend via Brevo Transactional Email API.</p>
              <p><strong>Recipient:</strong> ${targetTo}</p>
              <p><strong>Active Provider:</strong> ${verification.config.provider}</p>
              <p><strong>Timestamp:</strong> ${new Date().toISOString()}</p>
            </div>
          `,
        });
        testDispatch = {
          targetRecipient: targetTo,
          elapsedMs: Date.now() - startSend,
          ...sendResult,
        };
      }

      return res.json({
        success: verification.success && (testDispatch ? testDispatch.success : true),
        status: verification.success ? 'EMAIL_SERVICE_HEALTHY' : 'EMAIL_SERVICE_ATTENTION',
        environmentAudit: envAudit,
        activeConfiguration: verification.config,
        verification,
        testDispatch,
      });
    } catch (err: any) {
      console.error('[Server] [EMAIL DIAGNOSTIC ERROR]', err);
      return res.status(500).json({
        success: false,
        status: 'DIAGNOSTIC_FAILURE',
        error: err?.message || 'Diagnostic failed',
      });
    }
  };

  app.all('/api/auth/email-diagnostic', handleEmailDiagnostic);
  app.all('/api/auth/smtp-diagnostic', handleEmailDiagnostic);

  // Auth: Change Password (for authenticated users)
  app.post('/api/auth/change-password', requireAuth, async (req: Request, res: Response) => {
    const user = (req as any).currentUser as User;
    const match = (req as any).authMatch as AuthEntityMatch;
    const { currentPassword, newPassword } = req.body;

    if (!currentPassword || !newPassword) {
      return res.status(400).json({ success: false, error: 'Current password and new password are required' });
    }

    const cleanNewPass = String(newPassword);
    const changePolicyError = validateNewPassword(cleanNewPass);
    if (changePolicyError) {
      return res.status(400).json({ success: false, error: changePolicyError });
    }
    if (String(currentPassword) === cleanNewPass) {
      return res.status(400).json({ success: false, error: 'The new password must be different from the current one.' });
    }

    const entity = match.entity as any;
    const limiterKey = `${match.type}:${entity.id || user.id}`;
    const waitSec = changePasswordLimiter.blockedFor(limiterKey);
    if (waitSec > 0) {
      return res.status(429).json({ success: false, error: `Too many wrong attempts. Try again in ${Math.ceil(waitSec / 60)} minute(s).` });
    }
    let isCurrentValid = false;
    let currentHashForReuse: string | undefined;

    if (match.type === 'ADMIN' || match.type === 'STAFF') {
      let authoritativeHash = entity.passwordHash;
      if (mongoService.isConnected()) {
        const userDoc = await UserModel.findOne({
          $or: [
            { id: user.id },
            { id: entity.id },
            { id: `user-staff-${entity.id}` },
            ...(entity.employeeId ? [{ employeeId: entity.employeeId.toUpperCase() }, { employeeId: entity.employeeId }] : []),
            ...(user.username ? [{ username: user.username.toLowerCase() }] : []),
          ],
        }).lean();
        if (userDoc?.passwordHash) {
          authoritativeHash = userDoc.passwordHash;
        }
      }
      isCurrentValid = authoritativeHash ? bcrypt.compareSync(currentPassword, authoritativeHash) : false;
      currentHashForReuse = authoritativeHash;
    } else if (match.type === 'STUDENT') {
      if (entity.passwordHash && bcrypt.compareSync(currentPassword, entity.passwordHash)) {
        isCurrentValid = true;
      } else {
        const dobValidation = parseAndValidateDob(currentPassword);
        if (dobValidation.valid && entity.dob === dobValidation.isoDate) {
          isCurrentValid = true;
        }
      }
    } else if (match.type === 'PARENT') {
      let authoritativeHash = entity.passwordHash;
      if (mongoService.isConnected()) {
        try {
          const userDoc = await UserModel.findOne({
            $or: [
              { id: user.id },
              { phone: user.phone },
              { username: user.username },
              { id: `parent-${user.phone}` },
            ],
            userType: 'PARENT',
          }).lean();
          if (userDoc?.passwordHash) {
            authoritativeHash = userDoc.passwordHash;
          }
        } catch (e) {}
      }

      const hasOwnPassword = [authoritativeHash, entity.passwordHash].some((h) => typeof h === 'string' && (h.startsWith('$2a$') || h.startsWith('$2b$')));
      currentHashForReuse = authoritativeHash || entity.passwordHash;
      if (authoritativeHash && bcrypt.compareSync(currentPassword, authoritativeHash)) {
        isCurrentValid = true;
      } else if (entity.passwordHash && bcrypt.compareSync(currentPassword, entity.passwordHash)) {
        isCurrentValid = true;
      } else if (!hasOwnPassword && String(currentPassword).toUpperCase() === 'CPS123') {
        // The initial parent password is accepted only until the parent sets their own (same rule as login).
        isCurrentValid = true;
      } else {
        const dobValidation = parseAndValidateDob(currentPassword);
        if (dobValidation.valid && entity.studentIds && entity.studentIds.length > 0) {
          const linkedStudents = students.filter((s) => entity.studentIds.includes(s.id));
          isCurrentValid = linkedStudents.some((s) => s.dob === dobValidation.isoDate);
        }
      }
    }

    if (!isCurrentValid) {
      changePasswordLimiter.hit(limiterKey);
      logAudit(user.name, match.role, 'PASSWORD_CHANGE_FAILED', match.type, entity.id || user.id, 'Wrong current password on change-password');
      return res.status(400).json({ success: false, error: 'Current password is incorrect' });
    }
    changePasswordLimiter.reset(limiterKey);
    if (match.type === 'STUDENT') currentHashForReuse = entity.passwordHash;
    if (currentHashForReuse && /^\$2[ab]\$/.test(currentHashForReuse) && bcrypt.compareSync(cleanNewPass, currentHashForReuse)) {
      return res.status(400).json({ success: false, error: 'The new password must be different from the current one.' });
    }

    const newHash = bcrypt.hashSync(cleanNewPass, 10);
    entity.passwordHash = newHash;
    entity.failedLoginAttempts = 0;
    entity.lockoutUntil = undefined;
    entity.passwordResetToken = undefined;
    entity.passwordResetExpires = undefined;

    // Invalidate other sessions for this user, retaining only the current active session
    const currentToken = (req as any).currentSession?.token;
    for (const [t, s] of activeSessions.entries()) {
      if (t !== currentToken && (s.userId === entity.id || s.employeeId === entity.employeeId || s.studentId === entity.id)) {
        revokeToken(t, s.expiresAt);
      }
    }

    let recipientEmail: string | undefined = undefined;
    if (match.type === 'STAFF') {
      persistentStorage.saveStaffToDisk(staff);
      if (mongoService.isConnected()) {
        await UserModel.updateOne(
          {
            $or: [
              { id: user.id },
              { id: entity.id },
              { id: `user-staff-${entity.id}` },
              ...(entity.employeeId ? [{ employeeId: entity.employeeId.toUpperCase() }, { employeeId: entity.employeeId }, { username: entity.employeeId.toLowerCase() }] : []),
              ...(user.email ? [{ email: user.email.toLowerCase() }] : []),
            ],
          },
          {
            $set: {
              passwordHash: newHash,
              failedLoginAttempts: 0,
              lockoutUntil: null,
            },
          }
        );
        await StaffModel.updateOne(
          { $or: [{ id: entity.id }, ...(entity.employeeId ? [{ employeeId: entity.employeeId.toUpperCase() }] : [])] },
          { $set: { passwordHash: newHash, failedLoginAttempts: 0, lockoutUntil: null } }
        );
      }
      recipientEmail = entity.email;
    } else if (match.type === 'ADMIN') {
      persistentStorage.saveAdminAccountsToDisk(adminAccounts);
      if (mongoService.isConnected()) {
        await UserModel.updateOne(
          {
            $or: [
              { id: user.id },
              { id: entity.id },
              { username: (entity.username || user.username || '').toLowerCase() },
              { email: (entity.email || user.email || '').toLowerCase() },
            ],
          },
          {
            $set: {
              passwordHash: newHash,
              failedLoginAttempts: 0,
              lockoutUntil: null,
            },
          }
        );
      }
      recipientEmail = entity.email;
    } else if (match.type === 'STUDENT') {
      persistentStorage.saveStudentsToDisk(students);
      recipientEmail = entity.email || entity.parentEmail || entity.fatherEmail;
    } else if (match.type === 'PARENT') {
      persistentStorage.saveParentAccountsToDisk(Array.from(parentAccounts.values()));
      if (mongoService.isConnected()) {
        await UserModel.updateOne(
          {
            $or: [
              { id: user.id },
              { phone: user.phone },
              { username: user.username },
              { id: `parent-${user.phone}` },
            ],
            userType: 'PARENT',
          },
          {
            $set: {
              passwordHash: newHash,
              failedLoginAttempts: 0,
              lockoutUntil: null,
            },
          },
          { upsert: true }
        ).catch((e) => console.warn('[Password Change] Error updating parent UserModel in MongoDB:', e));
      }
      recipientEmail = entity.email || user.email;
    }

    if (recipientEmail) {
      const portalBaseUrl = process.env.FRONTEND_URL || `${req.protocol}://${req.get('host')}` || 'http://localhost:3000';
      emailService
        .sendPasswordChangedConfirmation({
          to: recipientEmail,
          userName: user.name,
          identifier: user.username || user.email || user.phone || user.id,
          schoolName: schoolSettings.schoolName || 'Chanakya Public School & Coaching Centre',
          portalUrl: portalBaseUrl,
        })
        .catch(() => {});
    }

    logAudit(user.name, match.role, 'PASSWORD_CHANGED', match.type, entity.id, 'User changed their own password');

    res.json({ success: true, message: 'Password has been updated successfully.' });
  });

  // Helper to resolve entity anywhere across systems
  function findEntityAnywhere(targetType: string, targetId: string): { type: string; entity: any; role: UserRole; identifier: string; email?: string } | null {
    const cleanId = String(targetId).trim();
    const cleanPhone = normalizePhone(cleanId);

    if (targetType === 'STAFF') {
      const st = staff.find(
        (s) =>
          s.id === cleanId ||
          s.employeeId.toLowerCase() === cleanId.toLowerCase() ||
          (s.email && s.email.toLowerCase() === cleanId.toLowerCase()) ||
          (cleanPhone.length >= 10 && normalizePhone(s.phone) === cleanPhone)
      );
      if (st) return { type: 'STAFF', entity: st, role: (st.systemRole || 'TEACHER') as UserRole, identifier: st.employeeId, email: st.email };
    }

    if (targetType === 'STUDENT') {
      const s = students.find(
        (st) =>
          st.id === cleanId ||
          st.admissionNumber.toLowerCase() === cleanId.toLowerCase() ||
          st.registrationNumber?.toLowerCase() === cleanId.toLowerCase() ||
          (st.email && st.email.toLowerCase() === cleanId.toLowerCase()) ||
          (cleanPhone.length >= 10 && normalizePhone(st.mobile || st.parentPhone || '') === cleanPhone)
      );
      if (s) return { type: 'STUDENT', entity: s, role: 'STUDENT', identifier: s.admissionNumber, email: s.email || s.parentEmail || s.fatherEmail };
    }

    if (targetType === 'PARENT') {
      syncParentAccounts();
      const p = parentAccounts.get(normalizePhone(cleanId)) || Array.from(parentAccounts.values()).find((x) => x.id === cleanId || normalizePhone(x.phone) === cleanPhone);
      if (p) return { type: 'PARENT', entity: p, role: 'PARENT', identifier: p.phone, email: p.email };
    }

    if (targetType === 'ADMIN') {
      const a = adminAccounts.find(
        (ad) =>
          ad.id === cleanId ||
          ad.username.toLowerCase() === cleanId.toLowerCase() ||
          ad.email.toLowerCase() === cleanId.toLowerCase() ||
          (cleanPhone.length >= 10 && normalizePhone(ad.phone) === cleanPhone)
      );
      if (a) return { type: 'ADMIN', entity: a, role: a.role, identifier: a.username, email: a.email };
    }

    // Fallback: search everywhere
    const st = staff.find(
      (s) =>
        s.id === cleanId ||
        s.employeeId.toLowerCase() === cleanId.toLowerCase() ||
        (s.email && s.email.toLowerCase() === cleanId.toLowerCase()) ||
        (cleanPhone.length >= 10 && normalizePhone(s.phone) === cleanPhone)
    );
    if (st) return { type: 'STAFF', entity: st, role: (st.systemRole || 'TEACHER') as UserRole, identifier: st.employeeId, email: st.email };

    const s = students.find(
      (st) =>
        st.id === cleanId ||
        st.admissionNumber.toLowerCase() === cleanId.toLowerCase() ||
        st.registrationNumber?.toLowerCase() === cleanId.toLowerCase() ||
        (st.email && st.email.toLowerCase() === cleanId.toLowerCase())
    );
    if (s) return { type: 'STUDENT', entity: s, role: 'STUDENT', identifier: s.admissionNumber, email: s.email || s.parentEmail || s.fatherEmail };

    const a = adminAccounts.find(
      (ad) =>
        ad.id === cleanId ||
        ad.username.toLowerCase() === cleanId.toLowerCase() ||
        ad.email.toLowerCase() === cleanId.toLowerCase() ||
        (cleanPhone.length >= 10 && normalizePhone(ad.phone) === cleanPhone)
    );
    if (a) return { type: 'ADMIN', entity: a, role: a.role, identifier: a.username, email: a.email };

    syncParentAccounts();
    const p = parentAccounts.get(normalizePhone(cleanId)) || Array.from(parentAccounts.values()).find((x) => x.id === cleanId || normalizePhone(x.phone) === cleanPhone);
    if (p) return { type: 'PARENT', entity: p, role: 'PARENT', identifier: p.phone, email: p.email };

    return null;
  }

  // --- UNIFIED ADMIN DIRECT RESET PASSWORD ENDPOINT ---
  app.post('/api/admin/reset-password-direct', async (req: Request, res: Response) => {
    const { user: currentUser } = getAuthContext(req);
    if (!currentUser || !['SUPER_ADMIN', 'SCHOOL_ADMIN', 'PRINCIPAL'].includes(currentUser.role)) {
      return res.status(403).json({ success: false, error: 'Forbidden: Insufficient privileges. Administrator access required.' });
    }

    const { targetType, targetId, newPassword, sendEmail = true, temporaryPassword = false } = req.body;

    if (!targetId || !newPassword) {
      return res.status(400).json({ success: false, error: 'Target ID and new password are required' });
    }

    const cleanPassword = String(newPassword).trim();
    if (cleanPassword.length < 6) {
      return res.status(400).json({ success: false, error: 'Password must be at least 6 characters long' });
    }

    const resolved = findEntityAnywhere(targetType, targetId);
    if (!resolved) {
      return res.status(404).json({ success: false, error: `User account not found for ${targetType || 'user'} with ID "${targetId}"` });
    }

    // Strict RBAC: Only SUPER_ADMIN can reset other administrators or Principal
    if ((resolved.role === 'SUPER_ADMIN' || resolved.type === 'ADMIN') && currentUser.role !== 'SUPER_ADMIN') {
      return res.status(403).json({ success: false, error: 'Access denied: Only Super Administrator can reset administrator account credentials.' });
    }
    if (resolved.role === 'PRINCIPAL' && currentUser.role !== 'SUPER_ADMIN') {
      return res.status(403).json({ success: false, error: 'Access denied: Only Super Administrator can reset Principal credentials.' });
    }
    const currentRank = ROLE_HIERARCHY[currentUser.role] || 0;
    const targetRank = ROLE_HIERARCHY[resolved.role] || 0;
    if (currentUser.role !== 'SUPER_ADMIN' && targetRank >= currentRank) {
      return res.status(403).json({
        success: false,
        error: `Access denied: You cannot reset credentials for an account with equal or higher rank (${resolved.role}).`,
      });
    }

    const { type, entity, identifier } = resolved;
    const passwordHash = bcrypt.hashSync(cleanPassword, 10);
    entity.passwordHash = passwordHash;
    entity.passwordResetToken = undefined;
    entity.passwordResetLinkToken = undefined;
    entity.passwordResetExpires = undefined;
    entity.failedLoginAttempts = 0;
    entity.lockoutUntil = undefined;

    // Invalidate/revoke relevant active sessions of the target user
    revokeUserSessions(entity.id);
    if (entity.employeeId) revokeUserSessions(entity.employeeId);
    if (entity.admissionNumber) revokeUserSessions(entity.admissionNumber);
    if (entity.username) revokeUserSessions(entity.username);

    // Immediately enable portal access and active status upon direct reset
    entity.loginEnabled = true;
    if (entity.accountStatus === 'INACTIVE') entity.accountStatus = 'ACTIVE';
    if (entity.status === 'INACTIVE') entity.status = 'ACTIVE';

    // Persist changes immediately to storage
    if (type === 'STAFF') {
      persistentStorage.saveStaffToDisk(staff);
      if (mongoService.isConnected()) {
        await UserModel.updateOne(
          {
            $or: [
              { employeeId: entity.employeeId?.toUpperCase() },
              { employeeId: entity.employeeId },
              { id: entity.id },
              { id: `user-staff-${entity.id}` },
              { username: entity.employeeId?.toLowerCase() },
            ],
          },
          {
            $set: {
              passwordHash: passwordHash,
              failedLoginAttempts: 0,
              lockoutUntil: null,
              status: 'ACTIVE',
              loginEnabled: true,
            },
          }
        );
        await mongoService.updateStaff(entity.id, {
          passwordHash: passwordHash,
          failedLoginAttempts: 0,
          lockoutUntil: undefined,
          loginEnabled: true,
          status: 'ACTIVE',
          accountStatus: 'ACTIVE',
        });
      }
    } else if (type === 'STUDENT') {
      persistentStorage.saveStudentsToDisk(students);
    } else if (type === 'PARENT') {
      persistentStorage.saveParentAccountsToDisk(Array.from(parentAccounts.values()));
    } else if (type === 'ADMIN') {
      persistentStorage.saveAdminAccountsToDisk(adminAccounts);
      if (mongoService.isConnected()) {
        UserModel.updateOne(
          {
            $or: [
              { id: entity.id },
              { username: (entity.username || '').toLowerCase() },
              { email: (entity.email || '').toLowerCase() },
            ],
          },
          {
            $set: {
              passwordHash: passwordHash,
              failedLoginAttempts: 0,
              lockoutUntil: null,
              status: 'ACTIVE',
            },
          }
        ).catch((err) => {
          console.warn('[Server] Error updating admin bcrypt hash in MongoDB:', err?.message);
        });
      }
    }

    const recipientEmail = resolved.email;
    let emailDispatched = false;

    if (sendEmail && recipientEmail) {
      const portalBaseUrl = process.env.FRONTEND_URL || `${req.protocol}://${req.get('host')}` || 'http://localhost:3000';
      try {
        if (temporaryPassword) {
          const emailRes = await emailService.sendTemporaryPasswordEmail({
            to: recipientEmail,
            userName: entity.name || entity.parentName || identifier,
            roleName: resolved.role,
            identifier,
            temporaryPassword: cleanPassword,
            portalUrl: portalBaseUrl,
            schoolName: schoolSettings.schoolName || 'CHANAKYA PUBLIC SCHOOL & COACHING CENTRE',
          });
          emailDispatched = emailRes.success;
        } else {
          const emailRes = await emailService.sendPasswordChangedConfirmation({
            to: recipientEmail,
            userName: entity.name || entity.parentName || identifier,
            identifier,
            schoolName: schoolSettings.schoolName || 'CHANAKYA PUBLIC SCHOOL & COACHING CENTRE',
            portalUrl: portalBaseUrl,
          });
          emailDispatched = emailRes.success;
        }
      } catch (err: any) {
        console.warn('[Server] Error dispatching password reset email:', err?.message);
      }
    }

    const adminName = (req as any).currentUser?.name || 'Administrator';
    logAudit(
      adminName,
      'SUPER_ADMIN',
      'ADMIN_DIRECT_RESET_PASSWORD',
      type,
      entity.id,
      `Directly reset password for ${entity.name || identifier} (${identifier}). Email sent: ${emailDispatched}`
    );

    res.json({
      success: true,
      message: `Password reset successfully for ${entity.name || identifier} (${identifier}). The account can now log in immediately with the new password.`,
      emailDispatched,
      recipientEmail: recipientEmail ? recipientEmail.replace(/^(.{2})(.*)(@.*)$/, '$1***$3') : undefined,
    });
  });

  // --- UNIFIED SEND LOGIN DETAILS / CREDENTIALS EMAIL ---
  app.post('/api/admin/send-login-details', requireRole(['SUPER_ADMIN', 'SCHOOL_ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL']), async (req: Request, res: Response) => {
    const { targetType, targetId, temporaryPassword, customNote } = req.body;
    if (!targetId) {
      return res.status(400).json({ success: false, error: 'Target ID is required' });
    }

    const resolved = findEntityAnywhere(targetType, targetId);
    if (!resolved) {
      return res.status(404).json({ success: false, error: 'User account not found' });
    }

    const { type, entity, identifier, email, role } = resolved;
    if (!email) {
      return res.status(400).json({
        success: false,
        error: `No registered email address found for ${entity.name || identifier}. Please update their profile with an email address first.`,
      });
    }

    const portalBaseUrl = process.env.FRONTEND_URL || `${req.protocol}://${req.get('host')}` || 'http://localhost:3000';
    const emailRes = await emailService.sendAccountWelcomeEmail({
      to: email,
      userName: entity.name || entity.parentName || identifier,
      roleName: role,
      identifier,
      temporaryPassword: temporaryPassword || undefined,
      portalUrl: portalBaseUrl,
      schoolName: schoolSettings.schoolName || 'CHANAKYA PUBLIC SCHOOL & COACHING CENTRE',
      instructions: customNote || undefined,
    });

    logAudit(
      (req as any).currentUser?.name || 'Administrator',
      'SUPER_ADMIN',
      'LOGIN_DETAILS_SENT',
      type,
      entity.id,
      `Sent login details to ${email}`
    );

    res.json({
      success: true,
      message: `Login details successfully dispatched to ${email}`,
      email,
      delivered: emailRes.success,
    });
  });

  // --- UNIFIED SEND RESET / SETUP LINK EMAIL ---
  app.post('/api/admin/send-reset-link', requireRole(['SUPER_ADMIN', 'SCHOOL_ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL']), async (req: Request, res: Response) => {
    const { targetType, targetId } = req.body;
    if (!targetId) {
      return res.status(400).json({ success: false, error: 'Target ID is required' });
    }

    const resolved = findEntityAnywhere(targetType, targetId);
    if (!resolved) {
      return res.status(404).json({ success: false, error: 'User account not found' });
    }

    const { type, entity, identifier, email } = resolved;
    if (!email) {
      return res.status(400).json({
        success: false,
        error: `No registered email address found for ${entity.name || identifier}. Please update their profile with an email address first.`,
      });
    }

    const resetToken = crypto.randomBytes(32).toString('hex');
    const tokenHash = crypto.createHash('sha256').update(resetToken).digest('hex');
    entity.passwordResetToken = tokenHash;
    entity.passwordResetTokenHash = tokenHash;
    entity.passwordResetExpires = Date.now() + 15 * 60 * 1000;
    delete entity.passwordResetLinkToken;
    delete entity.passwordResetOtp;

    if (type === 'STAFF') persistentStorage.saveStaffToDisk(staff);
    else if (type === 'STUDENT') persistentStorage.saveStudentsToDisk(students);
    else if (type === 'PARENT') persistentStorage.saveParentAccountsToDisk(Array.from(parentAccounts.values()));
    else if (type === 'ADMIN') persistentStorage.saveAdminAccountsToDisk(adminAccounts);

    const portalBaseUrl = resolveProductionFrontendUrl(req);
    const resetUrl = `${portalBaseUrl}/reset-password?token=${resetToken}`;

    const emailRes = await emailService.sendPasswordResetEmail({
      to: email,
      userName: entity.name || entity.parentName || identifier,
      resetUrl,
      schoolName: schoolSettings.schoolName || 'CHANAKYA PUBLIC SCHOOL & COACHING CENTRE',
      expiresInMinutes: 15,
    });

    logAudit(
      (req as any).currentUser?.name || 'Administrator',
      'SUPER_ADMIN',
      'RESET_LINK_SENT',
      type,
      entity.id,
      `Sent password reset link to ${email}`
    );

    if (emailRes.success) {
      return res.json({
        success: true,
        message: `Password reset link sent to ${email}`,
        email,
      });
    }

    console.error(`[Server] Admin reset link dispatch failed for ${email}:`, emailRes.error);
    return res.status(500).json({
      success: false,
      error: 'Unable to send the reset email. Please try again later.',
      email,
    });
  });

  // --- TEACHER & STAFF PORTAL ACCESS MANAGEMENT ---

  // Update Staff Login & Account Status
  app.patch('/api/teachers/:id/portal-status', requirePermission(['users.manage', 'roles.manage']), async (req: Request, res: Response) => {
    const { id } = req.params;
    const { loginEnabled, accountStatus, systemRole } = req.body;
    const currentUser = (req as any).currentUser as User;

    const staffMember = staff.find((s) => s.id === id || s.employeeId === id);
    if (!staffMember) {
      return res.status(404).json({ success: false, error: 'Staff member not found' });
    }

    // Prevent self-modification
    if (
      currentUser.id === staffMember.id ||
      (currentUser.employeeId && staffMember.employeeId && currentUser.employeeId.toUpperCase() === staffMember.employeeId.toUpperCase())
    ) {
      return res.status(403).json({ success: false, error: 'Self-modification forbidden: You cannot change or elevate your own role or access status.' });
    }
    const portalManageCheck = canManageUserAccount(rankRole(currentUser.role), (staffMember.systemRole || staffMember.role || 'TEACHER') as UserRole);
    if (!portalManageCheck.allowed) {
      return res.status(403).json({ success: false, error: portalManageCheck.reason });
    }

    if (systemRole) {
      const assignCheck = canAssignRole(currentUser.role, systemRole);
      if (!assignCheck.allowed && currentUser.role !== 'SUPER_ADMIN') {
        return res.status(403).json({ success: false, error: assignCheck.reason });
      }
      const manageCheck = canManageUserAccount(currentUser.role, (staffMember.systemRole || staffMember.role || 'TEACHER') as UserRole);
      if (!manageCheck.allowed && currentUser.role !== 'SUPER_ADMIN') {
        return res.status(403).json({ success: false, error: manageCheck.reason });
      }
      staffMember.systemRole = systemRole;
      staffMember.role = systemRole;
      staffMember.portalRole = systemRole;
    }

    if (loginEnabled !== undefined) staffMember.loginEnabled = !!loginEnabled;
    if (isNoLoginStaffRole(staffMember.portalRole || staffMember.systemRole || staffMember.role)) staffMember.loginEnabled = false;
    if (accountStatus) staffMember.accountStatus = accountStatus;

    if (loginEnabled === false || accountStatus === 'INACTIVE' || accountStatus === 'SUSPENDED') {
      revokeUserSessions(staffMember.id);
      if (staffMember.employeeId) revokeUserSessions(staffMember.employeeId);
    }

    persistentStorage.saveStaffToDisk(staff);
    if (mongoService.isConnected()) {
      const blocked =
        staffMember.loginEnabled === false ||
        BLOCKED_STAFF_ACCOUNT_STATUSES.includes(String(staffMember.accountStatus || '').toUpperCase()) ||
        BLOCKED_STAFF_ACCOUNT_STATUSES.includes(String(staffMember.status || '').toUpperCase());
      const staffSaved = await mongoService.updateStaff(staffMember.id, {
        loginEnabled: staffMember.loginEnabled,
        accountStatus: staffMember.accountStatus,
        systemRole: staffMember.systemRole,
        role: staffMember.role,
        portalRole: staffMember.portalRole,
      });
      const userSaved = await mongoService.updateUser(staffMember.id, {
        loginEnabled: !blocked,
        status: blocked ? 'INACTIVE' : 'ACTIVE',
        role: (staffMember.systemRole || staffMember.role || 'TEACHER') as UserRole,
      } as any);
      if (!staffSaved || !userSaved) {
        return res.status(500).json({ success: false, error: 'Could not save the portal access change. Please try again.' });
      }
    }
    logAudit(
      currentUser?.name || 'Administrator',
      (currentUser?.role as UserRole) || 'SUPER_ADMIN',
      'STAFF_PORTAL_UPDATED',
      'TeacherStaff',
      id,
      `Updated portal access: loginEnabled=${staffMember.loginEnabled}, status=${staffMember.accountStatus}${systemRole ? `, role=${systemRole}` : ''}`
    );
    res.json({ success: true, staff: sanitizeStaffRecord(staffMember, { includeFinancial: false }) });
  });

  // Admin Reset Staff Password (handles both /api/teachers/:id/reset-password AND /api/admin/staff/:id/reset-password)
  const handleStaffResetPassword = async (req: Request, res: Response) => {
    const { user: currentUser } = getAuthContext(req);
    if (!currentUser || !['SUPER_ADMIN', 'SCHOOL_ADMIN', 'PRINCIPAL'].includes(currentUser.role)) {
      return res.status(403).json({ success: false, error: 'Forbidden: Insufficient privileges to reset staff credentials.' });
    }

    const { id } = req.params;
    const { newPassword, sendEmail = true, temporaryPassword = false } = req.body;

    if (!newPassword || String(newPassword).length < 6) {
      return res.status(400).json({ success: false, error: 'Password must be at least 6 characters long' });
    }

    const cleanId = String(id).trim();
    const staffMember = staff.find(
      (s) =>
        s.id === cleanId ||
        s.employeeId.toLowerCase() === cleanId.toLowerCase() ||
        (s.email && s.email.toLowerCase() === cleanId.toLowerCase())
    );
    if (!staffMember) {
      return res.status(404).json({ success: false, error: 'Staff member not found' });
    }

    const targetStaffRole = (staffMember.systemRole || staffMember.role || 'TEACHER') as UserRole;
    if (targetStaffRole === 'SUPER_ADMIN' && currentUser.role !== 'SUPER_ADMIN') {
      return res.status(403).json({ success: false, error: 'Access denied: Only Super Administrator can reset Super Administrator credentials.' });
    }
    if (targetStaffRole === 'PRINCIPAL' && currentUser.role !== 'SUPER_ADMIN') {
      return res.status(403).json({ success: false, error: 'Access denied: Only Super Administrator can reset Principal credentials.' });
    }
    const currentRank = ROLE_HIERARCHY[currentUser.role] || 0;
    const targetRank = ROLE_HIERARCHY[targetStaffRole] || 0;
    if (currentUser.role !== 'SUPER_ADMIN' && targetRank >= currentRank) {
      return res.status(403).json({
        success: false,
        error: `Access denied: You cannot reset credentials for an account with equal or higher rank (${targetStaffRole}).`,
      });
    }

    const cleanPass = String(newPassword).trim();
    staffMember.passwordHash = bcrypt.hashSync(cleanPass, 10);
    staffMember.failedLoginAttempts = 0;
    staffMember.lockoutUntil = undefined;
    staffMember.passwordResetToken = undefined;
    staffMember.passwordResetExpires = undefined;
    staffMember.loginEnabled = true;
    if (staffMember.accountStatus === 'INACTIVE') staffMember.accountStatus = 'ACTIVE';

    revokeUserSessions(staffMember.id);
    if (staffMember.employeeId) revokeUserSessions(staffMember.employeeId);

    // CRITICAL: Persist to storage so it works after restart and in subsequent requests
    persistentStorage.saveStaffToDisk(staff);

    // CRITICAL: Authoritatively update UserModel and StaffModel in MongoDB
    if (mongoService.isConnected()) {
      await UserModel.updateOne(
        {
          $or: [
            { employeeId: staffMember.employeeId.toUpperCase() },
            { employeeId: staffMember.employeeId },
            { id: staffMember.id },
            { id: `user-staff-${staffMember.id}` },
            { username: staffMember.employeeId.toLowerCase() },
          ],
        },
        {
          $set: {
            passwordHash: staffMember.passwordHash,
            failedLoginAttempts: 0,
            lockoutUntil: null,
            status: 'ACTIVE',
            loginEnabled: true,
          },
        }
      );
      await mongoService.updateStaff(staffMember.id, {
        passwordHash: staffMember.passwordHash,
        failedLoginAttempts: 0,
        lockoutUntil: undefined,
        loginEnabled: true,
        status: 'ACTIVE',
        accountStatus: 'ACTIVE',
      });
    }

    let emailDispatched = false;
    if (sendEmail && staffMember.email) {
      const portalBaseUrl = process.env.FRONTEND_URL || `${req.protocol}://${req.get('host')}` || 'http://localhost:3000';
      try {
        if (temporaryPassword) {
          const emailRes = await emailService.sendTemporaryPasswordEmail({
            to: staffMember.email,
            userName: staffMember.name,
            roleName: staffMember.systemRole || staffMember.role || 'TEACHER',
            identifier: staffMember.employeeId,
            temporaryPassword: cleanPass,
            portalUrl: portalBaseUrl,
            schoolName: schoolSettings.schoolName || 'CHANAKYA PUBLIC SCHOOL & COACHING CENTRE',
          });
          emailDispatched = emailRes.success;
        } else {
          const emailRes = await emailService.sendPasswordChangedConfirmation({
            to: staffMember.email,
            userName: staffMember.name,
            identifier: staffMember.employeeId,
            schoolName: schoolSettings.schoolName || 'CHANAKYA PUBLIC SCHOOL & COACHING CENTRE',
            portalUrl: portalBaseUrl,
          });
          emailDispatched = emailRes.success;
        }
      } catch (err: any) {
        console.warn('[Server] Error dispatching staff email:', err?.message);
      }
    }

    logAudit(
      (req as any).currentUser?.name || 'Administrator',
      'SUPER_ADMIN',
      'STAFF_PASSWORD_RESET',
      'TeacherStaff',
      id,
      `Admin reset password for staff ${staffMember.name} (${staffMember.employeeId})`
    );

    res.json({
      success: true,
      message: `Password reset successfully for ${staffMember.name} (${staffMember.employeeId}). Immediate login enabled.`,
      emailDispatched,
      email: staffMember.email,
    });
  };

  app.post('/api/teachers/:id/reset-password', handleStaffResetPassword);
  app.post('/api/admin/staff/:id/reset-password', handleStaffResetPassword);

  // Helper: Cryptographically secure temporary password generation
  const generateSecureTemporaryPassword = (): string => {
    const upper = 'ABCDEFGHJKLMNPQRSTUVWXYZ';
    const lower = 'abcdefghjkmnpqrstuvwxyz';
    const digits = '23456789';
    const specials = '#$@!';

    let pwd = 'Cps';
    pwd += specials.charAt(crypto.randomInt(0, specials.length));
    for (let i = 0; i < 3; i++) {
      pwd += upper.charAt(crypto.randomInt(0, upper.length));
      pwd += digits.charAt(crypto.randomInt(0, digits.length));
    }
    return pwd;
  };

  // Helper: Compute next sequential employee ID based on current database/storage staff
  const getNextSequentialStaffEmployeeId = (): string => {
    let maxNum = 0;
    for (const s of staff) {
      const match = s.employeeId?.match(/\d+/);
      if (match) {
        const num = parseInt(match[0], 10);
        if (num > maxNum) maxNum = num;
      }
    }
    return `CPS${String(maxNum + 1).padStart(4, '0')}`;
  };

  // Resend Staff Login Credentials via Email (handles both /api/teachers/:id/resend-credentials AND /api/admin/staff/:id/resend-credentials)
  const handleStaffResendCredentials = async (req: Request, res: Response) => {
    const { user: currentUser } = getAuthContext(req);
    if (!currentUser || !['SUPER_ADMIN', 'SCHOOL_ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'HR_STAFF'].includes(currentUser.role)) {
      return res.status(403).json({ success: false, error: 'Forbidden: Insufficient privileges to resend staff credentials.' });
    }

    const { id } = req.params;
    const cleanId = String(id).trim();
    const staffMember = staff.find(
      (s) =>
        s.id === cleanId ||
        s.employeeId.toLowerCase() === cleanId.toLowerCase() ||
        (s.email && s.email.toLowerCase() === cleanId.toLowerCase())
    );
    if (!staffMember) {
      return res.status(404).json({ success: false, error: 'Staff member not found' });
    }

    // Verify recipient email format before sending
    const recipientEmail = (staffMember.email || '').trim();
    if (!recipientEmail || !recipientEmail.includes('@') || !recipientEmail.includes('.')) {
      return res.status(400).json({
        success: false,
        error: `Staff member ${staffMember.name} does not have a valid registered email address (${staffMember.email || 'None on file'}). Please update their profile with a valid email first.`,
      });
    }

    // Reuse existing secure reset flow: generate cryptographic token and hash
    const resetToken = crypto.randomBytes(32).toString('hex');
    const tokenHash = crypto.createHash('sha256').update(resetToken).digest('hex');
    const resetExpires = Date.now() + 60 * 60 * 1000; // 60 minutes validity

    staffMember.passwordResetToken = tokenHash;
    staffMember.passwordResetTokenHash = tokenHash;
    staffMember.passwordResetExpires = resetExpires;
    staffMember.failedLoginAttempts = 0;
    staffMember.lockoutUntil = undefined;
    staffMember.loginEnabled = true;
    if (staffMember.accountStatus === 'INACTIVE') staffMember.accountStatus = 'ACTIVE';

    persistentStorage.saveStaffToDisk(staff);

    // Sync or provision User account in MongoDB
    if (mongoService.isConnected()) {
      await mongoService.updateStaff(staffMember.id, staffMember);
      try {
        await UserModel.updateOne(
          {
            $or: [
              { employeeId: staffMember.employeeId.toUpperCase() },
              { employeeId: staffMember.employeeId },
              { id: staffMember.id },
              { id: `user-staff-${staffMember.id}` },
              { username: staffMember.employeeId.toLowerCase() },
              { email: recipientEmail.toLowerCase() },
            ],
          },
          {
            $set: {
              passwordResetToken: tokenHash,
              passwordResetTokenHash: tokenHash,
              passwordResetExpires: resetExpires,
              failedLoginAttempts: 0,
              lockoutUntil: null,
              status: 'ACTIVE',
              loginEnabled: true,
              role: staffMember.systemRole || staffMember.role || 'TEACHER',
              name: staffMember.name,
              email: recipientEmail,
              employeeId: staffMember.employeeId,
              username: staffMember.employeeId.toLowerCase(),
            },
          },
          { upsert: true }
        );
      } catch (err: any) {
        console.warn('[Server] Notice updating user record for credentials resend:', err?.message);
      }
    }

    const portalBaseUrl = resolveProductionFrontendUrl(req);
    const resetUrl = `${portalBaseUrl}/reset-password?token=${resetToken}`;
    const schoolName = schoolSettings.schoolName || 'CHANAKYA PUBLIC SCHOOL & COACHING CENTRE, SHEOHAR';

    let emailDispatched = false;
    let emailError: string | undefined = undefined;
    try {
      const emailRes = await emailService.sendStaffCredentialsWithResetLink({
        to: recipientEmail,
        staffName: staffMember.name,
        employeeId: staffMember.employeeId,
        portalUserId: staffMember.employeeId,
        roleName: staffMember.systemRole || staffMember.role || staffMember.designation || 'Faculty Member',
        portalUrl: portalBaseUrl,
        resetUrl,
        schoolName,
        expiresInMinutes: 60,
      });
      emailDispatched = emailRes.success;
      if (!emailRes.success) {
        emailError = emailRes.error;
      }
    } catch (err: any) {
      emailDispatched = false;
      emailError = err?.message;
      console.warn('[Server] Error dispatching credentials email:', err?.message);
    }

    logAudit(
      currentUser.name || 'Administrator',
      currentUser.role,
      'STAFF_CREDENTIALS_RESENT',
      'TeacherStaff',
      staffMember.id,
      `Resent portal login credentials and secure activation link to ${staffMember.name} (${recipientEmail})`
    );

    if (!emailDispatched) {
      return res.status(200).json({
        success: false,
        emailDispatched: false,
        email: recipientEmail,
        employeeId: staffMember.employeeId,
        portalUserId: staffMember.employeeId,
        error: emailError || 'Unable to send the email. Please try again later.',
        message: `Account verified and login ID confirmed (${staffMember.employeeId}), but the email could not be delivered: ${emailError || 'Email provider failure'}. Please verify Brevo configuration.`,
      });
    }

    res.json({
      success: true,
      emailDispatched: true,
      email: recipientEmail,
      employeeId: staffMember.employeeId,
      portalUserId: staffMember.employeeId,
      message: `Login credentials and secure activation link successfully sent to ${recipientEmail} (Login ID: ${staffMember.employeeId}).`,
    });
  };

  app.post('/api/teachers/:id/resend-credentials', handleStaffResendCredentials);
  app.post('/api/admin/staff/:id/resend-credentials', handleStaffResendCredentials);
  app.post('/api/staff/:id/resend-credentials', handleStaffResendCredentials);

  // --- STAFF ID CARD ENDPOINT WITH ROLE AUTHORIZATION ---
  const handleStaffIdCard = async (req: Request, res: Response) => {
    const { user: currentUser, session } = getAuthContext(req);
    if (!session || !currentUser) {
      return res.status(401).json({ success: false, error: 'Unauthorized: Authentication required.' });
    }

    const { id } = req.params;
    const cleanId = String(id || '').trim();

    // Own card: any authenticated staff member. Any other card requires an admin-tier role.
    const curStaff = findStaffForUser(currentUser, session);
    const isOwnCard =
      !!curStaff &&
      (curStaff.id === cleanId || curStaff.employeeId?.toUpperCase() === cleanId.toUpperCase());
    if (!isOwnCard && !isStaffAdminTier(session.role)) {
      return res.status(403).json({
        success: false,
        error: 'Forbidden: You are only authorized to view your own staff ID card.',
      });
    }

    // Look up staff member
    let staffMember = staff.find(
      (s) => s.id === cleanId || s.employeeId?.toUpperCase() === cleanId.toUpperCase()
    );
    if (!staffMember && mongoService.isConnected()) {
      try {
        const dbStaff = await mongoService.getStaff();
        if (Array.isArray(dbStaff)) {
          staff = dbStaff;
          staffMember = staff.find(
            (s) => s.id === cleanId || s.employeeId?.toUpperCase() === cleanId.toUpperCase()
          );
        }
      } catch {}
    }

    if (!staffMember) {
      return res.status(404).json({ success: false, error: 'Staff member not found.' });
    }

    res.json({
      success: true,
      staff: sanitizeStaffRecord(staffMember, { includeFinancial: false }),
      // Signed, data-free code for the card's QR (scanned by admins to mark staff attendance).
      qrToken: createIdCardQrToken('STAFF', staffMember.id),
      settings: {
        schoolName: schoolSettings.schoolName || 'CHANAKYA PUBLIC SCHOOL & COACHING CENTRE',
        schoolAddress: schoolSettings.schoolAddress || 'Kushahar Ward 07, Kushahar, Sheohar, Bihar - 843329',
        affiliationCode: schoolSettings.affiliationCode || schoolSettings.affiliationNumber || '10034104008',
        contactNumber: schoolSettings.contactNumber || '82078 70192',
        email: schoolSettings.email || '',
        website: schoolSettings.website || '',
        principalSignature: schoolSettings.principalSignature || '',
        principalName: schoolSettings.principalName || '',
        schoolLogo: schoolSettings.schoolLogo || '',
      },
    });
  };

  app.get('/api/staff/:id/id-card', handleStaffIdCard);
  app.get('/api/teachers/:id/id-card', handleStaffIdCard);

  // --- STUDENT & PARENT PORTAL ACCESS MANAGEMENT ---

  // Update Student Portal Access Status (handles /api/students/:id/portal-status and /api/admin/students/:id/portal-status)
  const handleStudentPortalStatus = async (req: Request, res: Response) => {
    const { user: currentUser } = getAuthContext(req);
    if (!currentUser || !['SUPER_ADMIN', 'SCHOOL_ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'ADMIN'].includes(currentUser.role)) {
      return res.status(403).json({ success: false, error: 'Forbidden: Insufficient privileges to update student portal access.' });
    }

    const { id } = req.params;
    const { loginEnabled, accountStatus } = req.body;

    let student = students.find((s) => s.id === id || s.admissionNumber === id);
    if (!student && mongoService.isConnected()) {
      const dbStudent = await mongoService.getStudentById(id);
      if (dbStudent) {
        students.unshift(dbStudent);
        student = dbStudent;
      }
    }
    if (!student) {
      return res.status(404).json({ success: false, error: 'Student record not found' });
    }

    if (loginEnabled !== undefined) student.loginEnabled = !!loginEnabled;
    if (accountStatus) student.accountStatus = accountStatus;

    if (loginEnabled === false || accountStatus === 'INACTIVE' || accountStatus === 'SUSPENDED') {
      revokeUserSessions(student.id);
    }

    persistentStorage.saveStudentsToDisk(students);
    if (mongoService.isConnected()) {
      await mongoService.updateStudent(student.id, {
        loginEnabled: student.loginEnabled,
        accountStatus: student.accountStatus,
      }).catch(() => {});
    }
    logAudit(
      (req as any).currentUser?.name || 'Administrator',
      'SUPER_ADMIN',
      'STUDENT_PORTAL_UPDATED',
      'Student',
      id,
      `Updated student portal status: loginEnabled=${student.loginEnabled}, status=${student.accountStatus}`
    );
    res.json({ success: true, student });
  };

  app.patch('/api/students/:id/portal-status', handleStudentPortalStatus);
  app.post('/api/students/:id/portal-status', handleStudentPortalStatus);
  app.patch('/api/admin/students/:id/portal-status', handleStudentPortalStatus);
  app.post('/api/admin/students/:id/portal-status', handleStudentPortalStatus);

  // Admin Reset Student Password (handles /api/students/:id/reset-password AND /api/admin/students/:id/reset-password)
  const handleStudentResetPassword = async (req: Request, res: Response) => {
    const { user: currentUser } = getAuthContext(req);
    if (!currentUser || !['SUPER_ADMIN', 'SCHOOL_ADMIN', 'PRINCIPAL'].includes(currentUser.role)) {
      return res.status(403).json({ success: false, error: 'Forbidden: Insufficient privileges to reset student credentials.' });
    }

    const { id } = req.params;
    const { newPassword, sendEmail = true, temporaryPassword = false } = req.body;

    if (!newPassword || String(newPassword).length < 6) {
      return res.status(400).json({ success: false, error: 'Password must be at least 6 characters long' });
    }

    let student = students.find((s) => s.id === id || s.admissionNumber === id);
    if (!student && mongoService.isConnected()) {
      const dbStudent = await mongoService.getStudentById(id);
      if (dbStudent) {
        students.unshift(dbStudent);
        student = dbStudent;
      }
    }
    if (!student) {
      return res.status(404).json({ success: false, error: 'Student record not found' });
    }

    const cleanPass = String(newPassword).trim();
    student.passwordHash = bcrypt.hashSync(cleanPass, 10);
    student.failedLoginAttempts = 0;
    student.lockoutUntil = undefined;
    student.passwordResetToken = undefined;
    student.passwordResetExpires = undefined;

    revokeUserSessions(student.id);
    if (student.admissionNumber) revokeUserSessions(student.admissionNumber);

    persistentStorage.saveStudentsToDisk(students);

    const recipientEmail = student.email || student.parentEmail || student.fatherEmail;
    let emailDispatched = false;
    if (sendEmail && recipientEmail) {
      const portalBaseUrl = process.env.FRONTEND_URL || `${req.protocol}://${req.get('host')}` || 'http://localhost:3000';
      try {
        if (temporaryPassword) {
          const emailRes = await emailService.sendTemporaryPasswordEmail({
            to: recipientEmail,
            userName: student.name,
            roleName: 'STUDENT',
            identifier: student.admissionNumber,
            temporaryPassword: cleanPass,
            portalUrl: portalBaseUrl,
            schoolName: schoolSettings.schoolName || 'CHANAKYA PUBLIC SCHOOL & COACHING CENTRE',
          });
          emailDispatched = emailRes.success;
        } else {
          const emailRes = await emailService.sendPasswordChangedConfirmation({
            to: recipientEmail,
            userName: student.name,
            identifier: student.admissionNumber,
            schoolName: schoolSettings.schoolName || 'CHANAKYA PUBLIC SCHOOL & COACHING CENTRE',
            portalUrl: portalBaseUrl,
          });
          emailDispatched = emailRes.success;
        }
      } catch (err: any) {
        console.warn('[Server] Error dispatching student email:', err?.message);
      }
    }

    logAudit(
      (req as any).currentUser?.name || 'Administrator',
      'SUPER_ADMIN',
      'STUDENT_PASSWORD_RESET',
      'Student',
      id,
      `Admin reset password for student ${student.name} (Adm: ${student.admissionNumber})`
    );

    res.json({
      success: true,
      message: `Password reset successfully for student ${student.name} (Adm: ${student.admissionNumber})`,
      emailDispatched,
      email: recipientEmail,
    });
  };

  app.post('/api/students/:id/reset-password', handleStudentResetPassword);
  app.post('/api/admin/students/:id/reset-password', handleStudentResetPassword);

  // Admin Reset Parent Password (handles /api/students/:id/reset-parent-password AND /api/admin/parents/:phone/reset-password)
  const handleParentResetPassword = async (req: Request, res: Response) => {
    const { user: currentUser } = getAuthContext(req);
    if (!currentUser || !['SUPER_ADMIN', 'SCHOOL_ADMIN', 'PRINCIPAL'].includes(currentUser.role)) {
      return res.status(403).json({ success: false, error: 'Forbidden: Insufficient privileges to reset parent credentials.' });
    }

    const { id, phone } = req.params;
    const { newPassword, sendEmail = true, temporaryPassword = false } = req.body;

    if (!newPassword || String(newPassword).length < 6) {
      return res.status(400).json({ success: false, error: 'Password must be at least 6 characters long' });
    }

    syncParentAccounts();
    let parent: InternalParentAccount | undefined;
    let targetPhone = phone ? normalizePhone(phone) : '';

    if (id && !targetPhone) {
      const student = students.find((s) => s.id === id || s.admissionNumber === id);
      if (student) {
        targetPhone = normalizePhone(student.parentPhone || student.fatherMobile || student.mobile || '');
      }
    }

    if (targetPhone) {
      parent = parentAccounts.get(targetPhone);
    }

    if (!parent && targetPhone) {
      parent = {
        id: `parent-${targetPhone}`,
        parentName: 'Parent / Guardian',
        phone: targetPhone,
        studentIds: [],
        loginEnabled: true,
        accountStatus: 'ACTIVE',
        passwordHash: bcrypt.hashSync(String(newPassword).trim(), 10),
        failedLoginAttempts: 0,
      };
      parentAccounts.set(targetPhone, parent);
    } else if (parent) {
      parent.passwordHash = bcrypt.hashSync(String(newPassword).trim(), 10);
      parent.failedLoginAttempts = 0;
      parent.lockoutUntil = undefined;
    } else {
      return res.status(404).json({ success: false, error: 'Parent record or phone not found' });
    }

    revokeUserSessions(parent.id);
    if (parent.phone) revokeUserSessions(parent.phone);

    persistentStorage.saveParentAccountsToDisk(Array.from(parentAccounts.values()));

    let emailDispatched = false;
    if (sendEmail && parent.email) {
      const portalBaseUrl = process.env.FRONTEND_URL || `${req.protocol}://${req.get('host')}` || 'http://localhost:3000';
      try {
        if (temporaryPassword) {
          const emailRes = await emailService.sendTemporaryPasswordEmail({
            to: parent.email,
            userName: parent.parentName,
            roleName: 'PARENT',
            identifier: parent.phone,
            temporaryPassword: String(newPassword).trim(),
            portalUrl: portalBaseUrl,
            schoolName: schoolSettings.schoolName || 'CHANAKYA PUBLIC SCHOOL & COACHING CENTRE',
          });
          emailDispatched = emailRes.success;
        } else {
          const emailRes = await emailService.sendPasswordChangedConfirmation({
            to: parent.email,
            userName: parent.parentName,
            identifier: parent.phone,
            schoolName: schoolSettings.schoolName || 'CHANAKYA PUBLIC SCHOOL & COACHING CENTRE',
            portalUrl: portalBaseUrl,
          });
          emailDispatched = emailRes.success;
        }
      } catch (err: any) {
        console.warn('[Server] Error dispatching parent email:', err?.message);
      }
    }

    logAudit(
      (req as any).currentUser?.name || 'Administrator',
      'SUPER_ADMIN',
      'PARENT_PASSWORD_RESET',
      'Parent',
      parent.id,
      `Reset parent login password for ${parent.parentName} (${parent.phone})`
    );

    res.json({
      success: true,
      message: `Parent password updated successfully for ${parent.parentName} (${parent.phone})`,
      emailDispatched,
      email: parent.email,
    });
  };

  app.post('/api/students/:id/reset-parent-password', handleParentResetPassword);
  app.post('/api/parents/:phone/reset-password', handleParentResetPassword);
  app.post('/api/admin/parents/:phone/reset-password', handleParentResetPassword);

  // Update Parent Portal Access Status (handles /api/parents/:phone/portal-status and /api/admin/parents/:phone/portal-status)
  const handleParentPortalStatus = async (req: Request, res: Response) => {
    const { user: currentUser } = getAuthContext(req);
    if (!currentUser || !['SUPER_ADMIN', 'SCHOOL_ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'ADMIN'].includes(currentUser.role)) {
      return res.status(403).json({ success: false, error: 'Forbidden: Insufficient privileges to update parent portal access.' });
    }

    const { phone } = req.params;
    const { loginEnabled, accountStatus } = req.body;
    syncParentAccounts();
    const cleanPhone = normalizePhone(phone);
    let parent = parentAccounts.get(cleanPhone) || Array.from(parentAccounts.values()).find((p) => normalizePhone(p.phone) === cleanPhone);
    if (!parent && cleanPhone) {
      parent = {
        id: `parent-${cleanPhone}`,
        parentName: 'Parent / Guardian',
        phone: cleanPhone,
        studentIds: [],
        loginEnabled: loginEnabled !== false,
        accountStatus: accountStatus || 'ACTIVE',
        passwordHash: DEFAULT_STAFF_PASSWORD_HASH,
        failedLoginAttempts: 0,
      };
      parentAccounts.set(cleanPhone, parent);
    }

    // Also update any matching students' parent portal flags
    const matchedStudents = students.filter((s) => normalizePhone(s.parentPhone || s.fatherMobile || s.motherMobile) === cleanPhone);
    for (const st of matchedStudents) {
      if (loginEnabled !== undefined) (st as any).parentLoginEnabled = !!loginEnabled;
      if (accountStatus) (st as any).parentAccountStatus = accountStatus;
    }
    if (matchedStudents.length > 0) {
      persistentStorage.saveStudentsToDisk(students);
    }

    if (parent) {
      if (loginEnabled !== undefined) parent.loginEnabled = !!loginEnabled;
      if (accountStatus) parent.accountStatus = accountStatus;
      if (loginEnabled === false || accountStatus === 'INACTIVE' || accountStatus === 'SUSPENDED') {
        revokeUserSessions(parent.id);
        revokeUserSessions(`parent-${cleanPhone}`);
      }
    }

    logAudit(
      (req as any).currentUser?.name || 'Administrator',
      'SUPER_ADMIN',
      'PARENT_PORTAL_UPDATED',
      'Parent',
      cleanPhone,
      `Updated parent portal status for ${cleanPhone}: loginEnabled=${loginEnabled}, status=${accountStatus}`
    );

    res.json({ success: true, parent: parent || { phone: cleanPhone, loginEnabled, accountStatus } });
  };

  app.patch('/api/parents/:phone/portal-status', handleParentPortalStatus);
  app.post('/api/parents/:phone/portal-status', handleParentPortalStatus);
  app.patch('/api/admin/parents/:phone/portal-status', handleParentPortalStatus);
  app.post('/api/admin/parents/:phone/portal-status', handleParentPortalStatus);

  // --- GENERAL USER RESET PASSWORD & USER DIRECTORY (Supports authService calls) ---
  app.post('/api/users/:id/reset-password', async (req: Request, res: Response) => {
    const { user: currentUser } = getAuthContext(req);
    if (!currentUser || !['SUPER_ADMIN', 'SCHOOL_ADMIN', 'PRINCIPAL'].includes(currentUser.role)) {
      return res.status(403).json({ success: false, error: 'Forbidden: Insufficient privileges. Administrator access required.' });
    }

    const { id } = req.params;
    const { newPassword, forcePasswordChange = false } = req.body;

    if (!newPassword || String(newPassword).length < 6) {
      return res.status(400).json({ success: false, error: 'Password must be at least 6 characters long' });
    }

    const resolved = findEntityAnywhere('ANY', id);
    if (!resolved) {
      return res.status(404).json({ success: false, error: 'User not found' });
    }

    // Strict RBAC: Only Super Admin can reset another admin or Principal
    if ((resolved.role === 'SUPER_ADMIN' || resolved.type === 'ADMIN') && currentUser.role !== 'SUPER_ADMIN') {
      return res.status(403).json({ success: false, error: 'Access denied: Only Super Administrator can reset administrator account credentials.' });
    }
    if (resolved.role === 'PRINCIPAL' && currentUser.role !== 'SUPER_ADMIN') {
      return res.status(403).json({ success: false, error: 'Access denied: Only Super Administrator can reset Principal credentials.' });
    }
    const currentRank = ROLE_HIERARCHY[currentUser.role] || 0;
    const targetRank = ROLE_HIERARCHY[resolved.role] || 0;
    if (currentUser.role !== 'SUPER_ADMIN' && targetRank >= currentRank) {
      return res.status(403).json({
        success: false,
        error: `Access denied: You cannot reset credentials for an account with equal or higher rank (${resolved.role}).`,
      });
    }

    const cleanPass = String(newPassword).trim();
    resolved.entity.passwordHash = bcrypt.hashSync(cleanPass, 10);
    resolved.entity.failedLoginAttempts = 0;
    resolved.entity.lockoutUntil = undefined;
    resolved.entity.passwordResetToken = undefined;
    resolved.entity.passwordResetExpires = undefined;

    revokeUserSessions(resolved.entity.id);
    if (resolved.entity.employeeId) revokeUserSessions(resolved.entity.employeeId);
    if (resolved.entity.admissionNumber) revokeUserSessions(resolved.entity.admissionNumber);
    if (resolved.entity.username) revokeUserSessions(resolved.entity.username);

    if (resolved.type === 'STAFF') {
      persistentStorage.saveStaffToDisk(staff);
      if (mongoService.isConnected()) {
        await UserModel.updateOne(
          {
            $or: [
              { employeeId: resolved.entity.employeeId?.toUpperCase() },
              { employeeId: resolved.entity.employeeId },
              { id: resolved.entity.id },
              { id: `user-staff-${resolved.entity.id}` },
              { username: resolved.entity.employeeId?.toLowerCase() },
            ],
          },
          {
            $set: {
              passwordHash: resolved.entity.passwordHash,
              failedLoginAttempts: 0,
              lockoutUntil: null,
              status: 'ACTIVE',
              loginEnabled: true,
            },
          }
        );
        await mongoService.updateStaff(resolved.entity.id, {
          passwordHash: resolved.entity.passwordHash,
          failedLoginAttempts: 0,
          lockoutUntil: undefined,
          loginEnabled: true,
          status: 'ACTIVE',
          accountStatus: 'ACTIVE',
        });
      }
    }
    else if (resolved.type === 'STUDENT') persistentStorage.saveStudentsToDisk(students);
    else if (resolved.type === 'PARENT') persistentStorage.saveParentAccountsToDisk(Array.from(parentAccounts.values()));
    else if (resolved.type === 'ADMIN') persistentStorage.saveAdminAccountsToDisk(adminAccounts);

    logAudit(
      (req as any).currentUser?.name || 'Administrator',
      'SUPER_ADMIN',
      'USER_PASSWORD_RESET',
      resolved.type,
      id,
      `Reset password for ${resolved.identifier}`
    );

    res.json({ success: true, message: `Password successfully updated for ${resolved.identifier}` });
  });

  // =========================================================================
  // --- ROLE-BASED ACCESS CONTROL (RBAC) & PERMISSION MANAGEMENT ENDPOINTS ---
  // =========================================================================

  // 1. Get all registered permission definitions and module groupings
  app.get('/api/rbac/permissions', (req: Request, res: Response) => {
    res.json({
      success: true,
      modules: PERMISSION_MODULE_GROUPS,
      allPermissions: ALL_PERMISSION_KEYS,
      definitions: PERMISSIONS_BY_KEY,
    });
  });

  // 2. Get all 12 roles with default & customized permissions
  app.get('/api/rbac/roles', (req: Request, res: Response) => {
    const rolesList = (Object.keys(ROLE_HIERARCHY) as UserRole[]).map((r) => ({
      role: r,
      label: ROLE_LABELS[r] || r,
      rank: ROLE_HIERARCHY[r] || 0,
      permissions: customizedRolePermissions[r] || DEFAULT_ROLE_PERMISSIONS[r] || [],
      defaultPermissions: DEFAULT_ROLE_PERMISSIONS[r] || [],
      isCustomized: !!customizedRolePermissions[r],
    }));
    res.json({ success: true, roles: rolesList });
  });

  // 3. Update default permissions for a role (Requires permissions.manage or SUPER_ADMIN)
  app.put('/api/rbac/roles/:role/permissions', requirePermission('permissions.manage'), async (req: Request, res: Response) => {
    const currentUser = (req as any).currentUser as User;
    const targetRole = req.params.role as UserRole;
    const { permissions: newPermissions } = req.body;

    if (!ROLE_HIERARCHY[targetRole]) {
      return res.status(400).json({ success: false, error: `Invalid role: ${targetRole}` });
    }

    if (!Array.isArray(newPermissions)) {
      return res.status(400).json({ success: false, error: 'permissions must be an array of string permission keys' });
    }

    // Role hierarchy check: Actor cannot configure permissions for a role equal to or higher than their own rank unless SUPER_ADMIN
    if (currentUser.role !== 'SUPER_ADMIN') {
      const actorRank = ROLE_HIERARCHY[currentUser.role] || 0;
      const targetRank = ROLE_HIERARCHY[targetRole] || 0;
      if (targetRank >= actorRank) {
        return res.status(403).json({
          success: false,
          error: `Forbidden: You cannot modify permissions for role ${targetRole} as its rank is equal to or higher than yours.`,
        });
      }
    }

    customizedRolePermissions[targetRole] = newPermissions;

    // Persist to MongoDB Atlas if connected
    if (mongoService.isConnected()) {
      try {
        await RolePermissionModel.findOneAndUpdate(
          { role: targetRole },
          { role: targetRole, permissions: newPermissions },
          { upsert: true, new: true }
        );
      } catch (err: any) {
        console.warn('[RBAC] Error saving RolePermission to MongoDB:', err?.message);
      }
    }

    // Invalidate sessions for all users with this role so changes take effect immediately
    for (const [token, session] of activeSessions.entries()) {
      if (session.role === targetRole) {
        session.user = undefined;
      }
    }

    logAudit(
      currentUser.name,
      currentUser.role,
      'ROLE_PERMISSIONS_UPDATED',
      'RolePermission',
      targetRole,
      `Updated default permissions for role ${targetRole} (${newPermissions.length} permissions assigned)`
    );

    res.json({ success: true, role: targetRole, permissions: newPermissions });
  });

  // 4. Get users list with RBAC details
  app.get('/api/rbac/users', requirePermission(['users.view', 'roles.manage', 'permissions.manage']), (req: Request, res: Response) => {
    const { search, role, status, page = '1', limit = '100' } = req.query;

    const allUsersList: any[] = [];

    // Admins
    adminAccounts.forEach((a) => {
      const effPerms = getEffectivePermissions(
        a.role,
        (a as any).permissions || [],
        (a as any).deniedPermissions || [],
        customizedRolePermissions as any
      );
      allUsersList.push({
        id: a.id,
        name: a.name,
        username: a.username,
        email: a.email,
        phone: a.phone,
        role: a.role,
        status: a.status || 'ACTIVE',
        type: 'ADMIN',
        permissions: effPerms,
        customPermissions: (a as any).permissions || [],
        deniedPermissions: (a as any).deniedPermissions || [],
        avatar: (a as any).avatar || (a as any).photo || (a as any).photoFileKey || '',
      });
    });

    // Staff (support staff have no app login, so they have no access to configure)
    staff.forEach((s) => {
      const staffRole = (s.systemRole || s.role || 'TEACHER') as UserRole;
      if (isNoLoginStaffRole(staffRole)) return;
      const effPerms = getEffectivePermissions(
        staffRole,
        (s as any).permissions || [],
        (s as any).deniedPermissions || [],
        customizedRolePermissions as any
      );
      allUsersList.push({
        id: s.id,
        name: s.name,
        username: s.employeeId,
        employeeId: s.employeeId,
        email: s.email,
        phone: s.phone,
        role: staffRole,
        status: s.loginEnabled !== false && (s.status === 'ACTIVE' || (s.status as any) === 'Active') ? 'ACTIVE' : 'INACTIVE',
        type: 'STAFF',
        permissions: effPerms,
        customPermissions: (s as any).permissions || [],
        deniedPermissions: (s as any).deniedPermissions || [],
        avatar: s.photo || s.photoFileKey || '',
      });
    });

    let filtered = allUsersList;
    if (role && role !== 'ALL') {
      filtered = filtered.filter((u) => u.role === role);
    }
    if (status && status !== 'ALL') {
      filtered = filtered.filter((u) => u.status === status);
    }
    if (search) {
      const q = String(search).toLowerCase().trim();
      filtered = filtered.filter(
        (u) =>
          u.name?.toLowerCase().includes(q) ||
          u.username?.toLowerCase().includes(q) ||
          u.email?.toLowerCase().includes(q) ||
          u.phone?.toLowerCase().includes(q) ||
          u.employeeId?.toLowerCase().includes(q)
      );
    }

    const pageNum = Math.max(1, parseInt(page as string, 10) || 1);
    const limitNum = Math.max(1, parseInt(limit as string, 10) || 100);
    const startIndex = (pageNum - 1) * limitNum;
    const paginated = filtered.slice(startIndex, startIndex + limitNum);

    res.json({
      success: true,
      users: paginated,
      total: filtered.length,
      page: pageNum,
      limit: limitNum,
      totalPages: Math.ceil(filtered.length / limitNum) || 1,
    });
  });

  // 5. Update user role (Requires roles.manage or SUPER_ADMIN)
  app.put('/api/rbac/users/:id/role', requirePermission('roles.manage'), async (req: Request, res: Response) => {
    const currentUser = (req as any).currentUser as User;
    const { id } = req.params;
    const { role: newRole } = req.body as { role: UserRole };

    if (!newRole || !ROLE_HIERARCHY[newRole]) {
      return res.status(400).json({ success: false, error: `Invalid role: ${newRole}` });
    }
    if (isNoLoginStaffRole(newRole)) {
      return res.status(400).json({ success: false, error: 'Support staff have no app login. Change it from the staff record (Teachers & Staff → Edit) instead.' });
    }

    const match = findAuthEntityById(id);
    if (!match) {
      return res.status(404).json({ success: false, error: 'User not found' });
    }

    // 1. Self modification safeguard: users cannot change their own role!
    if (currentUser.id === id || (currentUser.username && currentUser.username.toLowerCase() === id.toLowerCase())) {
      return res.status(403).json({ success: false, error: 'Self-modification forbidden: You cannot change or elevate your own role.' });
    }

    // 2. Role delegation safeguards:
    const delegationCheck = canAssignRole(currentUser.role, newRole);
    if (!delegationCheck.allowed && currentUser.role !== 'SUPER_ADMIN') {
      return res.status(403).json({ success: false, error: delegationCheck.reason });
    }

    const manageCheck = canManageUserAccount(currentUser.role, match.role);
    if (!manageCheck.allowed && currentUser.role !== 'SUPER_ADMIN') {
      return res.status(403).json({ success: false, error: manageCheck.reason });
    }

    // 3. Super Admin protection: Cannot demote the last active Super Admin!
    if (match.role === 'SUPER_ADMIN' && newRole !== 'SUPER_ADMIN') {
      const activeSuperAdmins = adminAccounts.filter((a) => a.role === 'SUPER_ADMIN' && a.status === 'ACTIVE');
      if (activeSuperAdmins.length <= 1) {
        return res.status(403).json({
          success: false,
          error: 'Protection violation: Cannot demote the last active Super Administrator. At least one Super Admin must remain active.',
        });
      }
    }

    const previousRole = match.role;

    // Apply role update to in-memory entity
    if (match.type === 'ADMIN') {
      match.entity.role = newRole as any;
      persistentStorage.saveAdminAccountsToDisk(adminAccounts);
    } else if (match.type === 'STAFF') {
      match.entity.systemRole = newRole;
      match.entity.role = newRole;
      persistentStorage.saveStaffToDisk(staff);
    }

    const entityUsername = (match.entity as any).username;

    // Update in MongoDB UserModel if connected
    if (mongoService.isConnected()) {
      try {
        const queryOr: any[] = [{ id }, { id: match.entity.id }];
        if (entityUsername) queryOr.push({ username: entityUsername });
        await UserModel.updateOne(
          { $or: queryOr },
          { $set: { role: newRole } }
        );
      } catch (err: any) {
        console.warn('[RBAC] Error updating role in MongoDB:', err?.message);
      }
    }

    // Invalidate user sessions so updated role takes effect immediately
    revokeUserSessions(id);
    if (entityUsername) revokeUserSessions(entityUsername);

    logAudit(
      currentUser.name,
      currentUser.role,
      'USER_ROLE_CHANGED',
      'User',
      id,
      `Changed role for ${match.entity.name || id} from ${previousRole} to ${newRole}`
    );

    const updatedUser = buildSafeUser(match);
    res.json({ success: true, user: updatedUser, previousRole, newRole });
  });

  // 6. Update user granular custom permissions (Requires permissions.manage or SUPER_ADMIN)
  app.put('/api/rbac/users/:id/permissions', requirePermission('permissions.manage'), async (req: Request, res: Response) => {
    const currentUser = (req as any).currentUser as User;
    const { id } = req.params;
    const { permissions: customPermissions = [], deniedPermissions = [] } = req.body;

    const match = findAuthEntityById(id);
    if (!match) {
      return res.status(404).json({ success: false, error: 'User not found' });
    }

    // 1. Self modification safeguard: users cannot modify their own permissions!
    if (currentUser.id === id || (currentUser.username && currentUser.username.toLowerCase() === id.toLowerCase())) {
      return res.status(403).json({ success: false, error: 'Self-modification forbidden: You cannot grant or modify your own permissions.' });
    }

    // 2. Cannot modify a user with equal or higher rank unless SUPER_ADMIN
    const manageCheck = canManageUserAccount(currentUser.role, match.role);
    if (!manageCheck.allowed && currentUser.role !== 'SUPER_ADMIN') {
      return res.status(403).json({ success: false, error: manageCheck.reason });
    }

    // 3. Actor cannot grant any permission they do not personally possess (unless SUPER_ADMIN)
    if (currentUser.role !== 'SUPER_ADMIN') {
      const actorPerms = currentUser.permissions || DEFAULT_ROLE_PERMISSIONS[currentUser.role] || [];
      for (const p of customPermissions) {
        if (!actorPerms.includes(p)) {
          return res.status(403).json({
            success: false,
            error: `Delegation violation: You cannot grant permission "${p}" because you do not possess this permission yourself.`,
          });
        }
      }
    }

    // Apply to in-memory entity
    (match.entity as any).permissions = customPermissions;
    (match.entity as any).deniedPermissions = deniedPermissions;

    if (match.type === 'ADMIN') {
      persistentStorage.saveAdminAccountsToDisk(adminAccounts);
    } else if (match.type === 'STAFF') {
      persistentStorage.saveStaffToDisk(staff);
    }

    const entityUsername = (match.entity as any).username;

    // Persist to MongoDB UserModel if connected
    if (mongoService.isConnected()) {
      try {
        const queryOr: any[] = [{ id }, { id: match.entity.id }];
        if (entityUsername) queryOr.push({ username: entityUsername });
        await UserModel.updateOne(
          { $or: queryOr },
          { $set: { permissions: customPermissions, deniedPermissions } }
        );
      } catch (err: any) {
        console.warn('[RBAC] Error updating permissions in MongoDB:', err?.message);
      }
    }

    // Invalidate user sessions immediately
    revokeUserSessions(id);
    if (entityUsername) revokeUserSessions(entityUsername);

    logAudit(
      currentUser.name,
      currentUser.role,
      'USER_PERMISSIONS_UPDATED',
      'User',
      id,
      `Updated permissions for ${match.entity.name || id}: ${customPermissions.length} custom granted, ${deniedPermissions.length} revoked`
    );

    const updatedUser = buildSafeUser(match);
    res.json({ success: true, user: updatedUser });
  });

  // Unified Users Directory (useful for user account administration)
  app.get('/api/users', requirePermission('users.view'), (req: Request, res: Response) => {
    const allUsers: Array<{
      id: string;
      name: string;
      username: string;
      email?: string;
      phone?: string;
      role: UserRole;
      status: 'ACTIVE' | 'INACTIVE' | 'SUSPENDED';
      type: string;
      permissions: string[];
    }> = [];

    adminAccounts.forEach((a) => {
      const effPerms = getEffectivePermissions(
        a.role,
        (a as any).permissions || [],
        (a as any).deniedPermissions || [],
        customizedRolePermissions as any
      );
      allUsers.push({
        id: a.id,
        name: a.name,
        username: a.username,
        email: a.email,
        phone: a.phone,
        role: a.role,
        status: a.status || 'ACTIVE',
        type: 'ADMIN',
        permissions: effPerms,
      });
    });

    staff.forEach((s) => {
      const staffRole = (s.systemRole || s.role || 'TEACHER') as UserRole;
      const effPerms = getEffectivePermissions(
        staffRole,
        (s as any).permissions || [],
        (s as any).deniedPermissions || [],
        customizedRolePermissions as any
      );
      allUsers.push({
        id: s.id,
        name: s.name,
        username: s.employeeId,
        email: s.email,
        phone: s.phone,
        role: staffRole,
        status: s.loginEnabled !== false && (s.status === 'ACTIVE' || (s.status as any) === 'Active') ? 'ACTIVE' : 'INACTIVE',
        type: 'STAFF',
        permissions: effPerms,
      });
    });

    res.json({ success: true, users: allUsers });
  });

  app.get('/api/users/:id', requirePermission('users.view'), (req: Request, res: Response) => {
    const { id } = req.params;
    const match = findAuthEntityById(id);
    if (!match) {
      return res.status(404).json({ success: false, error: 'User not found' });
    }
    const safeUser = buildSafeUser(match);
    res.json({ success: true, user: safeUser });
  });

  app.put(['/api/users/:id/status', '/api/users/:id'], requirePermission('users.manage'), (req: Request, res: Response) => {
    const currentUser = (req as any).currentUser as User;
    const { id } = req.params;
    const { status } = req.body;

    const target = adminAccounts.find((a) => a.id === id || a.username.toLowerCase() === id.toLowerCase());
    if (target) {
      // Super admin deactivation check
      if (target.role === 'SUPER_ADMIN' && status && status !== 'ACTIVE') {
        const activeSuperAdmins = adminAccounts.filter((a) => a.role === 'SUPER_ADMIN' && a.status === 'ACTIVE');
        if (activeSuperAdmins.length <= 1) {
          return res.status(403).json({
            success: false,
            error: 'Protection violation: Cannot deactivate the last active Super Administrator.',
          });
        }
      }
      if (status) target.status = status;
      persistentStorage.saveAdminAccountsToDisk(adminAccounts);
      logAudit(currentUser.name, currentUser.role, 'USER_STATUS_CHANGED', 'AdminAccount', target.id, `Status set to ${status}`);
      return res.json({ success: true, user: target });
    }

    const targetStaff = staff.find((s) => s.id === id || s.employeeId?.toLowerCase() === id.toLowerCase());
    if (targetStaff) {
      if (status) {
        targetStaff.accountStatus = status;
        targetStaff.status = status;
        targetStaff.loginEnabled = status === 'ACTIVE';
      }
      persistentStorage.saveStaffToDisk(staff);
      logAudit(currentUser.name, currentUser.role, 'USER_STATUS_CHANGED', 'Staff', targetStaff.id, `Status set to ${status}`);
      return res.json({ success: true, user: targetStaff });
    }

    const targetStudent = students.find((s) => s.id === id || s.admissionNumber === id);
    if (targetStudent) {
      if (status) targetStudent.accountStatus = status;
      persistentStorage.saveStudentsToDisk(students);
      logAudit(currentUser.name, currentUser.role, 'USER_STATUS_CHANGED', 'Student', targetStudent.id, `Status set to ${status}`);
      return res.json({ success: true, user: targetStudent });
    }
    res.status(404).json({ success: false, error: 'User not found' });
  });

  app.delete('/api/users/:id', requirePermission('users.manage'), (req: Request, res: Response) => {
    const currentUser = (req as any).currentUser as User;
    const { id } = req.params;

    const targetAdmin = adminAccounts.find((a) => a.id === id || a.username.toLowerCase() === id.toLowerCase());
    if (targetAdmin && targetAdmin.role === 'SUPER_ADMIN') {
      const activeSuperAdmins = adminAccounts.filter((a) => a.role === 'SUPER_ADMIN' && a.status === 'ACTIVE');
      if (activeSuperAdmins.length <= 1) {
        return res.status(403).json({
          success: false,
          error: 'Protection violation: Cannot delete the last active Super Administrator.',
        });
      }
    }

    const adminIdx = adminAccounts.findIndex((a) => a.id === id || a.username.toLowerCase() === id.toLowerCase());
    if (adminIdx !== -1) {
      if (adminAccounts[adminIdx].username === INITIAL_ADMIN_USERNAME || adminAccounts[adminIdx].username === 'admin') {
        return res.status(403).json({ success: false, error: 'Cannot delete root admin account' });
      }
      const [deleted] = adminAccounts.splice(adminIdx, 1);
      persistentStorage.saveAdminAccountsToDisk(adminAccounts);
      logAudit(currentUser.name, currentUser.role, 'USER_DELETED', 'AdminAccount', id, `Deleted administrator ${deleted.username}`);
      return res.json({ success: true, message: 'Admin deleted', user: deleted });
    }

    const staffIdx = staff.findIndex((s) => s.id === id || s.employeeId?.toLowerCase() === id.toLowerCase());
    if (staffIdx !== -1) {
      const [deleted] = staff.splice(staffIdx, 1);
      persistentStorage.saveStaffToDisk(staff);
      logAudit(currentUser.name, currentUser.role, 'USER_DELETED', 'Staff', id, `Deleted staff account ${deleted.name} (${deleted.employeeId})`);
      return res.json({ success: true, message: 'Staff deleted', user: deleted });
    }

    res.json({ success: true, message: 'User processed' });
  });

  // --- SCHOOL ADMIN ACCOUNTS SYSTEM (SUPER_ADMIN / SCHOOL_ADMIN) ---

  // List Admin Accounts
  app.get('/api/admin/accounts', requireRole(['SUPER_ADMIN', 'SCHOOL_ADMIN']), (req: Request, res: Response) => {
    const safeAccounts = adminAccounts.map(({ passwordHash, ...safe }) => safe);
    res.json({ success: true, accounts: safeAccounts });
  });

  // Create Admin Account
  app.post('/api/admin/accounts', requireRole(['SUPER_ADMIN']), (req: Request, res: Response) => {
    const currentUser = (req as any).currentUser as User;
    const { name, username, email, phone, role, password, status = 'ACTIVE' } = req.body;

    if (!name || !username || !email || !role || !password) {
      return res.status(400).json({ success: false, error: 'Name, Username, Email, Role, and Password are required' });
    }

    const cleanUsername = String(username).trim().toLowerCase();
    const existing = adminAccounts.find((a) => a.username.toLowerCase() === cleanUsername);
    if (existing) {
      return res.status(409).json({ success: false, error: `Username "${cleanUsername}" is already taken.` });
    }

    const cleanEmail = String(email).trim().toLowerCase();
    const existingEmail = adminAccounts.find((a) => a.email.toLowerCase() === cleanEmail);
    if (existingEmail) {
      return res.status(409).json({ success: false, error: `Email "${cleanEmail}" is already registered.` });
    }

    const newAdmin: InternalAdminAccount = {
      id: `admin-${Date.now()}`,
      name: String(name).trim(),
      username: cleanUsername,
      email: cleanEmail,
      phone: String(phone || '').trim(),
      role: role as 'SUPER_ADMIN' | 'SCHOOL_ADMIN',
      status: status as 'ACTIVE' | 'INACTIVE',
      createdAt: new Date().toISOString(),
      passwordHash: bcrypt.hashSync(String(password).trim(), 10),
      failedLoginAttempts: 0,
    };

    adminAccounts.push(newAdmin);
    persistentStorage.saveAdminAccountsToDisk(adminAccounts);
    logAudit(currentUser.name, currentUser.role as UserRole, 'ADMIN_ACCOUNT_CREATED', 'AdminAccount', newAdmin.id, `Created ${newAdmin.role} account (${newAdmin.username})`);

    const { passwordHash, ...safe } = newAdmin;
    res.status(201).json({ success: true, account: safe });
  });

  // Update Admin Account Status
  app.patch('/api/admin/accounts/:id/status', requireRole(['SUPER_ADMIN']), (req: Request, res: Response) => {
    const currentUser = (req as any).currentUser as User;
    const { id } = req.params;
    const { status } = req.body;

    if (!['ACTIVE', 'INACTIVE'].includes(status)) {
      return res.status(400).json({ success: false, error: 'Status must be ACTIVE or INACTIVE' });
    }

    const target = adminAccounts.find((a) => a.id === id);
    if (!target) return res.status(404).json({ success: false, error: 'Admin account not found' });

    if (currentUser.id === target.id) {
      return res.status(400).json({ success: false, error: 'You cannot alter your own active status' });
    }

    if (target.username === INITIAL_ADMIN_USERNAME || target.username === 'admin') {
      return res.status(403).json({ success: false, error: 'Root administrator account cannot be deactivated' });
    }

    target.status = status;

    if (status === 'INACTIVE') {
      revokeUserSessions(target.id);
    }

    persistentStorage.saveAdminAccountsToDisk(adminAccounts);
    logAudit(currentUser.name, currentUser.role as UserRole, 'ADMIN_STATUS_CHANGED', 'AdminAccount', target.id, `Updated admin ${target.username} status to ${status}`);
    const { passwordHash, ...safe } = target;
    res.json({ success: true, account: safe });
  });

  // Reset Admin Account Password (handles /api/admin/accounts/:id/reset-password AND /api/admin/admins/:id/reset-password)
  const handleAdminResetPassword = async (req: Request, res: Response) => {
    const { user: currentUser } = getAuthContext(req);
    if (!currentUser || currentUser.role !== 'SUPER_ADMIN') {
      return res.status(403).json({ success: false, error: 'Forbidden: Only Super Administrator can reset administrator account credentials.' });
    }
    const { id } = req.params;
    const { newPassword, sendEmail = true, temporaryPassword = false } = req.body;

    if (!newPassword || String(newPassword).length < 6) {
      return res.status(400).json({ success: false, error: 'Password must be at least 6 characters long' });
    }

    const target = adminAccounts.find((a) => a.id === id || a.username.toLowerCase() === id.toLowerCase());
    if (!target) return res.status(404).json({ success: false, error: 'Admin account not found' });

    const cleanPass = String(newPassword).trim();
    target.passwordHash = bcrypt.hashSync(cleanPass, 10);
    target.failedLoginAttempts = 0;
    target.lockoutUntil = undefined;
    target.passwordResetToken = undefined;
    target.passwordResetExpires = undefined;

    revokeUserSessions(target.id);
    if (target.username) revokeUserSessions(target.username);

    persistentStorage.saveAdminAccountsToDisk(adminAccounts);
    if (mongoService.isConnected()) {
      await UserModel.updateOne(
        {
          $or: [
            { id: target.id },
            { username: target.username.toLowerCase() },
            { email: (target.email || '').toLowerCase() },
          ],
        },
        {
          $set: {
            passwordHash: target.passwordHash,
            failedLoginAttempts: 0,
            lockoutUntil: null,
            status: 'ACTIVE',
          },
        }
      ).catch((err) => {
        console.warn('[Server] Error updating admin bcrypt hash in MongoDB:', err?.message);
      });
    }

    let emailDispatched = false;
    if (sendEmail && target.email) {
      const portalBaseUrl = process.env.FRONTEND_URL || `${req.protocol}://${req.get('host')}` || 'http://localhost:3000';
      try {
        if (temporaryPassword) {
          const emailRes = await emailService.sendTemporaryPasswordEmail({
            to: target.email,
            userName: target.name,
            roleName: target.role,
            identifier: target.username,
            temporaryPassword: cleanPass,
            portalUrl: portalBaseUrl,
            schoolName: schoolSettings.schoolName || 'CHANAKYA PUBLIC SCHOOL & COACHING CENTRE',
          });
          emailDispatched = emailRes.success;
        } else {
          const emailRes = await emailService.sendPasswordChangedConfirmation({
            to: target.email,
            userName: target.name,
            identifier: target.username,
            schoolName: schoolSettings.schoolName || 'CHANAKYA PUBLIC SCHOOL & COACHING CENTRE',
            portalUrl: portalBaseUrl,
          });
          emailDispatched = emailRes.success;
        }
      } catch (err: any) {
        console.warn('[Server] Error dispatching admin email:', err?.message);
      }
    }

    logAudit(currentUser.name, currentUser.role as UserRole, 'ADMIN_PASSWORD_RESET', 'AdminAccount', target.id, `Reset password for admin ${target.username}`);
    res.json({
      success: true,
      message: `Password reset successfully for admin ${target.username}`,
      emailDispatched,
      email: target.email,
    });
  };

  app.post('/api/admin/accounts/:id/reset-password', handleAdminResetPassword);
  app.post('/api/admin/admins/:id/reset-password', handleAdminResetPassword);

  // Update Admin Account (Super Admin can manage other admin accounts)
  app.put('/api/admin/accounts/:id', requireRole(['SUPER_ADMIN']), (req: Request, res: Response) => {
    const currentUser = (req as any).currentUser as User;
    const { id } = req.params;
    const updates = req.body || {};

    const target = adminAccounts.find((a) => a.id === id || a.username.toLowerCase() === id.toLowerCase());
    if (!target) return res.status(404).json({ success: false, error: 'Admin account not found' });

    if (updates.name !== undefined) target.name = String(updates.name).trim();
    if (updates.email !== undefined) target.email = String(updates.email).trim().toLowerCase();
    if (updates.phone !== undefined) target.phone = String(updates.phone).trim();
    if (updates.address !== undefined) target.address = String(updates.address).trim();
    if (updates.avatar !== undefined || updates.photo !== undefined) {
      target.avatar = updates.avatar || updates.photo;
      target.photo = target.avatar;
    }
    if (updates.status !== undefined && ['ACTIVE', 'INACTIVE'].includes(updates.status)) {
      if (target.username !== INITIAL_ADMIN_USERNAME && target.username !== 'admin') target.status = updates.status;
    }

    persistentStorage.saveAdminAccountsToDisk(adminAccounts);
    logAudit(currentUser.name, currentUser.role as UserRole, 'ADMIN_ACCOUNT_UPDATED', 'AdminAccount', target.id, `Updated admin account ${target.username}`);
    const { passwordHash, ...safe } = target;
    res.json({ success: true, account: safe, message: 'Admin account updated successfully' });
  });

  // Delete Admin Account
  app.delete(['/api/admin/accounts/:id', '/api/admin/admins/:id'], requireRole(['SUPER_ADMIN']), (req: Request, res: Response) => {
    const currentUser = (req as any).currentUser as User;
    const { id } = req.params;

    if (currentUser.id === id) {
      return res.status(400).json({ success: false, error: 'You cannot delete your own account' });
    }

    const targetIndex = adminAccounts.findIndex((a) => a.id === id || a.username.toLowerCase() === id.toLowerCase());
    if (targetIndex === -1) return res.status(404).json({ success: false, error: 'Admin account not found' });

    const target = adminAccounts[targetIndex];
    if (target.username === INITIAL_ADMIN_USERNAME || target.username === 'admin') {
      return res.status(403).json({ success: false, error: 'Root administrator account cannot be deleted' });
    }

    const deletedId = target.id;
    adminAccounts.splice(targetIndex, 1);
    persistentStorage.deleteAdminAccountFromDisk(deletedId);
    persistentStorage.saveAdminAccountsToDisk(adminAccounts);

    revokeUserSessions(deletedId);

    logAudit(currentUser.name, currentUser.role as UserRole, 'ADMIN_DELETED', 'AdminAccount', deletedId, `Deleted admin account ${target.username}`);
    broadcastRealtimeEvent('ADMIN_ACCOUNT', 'DELETE', { id: deletedId, username: target.username }, { description: `Deleted admin account ${target.username}` });
    res.json({ success: true, message: `Admin account ${target.username} has been deleted` });
  });

  // --- EMAIL DELIVERY STATUS & TEST TRANSMISSION ---
  app.get('/api/email/status', requireRole(filePolicy.SETTINGS_ROLES), (req: Request, res: Response) => {
    res.json({
      success: true,
      ...emailService.getStatus(),
    });
  });

  app.post('/api/email/test', requireRole(filePolicy.SETTINGS_ROLES), async (req: Request, res: Response) => {
    const { to } = req.body;
    if (!to) {
      return res.status(400).json({ success: false, error: 'Recipient email address is required' });
    }

    const portalBaseUrl = process.env.FRONTEND_URL || `${req.protocol}://${req.get('host')}` || 'http://localhost:3000';
    const result = await emailService.sendEmail({
      to: String(to).trim(),
      subject: `[${schoolSettings.schoolName || 'CHANAKYA PUBLIC SCHOOL & COACHING CENTRE'}] Institutional Brevo Delivery Test`,
      html: `
        <div style="font-family: Arial, sans-serif; padding: 24px; background: #f8fafc; border-radius: 12px; border: 1px solid #e2e8f0; max-width: 500px;">
          <h2 style="color: #1e3a8a; margin-top: 0;">Brevo Delivery Test Successful</h2>
          <p>This is a verified test email sent from the <strong>${schoolSettings.schoolName || 'CHANAKYA PUBLIC SCHOOL & COACHING CENTRE'}</strong> ERP backend via Brevo API.</p>
          <p style="font-size: 12px; color: #64748b;">Timestamp: ${new Date().toISOString()}</p>
          <a href="${portalBaseUrl}" style="display: inline-block; background: #1e3a8a; color: #fff; padding: 10px 20px; border-radius: 6px; text-decoration: none;">Go to School Portal</a>
        </div>
      `,
    });

    res.json(result);
  });

  // Dynamic Favicon: serves current school logo configured in School Settings
  app.get(['/favicon.ico', '/api/favicon', '/api/school-logo/favicon'], async (req: Request, res: Response) => {
    try {
      const rawLogo = schoolSettings.schoolLogo || schoolSettings.logoFileKey || '';
      if (!rawLogo) {
        return res.status(204).end();
      }

      if (rawLogo.startsWith('http://') || rawLogo.startsWith('https://')) {
        return res.redirect(302, rawLogo);
      }

      const cleanKey = rawLogo.replace(/^\/+/, '');
      const file = await persistentStorage.getFile(cleanKey);
      if (file && file.data) {
        res.setHeader('Content-Type', file.contentType || 'image/png');
        res.setHeader('Cache-Control', 'public, max-age=86400');
        res.setHeader('Access-Control-Allow-Origin', '*');
        res.setHeader('Cross-Origin-Resource-Policy', 'cross-origin');
        return res.send(file.data);
      }

      return res.redirect(302, `/api/files/content?key=${encodeURIComponent(cleanKey)}`);
    } catch {
      return res.status(204).end();
    }
  });

  // Settings
  // GET /api/app/version — public. The mobile app asks this on every launch / return to the foreground and
  // shows the "New update available" popup while its own build number is below latestVersionCode.
  // Set in School Settings → Mobile App Update (or APP_ANDROID_LATEST_VERSION_CODE / APP_ANDROID_MIN_VERSION_CODE env).
  app.get('/api/app/version', (_req: Request, res: Response) => {
    const cfg: any = (schoolSettings as any).mobileAppUpdate || {};
    const num = (v: any) => (Number.isFinite(Number(v)) && Number(v) > 0 ? Math.floor(Number(v)) : 0);
    const latestVersionCode = num(cfg.latestVersionCode) || num(process.env.APP_ANDROID_LATEST_VERSION_CODE);
    const minVersionCode = Math.min(num(cfg.minVersionCode) || num(process.env.APP_ANDROID_MIN_VERSION_CODE), latestVersionCode || Infinity) || 0;
    const storeUrl = /^https:\/\/play\.google\.com\//.test(String(cfg.storeUrl || ''))
      ? String(cfg.storeUrl)
      : 'https://play.google.com/store/apps/details?id=in.chanakyapublicschool.app';
    res.setHeader('Cache-Control', 'no-store');
    res.json({
      success: true,
      android: {
        latestVersionCode,
        latestVersionName: String(cfg.latestVersionName || process.env.APP_ANDROID_LATEST_VERSION_NAME || ''),
        minVersionCode,
        message: String(cfg.message || '').slice(0, 500),
        storeUrl,
        packageName: 'in.chanakyapublicschool.app',
      },
    });
  });

  app.get(['/api/settings', '/api/school-settings'], (req: Request, res: Response) => {
    // Public visitors get the school profile; the principal's signature image is for signed-in staff only.
    if (getAuthContext(req).user) return res.json(schoolSettings);
    const { principalSignature, principalSignatureFileKey, examControllerSignature, examControllerSignatureFileKey, ...publicSettings } = schoolSettings as any;
    res.json(publicSettings);
  });

  const handleUpdateSettings = async (req: Request, res: Response) => {
    if (!req.body || typeof req.body !== 'object' || Array.isArray(req.body)) {
      return res.status(400).json({ success: false, error: 'Invalid settings payload.' });
    }
    // Only plain settings fields are accepted: no prototype keys, no secret-like keys, bounded text.
    const BLOCKED = new Set(['_id', '__proto__', 'constructor', 'prototype', 'singleSchool', 'updatedAt', 'createdAt', 'id']);
    const cleanBody: Record<string, any> = {};
    const bounded = (v: any, depth = 0): any => {
      if (typeof v === 'string') return v.slice(0, 5000);
      if (typeof v === 'number' || typeof v === 'boolean' || v === null) return v;
      if (depth > 4) return undefined;
      if (Array.isArray(v)) return v.slice(0, 200).map((x) => bounded(x, depth + 1));
      if (v && typeof v === 'object') {
        const o: Record<string, any> = {};
        for (const [k, x] of Object.entries(v)) if (!BLOCKED.has(k)) o[k] = bounded(x, depth + 1);
        return o;
      }
      return undefined;
    };
    for (const [k, v] of Object.entries(req.body || {})) {
      if (BLOCKED.has(k) || /secret|password|token|apikey|api_key|privatekey/i.test(k)) continue;
      const b = bounded(v);
      if (b !== undefined) cleanBody[k] = b;
    }
    const changedKeys = Object.keys(cleanBody).filter((k) => JSON.stringify((schoolSettings as any)[k]) !== JSON.stringify(cleanBody[k]));
    if (Array.isArray(cleanBody.gradingSystem)) {
      cleanBody.gradingSystem = cleanBody.gradingSystem.map((g: any) => {
        const isFail = Number(g.minPercentage) < 33 || g.grade === 'E/F' || g.grade === 'E' || g.grade === 'F';
        return {
          ...g,
          grade: isFail ? 'E/F' : g.grade,
          minPercentage: isFail ? 0 : Number(g.minPercentage),
          maxPercentage: isFail ? 32 : Number(g.maxPercentage),
          gradePoint: isFail ? 0 : Number(g.gradePoint),
          status: isFail ? 'FAIL' : 'PASS',
          remark: isFail ? 'Essential Repeat' : (g.remark || g.description || 'Pass'),
          description: isFail ? 'Essential Repeat' : (g.description || g.remark || 'Pass'),
        };
      });
    }
    schoolSettings = { ...schoolSettings, ...cleanBody, singleSchool: true } as SchoolSettings;
    persistentStorage.saveSchoolSettingsToDisk(schoolSettings);
    if (mongoService.isConnected()) {
      try {
        await mongoService.saveSchoolSettings(schoolSettings);
      } catch (err) {
        console.warn('[server] Error syncing settings to MongoDB:', err);
      }
    }
    const currentUser = (req as any).currentUser;
    const actorName = currentUser?.name || 'Administrator';
    const actorRole = currentUser?.role || 'SUPER_ADMIN';
    logAudit(actorName, actorRole, 'SETTINGS_UPDATED', 'SchoolSettings', 'config', changedKeys.length ? `Changed: ${changedKeys.slice(0, 30).join(', ')}` : 'Saved school settings (no changes)');
    broadcastRealtimeEvent('SETTINGS', 'UPDATE', schoolSettings, { description: 'Updated school configurations' });
    res.json(schoolSettings);
  };

  app.put(['/api/settings', '/api/school-settings'], requirePermission('settings.manage'), handleUpdateSettings);
  app.patch(['/api/settings', '/api/school-settings'], requirePermission('settings.manage'), handleUpdateSettings);

  app.get(['/api/settings/exam-types', '/api/exam-types'], (req: Request, res: Response) => {
    res.json({ success: true, customExamTypes: schoolSettings.customExamTypes || [] });
  });

  app.post(['/api/settings/exam-types', '/api/exam-types'], requireRole(['SUPER_ADMIN', 'SCHOOL_ADMIN', 'PRINCIPAL', 'ACADEMIC_COORDINATOR', 'VICE_PRINCIPAL']), async (req: Request, res: Response) => {
    const rawName = (req.body?.name || req.body?.examType || '').trim();
    if (!rawName) {
      return res.status(400).json({ error: 'Exam type name is required.' });
    }

    if (!Array.isArray(schoolSettings.customExamTypes)) {
      schoolSettings.customExamTypes = [];
    }

    if (!schoolSettings.customExamTypes.includes(rawName)) {
      schoolSettings.customExamTypes.push(rawName);
      persistentStorage.saveSchoolSettingsToDisk(schoolSettings);
      if (mongoService.isConnected()) {
        try {
          await mongoService.saveSchoolSettings(schoolSettings);
        } catch (err) {
          console.warn('[server] Error syncing settings to MongoDB:', err);
        }
      }
      broadcastRealtimeEvent('SETTINGS', 'UPDATE', schoolSettings, { description: `Added custom exam type: ${rawName}` });
    }

    res.json({ success: true, customExamTypes: schoolSettings.customExamTypes, added: rawName });
  });

  // Academic Sessions
  app.get('/api/academic-sessions', (req: Request, res: Response) => {
    if (!schoolSettings.academicSessions || schoolSettings.academicSessions.length === 0) {
      schoolSettings.academicSessions = [
        {
          id: 'ses-1',
          name: '2026-2027',
          startDate: '2026-04-01',
          endDate: '2027-03-31',
          status: 'ACTIVE',
          description: 'Current regular academic session (Active)',
          isDefault: true,
          createdAt: new Date().toISOString(),
        },
        {
          id: 'ses-2',
          name: '2025-2026',
          startDate: '2025-04-01',
          endDate: '2026-03-31',
          status: 'INACTIVE',
          description: 'Preceding academic session (Archived)',
          isDefault: false,
          createdAt: new Date().toISOString(),
        },
        {
          id: 'ses-3',
          name: '2027-2028',
          startDate: '2027-04-01',
          endDate: '2028-03-31',
          status: 'INACTIVE',
          description: 'Upcoming academic session (Planned)',
          isDefault: false,
          createdAt: new Date().toISOString(),
        },
      ];
    }
    res.json(schoolSettings.academicSessions);
  });

  app.post(
    '/api/academic-sessions',
    requireRole(['SUPER_ADMIN', 'SCHOOL_ADMIN', 'ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'ACADEMIC_COORDINATOR']),
    (req: Request, res: Response) => {
    const { user } = getAuthContext(req);
    const { name, startDate, endDate, status, description } = req.body;
    if (!name || !startDate || !endDate) {
      return res.status(400).json({ error: 'Name, start date, and end date are required.' });
    }
    if (!schoolSettings.academicSessions) {
      schoolSettings.academicSessions = [];
    }
    const newSession = {
      id: `ses-${Date.now()}`,
      name: name.trim(),
      startDate,
      endDate,
      status: status || 'INACTIVE',
      description: description?.trim(),
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };
    if (newSession.status === 'ACTIVE') {
      schoolSettings.academicSessions.forEach((s: any) => (s.status = 'INACTIVE'));
      schoolSettings.currentAcademicSession = newSession.name;
    }
    schoolSettings.academicSessions.push(newSession as any);
    persistentStorage.saveSchoolSettingsToDisk(schoolSettings);
    logAudit(user?.name || 'Administrator', user?.role || 'SUPER_ADMIN', 'SESSION_CREATED', 'AcademicSession', newSession.id, `Created academic session ${newSession.name}`);
    broadcastRealtimeEvent('SESSION', 'CREATE', newSession, { academicSession: newSession.name, description: `Created academic session ${newSession.name}` });
    res.json(newSession);
  });

  app.put(
    '/api/academic-sessions/:id',
    requireRole(['SUPER_ADMIN', 'SCHOOL_ADMIN', 'ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'ACADEMIC_COORDINATOR']),
    (req: Request, res: Response) => {
    const { user } = getAuthContext(req);
    const { id } = req.params;
    if (!schoolSettings.academicSessions) {
      return res.status(404).json({ error: 'Session not found' });
    }
    const ses = schoolSettings.academicSessions.find((s: any) => s.id === id);
    if (!ses) {
      return res.status(404).json({ error: 'Session not found' });
    }
    const { name, startDate, endDate, status, description } = req.body;
    if (name) ses.name = name.trim();
    if (startDate) ses.startDate = startDate;
    if (endDate) ses.endDate = endDate;
    if (description !== undefined) ses.description = description;
    ses.updatedAt = new Date().toISOString();

    if (status === 'ACTIVE') {
      schoolSettings.academicSessions.forEach((s: any) => (s.status = s.id === id ? 'ACTIVE' : 'INACTIVE'));
      schoolSettings.currentAcademicSession = ses.name;
    } else if (status === 'INACTIVE' && ses.status === 'ACTIVE') {
      ses.status = 'INACTIVE';
      const other = schoolSettings.academicSessions.find((s: any) => s.id !== id);
      if (other) {
        other.status = 'ACTIVE';
        schoolSettings.currentAcademicSession = other.name;
      }
    }
    persistentStorage.saveSchoolSettingsToDisk(schoolSettings);
    logAudit(user?.name || 'Administrator', user?.role || 'SUPER_ADMIN', 'SESSION_UPDATED', 'AcademicSession', id, `Updated academic session ${ses.name}`);
    broadcastRealtimeEvent('SESSION', 'UPDATE', ses, { academicSession: ses.name, description: `Updated academic session ${ses.name}` });
    res.json(ses);
  });

  app.post(
    '/api/academic-sessions/:id/activate',
    requireRole(['SUPER_ADMIN', 'SCHOOL_ADMIN', 'ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'ACADEMIC_COORDINATOR']),
    (req: Request, res: Response) => {
    const { user } = getAuthContext(req);
    const { id } = req.params;
    if (!schoolSettings.academicSessions) {
      return res.status(404).json({ error: 'Session not found' });
    }
    const ses = schoolSettings.academicSessions.find((s: any) => s.id === id);
    if (!ses) {
      return res.status(404).json({ error: 'Session not found' });
    }
    schoolSettings.academicSessions.forEach((s: any) => (s.status = s.id === id ? 'ACTIVE' : 'INACTIVE'));
    schoolSettings.currentAcademicSession = ses.name;
    ses.updatedAt = new Date().toISOString();
    persistentStorage.saveSchoolSettingsToDisk(schoolSettings);
    logAudit(user?.name || 'Administrator', user?.role || 'SUPER_ADMIN', 'SESSION_ACTIVATED', 'AcademicSession', id, `Activated academic session ${ses.name}`);
    broadcastRealtimeEvent('SESSION', 'ACTIVATE', ses, { academicSession: ses.name, description: `Activated academic session ${ses.name}` });
    res.json({ success: true, activeSession: ses });
  });

  app.delete(
    '/api/academic-sessions/:id',
    requireRole(['SUPER_ADMIN', 'SCHOOL_ADMIN', 'ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'ACADEMIC_COORDINATOR']),
    (req: Request, res: Response) => {
    const { user } = getAuthContext(req);
    const { id } = req.params;
    if (!schoolSettings.academicSessions) {
      return res.status(404).json({ error: 'Session not found' });
    }
    const ses = schoolSettings.academicSessions.find((s: any) => s.id === id);
    if (!ses) {
      return res.status(404).json({ error: 'Session not found' });
    }
    if (ses.status === 'ACTIVE') {
      return res.status(400).json({ error: 'Cannot delete the currently ACTIVE academic session.' });
    }
    schoolSettings.academicSessions = schoolSettings.academicSessions.filter((s: any) => s.id !== id);
    persistentStorage.saveSchoolSettingsToDisk(schoolSettings);
    logAudit(user?.name || 'Administrator', user?.role || 'SUPER_ADMIN', 'SESSION_DELETED', 'AcademicSession', id, `Deleted academic session ${ses.name}`);
    broadcastRealtimeEvent('SESSION', 'DELETE', { id }, { description: `Deleted academic session ${ses.name}` });
    res.json({ success: true });
  });

  // Helper function for building dynamic executive dashboard summary
  const buildExecutiveDashboardSummary = (req: Request) => {
    const currentSession = (req.query.academicSession as string) || schoolSettings.currentAcademicSession || '2026-2027';
    const matchSession = (sess?: string): boolean => {
      if (!sess) return true;
      const s1 = sess.replace(/[\s-]/g, '').toLowerCase();
      const s2 = currentSession.replace(/[\s-]/g, '').toLowerCase();
      if (s1 === s2) return true;
      return s1.slice(0, 4) === s2.slice(0, 4);
    };

    // Current Date & Day — school timezone (Asia/Kolkata), not the server's UTC date.
    const requestedDate = req.query.date ? String(req.query.date).trim() : '';
    const todayDate = /^\d{4}-\d{2}-\d{2}$/.test(requestedDate) && !Number.isNaN(Date.parse(`${requestedDate}T12:00:00Z`))
      ? requestedDate
      : getNowInAsiaKolkata().isoDate;
    const dateObj = new Date(todayDate + 'T12:00:00Z');
    const dayNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
    const todayDay = dayNames[dateObj.getUTCDay()];

    // 1. ACTIVE STUDENTS (Enrolled & Active in Session)
    const activeStudents = students.filter(
      (s) => s.status === 'ACTIVE' && (!s.academicSession || matchSession(s.academicSession))
    );
    const activeStudentIdSet = new Set(activeStudents.map((s) => s.id));

    // 2. ACTIVE CLASSES ONLY — decided by each class's status in the database (no class names hardcoded).
    const activeClasses = classes
      .filter((c) => (c.status || 'ACTIVE') === 'ACTIVE' && (c as any).isActive !== false)
      .sort((a, b) => (a.numericOrder || 0) - (b.numericOrder || 0));

    const classDistribution = activeClasses.map((c) => {
      const studentCount = activeStudents.filter((s) => s.classId === c.id || s.className === c.name).length;
      return {
        id: c.id,
        name: c.name,
        numericOrder: c.numericOrder || 0,
        count: studentCount,
        capacity: c.maxCapacity || 40,
        sections: c.sections || ['A'],
      };
    });

    // Students of active classes not found among active classes are reported separately so the
    // class-wise distribution always adds up to the active-student total.
    const activeClassIds = new Set(activeClasses.map((c) => c.id));
    const activeClassNames = new Set(activeClasses.map((c) => c.name));
    const unassignedCount = activeStudents.filter((s) => !activeClassIds.has(s.classId) && !activeClassNames.has(s.className)).length;
    if (unassignedCount > 0) {
      classDistribution.push({
        id: '__not_in_active_class',
        name: 'Not in an active class',
        numericOrder: 9999,
        count: unassignedCount,
        capacity: 0,
        sections: [],
      });
    }

    // 3. STUDENT ATTENDANCE (today, active students only, one record per student)
    // LATE students are present (arrived late). HOLIDAY records are not attendance and are excluded.
    // Percentage = present ÷ students actually marked present/absent/leave; unmarked students are not counted.
    const attByStudent = new Map<string, string>();
    for (const a of attendance) {
      if (a.date !== todayDate || !activeStudentIdSet.has(a.studentId)) continue;
      if (a.academicSession && !matchSession(a.academicSession)) continue;
      if (!attByStudent.has(a.studentId)) attByStudent.set(a.studentId, String(a.status || '').toUpperCase());
    }
    const attStatuses = Array.from(attByStudent.values()).filter((st) => st !== 'HOLIDAY');
    const lateCount = attStatuses.filter((st) => st === 'LATE').length;
    const presentCount = attStatuses.filter((st) => st === 'PRESENT' || st === 'LATE').length;
    const absentCount = attStatuses.filter((st) => st === 'ABSENT').length;
    const leaveCount = attStatuses.filter((st) => st === 'LEAVE' || st === 'ON_LEAVE').length;
    const markedCount = presentCount + absentCount + leaveCount;
    const isAttMarked = markedCount > 0;
    const attPercentage = isAttMarked ? Math.round((presentCount / markedCount) * 100) : null;
    const notMarkedCount = Math.max(0, activeStudents.length - markedCount);

    // 4. STAFF & STAFF ATTENDANCE
    const activeStaff = staff.filter((s) => (s as any).status === 'ACTIVE' || !(s as any).status);
    const teachingStaff = activeStaff.filter(
      (s) =>
        s.role === 'TEACHER' ||
        s.designation?.toLowerCase().includes('teacher') ||
        s.designation?.toLowerCase().includes('faculty') ||
        (s.department === 'ACADEMICS' && s.role !== 'SUPER_ADMIN' && s.role !== 'SCHOOL_ADMIN' && s.role !== 'PRINCIPAL')
    );
    const nonTeachingStaff = activeStaff.filter((s) => !teachingStaff.includes(s));

    // Staff attendance: same rules as students (LATE = present, one record per active staff member).
    const activeStaffIds = new Set(activeStaff.map((s) => s.id));
    const activeStaffEmpIds = new Set(activeStaff.map((s) => String(s.employeeId || '').toUpperCase()).filter(Boolean));
    const staffAttById = new Map<string, string>();
    for (const a of staffAttendance) {
      if (a.date !== todayDate) continue;
      const emp = String(a.employeeId || '').toUpperCase();
      if (!activeStaffIds.has(a.staffId) && !(emp && activeStaffEmpIds.has(emp))) continue;
      const key = a.staffId || emp;
      if (!staffAttById.has(key)) staffAttById.set(key, String(a.status || '').toUpperCase());
    }
    const staffStatuses = Array.from(staffAttById.values()).filter((st) => st !== 'HOLIDAY' && st !== 'WEEK_OFF');
    const staffLate = staffStatuses.filter((st) => st === 'LATE').length;
    const staffPresent = staffStatuses.filter((st) => st === 'PRESENT' || st === 'LATE' || st === 'HALF_DAY').length;
    const staffAbsent = staffStatuses.filter((st) => st === 'ABSENT' || st === 'LWP' || st === 'UNPAID_LEAVE').length;
    const staffOnLeave = staffStatuses.filter((st) => st === 'LEAVE' || st === 'ON_LEAVE').length;
    const staffMarked = staffPresent + staffAbsent + staffOnLeave;
    const isStaffAttMarked = staffMarked > 0;
    const staffPercentage = isStaffAttMarked ? Math.round((staffPresent / staffMarked) * 100) : null;

    // 5. FEES & FINANCIALS
    // One receipt counts once (duplicate records of the same receipt are ignored), and payments that
    // did not complete are excluded. Dates may be stored with a time part, so compare the date only.
    const EXCLUDED_PAYMENT_STATUSES = ['FAILED', 'CANCELLED', 'CANCELED', 'VOID', 'VOIDED', 'REVERSED', 'REFUNDED'];
    const countedReceiptKeys = new Set<string>();
    const countablePayments = feePayments.filter((p: any) => {
      if (EXCLUDED_PAYMENT_STATUSES.includes(String(p.status || '').toUpperCase())) return false;
      const key = String(p.receiptNumber || p.id || '').trim();
      if (!key) return true;
      if (countedReceiptKeys.has(key)) return false;
      countedReceiptKeys.add(key);
      return true;
    });
    const paymentDay = (p: any) => String(p.paymentDate || '').substring(0, 10);
    const todayFeeCollection = countablePayments
      .filter((p) => paymentDay(p) === todayDate)
      .reduce((sum, p) => sum + (Number(p.amount) || 0), 0);

    const thisMonthPrefix = todayDate.substring(0, 7);
    const monthFeeCollection = countablePayments
      .filter((p) => paymentDay(p).startsWith(thisMonthPrefix) && paymentDay(p) <= todayDate)
      .reduce((sum, p) => sum + (Number(p.amount) || 0), 0);

    // Outstanding fees strictly for ACTIVE students in current session
    const activeLedgers = feeLedgers.filter((l) => activeStudentIdSet.has(l.studentId));
    let totalPendingAmount = 0;
    let studentsWithDuesCount = 0;
    for (const st of activeStudents) {
      const stLedgers = activeLedgers.filter((l) => l.studentId === st.id);
      const stPending = stLedgers.reduce(
        (sum, l) => sum + (Number(l.pendingAmount ?? Math.max(0, (l.total ?? l.amount ?? 0) - (l.paidAmount ?? 0))) || 0),
        0
      );
      if (stPending > 0) {
        totalPendingAmount += stPending;
        studentsWithDuesCount++;
      }
    }

    // Unique recent transactions deduplicated by receipt number
    const seenReceipts = new Set<string>();
    const recentPaymentsList: any[] = [];
    const sortedPayments = [...feePayments].sort(
      (a: any, b: any) => new Date(b.createdAt || b.paymentDate).getTime() - new Date(a.createdAt || a.paymentDate).getTime()
    );
    for (const p of sortedPayments) {
      const rKey = (p.receiptNumber || p.id || '').trim();
      if (!rKey || seenReceipts.has(rKey)) continue;
      seenReceipts.add(rKey);

      const st = activeStudents.find((s) => s.id === p.studentId) || students.find((s) => s.id === p.studentId);
      const displayClass = st ? (st.className || p.className) : (p.className && p.className !== 'Class 10' && p.className !== 'Class 9' ? p.className : '—');
      const displaySection = st?.section || p.section || '—';

      recentPaymentsList.push({
        id: p.id,
        receiptNumber: p.receiptNumber || '—',
        studentId: p.studentId,
        studentName: st?.name || p.studentName || '—',
        className: displayClass || '—',
        section: displaySection,
        feeHead: p.feeType || (p as any).feeHead || '—',
        paymentMode: p.paymentMethod || (p as any).paymentMode || '—',
        amount: Number(p.amount) || 0,
        paymentDate: p.paymentDate || '—',
        status: (p as any).status || 'SUCCESS',
      });
      if (recentPaymentsList.length >= 7) break;
    }

    // 6. ACADEMICS & TIMETABLE
    const activeSubjects = subjects.filter((s) => s.status === 'ACTIVE' || (s as any).isActive !== false);
    const totalSectionsCount = activeClasses.reduce(
      (sum, c) => sum + (c.detailedSections?.filter((s) => s.status === 'ACTIVE').length || c.sections?.length || 1),
      0
    );
    const todayTimetableSlots = timetable
      .filter((t) => (t.dayOfWeek || '').toLowerCase() === todayDay.toLowerCase())
      .sort((a, b) => Number(a.periodNumber) - Number(b.periodNumber));

    // 7. UPCOMING EXAMINATIONS (Strictly with valid future/current dates and published status)
    const seenExamNames = new Set<string>();
    const upcomingExams = exams
      .filter((e) => {
        const examName = (e.name || e.title || '').trim();
        if (!examName) return false;
        const validDate = e.endDate || e.startDate;
        if (!validDate || !/^\d{4}-\d{2}-\d{2}/.test(validDate)) return false;
        if (validDate < todayDate) return false;
        const dedupeKey = `${examName.toLowerCase()}_${e.startDate || ''}_${e.endDate || ''}`;
        if (seenExamNames.has(dedupeKey)) return false;
        seenExamNames.add(dedupeKey);
        return true;
      })
      .sort((a, b) => (a.startDate || '').localeCompare(b.startDate || ''));

    // 8. UPCOMING WEBSITE / SCHOOL EVENTS (Strictly future/current dates)
    const upcomingEvents = websiteEvents
      .filter((ev) => ev.isActive !== false && ev.eventDate && ev.eventDate >= todayDate)
      .sort((a, b) => a.eventDate.localeCompare(b.eventDate));

    // 9. RECENT NOTICES (Legitimate published notices, no debug/test)
    const legitimateNotices = notices
      .filter((n) => {
        if (n.status !== 'PUBLISHED') return false;
        const title = (n.title || '').trim().toLowerCase();
        const id = (n.id || '').trim().toLowerCase();
        if (id.includes('test-debug') || title.includes('debug draft') || title.startsWith('test all notice') || /msg \d+$/i.test(title)) {
          return false;
        }
        return true;
      })
      .sort((a, b) => (b.publishedDate || '').localeCompare(a.publishedDate || ''));

    // 10. HOSTEL METRICS
    let totalBeds = 0;
    let occupiedBeds = 0;
    hostelRooms.forEach((r) => {
      totalBeds += Number(r.capacityBeds || r.capacity || 0);
      occupiedBeds += (r.beds || []).filter((b) => Boolean(b.allocatedStudentId)).length;
    });

    // 11. TRANSPORT METRICS
    const activeVehicles = transportVehicles.filter((v) => v.status === 'ACTIVE').length;
    const activeRoutes = transportRoutes.filter((r) => r.status === 'ACTIVE').length;

    return {
      academicSession: currentSession,
      todayDate,
      todayDay,
      totalStudents: activeStudents.length,
      enrolledStudents: students.length,
      classDistribution,
      totalTeachers: teachingStaff.length,
      totalNonTeaching: nonTeachingStaff.length,
      totalStaff: activeStaff.length,
      attendance: {
        isMarked: isAttMarked,
        date: todayDate,
        percentage: attPercentage,
        present: presentCount,
        late: lateCount,
        absent: absentCount,
        leave: leaveCount,
        notMarked: notMarkedCount,
        totalMarked: markedCount,
        totalActive: activeStudents.length,
        displayText: isAttMarked ? `${attPercentage}%` : 'Not recorded',
      },
      staffAttendance: {
        isMarked: isStaffAttMarked,
        date: todayDate,
        present: staffPresent,
        late: staffLate,
        absent: staffAbsent,
        onLeave: staffOnLeave,
        totalMarked: staffMarked,
        totalStaff: activeStaff.length,
        percentage: staffPercentage,
      },
      fees: {
        todayCollection: todayFeeCollection,
        monthlyCollection: monthFeeCollection,
        pendingAmount: totalPendingAmount,
        studentsWithPendingCount: studentsWithDuesCount,
        recentPayments: recentPaymentsList,
      },
      studentOverview: {
        total: students.length,
        active: activeStudents.length,
        inactive: students.filter((s) => s.status !== 'ACTIVE').length,
        hostel: activeStudents.filter((s: any) => s.hostelRequired && s.hostelStatus !== 'VACATED').length,
        dayScholars: activeStudents.filter((s: any) => !(s.hostelRequired && s.hostelStatus !== 'VACATED')).length,
        // Class -> section counts of ACTIVE students (matches classDistribution).
        classSections: activeClasses.map((c) => {
          const inClass = activeStudents.filter((s) => s.classId === c.id || s.className === c.name);
          const sectionNames = (c.detailedSections && c.detailedSections.length > 0
            ? c.detailedSections.filter((ds: any) => (ds.status || 'ACTIVE') === 'ACTIVE').map((ds: any) => ds.name)
            : c.sections || ['A']) as string[];
          return {
            classId: c.id,
            className: c.name,
            total: inClass.length,
            sections: sectionNames.map((name) => ({
              name,
              count: inClass.filter((s) => String(s.section || 'A').toUpperCase() === String(name).toUpperCase()).length,
            })),
          };
        }),
      },
      staffOverview: {
        total: staff.length,
        active: activeStaff.length,
        inactive: staff.length - activeStaff.length,
        teaching: teachingStaff.length,
        nonTeaching: nonTeachingStaff.length,
        // Grouped case-insensitively ("ACADEMICS" and "Academics" are one department).
        departments: Array.from(
          activeStaff
            .reduce((acc: Map<string, { name: string; count: number }>, s: any) => {
              const d = String(s.department || 'Other').trim() || 'Other';
              const key = d.toLowerCase();
              const entry = acc.get(key) || { name: d, count: 0 };
              entry.count += 1;
              acc.set(key, entry);
              return acc;
            }, new Map<string, { name: string; count: number }>())
            .values()
        ).sort((a, b) => b.count - a.count || a.name.localeCompare(b.name)),
      },
      academics: {
        totalClasses: activeClasses.length,
        totalSections: totalSectionsCount,
        totalSubjects: activeSubjects.length,
        scheduledPeriodsToday: todayTimetableSlots.length,
      },
      timetable: {
        todayDay,
        scheduledCount: todayTimetableSlots.length,
        slots: todayTimetableSlots,
      },
      upcomingExams: upcomingExams.slice(0, 3),
      upcomingEvents: upcomingEvents.slice(0, 4),
      recentNotices: legitimateNotices.slice(0, 5),
      hostel: {
        totalRooms: hostelRooms.length,
        totalBeds,
        occupiedBeds,
        availableBeds: Math.max(0, totalBeds - occupiedBeds),
        occupancyRate: totalBeds > 0 ? Math.round((occupiedBeds / totalBeds) * 100) : 0,
      },
      transport: {
        totalVehicles: transportVehicles.length,
        activeVehicles,
        activeBuses: activeVehicles,
        totalRoutes: transportRoutes.length,
        activeRoutes,
      },
    };
  };

  // High-performance consolidated dashboard endpoints
  // The school-wide summary contains fee receipts with student names and staff figures, so it is for
  // signed-in staff only. Fee figures are included only for roles that may view fees.
  app.get(['/api/dashboard/summary', '/api/dashboard'], requireAuth, (req: Request, res: Response) => {
    const currentUser = (req as any).currentUser as User;
    const role = String(currentUser?.role || '').toUpperCase();
    if (role === 'STUDENT' || role === 'PARENT') {
      return res.status(403).json({ success: false, error: 'The school dashboard is available to staff only.' });
    }
    try {
      const summary: any = buildExecutiveDashboardSummary(req);
      const canViewFees = ['SUPER_ADMIN', 'SCHOOL_ADMIN', 'ADMIN'].includes(role) || hasPermission(currentUser, 'fees.view');
      if (!canViewFees) {
        summary.fees = null;
      }
      res.json(summary);
    } catch (err: any) {
      console.error('[Dashboard] Error generating summary:', err);
      res.status(500).json({ success: false, error: 'Unable to load the dashboard. Please try again.' });
    }
  });

  // Comprehensive Institutional Analytics & Official Reports Endpoint
  app.get(['/api/analytics/official-reports', '/api/analytics/official-reports/', '/api/reports/analytics', '/api/reports', '/api/reports/institutional'], requirePermission('reports.view'), async (req: Request, res: Response) => {
    try {
      const currentUser = (req as any).currentUser as User;
      const reportRole = String(currentUser.role || '').toUpperCase();
      // School-wide reports: administration, accounts and HR only. Teachers, students and
      // parents never receive school-wide data here, whatever permissions they were given.
      const REPORT_ROLES = ['SUPER_ADMIN', 'SCHOOL_ADMIN', 'ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'ACADEMIC_COORDINATOR', 'ACCOUNTANT', 'HR_STAFF'];
      if (!REPORT_ROLES.includes(reportRole)) {
        return res.status(403).json({ success: false, error: 'Reports are available to the school administration only.' });
      }
      // Salary figures: payroll roles and the principal. Fee figures and dues lists: fee roles.
      const isPrivileged = isStaffPayrollTier(reportRole) || reportRole === 'PRINCIPAL';
      const canSeeFees = ['SUPER_ADMIN', 'SCHOOL_ADMIN', 'ADMIN', 'PRINCIPAL', 'ACCOUNTANT'].includes(reportRole) || hasPermission(currentUser, 'fees.view');

      const currentSessionDefault = schoolSettings.currentAcademicSession || '2026-2027';
      const requestedSession = (req.query.academicSession as string) || currentSessionDefault;
      const dateFrom = req.query.dateFrom ? String(req.query.dateFrom).trim() : '';
      const dateTo = req.query.dateTo ? String(req.query.dateTo).trim() : '';
      const filterClassId = req.query.classId ? String(req.query.classId).trim() : '';
      const filterSection = req.query.section ? String(req.query.section).trim() : '';
      const filterExamId = req.query.examId ? String(req.query.examId).trim() : '';
      const filterSubjectId = req.query.subjectId ? String(req.query.subjectId).trim() : '';
      if ((dateFrom && !reportRules.isIsoDate(dateFrom)) || (dateTo && !reportRules.isIsoDate(dateTo))) {
        return res.status(400).json({ success: false, error: 'Dates must be in YYYY-MM-DD format.' });
      }
      if (dateFrom && dateTo && dateFrom > dateTo) {
        return res.status(400).json({ success: false, error: 'The start date is after the end date.' });
      }
      const sessionDates = reportRules.sessionRange(requestedSession, schoolSettings.academicSessions || []);
      const period = reportRules.reportPeriod(sessionDates, dateFrom, dateTo);
      const todayIst = new Date(Date.now() + 5.5 * 3600 * 1000).toISOString().slice(0, 10);
      const sameSessionOrUndated = (sess?: string) => !sess || reportRules.sameSession(sess, requestedSession);

      // Helper for flexible session matching (e.g. "2026-2027" vs "2026-27")
      const matchSession = (sess?: string): boolean => {
        if (!sess) return true;
        const s1 = sess.replace(/[\s-]/g, '').toLowerCase();
        const s2 = requestedSession.replace(/[\s-]/g, '').toLowerCase();
        if (s1 === s2) return true;
        const y1 = s1.slice(0, 4);
        const y2 = s2.slice(0, 4);
        return y1 === y2;
      };

      // 1. ACTIVE CLASSES ONLY (never show inactive classes or sections)
      const activeClasses = classes.filter((c) => reportRules.isActiveClass(c));
      if (filterClassId && !activeClasses.some((c) => c.id === filterClassId)) {
        return res.status(400).json({ success: false, error: 'That class is not an active class.' });
      }
      if (filterSection) {
        const cls = activeClasses.find((c) => c.id === filterClassId);
        if (!cls) return res.status(400).json({ success: false, error: 'Choose a class before choosing a section.' });
        if (!reportRules.activeSectionsOf(cls).includes(filterSection.toUpperCase())) {
          return res.status(400).json({ success: false, error: 'That section is not active for the selected class.' });
        }
      }
      const classNameById = new Map(activeClasses.map((c) => [c.id, c.name]));
      const inClass = (rec: any) => !filterClassId || rec?.classId === filterClassId || (!!rec?.className && rec.className === classNameById.get(filterClassId));
      const inSection = (rec: any) => !filterSection || String(rec?.section || '').toUpperCase() === filterSection.toUpperCase();

      // 2. ACTIVE STUDENTS ONLY
      let filteredStudents = students.filter((s) => s.status === 'ACTIVE');
      if (requestedSession) {
        filteredStudents = filteredStudents.filter((s) => !s.academicSession || matchSession(s.academicSession));
      }
      if (filterClassId) {
        filteredStudents = filteredStudents.filter((s) => s.classId === filterClassId);
      }
      if (filterSection) {
        filteredStudents = filteredStudents.filter((s) => inSection(s));
      }

      // Withdrawn / Inactive students for tracking
      let withdrawnStudents = students.filter((s) => s.status === 'INACTIVE' || s.status === 'WITHDRAWN' || s.status === 'TRANSFERRED');
      if (filterClassId) withdrawnStudents = withdrawnStudents.filter((s) => s.classId === filterClassId);
      if (filterSection) withdrawnStudents = withdrawnStudents.filter((s) => inSection(s));

      // Total students summary
      const totalActiveStudents = filteredStudents.length;
      const totalBoys = filteredStudents.filter((s) => s.gender === 'MALE').length;
      const totalGirls = filteredStudents.filter((s) => s.gender === 'FEMALE').length;
      const totalOtherGender = filteredStudents.filter((s) => s.gender !== 'MALE' && s.gender !== 'FEMALE').length;

      const totalHostelStudents = filteredStudents.filter((s) => Boolean(s.hostelRequired || s.hostelId || s.hostelRoomId || s.hostelStatus === 'ACTIVE')).length;
      const totalDayScholars = totalActiveStudents - totalHostelStudents;

      // New admission = admission date inside the reporting period (students without a date are not counted as new).
      const isNewAdmission = (s: any) => reportRules.inPeriod(s.admissionDate || s.enrollmentDate, period);
      const newAdmissions = filteredStudents.filter(isNewAdmission).length;
      const totalWithdrawn = withdrawnStudents.length;

      // 3. STAFF SUMMARY
      const activeStaff = staff.filter((st) => !isStaffInactive(st));
      const isTeaching = (st: any) => String(st.role || '').toUpperCase() === 'TEACHER' || String(st.staffType || st.category || '').toUpperCase() === 'TEACHING' || !!st.teachingProfile?.isTeaching;
      const teachingStaff = activeStaff.filter(isTeaching);
      const nonTeachingStaff = activeStaff.filter((st) => !isTeaching(st));

      // 4. CLASS-WISE STUDENT STRENGTH & DEMOGRAPHICS
      const classWiseStrength: any[] = [];
      let grandTotalStudents = 0;
      let grandTotalBoys = 0;
      let grandTotalGirls = 0;
      let grandTotalHostel = 0;
      let grandTotalDayScholars = 0;
      let grandTotalNew = 0;
      let grandTotalWithdrawn = 0;

      for (const cls of activeClasses) {
        if (filterClassId && cls.id !== filterClassId) continue;
        const sectionsToEvaluate = reportRules.activeSectionsOf(cls);
        for (const sec of sectionsToEvaluate) {
          if (filterSection && sec !== filterSection.toUpperCase()) continue;
          const classSecStudents = filteredStudents.filter((s) => s.classId === cls.id && String(s.section || 'A').toUpperCase() === sec);
          const classSecWithdrawn = withdrawnStudents.filter((s) => s.classId === cls.id && String(s.section || 'A').toUpperCase() === sec);

          const b = classSecStudents.filter((s) => s.gender === 'MALE').length;
          const g = classSecStudents.filter((s) => s.gender === 'FEMALE').length;
          const h = classSecStudents.filter((s) => Boolean(s.hostelRequired || s.hostelId || s.hostelRoomId || s.hostelStatus === 'ACTIVE')).length;
          const d = classSecStudents.length - h;
          const nw = classSecStudents.filter(isNewAdmission).length;
          const w = classSecWithdrawn.length;

          grandTotalStudents += classSecStudents.length;
          grandTotalBoys += b;
          grandTotalGirls += g;
          grandTotalHostel += h;
          grandTotalDayScholars += d;
          grandTotalNew += nw;
          grandTotalWithdrawn += w;

          classWiseStrength.push({
            classId: cls.id,
            className: cls.name,
            section: sec,
            totalStudents: classSecStudents.length,
            boys: b,
            girls: g,
            hostel: h,
            dayScholars: d,
            newAdmissions: nw,
            withdrawn: w,
            activeStrength: classSecStudents.length,
          });
        }
      }

      // Active students whose class or section is not an active class-section (data to fix).
      // They stay in the totals and get their own row so the table adds up.
      const placedIds = new Set<string>();
      for (const cls of activeClasses) {
        const secs = reportRules.activeSectionsOf(cls);
        filteredStudents.forEach((s) => { if (s.classId === cls.id && secs.includes(String(s.section || 'A').toUpperCase())) placedIds.add(s.id); });
      }
      const unplacedStudents = filterClassId ? [] : filteredStudents.filter((s) => !placedIds.has(s.id));
      if (unplacedStudents.length) {
        const h = unplacedStudents.filter((s) => Boolean(s.hostelRequired || s.hostelId || s.hostelRoomId || s.hostelStatus === 'ACTIVE')).length;
        const row = {
          classId: '',
          className: 'Class not set up',
          section: '—',
          totalStudents: unplacedStudents.length,
          boys: unplacedStudents.filter((s) => s.gender === 'MALE').length,
          girls: unplacedStudents.filter((s) => s.gender === 'FEMALE').length,
          hostel: h,
          dayScholars: unplacedStudents.length - h,
          newAdmissions: unplacedStudents.filter(isNewAdmission).length,
          withdrawn: 0,
          activeStrength: unplacedStudents.length,
          needsAttention: true,
        };
        classWiseStrength.push(row);
        grandTotalStudents += row.totalStudents;
        grandTotalBoys += row.boys;
        grandTotalGirls += row.girls;
        grandTotalHostel += row.hostel;
        grandTotalDayScholars += row.dayScholars;
        grandTotalNew += row.newAdmissions;
      }

      // Age distribution
      const ageGroups = {
        under5: 0,
        age5to8: 0,
        age9to12: 0,
        age13to16: 0,
        age17plus: 0,
        notSpecified: 0,
      };
      filteredStudents.forEach((s) => {
        const age = reportRules.ageOn(s.dob, todayIst);
        if (age === null) {
          ageGroups.notSpecified++;
          return;
        }
        if (age < 5) ageGroups.under5++;
        else if (age <= 8) ageGroups.age5to8++;
        else if (age <= 12) ageGroups.age9to12++;
        else if (age <= 16) ageGroups.age13to16++;
        else ageGroups.age17plus++;
      });

      // 5. FEES AUDIT & COLLECTION
      // Bills of the session (and class/section). Billed / paid / pending come from the bills themselves,
      // so billed = collected + outstanding always holds. Receipts are listed for the reporting period.
      const relevantLedgers = feeLedgers.filter((l) => sameSessionOrUndated(l.academicSession) && inClass(l) && inSection(l));
      const relevantPayments = feePayments.filter((p) => sameSessionOrUndated(p.academicSession) && reportRules.inPeriod(p.paymentDate, period) && inClass(p) && inSection(p));
      const ledgerTotals = relevantLedgers.reduce((acc, l) => {
        const f = reportRules.ledgerFigures(l);
        acc.billed += f.billed;
        acc.paid += f.paid;
        acc.pending += f.pending;
        acc.excess += f.excess;
        return acc;
      }, { billed: 0, paid: 0, pending: 0, excess: 0 });
      const totalFeeBilled = Math.round(ledgerTotals.billed);
      const totalFeeCollected = Math.round(ledgerTotals.paid);
      const totalOutstanding = Math.round(ledgerTotals.pending);
      // Received over the bill amount (e.g. a late fee paid after the bill total was revised). billed + excess = collected + outstanding.
      const excessReceived = Math.round(ledgerTotals.excess);
      const collectionPercentage = reportRules.pct(totalFeeCollected, totalFeeBilled);
      const collectedInPeriod = relevantPayments.reduce((sum, p) => sum + (Number(p.amount) || 0), 0);

      // Student accounts mapping
      const studentLedgerMap = new Map<string, { totalDue: number; paid: number; pending: number; count: number; oldestDue?: string }>();
      relevantLedgers.forEach((l) => {
        const sid = l.studentId;
        const curr = studentLedgerMap.get(sid) || { totalDue: 0, paid: 0, pending: 0, count: 0 };
        const f = reportRules.ledgerFigures(l);
        curr.totalDue += f.billed;
        curr.paid += f.paid;
        curr.pending += f.pending;
        curr.count++;
        if (l.dueDate && (!curr.oldestDue || l.dueDate < curr.oldestDue)) {
          curr.oldestDue = l.dueDate;
        }
        studentLedgerMap.set(sid, curr);
      });

      let paidAccounts = 0;
      let partialAccounts = 0;
      let pendingAccounts = 0;
      studentLedgerMap.forEach((acc) => {
        if (acc.pending <= 0 && acc.paid > 0) paidAccounts++;
        else if (acc.paid > 0 && acc.pending > 0) partialAccounts++;
        else if (acc.pending > 0) pendingAccounts++;
      });

      // Payment modes breakdown
      const paymentModesBreakdown: Record<string, { count: number; total: number }> = {
        CASH: { count: 0, total: 0 },
        UPI: { count: 0, total: 0 },
        BANK_TRANSFER: { count: 0, total: 0 },
        CARD: { count: 0, total: 0 },
        OTHER: { count: 0, total: 0 },
      };
      relevantPayments.forEach((p) => {
        const mode = String(p.paymentMethod || p.paymentMode || 'CASH').toUpperCase();
        const amt = Number(p.amount) || 0;
        if (mode.includes('CASH')) {
          paymentModesBreakdown.CASH.count++;
          paymentModesBreakdown.CASH.total += amt;
        } else if (mode.includes('UPI') || mode.includes('ONLINE')) {
          paymentModesBreakdown.UPI.count++;
          paymentModesBreakdown.UPI.total += amt;
        } else if (mode.includes('BANK') || mode.includes('NEFT') || mode.includes('RTGS') || mode.includes('TRANSFER')) {
          paymentModesBreakdown.BANK_TRANSFER.count++;
          paymentModesBreakdown.BANK_TRANSFER.total += amt;
        } else if (mode.includes('CARD')) {
          paymentModesBreakdown.CARD.count++;
          paymentModesBreakdown.CARD.total += amt;
        } else {
          paymentModesBreakdown.OTHER.count++;
          paymentModesBreakdown.OTHER.total += amt;
        }
      });

      // Class-wise fee collection
      const classWiseFeeCollection: any[] = [];
      for (const cls of activeClasses) {
        if (filterClassId && cls.id !== filterClassId) continue;
        const clsLedgers = relevantLedgers.filter((l) => l.classId === cls.id || l.className === cls.name);
        const clsStudents = filteredStudents.filter((s) => s.classId === cls.id);
        const t = clsLedgers.reduce((acc, l) => {
          const f = reportRules.ledgerFigures(l);
          acc.b += f.billed;
          acc.p += f.paid;
          acc.o += f.pending;
          return acc;
        }, { b: 0, p: 0, o: 0 });
        const billed = Math.round(t.b);
        const collected = Math.round(t.p);
        const outstanding = Math.round(t.o);
        const collPct = reportRules.pct(collected, billed);

        classWiseFeeCollection.push({
          classId: cls.id,
          className: cls.name,
          studentsCount: clsStudents.length,
          amountBilled: billed,
          amountCollected: collected,
          outstanding,
          collectionPercentage: collPct,
        });
      }

      // Outstanding dues report
      const outstandingDuesList: any[] = [];
      const todayIso = new Date().toISOString().substring(0, 10);
      filteredStudents.forEach((st) => {
        const acc = studentLedgerMap.get(st.id);
        if (acc && acc.pending > 0) {
          const oldestDue = acc.oldestDue || todayIso;
          const daysDiff = Math.max(0, Math.floor((new Date(todayIso).getTime() - new Date(oldestDue).getTime()) / (1000 * 60 * 60 * 24)));
          outstandingDuesList.push({
            studentId: st.id,
            studentName: st.name,
            admissionNumber: st.admissionNumber,
            className: st.className,
            section: st.section,
            parentName: st.parentName || st.fatherName || '',
            parentPhone: st.parentPhone || st.mobile || '',
            totalDue: acc.totalDue,
            amountPaid: acc.paid,
            pendingAmount: acc.pending,
            oldestDueDate: oldestDue,
            daysOutstanding: daysDiff,
          });
        }
      });
      outstandingDuesList.sort((a, b) => b.pendingAmount - a.pendingAmount);

      // Fee audit verification
      const feeAuditIssues: any[] = [];
      relevantLedgers.forEach((l) => {
        const f = reportRules.ledgerFigures(l);
        if (f.excess >= 1) {
          feeAuditIssues.push({
            type: 'PAID_MORE_THAN_BILL',
            severity: 'MEDIUM',
            receiptNumber: l.receiptNumber || l.invoiceNumber || '',
            description: `${l.studentName || 'A student'} (${l.feeType || l.feeMonth || 'bill'}): received ₹${Math.round(f.paid + f.pending).toLocaleString('en-IN')} against a bill of ₹${Math.round(f.billed).toLocaleString('en-IN')}.`,
            recordId: l.id,
          });
        }
      });
      const seenReceipts = new Set<string>();
      relevantPayments.forEach((p) => {
        if (p.receiptNumber) {
          if (seenReceipts.has(p.receiptNumber)) {
            feeAuditIssues.push({
              type: 'DUPLICATE_RECEIPT',
              severity: 'HIGH',
              receiptNumber: p.receiptNumber,
              description: `Duplicate receipt number ${p.receiptNumber} identified.`,
              recordId: p.id,
            });
          }
          seenReceipts.add(p.receiptNumber);
        }
        if (!p.studentName && !p.studentId) {
          feeAuditIssues.push({
            type: 'UNALLOCATED_PAYMENT',
            severity: 'MEDIUM',
            receiptNumber: p.receiptNumber,
            description: `Payment entry without associated student record.`,
            recordId: p.id,
          });
        }
      });

      // 6. ATTENDANCE & DEFAULTERS
      const activeStudentIds = new Set(filteredStudents.map((s) => s.id));
      const relevantAttendance = attendance.filter((a) => reportRules.inPeriod(a.date, period) && activeStudentIds.has(a.studentId));

      const totalAttendanceMarked = relevantAttendance.length;
      const totalPresent = relevantAttendance.filter((a) => a.status === 'PRESENT').length;
      const totalAbsent = relevantAttendance.filter((a) => a.status === 'ABSENT').length;
      const totalLeave = relevantAttendance.filter((a) => a.status === 'LEAVE' || a.status === 'HALF_DAY').length;
      const overallAttendancePercentage = totalAttendanceMarked > 0
        ? Math.round((totalPresent / totalAttendanceMarked) * 1000) / 10
        : 0;

      const studentAttendanceMap = new Map<string, { workingDays: number; present: number; absent: number; leave: number }>();
      relevantAttendance.forEach((a) => {
        const sid = a.studentId;
        const curr = studentAttendanceMap.get(sid) || { workingDays: 0, present: 0, absent: 0, leave: 0 };
        curr.workingDays++;
        if (a.status === 'PRESENT') curr.present++;
        else if (a.status === 'ABSENT') curr.absent++;
        else curr.leave++;
        studentAttendanceMap.set(sid, curr);
      });

      let countGte75 = 0;
      let countLt75 = 0;
      let countLt60 = 0;
      let countLt50 = 0;
      let countPerfect = 0;

      const attendanceDefaultersList: any[] = [];
      filteredStudents.forEach((st) => {
        const att = studentAttendanceMap.get(st.id) || { workingDays: 0, present: 0, absent: 0, leave: 0 };
        const pctOrNull = reportRules.attendancePct(att.present, att.workingDays);
        const pct = pctOrNull ?? 0;
        let status: 'Good' | 'Warning' | 'Critical' | 'Severe' | 'No records' = pctOrNull === null ? 'No records' : 'Good';
        if (pctOrNull === null) {
          // Nothing marked for this student in the period: not counted in any band.
        } else if (pct < 50) {
          status = 'Severe';
          countLt50++;
          countLt60++;
          countLt75++;
        } else if (pct < 60) {
          status = 'Critical';
          countLt60++;
          countLt75++;
        } else if (pct < 75) {
          status = 'Warning';
          countLt75++;
        } else {
          countGte75++;
          if (pct === 100 && att.workingDays > 0) countPerfect++;
        }

        attendanceDefaultersList.push({
          studentId: st.id,
          studentName: st.name,
          admissionNumber: st.admissionNumber,
          className: st.className,
          section: st.section,
          workingDays: att.workingDays,
          present: att.present,
          absent: att.absent,
          leave: att.leave,
          attendancePercentage: pctOrNull,
          status,
        });
      });

      attendanceDefaultersList.sort((a, b) => (a.attendancePercentage ?? 101) - (b.attendancePercentage ?? 101));

      // Class-wise attendance table
      const classWiseAttendance: any[] = [];
      for (const cls of activeClasses) {
        if (filterClassId && cls.id !== filterClassId) continue;
        const sectionsToEvaluate = reportRules.activeSectionsOf(cls);
        for (const sec of sectionsToEvaluate) {
          if (filterSection && sec !== filterSection.toUpperCase()) continue;
          const clsSecStudents = filteredStudents.filter((s) => s.classId === cls.id && String(s.section || 'A').toUpperCase() === sec);
          const secIds = new Set(clsSecStudents.map((s) => s.id));
          const clsSecAtt = relevantAttendance.filter((a) => secIds.has(a.studentId));
          const pres = clsSecAtt.filter((a) => a.status === 'PRESENT').length;
          const abs = clsSecAtt.filter((a) => a.status === 'ABSENT').length;
          const lev = clsSecAtt.filter((a) => a.status === 'LEAVE' || a.status === 'HALF_DAY').length;
          const avgPct = clsSecAtt.length > 0 ? Math.round((pres / clsSecAtt.length) * 1000) / 10 : 0;

          let b75 = 0;
          let b60 = 0;
          clsSecStudents.forEach((st) => {
            const att = studentAttendanceMap.get(st.id);
            if (att && att.workingDays > 0) {
              const p = (att.present / att.workingDays) * 100;
              if (p < 75) b75++;
              if (p < 60) b60++;
            }
          });

          classWiseAttendance.push({
            classId: cls.id,
            className: cls.name,
            section: sec,
            totalStudents: clsSecStudents.length,
            workingDays: clsSecAtt.length > 0 ? Array.from(new Set(clsSecAtt.map((a) => a.date))).length : 0,
            present: pres,
            absent: abs,
            leave: lev,
            averageAttendancePct: avgPct,
            below75Count: b75,
            below60Count: b60,
          });
        }
      }

      // 7. FACULTY & PAYROLL
      // Payroll records whose month falls in the reporting period.
      const staffPayrollRecords = staffPayroll.filter((p: any) => {
        const ym = String(p.payrollMonth || '').slice(0, 7);
        return /^\d{4}-\d{2}$/.test(ym) && (!period.from || `${ym}-31` >= period.from) && (!period.to || `${ym}-01` <= period.to);
      });
      const grossSum = staffPayrollRecords.reduce((sum, p) => sum + (p.basicSalary + p.totalAllowances), 0);
      const netSum = staffPayrollRecords.reduce((sum, p) => sum + p.netSalary, 0);
      const dedSum = staffPayrollRecords.reduce((sum, p) => sum + p.totalDeductions, 0);
      const allowSum = staffPayrollRecords.reduce((sum, p) => sum + p.totalAllowances, 0);

      const staffSummary = {
        totalActiveFaculty: activeStaff.length,
        teachingStaff: teachingStaff.length,
        nonTeachingStaff: nonTeachingStaff.length,
        grossPayroll: isPrivileged ? grossSum : 0,
        netPayroll: isPrivileged ? netSum : 0,
        totalDeductions: isPrivileged ? dedSum : 0,
        totalAllowances: isPrivileged ? allowSum : 0,
        averageSalary: isPrivileged && staffPayrollRecords.length > 0 ? Math.round(netSum / staffPayrollRecords.length) : 0,
        monthlyPayrollExpense: isPrivileged ? netSum : 0,
        canViewPayroll: isPrivileged,
      };

      const staffWiseList = activeStaff.map((st) => {
        // Latest payroll record in the period; without one, salary columns stay empty (not guessed).
        const recs = staffPayrollRecords.filter((p) => p.staffId === st.id || p.employeeId === st.employeeId).sort((a: any, b: any) => String(b.payrollMonth).localeCompare(String(a.payrollMonth)));
        const rec = recs[0];
        const basic = rec ? rec.basicSalary : null;
        const allowances = rec ? rec.totalAllowances : null;
        const deductions = rec ? rec.totalDeductions : null;
        const gross = rec ? rec.basicSalary + rec.totalAllowances : null;
        const net = rec ? rec.netSalary : null;

        return {
          employeeId: st.employeeId,
          employeeName: st.name,
          designation: st.designation,
          department: st.department,
          employmentStatus: st.status || st.accountStatus || 'ACTIVE',
          payrollMonth: rec ? (rec as any).month || (rec as any).payrollMonth : null,
          basicSalary: isPrivileged ? basic : 'CONFIDENTIAL',
          allowances: isPrivileged ? allowances : 'CONFIDENTIAL',
          deductions: isPrivileged ? deductions : 'CONFIDENTIAL',
          grossSalary: isPrivileged ? gross : 'CONFIDENTIAL',
          netSalary: isPrivileged ? net : 'CONFIDENTIAL',
          paymentStatus: rec ? rec.paymentStatus : 'NOT_GENERATED',
        };
      });

      // 8. EXAMINATION ANALYSIS
      let relevantExams = exams.filter((e) => matchSession(e.academicSession));
      if (filterExamId) relevantExams = relevantExams.filter((e) => e.id === filterExamId);
      if (filterClassId) relevantExams = relevantExams.filter((e) => !e.classIds || e.classIds.length === 0 || e.classIds.includes(filterClassId));

      const examIds = new Set(relevantExams.map((e) => e.id));
      let relevantMarks = examMarks.filter((m) => examIds.has(m.examId));
      if (filterClassId) relevantMarks = relevantMarks.filter((m) => m.classId === filterClassId);
      if (filterSection) relevantMarks = relevantMarks.filter((m) => inSection(m));
      if (filterSubjectId) relevantMarks = relevantMarks.filter((m) => m.subjectId === filterSubjectId);

      const passedMarks = relevantMarks.filter((m) => m.status === 'PASS' || (!m.isAbsent && m.marksObtained >= (m.maxMarks * 0.33)));
      const failedMarks = relevantMarks.filter((m) => m.status === 'FAIL' || (!m.isAbsent && m.marksObtained < (m.maxMarks * 0.33)));

      const passPercentage = relevantMarks.length > 0 ? Math.round((passedMarks.length / relevantMarks.length) * 1000) / 10 : 0;
      const failPercentage = relevantMarks.length > 0 ? Math.round((failedMarks.length / relevantMarks.length) * 1000) / 10 : 0;

      let highestPct = 0;
      let lowestPct = relevantMarks.length > 0 ? 100 : 0;
      let highestScorerName = 'N/A';
      let totalPercentageSum = 0;

      const gradeDistribution: Record<string, number> = {
        A1: 0, A2: 0, B1: 0, B2: 0, C1: 0, C2: 0, D: 0, 'E/F': 0,
      };

      const studentExamScoreMap = new Map<string, { name: string; admissionNo: string; className: string; section: string; totalObtained: number; totalMax: number }>();

      relevantMarks.forEach((m) => {
        const g = m.grade || '';
        if (g && gradeDistribution[g] !== undefined) gradeDistribution[g]++;
        else if (g) gradeDistribution['E/F']++;

        const pct = m.maxMarks > 0 ? (m.marksObtained / m.maxMarks) * 100 : 0;
        totalPercentageSum += pct;
        if (pct > highestPct) {
          highestPct = pct;
          highestScorerName = `${m.studentName} (${m.marksObtained}/${m.maxMarks})`;
        }
        if (pct < lowestPct) lowestPct = pct;

        const curr = studentExamScoreMap.get(m.studentId) || {
          name: m.studentName,
          admissionNo: m.admissionNumber,
          className: '',
          section: m.section,
          totalObtained: 0,
          totalMax: 0,
        };
        curr.totalObtained += m.marksObtained;
        curr.totalMax += m.maxMarks;
        studentExamScoreMap.set(m.studentId, curr);
      });

      const averagePercentage = relevantMarks.length > 0 ? Math.round((totalPercentageSum / relevantMarks.length) * 10) / 10 : 0;

      const topPerformers = Array.from(studentExamScoreMap.values())
        .map((st) => ({
          name: st.name,
          admissionNo: st.admissionNo,
          section: st.section,
          totalObtained: st.totalObtained,
          totalMax: st.totalMax,
          percentage: st.totalMax > 0 ? Math.round((st.totalObtained / st.totalMax) * 1000) / 10 : 0,
        }))
        .sort((a, b) => b.percentage - a.percentage)
        .slice(0, 5);

      const academicSupportNeeded = Array.from(studentExamScoreMap.values())
        .map((st) => ({
          name: st.name,
          admissionNo: st.admissionNo,
          section: st.section,
          percentage: st.totalMax > 0 ? Math.round((st.totalObtained / st.totalMax) * 1000) / 10 : 0,
        }))
        .filter((st) => st.percentage < 40)
        .sort((a, b) => a.percentage - b.percentage);

      // Class-wise examination table
      const classWiseExamTable: any[] = [];
      for (const cls of activeClasses) {
        if (filterClassId && cls.id !== filterClassId) continue;
        const clsMarks = relevantMarks.filter((m) => m.classId === cls.id);
        if (clsMarks.length === 0) continue;
        const app = Array.from(new Set(clsMarks.map((m) => m.studentId))).length;
        const pass = clsMarks.filter((m) => m.status === 'PASS' || (!m.isAbsent && m.marksObtained >= (m.maxMarks * 0.33))).length;
        const fail = clsMarks.length - pass;
        const pPct = clsMarks.length > 0 ? Math.round((pass / clsMarks.length) * 1000) / 10 : 0;
        const avg = clsMarks.reduce((sum, m) => sum + (m.maxMarks > 0 ? (m.marksObtained / m.maxMarks) * 100 : 0), 0) / clsMarks.length;
        const high = Math.max(...clsMarks.map((m) => m.maxMarks > 0 ? (m.marksObtained / m.maxMarks) * 100 : 0));

        classWiseExamTable.push({
          classId: cls.id,
          className: cls.name,
          studentsAppeared: app,
          marksRecorded: clsMarks.length,
          passed: pass,
          failed: fail,
          passPercentage: pPct,
          averagePercentage: Math.round(avg * 10) / 10,
          highestPercentage: Math.round(high * 10) / 10,
        });
      }

      // Subject-wise examination table
      const subjectWiseExamTable: any[] = [];
      const distinctSubjects = Array.from(new Set(relevantMarks.map((m) => m.subjectId || m.subjectName)));
      distinctSubjects.forEach((subKey) => {
        const subMarks = relevantMarks.filter((m) => (m.subjectId === subKey || m.subjectName === subKey));
        if (subMarks.length === 0) return;
        const subName = subMarks[0].subjectName;
        const pass = subMarks.filter((m) => m.status === 'PASS' || (!m.isAbsent && m.marksObtained >= (m.maxMarks * 0.33))).length;
        const fail = subMarks.length - pass;
        const pPct = subMarks.length > 0 ? Math.round((pass / subMarks.length) * 1000) / 10 : 0;
        const avg = subMarks.reduce((sum, m) => sum + m.marksObtained, 0) / subMarks.length;
        const high = Math.max(...subMarks.map((m) => m.marksObtained));

        subjectWiseExamTable.push({
          subjectId: subMarks[0].subjectId,
          subjectName: subName,
          studentsAppeared: subMarks.length,
          passed: pass,
          failed: fail,
          passPercentage: pPct,
          averageMarks: Math.round(avg * 10) / 10,
          highestMarks: high,
        });
      });

      // 9. REAL HISTORICAL TRENDS
      // Monthly fee collection trend
      const monthlyFeeMap = new Map<string, { collected: number; count: number }>();
      relevantPayments.forEach((p) => {
        if (!p.paymentDate) return;
        const mKey = p.paymentDate.substring(0, 7);
        const curr = monthlyFeeMap.get(mKey) || { collected: 0, count: 0 };
        curr.collected += Number(p.amount) || 0;
        curr.count++;
        monthlyFeeMap.set(mKey, curr);
      });
      const monthlyFeeTrends = Array.from(monthlyFeeMap.entries())
        .sort((a, b) => a[0].localeCompare(b[0]))
        .map(([month, data]) => ({ month, collected: data.collected, count: data.count }));

      // Monthly admissions trend
      const monthlyAdmissionMap = new Map<string, number>();
      filteredStudents.forEach((st) => {
        const admDate = st.admissionDate || st.enrollmentDate;
        if (!admDate || !reportRules.inPeriod(admDate, period)) return;
        const admMonth = String(admDate).substring(0, 7);
        monthlyAdmissionMap.set(admMonth, (monthlyAdmissionMap.get(admMonth) || 0) + 1);
      });
      const monthlyAdmissionTrends = Array.from(monthlyAdmissionMap.entries())
        .sort((a, b) => a[0].localeCompare(b[0]))
        .map(([month, count]) => ({ month, count }));

      // Monthly attendance trend
      const monthlyAttendanceMap = new Map<string, { present: number; total: number }>();
      relevantAttendance.forEach((a) => {
        if (!a.date) return;
        const attMonth = a.date.substring(0, 7);
        const curr = monthlyAttendanceMap.get(attMonth) || { present: 0, total: 0 };
        curr.total++;
        if (a.status === 'PRESENT') curr.present++;
        monthlyAttendanceMap.set(attMonth, curr);
      });
      const monthlyAttendanceTrends = Array.from(monthlyAttendanceMap.entries())
        .sort((a, b) => a[0].localeCompare(b[0]))
        .map(([month, d]) => ({
          month,
          present: d.present,
          total: d.total,
          percentage: d.total > 0 ? Math.round((d.present / d.total) * 1000) / 10 : 0,
        }));

      // Monthly payroll trend
      const monthlyPayrollMap = new Map<string, { gross: number; net: number }>();
      staffPayrollRecords.forEach((p) => {
        const pKey = (p as any).payrollMonth || p.month;
        if (!pKey) return;
        const curr = monthlyPayrollMap.get(pKey) || { gross: 0, net: 0 };
        curr.gross += (p.basicSalary + p.totalAllowances);
        curr.net += p.netSalary;
        monthlyPayrollMap.set(pKey, curr);
      });
      const monthlyPayrollTrends = Array.from(monthlyPayrollMap.entries()).sort((a, b) => String(a[0]).localeCompare(String(b[0]))).map(([month, d]) => ({
        month,
        gross: isPrivileged ? d.gross : 0,
        net: isPrivileged ? d.net : 0,
      }));

      // Examination pass percentage trend
      const examWiseTrends = relevantExams.map((ex) => {
        const exMarks = examMarks.filter((m) => m.examId === ex.id);
        const pass = exMarks.filter((m) => m.status === 'PASS' || (!m.isAbsent && m.marksObtained >= (m.maxMarks * 0.33))).length;
        const passPct = exMarks.length > 0 ? Math.round((pass / exMarks.length) * 1000) / 10 : 0;
        return {
          examId: ex.id,
          title: ex.title,
          passPercentage: passPct,
          totalCandidates: exMarks.length,
        };
      });

      const reportPayload: any = {
        success: true,
        meta: {
          schoolName: schoolSettings.schoolName || '',
          schoolAddress: schoolSettings.schoolAddress || '',
          affiliationCode: schoolSettings.affiliationCode || schoolSettings.affiliationNumber || '',
          affiliatedBoard: schoolSettings.affiliatedBoard || '',
          schoolCode: schoolSettings.schoolCode || '',
          logoFileKey: schoolSettings.logoFileKey || schoolSettings.schoolLogo || '',
          academicSession: requestedSession,
          period,
          access: { payroll: isPrivileged, fees: canSeeFees },
          generatedAt: new Date().toISOString(),
          generatedBy: currentUser ? `${currentUser.name} (${currentUser.role})` : 'Administrator',
          appliedFilters: {
            academicSession: requestedSession,
            dateFrom: period.from || 'Session start',
            dateTo: period.to || 'Session end',
            classId: filterClassId || 'All Classes',
            section: filterSection || 'All Sections',
            examId: filterExamId || 'All Exams',
            subjectId: filterSubjectId || 'All Subjects',
          },
        },
        executiveSummary: {
          students: {
            totalActive: totalActiveStudents,
            boys: totalBoys,
            girls: totalGirls,
            otherGender: totalOtherGender,
            newAdmissions,
            withdrawn: totalWithdrawn,
            hostelStudents: totalHostelStudents,
            dayScholars: totalDayScholars,
          },
          staff: {
            totalActiveStaff: activeStaff.length,
            teachingStaff: teachingStaff.length,
            nonTeachingStaff: nonTeachingStaff.length,
          },
          fees: {
            totalFeeBilled,
            totalFeeCollected,
            outstandingFees: totalOutstanding,
            excessReceived,
            collectionPercentage,
            totalReceipts: relevantPayments.length,
            collectedInPeriod,
            pendingAccounts,
            paidAccounts,
            partialAccounts,
            averageReceiptAmount: relevantPayments.length > 0 ? Math.round(collectedInPeriod / relevantPayments.length) : 0,
          },
          attendance: {
            overallAttendancePercentage,
            totalMarked: totalAttendanceMarked,
            present: totalPresent,
            absent: totalAbsent,
            leave: totalLeave,
            studentsBelow75: countLt75,
            studentsBelow60: countLt60,
            studentsBelow50: countLt50,
            studentsPerfectAttendance: countPerfect,
          },
          examination: {
            appeared: Array.from(new Set(relevantMarks.map((m) => m.studentId))).length,
            marksRecorded: relevantMarks.length,
            passed: passedMarks.length,
            failed: failedMarks.length,
            passPercentage,
            failPercentage,
            averagePercentage,
            highestPercentage: Math.round(highestPct * 10) / 10,
            lowestPercentage: Math.round(lowestPct * 10) / 10,
            highestScorer: highestScorerName,
          },
        },
        studentStrength: {
          classWise: classWiseStrength,
          grandTotals: {
            totalStudents: grandTotalStudents,
            boys: grandTotalBoys,
            girls: grandTotalGirls,
            hostel: grandTotalHostel,
            dayScholars: grandTotalDayScholars,
            newAdmissions: grandTotalNew,
            withdrawn: grandTotalWithdrawn,
          },
          studentsWithoutActiveClass: unplacedStudents.length,
          demographics: {
            gender: { boys: totalBoys, girls: totalGirls, other: totalOtherGender },
            ageGroups,
            hostelVsDayScholar: { hostel: totalHostelStudents, dayScholar: totalDayScholars },
            newVsExisting: { newStudents: newAdmissions, existingStudents: totalActiveStudents - newAdmissions },
          },
        },
        feeCollectionAndAudit: {
          summary: {
            totalFeeBilled,
            totalFeeCollected,
            outstandingFees: totalOutstanding,
            excessReceived,
            collectionPercentage,
            collectedInPeriod,
            paidAccounts,
            partialAccounts,
            pendingAccounts,
            totalReceipts: relevantPayments.length,
            averageReceiptAmount: relevantPayments.length > 0 ? Math.round(collectedInPeriod / relevantPayments.length) : 0,
            paymentModes: paymentModesBreakdown,
          },
          classWise: classWiseFeeCollection,
          detailedPayments: relevantPayments.slice(0, 100).map((p) => ({
            id: p.id,
            receiptNumber: p.receiptNumber,
            paymentDate: p.paymentDate,
            studentName: p.studentName,
            admissionNumber: p.admissionNumber,
            className: p.className,
            feeType: p.feeType,
            invoiceNumber: p.invoiceNumber || '-',
            amountDue: p.totalBill || p.amount,
            amountPaid: p.amount,
            balance: p.balanceDue || 0,
            paymentMode: p.paymentMethod || p.paymentMode || 'CASH',
            razorpayPaymentId: (p as any).razorpayPaymentId || '', // older receipts
            phonepeTransactionId: (p as any).phonepeTransactionId || '',
            transactionReference: p.transactionReference || '',
            collectedBy: p.collectedBy || 'Accounts Office',
            status: 'COMPLETED',
          })),
          outstandingDues: outstandingDuesList,
          audit: {
            clean: feeAuditIssues.length === 0,
            discrepanciesCount: feeAuditIssues.length,
            issues: feeAuditIssues,
          },
        },
        attendanceAndDefaulters: {
          summary: {
            overallAttendancePercentage,
            totalStudents: filteredStudents.length,
            studentsGte75: countGte75,
            studentsLt75: countLt75,
            studentsLt60: countLt60,
            studentsLt50: countLt50,
            studentsPerfectAttendance: countPerfect,
            totalMarked: totalAttendanceMarked,
            present: totalPresent,
            absent: totalAbsent,
            leave: totalLeave,
          },
          classWise: classWiseAttendance,
          defaulters: attendanceDefaultersList,
        },
        facultyAndPayroll: {
          summary: staffSummary,
          staffWise: staffWiseList,
        },
        examinationAnalysis: {
          summary: {
            appeared: Array.from(new Set(relevantMarks.map((m) => m.studentId))).length,
            passed: passedMarks.length,
            failed: failedMarks.length,
            passPercentage,
            failPercentage,
            averagePercentage,
            highestPercentage: Math.round(highestPct * 10) / 10,
            lowestPercentage: Math.round(lowestPct * 10) / 10,
            highestScorer: highestScorerName,
          },
          classWise: classWiseExamTable,
          subjectWise: subjectWiseExamTable,
          gradeDistribution,
          topPerformers,
          academicSupportNeeded,
        },
        trends: {
          monthlyFee: monthlyFeeTrends,
          monthlyAdmission: monthlyAdmissionTrends,
          monthlyAttendance: monthlyAttendanceTrends,
          monthlyPayroll: monthlyPayrollTrends,
          examWisePassPercentage: examWiseTrends,
        },
      };
      // Fee figures and the dues list (with parent phone numbers) only for fee roles.
      if (!canSeeFees) {
        reportPayload.executiveSummary.fees = null;
        reportPayload.feeCollectionAndAudit = null;
        reportPayload.trends.monthlyFee = [];
      }
      // Lists are capped; totals above are computed on everything.
      const cap = (arr: any[], n: number) => ({ rows: arr.slice(0, n), total: arr.length });
      if (reportPayload.feeCollectionAndAudit) {
        const od = cap(reportPayload.feeCollectionAndAudit.outstandingDues, 500);
        reportPayload.feeCollectionAndAudit.outstandingDues = od.rows;
        reportPayload.feeCollectionAndAudit.outstandingDuesTotal = od.total;
      }
      const df = cap(reportPayload.attendanceAndDefaulters.defaulters, 1000);
      reportPayload.attendanceAndDefaulters.defaulters = df.rows;
      reportPayload.attendanceAndDefaulters.defaultersTotal = df.total;
      logAudit(currentUser.name, reportRole, 'REPORT_VIEWED', 'Reports', requestedSession, `Viewed reports (${period.from} to ${period.to}${filterClassId ? `, class ${classNameById.get(filterClassId)}` : ''}${filterSection ? `-${filterSection}` : ''})`);
      return res.json(reportPayload);
    } catch (err: any) {
      console.error('[OfficialReports] Analytics aggregation failed:', err);
      res.status(500).json({ success: false, error: 'The report could not be generated. Please try again.' });
    }
  });

  // Database connection and health diagnostic endpoint
  app.get('/api/db/status', requireRole(filePolicy.SETTINGS_ROLES), async (req: Request, res: Response) => {
    const status = mongoService.getStatus();
    res.json({
      ...status,
      timestamp: new Date().toISOString(),
      studentCount: students.length,
      schoolCode: schoolSettings.schoolCode,
      message: status.connected
        ? 'Connected to MongoDB cluster with active tenant indexing'
        : `MongoDB Status: ${status.error || 'Operating in fallback mode'}. Application continues running seamlessly with in-memory tenant isolation.`,
    });
  });

  // --- Student record helpers (validation, identifiers, secret fields) ---
  const STUDENT_SECRET_FIELDS = [
    'passwordHash', 'temporaryPassword', 'initialPassword', 'password', 'passwordResetToken',
    'passwordResetTokenHash', 'passwordResetLinkToken', 'passwordResetExpires', 'passwordResetEmail',
    'failedLoginAttempts', 'lockoutUntil',
  ];
  const VALID_STUDENT_STATUSES: StudentStatus[] = ['ACTIVE', 'INACTIVE', 'ON_LEAVE', 'SUSPENDED', 'TRANSFERRED', 'WITHDRAWN'];
  const VALID_GENDERS = ['MALE', 'FEMALE', 'OTHER'];

  function stripStudentSecrets<T extends Record<string, any>>(record: T): T {
    if (!record || typeof record !== 'object') return record;
    const out: Record<string, any> = { ...record };
    for (const key of STUDENT_SECRET_FIELDS) delete out[key];
    delete out._id;
    delete out.__v;
    return out as T;
  }

  function isValidIsoDate(value: any): boolean {
    const v = String(value || '').substring(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(v)) return false;
    const d = new Date(`${v}T00:00:00Z`);
    return !Number.isNaN(d.getTime()) && d.toISOString().substring(0, 10) === v;
  }

  function isValidEmailAddress(value: any): boolean {
    const v = String(value || '').trim();
    return v.length <= 254 && /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v);
  }

  function maskEmailAddress(value: string): string {
    return String(value || '').replace(/^(.{2})[^@]*(@.*)$/, '$1***$2');
  }

  function findClassForStudent(data: { classId?: string; className?: string }): AcademicClass | undefined {
    const byId = data.classId ? classes.find((c) => c.id === data.classId) : undefined;
    if (byId) return byId;
    return data.className ? classes.find((c) => c.name === data.className) : undefined;
  }

  // Validates the fields every admission needs. Returns the resolved active class and normalised section.
  function validateStudentAdmissionInput(data: any): { error?: string; cls?: AcademicClass; section?: string } {
    const name = String(data.name || '').trim();
    if (!name) return { error: "Student's name is required." };
    if (name.length > 120) return { error: "Student's name is too long (maximum 120 characters)." };
    if (!data.classId && !data.className) return { error: 'Please select a class.' };
    const cls = findClassForStudent(data);
    if (!cls) return { error: 'The selected class does not exist. Please refresh and choose a class again.' };
    if ((cls.status || 'ACTIVE') !== 'ACTIVE') return { error: `${cls.name} is not active. Please choose an active class.` };
    const sections = (cls.sections || []).map((x) => String(x));
    const requested = String(data.section || '').trim();
    let section = requested;
    if (sections.length > 0) {
      const match = sections.find((x) => x.toUpperCase() === requested.toUpperCase());
      if (!requested) return { error: 'Please select a section.' };
      if (!match) return { error: `${cls.name} has no section "${requested}". Available sections: ${sections.join(', ')}.` };
      section = match;
    } else if (!requested) {
      return { error: 'Please select a section.' };
    }
    if (!data.dob) return { error: 'Date of birth is required.' };
    if (!isValidIsoDate(data.dob)) return { error: 'Date of birth is not a valid date.' };
    const today = getNowInAsiaKolkata().isoDate;
    if (String(data.dob).substring(0, 10) >= today) return { error: 'Date of birth must be in the past.' };
    if (String(data.dob).substring(0, 10) < '1950-01-01') return { error: 'Date of birth is not valid.' };
    if (data.gender && !VALID_GENDERS.includes(String(data.gender).toUpperCase())) return { error: 'Please select a valid gender.' };
    for (const field of ['admissionDate', 'enrollmentDate', 'feeStartDate']) {
      if (data[field] && !isValidIsoDate(data[field])) return { error: `${field === 'admissionDate' ? 'Admission' : field === 'enrollmentDate' ? 'Enrollment' : 'Fee start'} date is not a valid date.` };
    }
    if (data.status && !VALID_STUDENT_STATUSES.includes(String(data.status).toUpperCase() as StudentStatus)) {
      return { error: 'Student status is not valid.' };
    }
    for (const field of ['parentEmail', 'fatherEmail', 'motherEmail', 'email']) {
      if (data[field] && !isValidEmailAddress(data[field])) return { error: `The email address "${data[field]}" is not valid.` };
    }
    return { cls, section };
  }

  // Admission numbers follow the school's 8-digit scheme starting with 6401 (the login ID shown on the form).
  function allocateNextAdmissionNumber(commit = true): string {
    const used = new Set<string>([
      ...students.map((s) => String(s.admissionNumber || '')),
      ...feeLedgers.map((l) => String(l.admissionNumber || '')),
    ]);
    let max = 64010000;
    for (const v of used) {
      if (/^6401\d{4}$/.test(v)) max = Math.max(max, Number(v));
    }
    let next = Math.max(max + 1, nextAdmissionCounter && /^6401\d{4}$/.test(String(nextAdmissionCounter)) ? nextAdmissionCounter : 0);
    while (used.has(String(next))) next++;
    if (commit) nextAdmissionCounter = next + 1;
    return String(next);
  }

  function allocateNextRegistrationNumber(cls: AcademicClass, session?: string): string {
    const year = (String(session || '').match(/\d{4}/) || [String(getNowInAsiaKolkata().year)])[0];
    const classNumeric = String(cls.numericOrder ?? 0).padStart(2, '0');
    const used = new Set(students.map((s) => String(s.registrationNumber || '')));
    let maxSeq = 0;
    for (const v of used) {
      const m = v.match(/^CPS\d{4}\d{2}(\d{4})$/);
      if (m) maxSeq = Math.max(maxSeq, Number(m[1]));
    }
    let seq = maxSeq + 1;
    let candidate = `CPS${year}${classNumeric}${String(seq).padStart(4, '0')}`;
    while (used.has(candidate)) {
      seq++;
      candidate = `CPS${year}${classNumeric}${String(seq).padStart(4, '0')}`;
    }
    return candidate;
  }

  function allocateNextRollNumber(classId: string, section: string): string {
    const peers = students.filter((s) => s.classId === classId && String(s.section || '').toUpperCase() === String(section || '').toUpperCase());
    const maxRoll = peers.reduce((m, s) => Math.max(m, parseInt(String(s.rollNumber || '0'), 10) || 0), 0);
    return String(maxRoll + 1);
  }

  // Students Dashboard Statistics
  app.get('/api/students/stats', requireAuth, (req: Request, res: Response) => {
    const totalStudents = students.length;
    const activeStudents = students.filter((s) => s.status === 'ACTIVE').length;
    const inactiveStudents = students.filter(
      (s) => s.status === 'INACTIVE' || s.status === 'WITHDRAWN' || s.status === 'TRANSFERRED'
    ).length;
    const newlyAdmittedStudents = students.filter(
      (s) => s.academicSession === schoolSettings.currentAcademicSession
    ).length;

    // Class-wise counts
    const classCounts: Record<string, number> = {};
    classes.forEach((c) => {
      classCounts[c.name] = students.filter((s) => s.classId === c.id).length;
    });

    // Section-wise counts
    const sectionCounts: Record<string, number> = { A: 0, B: 0, C: 0 };
    students.forEach((s) => {
      const sec = s.section || 'A';
      sectionCounts[sec] = (sectionCounts[sec] || 0) + 1;
    });

    res.json({
      totalStudents,
      activeStudents,
      inactiveStudents,
      newlyAdmittedStudents,
      classCounts,
      sectionCounts,
    });
  });

  // Preview next auto-generated admission number and class-wise roll number
  app.get('/api/students/next-numbers', requireAuth, (req: Request, res: Response) => {
    const { classId, section } = req.query;
    const admissionNumber = allocateNextAdmissionNumber(false);

    const targetClassId = (classId as string) || classes[0]?.id || 'c-10';
    const targetSection = (section as string) || 'A';

    const currentClass = classes.find((c) => c.id === targetClassId);
    const classNumeric = currentClass ? String(currentClass.numericOrder).padStart(2, '0') : '10';
    const regDigits = String(students.length + 1).padStart(4, '0');
    const registrationNumber = `CPS2026${classNumeric}${regDigits}`;

    const enrolledCount = students.filter(
      (s) => s.classId === targetClassId && s.section === targetSection
    ).length;
    const rollNumber = String(enrolledCount + 1);

    res.json({
      admissionNumber,
      registrationNumber,
      rollNumber,
      classId: targetClassId,
      section: targetSection,
      academicSession: schoolSettings.currentAcademicSession,
    });
  });

  // Students CRUD with pagination
  app.get('/api/students', requireAuth, async (req: Request, res: Response) => {
    const { user, session } = getAuthContext(req);
    const { classId, section, subjectId, search, status, academicSession, page = '1', limit = '50' } = req.query;

    // MongoDB is single source of truth
    if (mongoService.isConnected()) {
      try {
        const dbStudents = await mongoService.getStudents();
        if (Array.isArray(dbStudents) && dbStudents.length > 0) {
          students = dbStudents;
        }
      } catch (e) {}
    }

    let result = [...students];

    // Data ownership restrictions
    if (session?.role === 'STUDENT' && session.studentId) {
      result = result.filter((s) => s.id === session.studentId);
    } else if (session?.role === 'PARENT') {
      const linked = [
        ...(Array.isArray(session.linkedStudentIds) ? session.linkedStudentIds : []),
        ...(Array.isArray(user?.linkedStudentIds) ? user.linkedStudentIds : []),
        ...(session.studentId ? [session.studentId] : []),
        ...(session.activeStudentId ? [session.activeStudentId] : []),
      ];
      const parentPhone = normalizePhone(user?.phone || user?.username || '');
      result = result.filter((s) =>
        linked.includes(s.id) ||
        linked.includes(s.admissionNumber) ||
        (parentPhone && (
          normalizePhone(s.parentPhone) === parentPhone ||
          normalizePhone(s.fatherMobile) === parentPhone ||
          normalizePhone(s.motherMobile) === parentPhone ||
          normalizePhone(s.guardianMobile) === parentPhone ||
          normalizePhone(s.mobile) === parentPhone
        ))
      );
    } else if (session?.role === 'TEACHER') {
      const currentTeacher = findStaffForUser(user, session);
      if (!currentTeacher) {
        return res.status(403).json({ error: 'Forbidden: Teacher profile not found.' });
      }
      const assigned = getTeacherAssignedClassesAndSections(currentTeacher);
      const detailed = getTeacherTeachingAssignmentsDetailed(currentTeacher);

      if (classId && classId !== 'ALL') {
        const targetCls = classes.find(
          (c) => c.id === classId || c.name.toLowerCase() === (classId as string).toLowerCase()
        );
        const canonId = targetCls ? targetCls.id : (classId as string);
        const canonName = targetCls ? targetCls.name.toLowerCase() : (classId as string).toLowerCase();
        const isClassAssigned = assigned.some(
          (a) => a.classId.toLowerCase() === canonId.toLowerCase() || a.className.toLowerCase() === canonName
        );
        if (!isClassAssigned) {
          return res.status(403).json({ error: 'Forbidden: You cannot access student records for an unassigned class.' });
        }
        if (section && section !== 'ALL') {
          const isPermitted = isClassAndSectionAssignedToTeacher(currentTeacher, classId as string, section as string);
          if (!isPermitted) {
            return res.status(403).json({ error: 'Forbidden: You cannot access student records for an unassigned class/section.' });
          }
        }
      }

      if (subjectId && subjectId !== 'ALL') {
        const subStr = (subjectId as string).trim().toLowerCase();
        const teachesSubInAnyAssigned = detailed.some(
          (a) => a.subjects.some((s) => s.id.toLowerCase() === subStr || s.name.toLowerCase() === subStr)
        );
        if (!teachesSubInAnyAssigned) {
          return res.status(403).json({ error: 'Forbidden: You cannot access student records for a subject you are not assigned to teach.' });
        }
      }

      result = result.filter((s) => {
        if (!isTeacherAuthorizedForStudent(currentTeacher, s)) return false;
        if (subjectId && subjectId !== 'ALL') {
          return isTeacherAuthorizedForSubject(currentTeacher, s.classId || s.className, s.section || 'A', subjectId as string);
        }
        return true;
      });
    }

    if (classId && classId !== 'ALL') {
      result = result.filter((s) => s.classId === classId || s.className === classId);
    }
    if (section && section !== 'ALL') {
      result = result.filter((s) => s.section === section);
    }
    if (status && status !== 'ALL') {
      result = result.filter((s) => s.status === status);
    }
    if (academicSession && academicSession !== 'ALL') {
      result = result.filter((s) => s.academicSession === academicSession);
    }
    if (search) {
      const q = (search as string).toLowerCase().trim();
      result = result.filter(
        (s) =>
          s.name.toLowerCase().includes(q) ||
          (s.firstName && s.firstName.toLowerCase().includes(q)) ||
          (s.lastName && s.lastName.toLowerCase().includes(q)) ||
          s.admissionNumber.includes(q) ||
          s.registrationNumber.toLowerCase().includes(q) ||
          s.rollNumber === q ||
          (s.parentPhone && s.parentPhone.includes(q)) ||
          (s.parentName && s.parentName.toLowerCase().includes(q)) ||
          (s.mobile && s.mobile.includes(q))
      );
    }

    const pageNum = Math.max(1, parseInt(page as string, 10) || 1);
    const limitNum = Math.max(1, parseInt(limit as string, 10) || 50);
    const startIndex = (pageNum - 1) * limitNum;
    const paginated = result.slice(startIndex, startIndex + limitNum);

    res.json({
      data: paginated.map((st) => stripStudentSecrets(st)),
      pagination: {
        total: result.length,
        page: pageNum,
        limit: limitNum,
        totalPages: Math.ceil(result.length / limitNum) || 1,
      },
    });
  });

  // Get student by ID
  app.get('/api/students/:id', requireAuth, async (req: Request, res: Response) => {
    const { user, session } = getAuthContext(req);
    const { id } = req.params;
    let student = students.find((s) => s.id === id || s.admissionNumber === id);

    if (mongoService.isConnected()) {
      try {
        const dbStudent = await StudentModel.findOne({
          $or: [{ id }, { admissionNumber: id }],
        }).lean();
        if (dbStudent) {
          student = dbStudent as any;
          const idx = students.findIndex((s) => s.id === (dbStudent as any).id);
          if (idx !== -1) {
            students[idx] = student;
          } else {
            students.push(student);
          }
        }
      } catch (err) {
        console.warn('[Server] Error fetching student from MongoDB:', err);
      }
    }

    if (!student) {
      res.status(404).json({ error: 'Student record not found' });
      return;
    }

    // Role-based ownership check
    if (session?.role === 'STUDENT') {
      if (session.studentId !== student.id && session.studentId !== student.admissionNumber && session.studentId !== id) {
        return res.status(403).json({ error: 'Forbidden: You can only view your own student profile.' });
      }
    }
    if (session?.role === 'PARENT') {
      const linked = [
        ...(Array.isArray(session.linkedStudentIds) ? session.linkedStudentIds : []),
        ...(Array.isArray(user?.linkedStudentIds) ? user.linkedStudentIds : []),
        ...(session.studentId ? [session.studentId] : []),
        ...(session.activeStudentId ? [session.activeStudentId] : []),
      ];
      const parentPhone = normalizePhone(user?.phone || user?.username || '');
      const isLinked =
        linked.includes(student.id) ||
        (!!student.admissionNumber && linked.includes(student.admissionNumber)) ||
        (parentPhone && (
          normalizePhone(student.parentPhone) === parentPhone ||
          normalizePhone(student.fatherMobile) === parentPhone ||
          normalizePhone(student.motherMobile) === parentPhone ||
          normalizePhone(student.guardianMobile) === parentPhone ||
          normalizePhone(student.mobile) === parentPhone
        ));
      if (!isLinked) {
        return res.status(403).json({ error: 'Forbidden: You can only view profiles of your linked children.' });
      }
    }
    if (session?.role === 'TEACHER') {
      const currentTeacher = findStaffForUser(user, session);
      if (!currentTeacher || !isTeacherAuthorizedForStudent(currentTeacher, student)) {
        return res.status(403).json({ error: 'Forbidden: You are only authorized to view student records in your assigned classes and sections.' });
      }
    }

    res.json(stripStudentSecrets(student));
  });

  // Hierarchical Fee Resolver Helper:
  // Priority 1: Section Override + Student Category
  // Priority 2: Section Override + ALL Categories
  // Priority 3: Class Default + Student Category
  // Priority 4: Class Default + ALL Categories
  // Priority 5: Any config for Class
  function getEffectiveFeeConfigServer(
    classIdOrName: string,
    section?: string,
    academicSession?: string,
    studentCategory?: string
  ): ClassFeeConfiguration | null {
    const targetSession = academicSession || schoolSettings.currentAcademicSession || '2026-2027';

    // Normalize class identifiers
    const targetClass = classes.find(
      (c) =>
        c.id?.toLowerCase() === classIdOrName?.toLowerCase() ||
        c.name?.toLowerCase() === classIdOrName?.toLowerCase() ||
        c.id?.replace(/^c-/, 'class-').toLowerCase() === classIdOrName?.toLowerCase() ||
        c.id?.replace(/^class-/, 'c-').toLowerCase() === classIdOrName?.toLowerCase()
    );

    const validClassIdentifiers = new Set(
      [
        classIdOrName?.toLowerCase(),
        targetClass?.id?.toLowerCase(),
        targetClass?.name?.toLowerCase(),
        classIdOrName?.replace(/^c-/, 'class-')?.toLowerCase(),
        classIdOrName?.replace(/^class-/, 'c-')?.toLowerCase(),
      ].filter(Boolean) as string[]
    );

    // Filter by session if available, else all
    let sessionList = feeConfigurations.filter((c) => c.academicSession === targetSession);
    if (sessionList.length === 0) sessionList = feeConfigurations;

    // Filter by class
    const classConfigs = sessionList.filter((c) => {
      const cId = c.classId?.toLowerCase();
      const cName = c.className?.toLowerCase();
      return (
        (cId && validClassIdentifiers.has(cId)) ||
        (cName && validClassIdentifiers.has(cName))
      );
    });

    if (classConfigs.length === 0) {
      const anyClassConfig = feeConfigurations.find((c) => {
        const cId = c.classId?.toLowerCase();
        const cName = c.className?.toLowerCase();
        return (
          (cId && validClassIdentifiers.has(cId)) ||
          (cName && validClassIdentifiers.has(cName))
        );
      });
      return anyClassConfig || null;
    }

    // 1. Priority 1: Specific section match + Specific student category
    if (section && section !== 'ALL') {
      if (studentCategory && studentCategory !== 'ALL') {
        const exactSectionCat = classConfigs.find(
          (c) => c.section === section && c.studentCategory === studentCategory
        );
        if (exactSectionCat) return exactSectionCat;
      }
      // Priority 2: Specific section match + All categories (or undefined)
      const sectionMatch = classConfigs.find(
        (c) => c.section === section && (!c.studentCategory || c.studentCategory === 'ALL')
      );
      if (sectionMatch) return sectionMatch;
    }

    // 2. Priority 3: Class-level default + Specific student category
    if (studentCategory && studentCategory !== 'ALL') {
      const classCatMatch = classConfigs.find(
        (c) => (!c.section || c.section === 'ALL' || c.section === 'Default') && c.studentCategory === studentCategory
      );
      if (classCatMatch) return classCatMatch;
    }

    // 3. Priority 4: Class-level default (ALL or no section) + All categories (or undefined)
    const classDefault = classConfigs.find(
      (c) => (!c.section || c.section === 'ALL' || c.section === 'Default') && (!c.studentCategory || c.studentCategory === 'ALL')
    );
    if (classDefault) return classDefault;

    // 4. Fallback: Any match for class
    return classConfigs[0] || null;
  }

  app.post('/api/students', requireRole(['SUPER_ADMIN', 'SCHOOL_ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'ACADEMIC_COORDINATOR', 'ACCOUNTANT', 'ADMIN']), async (req: Request, res: Response) => {
    const studentData = { ...req.body };
    const actor = (req as any).currentUser as User | undefined;

    // Secrets are never stored on the student record or echoed back (portal passwords are set separately).
    for (const key of STUDENT_SECRET_FIELDS) delete (studentData as any)[key];

    const fullName = String(
      studentData.name ||
      [studentData.firstName, studentData.middleName, studentData.lastName].filter(Boolean).join(' ') ||
      ''
    ).replace(/\s+/g, ' ').trim();

    const validation = validateStudentAdmissionInput({ ...studentData, name: fullName });
    if (validation.error) {
      return res.status(400).json({ success: false, error: validation.error });
    }
    const currentClass = validation.cls!;
    studentData.section = validation.section;

    // The create endpoint never updates an existing record (use PUT /api/students/:id for edits).
    if (studentData.id && students.some((s) => s.id === studentData.id)) {
      return res.status(409).json({ success: false, error: 'This student record already exists. Refresh the page to see it.', code: 'STUDENT_EXISTS' });
    }
    const requestedAdmissionNumber = studentData.admissionNumber ? String(studentData.admissionNumber).trim() : '';
    if (requestedAdmissionNumber && (students.some((s) => s.admissionNumber === requestedAdmissionNumber) || feeLedgers.some((l) => l.admissionNumber === requestedAdmissionNumber))) {
      return res.status(409).json({ success: false, error: `Admission number ${requestedAdmissionNumber} is already in use.`, code: 'ADMISSION_NUMBER_IN_USE' });
    }
    // Same child submitted twice (double click, network retry, or two people entering the same form).
    const parentMobileKey = normalizePhone(studentData.fatherMobile || studentData.parentPhone || studentData.motherMobile || studentData.mobile || '');
    const duplicateChild = students.find((s) =>
      String(s.name || '').trim().toLowerCase() === fullName.toLowerCase() &&
      String(s.dob || '').substring(0, 10) === String(studentData.dob || '').substring(0, 10) &&
      (!parentMobileKey || normalizePhone(s.fatherMobile || s.parentPhone || s.motherMobile || s.mobile || '') === parentMobileKey)
    );
    if (duplicateChild) {
      return res.status(409).json({
        success: false,
        error: `${duplicateChild.name} (date of birth ${duplicateChild.dob}) is already admitted with admission number ${duplicateChild.admissionNumber}.`,
        code: 'DUPLICATE_ADMISSION',
        existingStudentId: duplicateChild.id,
        existingAdmissionNumber: duplicateChild.admissionNumber,
      });
    }

    // Strict Anti-Double-Booking validation during admission
    if (studentData.hostelRequired && studentData.hostelRoomId && studentData.hostelBedNumber) {
      const targetRoom = hostelRooms.find((r) => r.id === studentData.hostelRoomId);
      if (!targetRoom) {
        return res.status(400).json({ error: 'Selected hostel room was not found.' });
      }
      const targetBed = targetRoom.beds?.find((b) => String(b.bedNumber) === String(studentData.hostelBedNumber));
      if (!targetBed) {
        return res.status(400).json({ error: `Bed ${studentData.hostelBedNumber} was not found in Room ${targetRoom.roomNumber}.` });
      }
      if (targetBed.allocatedStudentId) {
        return res.status(409).json({
          error: 'BED_ALREADY_OCCUPIED',
          message: `Bed ${studentData.hostelBedNumber} in Room ${targetRoom.roomNumber} is already occupied by ${targetBed.allocatedStudentName || 'another student'}. Please select an available bed.`,
        });
      }
    } else if (!studentData.hostelRequired) {
      // Explicitly clear hostel fields when not opted in
      studentData.hostelRequired = false;
      studentData.hostelId = undefined;
      studentData.hostelName = undefined;
      studentData.hostelRoomId = undefined;
      studentData.hostelFloor = undefined;
      studentData.hostelBedNumber = undefined;
      studentData.hostelWarden = undefined;
      studentData.hostelAllocationDate = undefined;
      studentData.hostelStatus = undefined;
      studentData.hostelMonthlyFee = 0;
      studentData.messMonthlyFee = 0;
    }

    // Identifiers are allocated by the server (the admission form only shows a preview).
    const admissionNumber = requestedAdmissionNumber || allocateNextAdmissionNumber();
    const registrationNumber = allocateNextRegistrationNumber(currentClass, studentData.academicSession || schoolSettings.currentAcademicSession);
    const rollNumber = allocateNextRollNumber(currentClass.id, studentData.section);
    delete studentData.registrationNumber;
    delete studentData.rollNumber;
    studentData.admittedBy = actor?.name || actor?.id;

    const cleanPhoto = (studentData.photo && !studentData.photo.startsWith('blob:') && !studentData.photo.startsWith('data:'))
      ? studentData.photo
      : (studentData.photoFileKey || '');
    const cleanPhotoKey = studentData.photoFileKey || (cleanPhoto ? cleanPhoto : '');

    const istToday = getNowInAsiaKolkata().isoDate;
    const effectiveEnrollmentDate = studentData.enrollmentDate || studentData.admissionDate || istToday;
    const effectiveFeeStartDate = studentData.feeStartDate || effectiveEnrollmentDate;
    const effectivePortalEntryDate = studentData.portalEntryDate || istToday;

    let newStudentId = studentData.id ? String(studentData.id).trim() : '';
    if (!newStudentId) {
      newStudentId = `st-${Date.now()}`;
      while (students.some((s) => s.id === newStudentId)) newStudentId = `st-${Date.now()}-${crypto.randomBytes(2).toString('hex')}`;
    }

    const newStudent: Student = {
      ...studentData,
      id: newStudentId,
      name: fullName,
      admissionNumber,
      registrationNumber,
      rollNumber,
      admissionDate: studentData.admissionDate || effectiveEnrollmentDate,
      enrollmentDate: effectiveEnrollmentDate,
      feeStartDate: effectiveFeeStartDate,
      portalEntryDate: effectivePortalEntryDate,
      feeProfile: studentData.feeProfile,
      className: currentClass.name,
      classId: currentClass.id,
      academicSession: studentData.academicSession || schoolSettings.currentAcademicSession,
      status: studentData.status || 'ACTIVE',
      parentName: studentData.parentName || studentData.fatherName || studentData.motherName || studentData.guardianName || '',
      parentPhone: studentData.parentPhone || studentData.fatherMobile || studentData.mobile || '',
      photo: cleanPhoto,
      photoFileKey: cleanPhotoKey,
      documents: Array.isArray(studentData.documents) ? studentData.documents : [],
    };

    // Resolve transport details if opted in
    if (newStudent.transportRequired) {
      let transportFee = Number(newStudent.transportMonthlyFee || 0);
      if (newStudent.transportRouteId) {
        const route = transportRoutes.find((r) => r.id === newStudent.transportRouteId || r.routeName === newStudent.transportRouteId);
        if (route) {
          const stop = (route.stops || []).find((s) => s.id === newStudent.transportStopId || s.stopName === newStudent.transportStopName || s.name === newStudent.transportStopName);
          if (stop) {
            transportFee = Number(stop.monthlyFare ?? stop.fare ?? stop.fee ?? 0);
            newStudent.transportMonthlyFee = transportFee;
            if (!newStudent.transportStopName) newStudent.transportStopName = stop.stopName;
            if (!newStudent.transportStopId) newStudent.transportStopId = stop.id;
          }
          if (!newStudent.vehicleNumber && route.vehicleNumber) newStudent.vehicleNumber = route.vehicleNumber;
          if (!newStudent.driverName && route.driverName) newStudent.driverName = route.driverName;
          if (!newStudent.driverContact && route.driverPhone) newStudent.driverContact = route.driverPhone;
        }
      }
      if (!transportFee && newStudent.transportSlabId) {
        const slab = transportSlabs.find((s) => s.id === newStudent.transportSlabId || s.id === newStudent.transportRouteId);
        transportFee = slab ? Number(slab.monthlyFee || slab.monthlyAmount || 0) : 0;
        if (transportFee) newStudent.transportMonthlyFee = transportFee;
      }
      // The amount the office typed for Transport Fee in Step 4 wins over the stop's standard fare.
      const typedTransportHead = (newStudent.feeProfile?.feeHeads || []).find(
        (h) => h.head === 'Transport Fee' && h.selected && Number(h.amount) > 0
      );
      if (typedTransportHead) {
        transportFee = Number(typedTransportHead.amount);
        newStudent.transportMonthlyFee = transportFee;
      }
      // Ensure feeProfile has Transport Fee
      if (!newStudent.feeProfile) {
        newStudent.feeProfile = {
          feeHeads: [],
          totalOneTimeFee: 0,
          totalMonthlyFee: 0,
          totalYearlyFee: 0,
          monthlyPayableAmount: 0,
          totalApplicableFee: 0,
          transportIncluded: true,
        };
      }
      if (!Array.isArray(newStudent.feeProfile.feeHeads)) {
        newStudent.feeProfile.feeHeads = [];
      }
      const existingHead = newStudent.feeProfile.feeHeads.find((h) => h.head === 'Transport Fee');
      if (existingHead) {
        existingHead.amount = transportFee;
        existingHead.selected = true;
      } else if (transportFee > 0) {
        newStudent.feeProfile.feeHeads.push({
          id: `head-transport-${Date.now()}`,
          head: 'Transport Fee',
          category: 'FACILITY',
          frequency: 'Monthly',
          amount: transportFee,
          selected: true,
          isDefault: false,
          remarks: `School Bus ${newStudent.transportStopName || ''}`,
        });
      }
      newStudent.feeProfile.transportIncluded = true;
    }

    // Write to MongoDB first and only report success once the database has accepted the record.
    if (mongoService.isConnected()) {
      const saved = await mongoService.insertStudent(newStudent);
      if (!saved) {
        return res.status(500).json({ success: false, error: 'Could not save the admission. Please try again.' });
      }
    }
    students.unshift(newStudent);
    persistentStorage.saveStudentsToDisk(students);
    if (newStudent.transportRequired) {
      syncRouteStudentCounts();
      persistentStorage.saveRoutesToDisk(transportRoutes);
    }

    const initialParentPhone = newStudent.fatherMobile || newStudent.parentPhone || newStudent.mobile || '';
    if (initialParentPhone) {
      handleParentPhoneMigration(
        newStudent.id,
        '',
        initialParentPhone,
        newStudent.parentName || newStudent.fatherName
      ).catch(() => {});
    }

    // Automatically update hostel room bed allocation if student is a hosteller
    if (newStudent.hostelRequired && newStudent.hostelRoomId && newStudent.hostelBedNumber) {
      const roomIdx = hostelRooms.findIndex((r) => r.id === newStudent.hostelRoomId);
      if (roomIdx !== -1) {
        const room = hostelRooms[roomIdx];
        const targetBed = room.beds?.find((b) => String(b.bedNumber) === String(newStudent.hostelBedNumber));
        if (targetBed) {
          targetBed.allocatedStudentId = newStudent.id;
          targetBed.allocatedStudentName = newStudent.name;
          targetBed.allocatedAdmissionNo = newStudent.admissionNumber;
          targetBed.allocationDate = newStudent.admissionDate || new Date().toISOString().substring(0, 10);
          targetBed.status = 'OCCUPIED';
        }
        room.occupiedBeds = (room.beds || []).filter((b) => Boolean(b.allocatedStudentId)).length;
        if (room.occupiedBeds >= (room.capacity || room.capacityBeds)) room.status = 'FULL';
        persistentStorage.saveHostelRoomsToDisk(hostelRooms);

        const newAllocation: HostelAllocation = {
          id: `ha-${newStudent.id}-${Date.now()}`,
          studentId: newStudent.id,
          studentName: newStudent.name,
          admissionNumber: newStudent.admissionNumber,
          hostelId: room.hostelId,
          hostelName: room.hostelName || newStudent.hostelName || 'Hostel',
          roomId: room.id,
          roomNumber: room.roomNumber,
          floor: room.floor,
          bedNumber: newStudent.hostelBedNumber,
          allocationDate: newStudent.admissionDate || new Date().toISOString().substring(0, 10),
          monthlyRent: room.monthlyFee || newStudent.hostelMonthlyFee || 0,
          messFee: newStudent.messMonthlyFee || 0,
          status: 'ACTIVE',
        };
        hostelAllocations.push(newAllocation);
        persistentStorage.saveHostelAllocationsToDisk(hostelAllocations);
      }
    }

    // Dynamic Admission Fee Calculation & Initial Fee Ledger Generation
    // At admission, immediately generate the payable invoice for all selected ONE-TIME admission charges.
    const breakdownItems: { head: string; amount: number; isOneTime?: boolean }[] = [];

    if (newStudent.feeProfile?.feeHeads && Array.isArray(newStudent.feeProfile.feeHeads) && newStudent.feeProfile.feeHeads.length > 0) {
      // Respect configured fee profile selected in Step 4: Fee Structure & Facilities.
      // One-time heads + Books & Stationery (yearly, for the class joined) are paid at admission.
      // The Exam Fee is NOT billed here: it is added when the Annual Examination is published.
      const activeOneTimeHeads = newStudent.feeProfile.feeHeads.filter(
        (h: any) =>
          h.selected &&
          Number(h.amount) > 0 &&
          !isExamHeadServer(h.head) &&
          (h.category === 'ONE_TIME' || h.frequency === 'One Time' || isBooksHeadServer(h.head))
      );
      for (const h of activeOneTimeHeads) {
        breakdownItems.push({
          head: h.head,
          amount: Number(h.amount) || 0,
          isOneTime: true,
        });
      }
    } else {
      const classCfg = getEffectiveFeeConfigServer(
        newStudent.classId,
        newStudent.section,
        newStudent.academicSession,
        newStudent.category
      );
      const admFee = classCfg ? Number(classCfg.admissionFee || 0) : 5000;
      const dressFee = newStudent.dressCodeSelected !== false ? (classCfg ? Number(classCfg.dressCodeFee || 0) : 2200) : 0;
      const booksFee = newStudent.booksSelected ? (classCfg ? Number(classCfg.booksFee || classCfg.booksStationeryFee || 0) : 1500) : 0;
      const idCardFee = classCfg ? Number(classCfg.idCardFee || 0) : 200;

      if (admFee > 0) {
        breakdownItems.push({ head: 'Admission Fee', amount: admFee, isOneTime: true });
      }
      if (dressFee > 0) {
        breakdownItems.push({ head: 'Uniform / Dress Code', amount: dressFee, isOneTime: true });
      }
      if (booksFee > 0) {
        breakdownItems.push({ head: 'Books & Stationery Kit', amount: booksFee, isOneTime: true });
      }
      if (idCardFee > 0) {
        breakdownItems.push({ head: 'ID Card & Student Diary', amount: idCardFee, isOneTime: true });
      }

      if (classCfg?.items && Array.isArray(classCfg.items)) {
        for (const it of classCfg.items) {
          if (it.category === 'ONE_TIME' && it.mandatory && Number(it.amount) > 0) {
            breakdownItems.push({ head: it.name, amount: Number(it.amount), isOneTime: true });
          }
        }
      }
    }

    const initialPayableTotal = breakdownItems.reduce((acc, item) => acc + item.amount, 0);

    // Prevent duplicate initial fee ledger if already exists for this student
    const admissionInvoiceNumber = `INV-ADM-${newStudent.admissionNumber}`;
    const existingLedger = feeLedgers.find(
      (l) =>
        l.studentId === newStudent.id &&
        (l.feeType?.includes('Admission') || l.feeMonth?.includes('Admission') || l.invoiceNumber === admissionInvoiceNumber)
    );
    if (!existingLedger) {
      const initialLedger: FeeLedgerEntry = {
        ...(breakdownItems.some((b) => isBooksHeadServer(b.head))
          ? { booksFeeSession: newStudent.academicSession || schoolSettings.currentAcademicSession }
          : {}),
        id: `fl-adm-${newStudent.id}-${Date.now()}`,
        invoiceNumber: admissionInvoiceNumber,
        studentId: newStudent.id,
        admissionNumber: newStudent.admissionNumber,
        studentName: newStudent.name,
        className: newStudent.className,
        section: newStudent.section,
        academicSession: newStudent.academicSession,
        feeMonth: `Admission ${newStudent.academicSession?.split('-')[0] || '2026'}`,
        monthYear: `Admission ${newStudent.academicSession?.split('-')[0] || '2026'}`,
        billingPeriod: `Admission ${newStudent.academicSession?.split('-')[0] || '2026'}`,
        feeType: 'Admission & One-Time Charges',
        breakdown: breakdownItems,
        amount: initialPayableTotal,
        discount: 0,
        fine: 0,
        total: initialPayableTotal,
        totalAmount: initialPayableTotal,
        paidAmount: 0,
        pendingAmount: initialPayableTotal,
        status: 'PENDING',
        dueDate: new Date(Date.now() + 15 * 86400000).toISOString().substring(0, 10),
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };
      feeLedgers.unshift(initialLedger);
      persistentStorage.saveFeeLedgersToDisk(feeLedgers);
      if (mongoService.isConnected()) {
        mongoService.insertFeeLedger(initialLedger).catch(() => {});
      }
    }

    // The enrollment month's fee is collected on admission day (e.g. enrolled 01-11-2026 -> November bill now).
    try {
      const enrollmentMonthLedger = createEnrollmentMonthInvoiceServer(newStudent);
      if (enrollmentMonthLedger) {
        feeLedgers.unshift(enrollmentMonthLedger);
        persistentStorage.saveFeeLedgersToDisk(feeLedgers);
        if (mongoService.isConnected()) {
          mongoService.insertFeeLedger(enrollmentMonthLedger).catch(() => {});
        }
      }
    } catch (enrollMonthErr) {
      console.error('[StudentAdmission] Enrollment month fee bill warning:', enrollMonthErr);
    }

    try {
      runAutomatedMonthlyFeeGeneration();
    } catch (engineErr) {
      console.error('[StudentAdmission] Automated fee generation warning:', engineErr);
    }

    logAudit('Administrator', 'SCHOOL_ADMIN', 'STUDENT_ADMISSION', 'Student', newStudent.id, `Admitted ${newStudent.name} (Adm: ${newStudent.admissionNumber})`);
    broadcastRealtimeEvent('STUDENT', 'CREATE', newStudent, {
      studentId: newStudent.id,
      classId: newStudent.classId,
      section: newStudent.section,
      description: `Admitted student ${newStudent.name} (Adm: ${newStudent.admissionNumber})`,
    });

    // Email dispatch: If student has a valid parent email, send admission confirmation via Brevo
    const targetParentEmail = (newStudent.parentEmail || newStudent.fatherEmail || newStudent.motherEmail || newStudent.email || '').trim();
    if (targetParentEmail && targetParentEmail.includes('@')) {
      const portalBaseUrl = resolveProductionFrontendUrl(req);
      emailService.sendAdmissionConfirmationEmail({
        to: targetParentEmail,
        parentName: newStudent.parentName || newStudent.fatherName || 'Parent / Guardian',
        studentName: newStudent.name,
        admissionNumber: newStudent.admissionNumber,
        registrationNumber: newStudent.registrationNumber,
        className: newStudent.className,
        section: newStudent.section,
        temporaryPassword: (studentData as any).temporaryPassword || undefined,
        portalUrl: portalBaseUrl,
        schoolName: schoolSettings.schoolName || 'CHANAKYA PUBLIC SCHOOL & COACHING CENTRE',
      }).then((res) => {
        // Brevo accepting the message is not proof of delivery; record it as accepted.
        logAudit(
          actor?.name || 'Administrator',
          (actor?.role as UserRole) || 'SCHOOL_ADMIN',
          res.success ? 'ADMISSION_EMAIL_ACCEPTED' : 'ADMISSION_EMAIL_FAILED',
          'Student',
          newStudent.id,
          res.success
            ? `Admission confirmation accepted by the email provider for ${maskEmailAddress(targetParentEmail)}${res.messageId ? ` (message ${res.messageId})` : ''}`
            : `Admission confirmation email could not be sent to ${maskEmailAddress(targetParentEmail)}`
        );
      }).catch((err) => {
        console.warn('[StudentAdmission] Error dispatching admission email:', err?.message);
      });
    }

    logAudit(actor?.name || 'Administrator', (actor?.role as UserRole) || 'SCHOOL_ADMIN', 'STUDENT_ADMITTED', 'Student', newStudent.id, `Admitted ${newStudent.name} (Adm: ${newStudent.admissionNumber}) to ${newStudent.className}-${newStudent.section}`);
    res.status(200).json(stripStudentSecrets(newStudent));
  });

  // Promote students to the next class (one student or a whole class at once).
  // Body: { studentIds, toClassId, toSection?, targetSession?, remark?, chargeBooksFee? (default true), booksFee? }
  // Each student's current year goes into academicHistory, roll numbers continue in the new class, and
  // the new class's Books & Stationery fee is billed once for the new session.
  app.post('/api/students/promote', requireRole(['SUPER_ADMIN', 'SCHOOL_ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'ACADEMIC_COORDINATOR', 'ADMIN']), async (req: Request, res: Response) => {
    const { studentIds, toClassId, toSection, targetSession, remark, chargeBooksFee = true, booksFee, customRoll } = req.body || {};
    if (!Array.isArray(studentIds) || studentIds.length === 0) {
      return res.status(400).json({ error: 'Select at least one student to promote.' });
    }
    const toClass = classes.find((c) => c.id === toClassId || c.name === toClassId);
    if (!toClass) {
      return res.status(400).json({ error: 'Choose the class to promote to.' });
    }
    const actor = auditActor(req);
    const session = String(targetSession || '').trim() || nextAcademicSessionServer(schoolSettings.currentAcademicSession);
    const today = todayIstServer();
    const booksOverride = booksFee !== undefined && booksFee !== null && booksFee !== '' ? Math.max(0, Math.round(Number(booksFee) || 0)) : null;

    const picked = studentIds
      .map((id: string) => students.find((s) => s.id === id))
      .filter(Boolean) as Student[];
    // Promote in current roll-number order so the new roll numbers keep the same order
    picked.sort((a, b) => (parseInt(a.rollNumber || '', 10) || 9999) - (parseInt(b.rollNumber || '', 10) || 9999) || a.name.localeCompare(b.name));

    const promoted: { id: string; name: string; from: string; to: string; rollNumber: string; booksBilled: number }[] = [];
    const skipped: { id: string; name: string; reason: string }[] = [];
    const newBills: FeeLedgerEntry[] = [];
    const nextRoll: Record<string, number> = {};

    for (const student of picked) {
      if (student.status !== 'ACTIVE') {
        skipped.push({ id: student.id, name: student.name, reason: `status is ${student.status}` });
        continue;
      }
      const section = String(toSection && toSection !== 'SAME' ? toSection : student.section || 'A');
      if ((student.classId === toClass.id || student.className === toClass.name) && student.academicSession === session) {
        skipped.push({ id: student.id, name: student.name, reason: `already in ${toClass.name} for ${session}` });
        continue;
      }
      const key = `${toClass.id}|${section}`;
      if (nextRoll[key] === undefined) {
        const existingRolls = students
          .filter((s) => s.status === 'ACTIVE' && (s.classId === toClass.id || s.className === toClass.name) && s.section === section && s.academicSession === session)
          .map((s) => parseInt(s.rollNumber || '', 10) || 0);
        nextRoll[key] = (existingRolls.length ? Math.max(...existingRolls) : 0) + 1;
      }
      // A roll number typed for a single-student promotion is used as it is
      const rollNumber = picked.length === 1 && customRoll ? String(customRoll).trim() : String(nextRoll[key]++);
      const from = `${student.className}-${student.section}`;
      const to = `${toClass.name}-${section}`;

      student.academicHistory = [
        {
          session: student.academicSession,
          className: student.className,
          section: student.section,
          rollNumber: student.rollNumber,
          result: 'PROMOTED',
          promotionDate: today,
          status: `Promoted to ${to}`,
        } as any,
        ...(student.academicHistory || []),
      ];
      student.activityHistory = [
        {
          id: `act-${Date.now()}-${Math.random().toString(36).substring(2, 6)}`,
          timestamp: today,
          title: `Promoted to ${to}`,
          description: `Academic promotion from ${from} (${student.academicSession}) to ${to} (${session}).${remark ? ` Remark: ${remark}` : ''}`,
          category: 'ACADEMIC',
          performedBy: actor.name,
        } as any,
        ...(student.activityHistory || []),
      ];
      student.classId = toClass.id;
      student.className = toClass.name;
      student.section = section;
      student.rollNumber = rollNumber;
      student.academicSession = session;

      // Books & Stationery of the new class, once for the new session
      let booksBilled = 0;
      const booksHead = (student.feeProfile?.feeHeads || []).find((h) => isBooksHeadServer(h.head));
      if (chargeBooksFee !== false) {
        const cfg: any = getEffectiveFeeConfigServer(toClass.id, section, session, student.category);
        const amount = booksOverride ?? Math.max(0, Number(cfg?.booksFee ?? cfg?.booksStationeryFee ?? 0));
        if (booksHead && booksHead.selected === false) {
          // the office switched Books off for this student (e.g. buys their own books)
        } else if (amount > 0 && !hasBooksBillServer(student.id, session)) {
          const bill = buildBooksBillServer(student, amount, session, toClass.name);
          feeLedgers.unshift(bill);
          newBills.push(bill);
          booksBilled = amount;
          if (booksHead) booksHead.amount = amount;
        }
      }
      if (student.feeProfile) {
        student.feeProfile = {
          ...student.feeProfile,
          className: toClass.name,
          section,
          academicSession: session,
          updatedAt: new Date().toISOString(),
        } as any;
      }

      try {
        await persistentStorage.saveStudent(student);
        if (mongoService.isConnected()) await mongoService.updateStudent(student.id, student);
      } catch (saveErr) {
        console.error('[Promotion] Save warning for', student.id, saveErr);
      }
      promoted.push({ id: student.id, name: student.name, from, to, rollNumber, booksBilled });
    }

    if (promoted.length > 0) {
      persistentStorage.saveStudentsToDisk(students);
      if (newBills.length > 0) persistentStorage.saveFeeLedgersToDisk(feeLedgers);
      logAudit(actor.name, actor.role, 'STUDENTS_PROMOTED', 'Student', toClass.id,
        `Promoted ${promoted.length} student(s) to ${toClass.name} (${session})${newBills.length ? `, books fee billed for ${newBills.length}` : ''}`);
      broadcastRealtimeEvent('STUDENT', 'UPDATE', { count: promoted.length, classId: toClass.id }, {
        classId: toClass.id,
        description: `Promoted ${promoted.length} student(s) to ${toClass.name}`,
      });
      if (newBills.length > 0) {
        broadcastRealtimeEvent('FEE_LEDGER', 'CREATE', { count: newBills.length }, {
          description: `Books & Stationery fee added for ${newBills.length} promoted students`,
        });
      }
    }

    res.json({
      success: true,
      session,
      toClass: { id: toClass.id, name: toClass.name },
      promoted,
      skipped,
      booksBills: newBills.length,
      booksTotal: newBills.reduce((sum, b) => sum + b.total, 0),
      students: promoted.map((p) => stripStudentSecrets(students.find((s) => s.id === p.id)!)),
    });
  });

  // Update student endpoint (supports both PUT and PATCH)
  const handleStudentUpdate = async (req: Request, res: Response) => {
    const { id } = req.params;

    // Find student in memory by id, admissionNumber, or _id
    let index = students.findIndex((s) => s.id === id || (s as any)._id?.toString() === id || s.admissionNumber === id);
    if (index === -1 && mongoService.isConnected()) {
      try {
        const dbStudent = await mongoService.getStudentById(id);
        if (dbStudent) {
          students.push(dbStudent);
          index = students.length - 1;
        }
      } catch (err) {
        console.warn('[Server] Error finding student in MongoDB on update:', err);
      }
    }

    if (index === -1) {
      res.status(404).json({ success: false, error: `Student with identifier "${id}" not found.` });
      return;
    }

    const existing = students[index];
    const targetId = existing.id;
    const oldPrimaryPhone = existing.fatherMobile || existing.parentPhone || existing.mobile || '';
    const oldEnrollmentDate = existing.feeStartDate || existing.enrollmentDate || existing.admissionDate || '';
    // Preserve immutable identifiers
    const immutableAdmissionNumber = existing.admissionNumber;
    const immutableRegistrationNumber = existing.registrationNumber;
    const updates = { ...req.body };
    delete updates.admissionNumber;
    delete updates.registrationNumber;
    delete updates.id;
    delete updates._id;
    // Passwords are changed only through the dedicated reset endpoints.
    for (const key of STUDENT_SECRET_FIELDS) delete updates[key];

    if (updates.firstName || updates.lastName) {
      updates.name = [updates.firstName, updates.middleName, updates.lastName].filter(Boolean).join(' ') || updates.name || existing.name;
    }

    // Fee structure (the admission fee heads). Only people who may manage fee structures can change it
    // (Super Admin, School Admin, or anyone granted "fees.structure.manage"); for others the stored
    // profile is kept. The heads are cleaned and the totals recalculated on the server.
    const prevFeeHeads = JSON.parse(JSON.stringify(existing.feeProfile?.feeHeads || []));
    let feeProfileEdited = false;
    if (updates.feeProfile !== undefined) {
      const actor = (req as any).currentUser as User | undefined;
      const mayEditFees = !!actor && hasPermission(actor, 'fees.structure.manage');
      const incoming = updates.feeProfile;
      if (!mayEditFees || !incoming || typeof incoming !== 'object' || !Array.isArray((incoming as any).feeHeads)) {
        delete updates.feeProfile;
      } else {
        const heads = normalizeFeeHeads((incoming as any).feeHeads);
        const sameAsBefore = JSON.stringify(normalizeFeeHeads(prevFeeHeads)) === JSON.stringify(heads);
        if (sameAsBefore && existing.feeProfile) {
          delete updates.feeProfile;
        } else {
          feeProfileEdited = true;
          const cls = classes.find((c) => c.id === (updates.classId || existing.classId));
          updates.feeProfile = {
            ...(existing.feeProfile || {}),
            ...(incoming as any),
            className: cls?.name || existing.className,
            section: updates.section || existing.section,
            academicSession: existing.academicSession || schoolSettings.currentAcademicSession,
            feeHeads: heads,
            ...feeProfileTotals(heads),
            transportIncluded: heads.some((h) => h.selected && facilityKindOf(h.head) === 'transport'),
            hostelIncluded: heads.some((h) => h.selected && facilityKindOf(h.head) === 'hostel'),
            updatedAt: new Date().toISOString(),
          };
        }
      }
    }

    // Validate only the fields being changed so partial edits keep working.
    if (updates.name !== undefined && !String(updates.name || '').trim()) {
      return res.status(400).json({ success: false, error: "Student's name cannot be empty." });
    }
    const classChanging = (updates.classId !== undefined && updates.classId !== existing.classId) ||
      (updates.classId === undefined && updates.className !== undefined && updates.className !== existing.className);
    const sectionChanging = updates.section !== undefined && String(updates.section) !== String(existing.section);
    if (classChanging || sectionChanging) {
      const targetCls = findClassForStudent({
        classId: updates.classId !== undefined ? updates.classId : existing.classId,
        className: updates.classId !== undefined ? undefined : (updates.className ?? existing.className),
      });
      if (!targetCls) {
        return res.status(400).json({ success: false, error: 'The selected class does not exist. Please choose a class again.' });
      }
      if (classChanging && (targetCls.status || 'ACTIVE') !== 'ACTIVE') {
        return res.status(400).json({ success: false, error: `${targetCls.name} is not active. Please choose an active class.` });
      }
      const targetSection = String(updates.section !== undefined ? updates.section : existing.section || '');
      const secs = (targetCls.sections || []).map(String);
      const secMatch = secs.find((x) => x.toUpperCase() === targetSection.toUpperCase());
      if (secs.length > 0 && !secMatch) {
        return res.status(400).json({ success: false, error: `${targetCls.name} has no section "${targetSection}". Available sections: ${secs.join(', ')}.` });
      }
      updates.classId = targetCls.id;
      updates.className = targetCls.name;
      if (secMatch) updates.section = secMatch;
    }
    const changed = (field: string) => updates[field] !== undefined && updates[field] !== (existing as any)[field];
    if (changed('status') && !VALID_STUDENT_STATUSES.includes(String(updates.status).toUpperCase() as StudentStatus)) {
      return res.status(400).json({ success: false, error: 'Student status is not valid.' });
    }
    if (changed('dob') && updates.dob && (!isValidIsoDate(updates.dob) || String(updates.dob).substring(0, 10) >= getNowInAsiaKolkata().isoDate)) {
      return res.status(400).json({ success: false, error: 'Date of birth must be a valid date in the past.' });
    }
    for (const field of ['parentEmail', 'fatherEmail', 'motherEmail', 'email']) {
      if (changed(field) && updates[field] && !isValidEmailAddress(updates[field])) {
        return res.status(400).json({ success: false, error: `The email address "${updates[field]}" is not valid.` });
      }
    }

    // Preserve existing photo unless explicitly updated with a valid non-blob string
    if (!updates.photo && existing.photo) {
      updates.photo = existing.photo;
    } else if (updates.photo && (updates.photo.startsWith('blob:') || updates.photo.startsWith('data:')) && existing.photo) {
      updates.photo = existing.photo;
    }
    if (!updates.photoFileKey && existing.photoFileKey) {
      updates.photoFileKey = existing.photoFileKey;
    }

    // Preserve existing documents unless explicitly provided with non-empty array
    if ((!updates.documents || !Array.isArray(updates.documents) || updates.documents.length === 0) && existing.documents?.length) {
      updates.documents = existing.documents;
    }

    // Core rule: Fee Start Date automatically syncs with Enrollment Date
    if (updates.enrollmentDate) {
      updates.feeStartDate = updates.enrollmentDate;
    } else if (updates.feeStartDate && !updates.enrollmentDate) {
      updates.enrollmentDate = updates.feeStartDate;
    }

    students[index] = {
      ...existing,
      ...updates,
      id: targetId,
      admissionNumber: immutableAdmissionNumber,
      registrationNumber: immutableRegistrationNumber,
    };

    // Synchronize transport fee in feeProfile if transport is toggled/edited
    if (updates.transportRequired !== undefined || updates.transportRouteId !== undefined || updates.transportMonthlyFee !== undefined) {
      const s = students[index];
      if (s.transportRequired) {
        let tFee = Number(s.transportMonthlyFee || 0);
        if (!tFee && s.transportRouteId) {
          const r = transportRoutes.find((rt) => rt.id === s.transportRouteId || rt.routeName === s.transportRouteId);
          if (r) {
            const stp = (r.stops || []).find((st) => st.id === s.transportStopId || st.stopName === s.transportStopName || st.name === s.transportStopName);
            if (stp) {
              tFee = Number(stp.monthlyFare ?? stp.fare ?? stp.fee ?? 0);
              s.transportMonthlyFee = tFee;
              s.transportStopName = stp.stopName;
            }
            if (!s.vehicleNumber && r.vehicleNumber) s.vehicleNumber = r.vehicleNumber;
            if (!s.driverName && r.driverName) s.driverName = r.driverName;
            if (!s.driverContact && r.driverPhone) s.driverContact = r.driverPhone;
          }
        }
        if (!s.feeProfile) {
          s.feeProfile = {
            feeHeads: [],
            totalOneTimeFee: 0,
            totalMonthlyFee: 0,
            totalYearlyFee: 0,
            monthlyPayableAmount: 0,
            totalApplicableFee: 0,
            transportIncluded: true,
          };
        }
        if (!Array.isArray(s.feeProfile.feeHeads)) {
          s.feeProfile.feeHeads = [];
        }
        const existingHead = s.feeProfile.feeHeads.find((h) => h.head === 'Transport Fee');
        if (existingHead) {
          existingHead.amount = tFee;
          existingHead.selected = true;
        } else {
          s.feeProfile.feeHeads.push({
            id: `head-transport-${Date.now()}`,
            head: 'Transport Fee',
            category: 'FACILITY',
            frequency: 'Monthly',
            amount: tFee,
            selected: true,
            isDefault: false,
            remarks: `School Bus ${s.transportStopName || ''}`,
          });
        }
        s.feeProfile.transportIncluded = true;
      } else if (s.feeProfile && Array.isArray(s.feeProfile.feeHeads)) {
        s.transportMonthlyFee = 0;
        s.transportRouteId = '';
        s.transportStopName = '';
        s.transportStopId = '';
        s.feeProfile.transportIncluded = false;
        s.feeProfile.feeHeads.forEach((h) => {
          if (h.head === 'Transport Fee') {
            h.selected = false;
          }
        });
      }
      if (s.feeProfile && Array.isArray(s.feeProfile.feeHeads)) {
        let oneTime = 0, monthly = 0, yearly = 0;
        for (const h of s.feeProfile.feeHeads) {
          if (!h.selected) continue;
          const amt = Number(h.amount) || 0;
          const freq = String(h.frequency);
          if (h.category === 'ONE_TIME' || freq === 'One Time') oneTime += amt;
          else if (h.category === 'MONTHLY' || freq === 'Monthly' || (h.category === 'FACILITY' && freq === 'Monthly')) monthly += amt;
          else yearly += amt;
        }
        s.feeProfile.totalOneTimeFee = oneTime;
        s.feeProfile.totalMonthlyFee = monthly;
        s.feeProfile.totalYearlyFee = yearly;
        s.feeProfile.monthlyPayableAmount = monthly;
      }
      syncRouteStudentCounts();
    }

    // Synchronize Hostel Residency if hostel fields were provided / updated
    const hostelUpdated =
      updates.hostelRequired !== undefined ||
      updates.hostelRoomId !== undefined ||
      updates.hostelBedNumber !== undefined ||
      updates.hostelId !== undefined ||
      updates.hostelStatus !== undefined ||
      updates.hostelMonthlyFee !== undefined ||
      updates.messMonthlyFee !== undefined;

    if (hostelUpdated) {
      const s = students[index];
      const isHostelActive = s.hostelRequired && s.hostelStatus !== 'VACATED' && Boolean(s.hostelRoomId) && Boolean(s.hostelBedNumber);

      if (!isHostelActive) {
        // Student is Day Scholar or Vacated: release any beds previously occupied by this student
        for (const rm of hostelRooms) {
          let modified = false;
          for (const b of rm.beds || []) {
            if (b.allocatedStudentId === targetId || (existing.hostelRoomId === rm.id && String(b.bedNumber) === String(existing.hostelBedNumber))) {
              b.allocatedStudentId = undefined;
              b.allocatedStudentName = undefined;
              b.allocatedAdmissionNo = undefined;
              b.allocationDate = undefined;
              b.status = 'AVAILABLE';
              modified = true;
            }
          }
          if (modified) {
            rm.occupiedBeds = (rm.beds || []).filter((b) => Boolean(b.allocatedStudentId)).length;
            if (rm.status === 'FULL') rm.status = 'AVAILABLE';
          }
        }
        // Mark active allocations as VACATED
        const activeAllocs = hostelAllocations.filter((a) => a.studentId === targetId && a.status === 'ACTIVE');
        for (const a of activeAllocs) {
          a.status = 'VACATED';
          a.vacateDate = new Date().toISOString().substring(0, 10);
          a.remarks = a.remarks || 'Vacated via Student Profile edit';
        }
        if (mongoService.isConnected()) {
          HostelAllocationModel.updateMany(
            { studentId: targetId, status: 'ACTIVE' },
            { $set: { status: 'VACATED', vacateDate: new Date().toISOString().substring(0, 10) } }
          ).catch(() => {});
        }

        s.hostelRequired = false;
        s.hostelStatus = 'VACATED';
        s.hostelRoomId = undefined;
        s.hostelBedNumber = undefined;
      } else {
        // Student is a Hostel Resident: find target room
        const targetRoom = hostelRooms.find(
          (r) => r.id === s.hostelRoomId || r.roomNumber === s.hostelRoomId
        );

        if (targetRoom) {
          const targetBed = targetRoom.beds?.find(
            (b) => String(b.bedNumber) === String(s.hostelBedNumber)
          );

          if (targetBed) {
            // Anti-double-booking: check if already occupied by someone else
            if (targetBed.allocatedStudentId && targetBed.allocatedStudentId !== targetId) {
              return res.status(409).json({
                error: 'BED_ALREADY_OCCUPIED',
                message: `Bed ${s.hostelBedNumber} in Room ${targetRoom.roomNumber} is already occupied by ${targetBed.allocatedStudentName || 'another student'}.`,
              });
            }

            // If changing bed from another room or bed, vacate previous bed
            const isBedChanged =
              existing.hostelRoomId &&
              existing.hostelBedNumber &&
              (existing.hostelRoomId !== targetRoom.id || String(existing.hostelBedNumber) !== String(targetBed.bedNumber));

            if (isBedChanged) {
              for (const rm of hostelRooms) {
                let modified = false;
                for (const b of rm.beds || []) {
                  if (b.allocatedStudentId === targetId && (rm.id !== targetRoom.id || String(b.bedNumber) !== String(targetBed.bedNumber))) {
                    b.allocatedStudentId = undefined;
                    b.allocatedStudentName = undefined;
                    b.allocatedAdmissionNo = undefined;
                    b.allocationDate = undefined;
                    b.status = 'AVAILABLE';
                    modified = true;
                  }
                }
                if (modified) {
                  rm.occupiedBeds = (rm.beds || []).filter((b) => Boolean(b.allocatedStudentId)).length;
                  if (rm.status === 'FULL') rm.status = 'AVAILABLE';
                }
              }
              const prevAllocs = hostelAllocations.filter((a) => a.studentId === targetId && a.status === 'ACTIVE');
              for (const a of prevAllocs) {
                a.status = 'TRANSFERRED';
                a.vacateDate = new Date().toISOString().substring(0, 10);
              }
              if (mongoService.isConnected()) {
                HostelAllocationModel.updateMany(
                  { studentId: targetId, status: 'ACTIVE' },
                  { $set: { status: 'TRANSFERRED', vacateDate: new Date().toISOString().substring(0, 10) } }
                ).catch(() => {});
              }
            }

            // Allocate target bed
            targetBed.allocatedStudentId = targetId;
            targetBed.allocatedStudentName = s.name;
            targetBed.allocatedAdmissionNo = s.admissionNumber;
            targetBed.allocationDate = s.hostelAllocationDate || new Date().toISOString().substring(0, 10);
            targetBed.status = 'OCCUPIED';

            targetRoom.occupiedBeds = (targetRoom.beds || []).filter((b) => Boolean(b.allocatedStudentId)).length;
            if (targetRoom.occupiedBeds >= (targetRoom.capacity || targetRoom.capacityBeds)) {
              targetRoom.status = 'FULL';
            }

            const hostel = hostels.find((h) => h.id === targetRoom.hostelId);
            s.hostelId = targetRoom.hostelId;
            s.hostelName = targetRoom.hostelName || hostel?.name || s.hostelName;
            s.hostelRoomId = targetRoom.id;
            s.hostelFloor = targetRoom.floor;
            s.hostelBedNumber = targetBed.bedNumber;
            s.hostelWarden = hostel?.wardenName || s.hostelWarden;
            s.hostelStatus = 'ACTIVE';
            if (s.hostelMonthlyFee === undefined || s.hostelMonthlyFee === null) {
              s.hostelMonthlyFee = targetRoom.monthlyFee || hostel?.monthlyFee || 0;
            }
            if (s.messMonthlyFee === undefined || s.messMonthlyFee === null) {
              s.messMonthlyFee = hostel?.messFee || 0;
            }
            if (!s.hostelAllocationDate) {
              s.hostelAllocationDate = new Date().toISOString().substring(0, 10);
            }

            // Sync active allocation
            let currentAlloc = hostelAllocations.find(
              (a) => a.studentId === targetId && a.status === 'ACTIVE'
            );
            if (!currentAlloc || currentAlloc.roomId !== targetRoom.id || String(currentAlloc.bedNumber) !== String(targetBed.bedNumber)) {
              if (currentAlloc) {
                currentAlloc.status = 'TRANSFERRED';
                currentAlloc.vacateDate = new Date().toISOString().substring(0, 10);
              }
              currentAlloc = {
                id: `ha-${targetId}-${Date.now()}`,
                studentId: targetId,
                studentName: s.name,
                admissionNumber: s.admissionNumber,
                hostelId: targetRoom.hostelId,
                hostelName: targetRoom.hostelName || hostel?.name || 'Hostel',
                roomId: targetRoom.id,
                roomNumber: targetRoom.roomNumber,
                floor: targetRoom.floor,
                bedNumber: targetBed.bedNumber,
                allocationDate: s.hostelAllocationDate,
                monthlyRent: s.hostelMonthlyFee || 0,
                messFee: s.messMonthlyFee || 0,
                status: 'ACTIVE',
                remarks: 'Allocated/updated via Student Profile edit',
              };
              hostelAllocations.push(currentAlloc);
            } else {
              currentAlloc.monthlyRent = s.hostelMonthlyFee || 0;
              currentAlloc.messFee = s.messMonthlyFee || 0;
              currentAlloc.allocationDate = s.hostelAllocationDate;
            }

            if (mongoService.isConnected()) {
              HostelAllocationModel.findOneAndUpdate(
                { studentId: targetId, status: 'ACTIVE' },
                {
                  $set: {
                    hostelId: targetRoom.hostelId,
                    hostelName: targetRoom.hostelName,
                    roomId: targetRoom.id,
                    roomNumber: targetRoom.roomNumber,
                    floor: targetRoom.floor,
                    bedNumber: targetBed.bedNumber,
                    allocationDate: s.hostelAllocationDate,
                    monthlyRent: s.hostelMonthlyFee,
                    messFee: s.messMonthlyFee,
                  },
                },
                { upsert: true, new: true }
              ).catch(() => {});
            }
          }
        }
      }

      // Persist hostel rooms & allocations to disk and MongoDB
      persistentStorage.saveHostelRoomsToDisk(hostelRooms);
      persistentStorage.saveHostelAllocationsToDisk(hostelAllocations);
      if (mongoService.isConnected()) {
        persistentStorage.saveHostelRooms(hostelRooms).catch(() => {});
        persistentStorage.saveHostelAllocations(hostelAllocations).catch(() => {});
      }
      broadcastRealtimeEvent('HOSTEL', 'UPDATE', { studentId: targetId }, {
        studentId: targetId,
        description: `Hostel residency updated for ${s.name}`,
      });
    }

    // Hostel / mess fee heads follow the hostel residency (like the transport head above). Before, a
    // student admitted as a day scholar kept switched-off hostel heads after a hostel was allotted by
    // editing, and since a listed head stops the facility charge, hostel and mess were never billed.
    {
      const s = students[index];
      if (s.feeProfile && Array.isArray(s.feeProfile.feeHeads)) {
        const hostelActive = !!(s.hostelRequired && s.hostelStatus !== 'VACATED' && s.hostelRoomId && s.hostelBedNumber);
        for (const h of s.feeProfile.feeHeads) {
          const kind = facilityKindOf(h.head);
          if (kind === 'hostel') {
            if (hostelActive && Number(s.hostelMonthlyFee) > 0) h.amount = Number(s.hostelMonthlyFee);
            h.selected = hostelActive && Number(h.amount) > 0;
          } else if (kind === 'mess') {
            if (hostelActive && s.messMonthlyFee !== undefined && s.messMonthlyFee !== null) h.amount = Math.max(0, Number(s.messMonthlyFee) || 0);
            h.selected = hostelActive && Number(h.amount) > 0;
          }
        }
        Object.assign(s.feeProfile, feeProfileTotals(normalizeFeeHeads(s.feeProfile.feeHeads)), {
          hostelIncluded: hostelActive,
          transportIncluded: !!s.transportRequired,
        });
      }
    }

    // Fee structure edited: one-time / yearly heads that were added or switched on are billed once now,
    // in their own bill. Monthly heads go into the coming monthly bills; amounts already billed stay.
    let feeStructureBill: FeeLedgerEntry | null = null;
    if (feeProfileEdited) {
      const s = students[index];
      // A student without a fee structure of their own was charged by the class fee settings (one-time
      // charges at admission), so those defaults are the "before" and are not billed a second time.
      const before = prevFeeHeads.length
        ? normalizeFeeHeads(prevFeeHeads)
        : buildDefaultFeeHeads(getEffectiveFeeConfigServer(s.classId, s.section, s.academicSession || schoolSettings.currentAcademicSession, s.category), s);
      const billable = newlyBillableHeads(before, normalizeFeeHeads(s.feeProfile?.feeHeads || []));
      if (billable.length) {
        const total = Math.round(billable.reduce((a, b) => a + b.amount, 0) * 100) / 100;
        const nowIso = new Date().toISOString();
        const session = s.academicSession || schoolSettings.currentAcademicSession || '2026-2027';
        feeStructureBill = {
          id: `fl-ext-${s.id}-${Date.now()}-${Math.random().toString(36).substring(2, 6)}`,
          invoiceNumber: `INV-EXT-${(s.admissionNumber || s.id).slice(-6)}-${Date.now().toString(36).toUpperCase()}`,
          studentId: s.id,
          admissionNumber: s.admissionNumber || '',
          studentName: s.name,
          className: s.className,
          section: s.section,
          academicSession: session,
          feeMonth: `Additional charges ${todayIstServer()}`,
          monthYear: `Additional charges ${todayIstServer()}`,
          billingPeriod: 'ONE_TIME',
          feeType: 'Additional charges (fee structure updated)',
          breakdown: billable.map((b) => ({ head: b.head, amount: b.amount, isOneTime: true })),
          amount: total,
          discount: 0,
          fine: 0,
          total,
          totalAmount: total,
          paidAmount: 0,
          pendingAmount: total,
          status: 'PENDING',
          dueDate: addDaysIsoServer(15),
          billKind: 'EXTRA',
          createdAt: nowIso,
          updatedAt: nowIso,
        } as FeeLedgerEntry;
        feeLedgers.unshift(feeStructureBill);
        persistentStorage.saveFeeLedgersToDisk(feeLedgers);
        if (mongoService.isConnected()) {
          mongoService.insertFeeLedger(feeStructureBill).catch(() => {});
        }
      }
    }

    persistentStorage.saveStudentsToDisk(students);
    await persistentStorage.saveStudent(students[index]);
    if (mongoService.isConnected()) {
      const saved = await mongoService.updateStudent(targetId, students[index]);
      if (!saved) {
        return res.status(500).json({ success: false, error: 'Could not save changes. Please try again.' });
      }
    }

    const newPrimaryPhone = students[index].fatherMobile || students[index].parentPhone || students[index].mobile || '';
    if (oldPrimaryPhone && newPrimaryPhone && normalizePhone(oldPrimaryPhone) !== normalizePhone(newPrimaryPhone)) {
      try {
        await handleParentPhoneMigration(
          targetId,
          oldPrimaryPhone,
          newPrimaryPhone,
          students[index].parentName || students[index].fatherName
        );
      } catch (migErr) {
        console.warn('[StudentUpdate] Error migrating parent phone:', migErr);
      }
    }

    // Enrollment date changed: bill the new enrollment month (paid at admission) and drop unpaid bills
    // that now fall before it; the run below adds the months after it up to today.
    const newEnrollmentDate = students[index].feeStartDate || students[index].enrollmentDate || students[index].admissionDate || '';
    if (newEnrollmentDate && newEnrollmentDate !== oldEnrollmentDate) {
      try {
        const enrollBill = createEnrollmentMonthInvoiceServer(students[index]);
        if (enrollBill) {
          feeLedgers.unshift(enrollBill);
          persistentStorage.saveFeeLedgersToDisk(feeLedgers);
        }
        auditAndReconcileFeeLedgers();
      } catch (enrollErr) {
        console.error('[StudentUpdate] Enrollment month bill warning:', enrollErr);
      }
    }

    try {
      runAutomatedMonthlyFeeGeneration();
    } catch (engineErr) {
      console.error('[StudentUpdate] Automated fee generation warning:', engineErr);
    }

    const updateActor = (req as any).currentUser as User | undefined;
    logAudit(updateActor?.name || 'Administrator', (updateActor?.role as UserRole) || 'SCHOOL_ADMIN', 'STUDENT_UPDATE', 'Student', targetId, `Updated student record for ${students[index].name}`);
    broadcastRealtimeEvent('STUDENT', 'UPDATE', students[index], {
      studentId: targetId,
      classId: students[index].classId,
      section: students[index].section,
      description: `Updated student record for ${students[index].name}`,
    });
    if (feeProfileEdited) {
      const fp = students[index].feeProfile;
      logAudit(
        updateActor?.name || 'Administrator',
        (updateActor?.role as UserRole) || 'SCHOOL_ADMIN',
        'STUDENT_FEE_STRUCTURE_UPDATE',
        'Student',
        targetId,
        `Fee structure changed for ${students[index].name}: monthly ₹${fp?.totalMonthlyFee ?? 0}, one-time ₹${fp?.totalOneTimeFee ?? 0}, yearly ₹${fp?.totalYearlyFee ?? 0}` +
          (feeStructureBill ? `; new bill ${feeStructureBill.invoiceNumber} for ₹${feeStructureBill.totalAmount}` : '')
      );
    }
    res.json({
      ...stripStudentSecrets(students[index]),
      // Bill created by this edit for newly added one-time / yearly heads (shown to the office).
      ...(feeStructureBill
        ? { feeStructureBill: { invoiceNumber: feeStructureBill.invoiceNumber, total: feeStructureBill.totalAmount, items: feeStructureBill.breakdown } }
        : {}),
    });
  };

  app.put('/api/students/:id', requireRole(['SUPER_ADMIN', 'SCHOOL_ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'ADMIN']), handleStudentUpdate);
  app.patch('/api/students/:id', requireRole(['SUPER_ADMIN', 'SCHOOL_ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'ADMIN']), handleStudentUpdate);

  // Change student status
  app.patch('/api/students/:id/status', requireRole(['SUPER_ADMIN', 'SCHOOL_ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'ADMIN']), async (req: Request, res: Response) => {
    const { id } = req.params;
    const status = String(req.body?.status || '').trim().toUpperCase() as StudentStatus;
    if (!VALID_STUDENT_STATUSES.includes(status)) {
      return res.status(400).json({ success: false, error: `Student status must be one of: ${VALID_STUDENT_STATUSES.join(', ')}.` });
    }

    let index = students.findIndex((s) => s.id === id || (s as any)._id?.toString() === id || s.admissionNumber === id);
    if (index === -1) {
      res.status(404).json({ success: false, error: 'Student not found' });
      return;
    }

    const targetId = students[index].id;
    const previousStatus = students[index].status;
    if (mongoService.isConnected()) {
      const saved = await mongoService.updateStudent(targetId, { status });
      if (!saved) {
        return res.status(500).json({ success: false, error: 'Could not save the status change. Please try again.' });
      }
    }
    students[index].status = status;
    persistentStorage.saveStudentsToDisk(students);

    const statusActor = (req as any).currentUser as User | undefined;
    logAudit(statusActor?.name || 'Administrator', (statusActor?.role as UserRole) || 'SCHOOL_ADMIN', 'STUDENT_STATUS_CHANGE', 'Student', targetId, `Changed status of ${students[index].name} from ${previousStatus} to ${status}`);
    broadcastRealtimeEvent('STUDENT', 'UPDATE', students[index], {
      studentId: targetId,
      classId: students[index].classId,
      section: students[index].section,
      description: `Changed status of ${students[index].name} to ${status}`,
    });
    res.json(stripStudentSecrets(students[index]));
  });

  const handleStudentDelete = async (req: Request, res: Response) => {
    const { id } = req.params;

    let student = students.find((s) => s.id === id || (s as any)._id?.toString() === id || s.admissionNumber === id);
    if (!student && mongoService.isConnected()) {
      try {
        const dbStudent = await mongoService.getStudentById(id);
        if (dbStudent) {
          student = dbStudent;
        }
      } catch (err) {
        console.warn('[Server] Error finding student in MongoDB on delete:', err);
      }
    }

    if (!student) {
      res.status(404).json({ success: false, error: `Student with identifier "${id}" not found.` });
      return;
    }

    // A student with payments, attendance or exam marks is part of the school's records. Deleting the
    // profile would orphan receipts and registers, so such students must be marked Withdrawn/Inactive.
    const sid = student.id;
    const adm = student.admissionNumber;
    const hasPayments = feePayments.some((p: any) => p.studentId === sid || (adm && p.admissionNumber === adm));
    const hasPaidLedger = feeLedgers.some((l: any) => (l.studentId === sid || (adm && l.admissionNumber === adm)) && Number(l.paidAmount || 0) > 0);
    const hasAttendance = attendance.some((a) => a.studentId === sid);
    const hasMarks = examMarks.some((m: any) => m.studentId === sid);
    if (hasPayments || hasPaidLedger || hasAttendance || hasMarks) {
      const reasons = [
        hasPayments || hasPaidLedger ? 'fee payments' : '',
        hasAttendance ? 'attendance' : '',
        hasMarks ? 'exam marks' : '',
      ].filter(Boolean).join(', ');
      return res.status(409).json({
        success: false,
        code: 'STUDENT_HAS_RECORDS',
        error: `${student.name} has ${reasons} on record and cannot be deleted. Change the status to Withdrawn or Inactive instead.`,
      });
    }

    const targetId = student.id;
    const wasTransport = !!student.transportRequired;
    students = students.filter((s) => s.id !== targetId && (s as any)._id?.toString() !== id && s.admissionNumber !== id);

    persistentStorage.saveStudentsToDisk(students);
    if (wasTransport) {
      syncRouteStudentCounts();
    }
    // Free any hostel bed held by the deleted record so occupancy stays correct.
    let bedsFreed = false;
    for (const rm of hostelRooms) {
      for (const b of rm.beds || []) {
        if (b.allocatedStudentId === targetId) {
          b.allocatedStudentId = undefined;
          b.allocatedStudentName = undefined;
          b.allocatedAdmissionNo = undefined;
          b.allocationDate = undefined;
          b.status = 'AVAILABLE';
          bedsFreed = true;
        }
      }
      if (bedsFreed) {
        rm.occupiedBeds = (rm.beds || []).filter((b) => Boolean(b.allocatedStudentId)).length;
        if (rm.status === 'FULL') rm.status = 'AVAILABLE';
      }
    }
    if (bedsFreed) persistentStorage.saveHostelRoomsToDisk(hostelRooms);
    if (mongoService.isConnected()) {
      await mongoService.deleteStudent(targetId);
      if (id !== targetId) {
        await mongoService.deleteStudent(id);
      }
    }

    const deleteActor = (req as any).currentUser as User | undefined;
    logAudit(deleteActor?.name || 'Administrator', (deleteActor?.role as UserRole) || 'SUPER_ADMIN', 'STUDENT_DELETE', 'Student', targetId, `Removed student ${student.name} (Adm: ${student.admissionNumber})`);
    broadcastRealtimeEvent('STUDENT', 'DELETE', { id: targetId, studentName: student.name }, {
      studentId: targetId,
      classId: student.classId,
      section: student.section,
      description: `Removed student ${student.name}`,
    });

    res.json({ success: true, message: 'Student record deleted successfully', id: targetId });
  };

  app.delete('/api/students/:id', requireRole(['SUPER_ADMIN', 'SCHOOL_ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'ADMIN']), handleStudentDelete);

  // Email the admission letter PDF to the parent address saved on the student record.
  // The PDF is produced by the same renderer as the Download button. The recipient always comes from
  // the stored record (never from the request). "ACCEPTED" means the email service took the message for
  // delivery; delivery itself is not confirmed by this API.
  const admissionLetterEmailsInFlight = new Set<string>();
  app.post(
    '/api/students/:id/admission-letter/email',
    requireRole(['SUPER_ADMIN', 'SCHOOL_ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'ACADEMIC_COORDINATOR', 'ACCOUNTANT', 'ADMIN']),
    async (req: Request, res: Response) => {
      const actor = (req as any).currentUser as User;
      const student = students.find((s) => s.id === req.params.id || s.admissionNumber === req.params.id);
      if (!student) {
        return res.status(404).json({ success: false, error: 'Student not found.' });
      }

      const stored = [student.parentEmail, student.fatherEmail, student.motherEmail].map((v) => String(v || '').trim()).filter(Boolean);
      if (stored.length === 0) {
        return res.status(400).json({
          success: false,
          code: 'NO_PARENT_EMAIL',
          error: "No parent email address is saved for this student. Add it in the student's profile, or download the letter and share it another way.",
        });
      }
      const recipient = stored[0];
      if (!isValidEmailAddress(recipient)) {
        return res.status(400).json({
          success: false,
          code: 'INVALID_PARENT_EMAIL',
          error: `The saved parent email "${recipient}" is not a valid address. Correct it in the student's profile first.`,
        });
      }

      const pdfBase64 = typeof req.body?.pdfBase64 === 'string' ? req.body.pdfBase64.replace(/^data:application\/pdf;base64,/, '') : '';
      let pdfBuffer: Buffer;
      try {
        pdfBuffer = Buffer.from(pdfBase64, 'base64');
      } catch {
        pdfBuffer = Buffer.alloc(0);
      }
      if (pdfBuffer.length < 20 || pdfBuffer.subarray(0, 5).toString('latin1') !== '%PDF-') {
        return res.status(400).json({ success: false, code: 'INVALID_ATTACHMENT', error: 'The admission letter PDF is missing or not a valid PDF.' });
      }
      if (pdfBuffer.length > 8 * 1024 * 1024) {
        return res.status(400).json({ success: false, code: 'ATTACHMENT_TOO_LARGE', error: 'The admission letter PDF is too large to email (limit 8 MB).' });
      }

      if (!emailService.getStatus().configured) {
        return res.status(503).json({
          success: false,
          status: 'FAILED',
          code: 'EMAIL_NOT_CONFIGURED',
          error: 'Email is not set up for the school yet, so nothing was sent. Download the letter and share it instead.',
        });
      }

      // Duplicate protection: one send at a time per student, and a confirmation for a resend soon after.
      if (admissionLetterEmailsInFlight.has(student.id)) {
        return res.status(409).json({ success: false, code: 'SEND_IN_PROGRESS', error: 'The admission letter is already being sent. Please wait.' });
      }
      const last = (student as any).admissionLetterEmail;
      if (last?.status === 'ACCEPTED' && last.at && Date.now() - Date.parse(last.at) < 10 * 60 * 1000 && req.body?.resend !== true) {
        return res.status(409).json({
          success: false,
          code: 'RECENTLY_SENT',
          error: `The admission letter was already sent to ${last.recipient} at ${new Date(last.at).toLocaleTimeString('en-IN', { timeZone: 'Asia/Kolkata', hour: '2-digit', minute: '2-digit' })}. Send it again?`,
          lastSent: last,
        });
      }

      admissionLetterEmailsInFlight.add(student.id);
      try {
        const schoolName = schoolSettings.schoolName || 'CHANAKYA PUBLIC SCHOOL & COACHING CENTRE';
        const esc = (v: any) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c] as string));
        const parentName = student.fatherName || student.parentName || student.motherName || 'Parent / Guardian';
        const html = `
          <div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#1e293b;line-height:1.6">
            <p>Dear ${esc(parentName)},</p>
            <p>Please find attached the admission letter for <strong>${esc(student.name)}</strong>
               (Admission No. <strong>${esc(student.admissionNumber)}</strong>), ${esc(student.className)} – Section ${esc(student.section)},
               Academic Session ${esc(student.academicSession)}.</p>
            <p>For any questions, please contact the school office.</p>
            <p>Regards,<br/>${esc(schoolName)}${schoolSettings.schoolAddress ? `<br/>${esc(schoolSettings.schoolAddress)}` : ''}</p>
          </div>`;
        const result = await emailService.sendEmail({
          to: recipient,
          recipientName: parentName,
          subject: `Admission Letter – ${student.name} (${student.admissionNumber})`,
          html,
          attachments: [{ name: `Admission-Letter-${String(student.admissionNumber).replace(/[^A-Za-z0-9_-]/g, '')}.pdf`, contentBase64: pdfBuffer.toString('base64') }],
        });

        const record = {
          status: result.success ? 'ACCEPTED' : 'FAILED',
          at: new Date().toISOString(),
          recipient: maskEmailAddress(recipient),
          messageId: result.success ? result.messageId : undefined,
          by: actor?.name || actor?.id,
          error: result.success ? undefined : 'Not accepted by the email service',
        } as Student['admissionLetterEmail'];
        (student as any).admissionLetterEmail = record;
        persistentStorage.saveStudentsToDisk(students);
        if (mongoService.isConnected()) {
          const saved = await mongoService.updateStudent(student.id, { admissionLetterEmail: record } as any);
          if (!saved) console.warn(`[AdmissionLetterEmail] Send status for ${student.id} was not saved to the database.`);
        }
        logAudit(
          actor?.name || 'Administrator',
          (actor?.role as UserRole) || 'SCHOOL_ADMIN',
          result.success ? 'ADMISSION_LETTER_EMAIL_ACCEPTED' : 'ADMISSION_LETTER_EMAIL_FAILED',
          'Student',
          student.id,
          `Admission letter email for ${student.name} to ${maskEmailAddress(recipient)}: ${result.success ? `accepted by the email service${result.messageId ? ` (message ${result.messageId})` : ''}` : 'not accepted'}`
        );

        if (!result.success) {
          return res.status(502).json({
            success: false,
            status: 'FAILED',
            code: 'EMAIL_NOT_ACCEPTED',
            error: 'The email service did not accept the message, so it was not sent. Please try again later or download the letter.',
          });
        }
        return res.json({
          success: true,
          status: 'ACCEPTED',
          recipient: maskEmailAddress(recipient),
          messageId: result.messageId,
          message: `Admission letter accepted for delivery to ${maskEmailAddress(recipient)}.`,
          admissionLetterEmail: record,
        });
      } catch (err: any) {
        console.error('[AdmissionLetterEmail] Error:', err?.message || err);
        return res.status(500).json({ success: false, status: 'FAILED', error: 'Could not send the email. Please try again.' });
      } finally {
        admissionLetterEmailsInFlight.delete(student.id);
      }
    }
  );

  // Batch sync from client persistent cache
  app.post('/api/students/sync-batch', requireRole(['SUPER_ADMIN', 'SCHOOL_ADMIN', 'ADMIN']), (req: Request, res: Response) => {
    const { students: clientStudents } = req.body;
    if (Array.isArray(clientStudents)) {
      clientStudents.forEach((clientStu: any) => {
        const idx = students.findIndex((s) => s.id === clientStu.id || s.admissionNumber === clientStu.admissionNumber);
        if (idx !== -1) {
          if (clientStu.photo !== undefined) {
            students[idx].photo = clientStu.photo;
          }
          if (clientStu.photoFileKey !== undefined) {
            students[idx].photoFileKey = clientStu.photoFileKey;
          }
          if (clientStu.documents !== undefined) {
            students[idx].documents = clientStu.documents;
          }
          if (clientStu.enrollmentDate !== undefined) {
            students[idx].enrollmentDate = clientStu.enrollmentDate;
            students[idx].feeStartDate = clientStu.feeStartDate || clientStu.enrollmentDate;
          }
        } else if (clientStu.id && clientStu.admissionNumber) {
          students.push(clientStu);
        }
      });
      persistentStorage.saveStudentsToDisk(students);
      broadcastRealtimeEvent('STUDENT', 'UPDATE', { count: students.length }, { description: 'Batch students synchronized' });
    }
    res.json({ success: true, total: students.length });
  });

  // Parents query endpoint
  app.get('/api/parents', requireRole(['SUPER_ADMIN', 'SCHOOL_ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'ACADEMIC_COORDINATOR', 'TEACHER', 'ADMIN']), (req: Request, res: Response) => {
    syncParentAccounts();
    res.json(Array.from(parentAccounts.values()));
  });

  // Synchronize Class Teacher Assignment with classes & detailedSections in memory & MongoDB
  async function syncTeacherClassAssignment(updatedStaff: TeacherStaff) {
    if (!updatedStaff) return;
    const newAssignment = updatedStaff.classTeacherOf;
    let targetClassMatch: AcademicClass | undefined;
    let targetSecMatch = 'A';

    if (newAssignment) {
      const parts = newAssignment.trim().split(/[-:]/);
      const classPart = parts[0].trim();
      targetSecMatch = parts[1] ? parts[1].trim().toUpperCase() : 'A';
      targetClassMatch = classes.find(
        (c) =>
          c.name.toLowerCase() === classPart.toLowerCase() ||
          c.id.toLowerCase() === classPart.toLowerCase()
      );
    } else if (updatedStaff.teachingProfile?.isClassTeacher && updatedStaff.teachingProfile?.assignedClassId) {
      targetClassMatch = classes.find(
        (c) =>
          c.id === updatedStaff.teachingProfile?.assignedClassId ||
          c.name.toLowerCase() === (updatedStaff.teachingProfile?.assignedClassName || '').toLowerCase()
      );
      targetSecMatch = (updatedStaff.teachingProfile?.assignedSection || 'A').toUpperCase();
    }

    let classesModified = false;
    // Clear old classTeacher assignment for this teacher in any other class/section
    classes.forEach((c) => {
      if (c.classTeacherId === updatedStaff.id || c.classTeacherId === updatedStaff.employeeId) {
        if (!targetClassMatch || c.id !== targetClassMatch.id) {
          c.classTeacherId = undefined;
          c.classTeacherName = undefined;
          classesModified = true;
        }
      }
      if (Array.isArray(c.detailedSections)) {
        c.detailedSections.forEach((ds) => {
          if (ds.classTeacherId === updatedStaff.id || ds.classTeacherId === updatedStaff.employeeId) {
            if (!targetClassMatch || c.id !== targetClassMatch.id || ds.name.toUpperCase() !== targetSecMatch) {
              ds.classTeacherId = undefined;
              ds.classTeacherName = undefined;
              classesModified = true;
            }
          }
        });
      }
    });

    // Set new classTeacher assignment
    if (targetClassMatch && (updatedStaff.classTeacherOf || updatedStaff.teachingProfile?.isClassTeacher)) {
      if (Array.isArray(targetClassMatch.detailedSections)) {
        const secObj = targetClassMatch.detailedSections.find(
          (ds) => ds.name.toUpperCase() === targetSecMatch
        );
        if (secObj) {
          secObj.classTeacherId = updatedStaff.id;
          secObj.classTeacherName = updatedStaff.name;
          classesModified = true;
        }
      }
      targetClassMatch.classTeacherId = updatedStaff.id;
      targetClassMatch.classTeacherName = updatedStaff.name;
      classesModified = true;
    }

    if (classesModified) {
      await persistentStorage.saveClasses(classes);
      if (mongoService.isConnected()) {
        try {
          await mongoService.saveAllClasses(classes);
        } catch (e: any) {
          console.warn('[SyncTeacher] Notice saving classes to MongoDB:', e?.message);
        }
      }
      broadcastRealtimeEvent('CLASS', 'UPDATE', classes, {
        description: `Updated class teacher assignment for ${updatedStaff.name}`,
      });
    }
  }

  // Teachers / Staff CRUD with Disk and MongoDB persistence
  app.get(['/api/teachers', '/api/staff'], async (req: Request, res: Response) => {
    const { user: callerUser, session: callerSession } = getAuthContext(req);
    if (!callerSession || !callerUser) {
      return res.status(401).json({ error: 'Unauthorized: Authentication required.' });
    }
    if (['STUDENT', 'PARENT'].includes(String(callerSession.role).toUpperCase())) {
      return res.status(403).json({ error: 'Forbidden: Insufficient privileges to view the staff directory.' });
    }
    if (mongoService.isConnected()) {
      try {
        const dbStaff = await mongoService.getStaff();
        if (Array.isArray(dbStaff) && dbStaff.length > 0) {
          staff = dbStaff;
        }
      } catch (e) {
        console.warn('[Server] Error fetching staff from MongoDB:', e);
      }
    }
    const adminView = isStaffAdminTier(callerSession.role);
    res.json(
      staff.map((s) =>
        adminView
          ? sanitizeStaffRecord(s, { includeFinancial: isStaffPayrollTier(callerSession.role) })
          : sanitizeStaffDirectoryEntry(s)
      )
    );
  });

  // Single Staff Member Lookup by ID or Employee ID
  app.get(['/api/teachers/:id', '/api/staff/:id'], async (req: Request, res: Response) => {
    const { user: callerUser, session: callerSession } = getAuthContext(req);
    if (!callerSession || !callerUser) {
      return res.status(401).json({ error: 'Unauthorized: Authentication required.' });
    }
    const id = req.params.id;
    const callerStaff = findStaffForUser(callerUser, callerSession);
    const isSelf = !!callerStaff && (callerStaff.id === id || callerStaff.employeeId === id);
    if (!isSelf && !isStaffAdminTier(callerSession.role)) {
      return res.status(403).json({ error: 'Forbidden: You can only view your own staff record.' });
    }
    if (mongoService.isConnected()) {
      try {
        const dbStaff = await mongoService.getStaff();
        if (Array.isArray(dbStaff) && dbStaff.length > 0) {
          staff = dbStaff;
        }
      } catch (e) {
        console.warn('[Server] Error fetching staff from MongoDB:', e);
      }
    }
    const found = staff.find((s) => s.id === id || s.employeeId === id);
    if (found) {
      res.json(sanitizeStaffRecord(found, { includeFinancial: isStaffPayrollTier(callerSession.role) }));
    } else {
      res.status(404).json({ error: 'Staff member not found' });
    }
  });

  // --- Staff write helpers ---
  // Fields a client may never set directly on a staff record (credentials and lockout state).
  const STAFF_WRITE_BLOCKED_FIELDS = [
    'passwordHash', 'initialPassword', 'temporaryPassword', 'password', 'passwordResetToken', 'passwordResetTokenHash',
    'passwordResetLinkToken', 'passwordResetExpires', 'passwordResetEmail', 'failedLoginAttempts', 'lockoutUntil',
    '_id', '__v',
  ];
  // Legacy 'ADMIN' accounts are treated as School Admin for rank checks (matches requireRole()).
  const rankRole = (role?: string): UserRole => (String(role || '').toUpperCase() === 'ADMIN' ? 'SCHOOL_ADMIN' : String(role || '').toUpperCase()) as UserRole;
  const isSameStaffPerson = (u: User | undefined, s: TeacherStaff) =>
    !!u && (u.id === s.id || (!!u.employeeId && !!s.employeeId && u.employeeId.toUpperCase() === s.employeeId.toUpperCase()));
  const currentStaffRole = (s: TeacherStaff): UserRole => (s.systemRole || s.portalRole || s.role || 'TEACHER') as UserRole;

  /** Staff log in with their mobile number, so two staff records may not share one. */
  function staffPhoneTakenBy(phone: unknown, exceptStaffId?: string): string | null {
    const p = normalizePhone(String(phone ?? ""));
    if (p.length < 10) return null;
    const other = staff.find((s) => s.id !== exceptStaffId && normalizePhone(s.phone) === p);
    if (other) return `Mobile number ${p} is already used by ${other.name}${other.employeeId ? ` (${other.employeeId})` : ''}.`;
    const admin = adminAccounts.find((a) => normalizePhone((a as any).phone) === p);
    if (admin) return `Mobile number ${p} is already used by an administrator account.`;
    return null;
  }

  function validateStaffFields(data: any, opts: { isCreate: boolean; existing?: TeacherStaff }): string | null {
    const changed = (f: string) => opts.isCreate ? data[f] !== undefined && data[f] !== '' : data[f] !== undefined && data[f] !== (opts.existing as any)?.[f];
    if (opts.isCreate || data.name !== undefined) {
      const name = String(data.name || '').trim();
      if (!name) return "Staff member's name is required.";
      if (name.length > 120) return "Name is too long (maximum 120 characters).";
    }
    if (opts.isCreate && !String(data.phone || '').trim()) return 'Mobile number is required.';
    if (changed('phone') && normalizePhone(data.phone).length < 10) return 'Mobile number must have 10 digits.';
    if (changed('email') && data.email && !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(String(data.email).trim())) return `The email address "${data.email}" is not valid.`;
    if (changed('monthlySalary') && data.monthlySalary !== null && data.monthlySalary !== '') {
      const n = Number(data.monthlySalary);
      if (!Number.isFinite(n) || n < 0) return 'Monthly salary must be a positive amount.';
    }
    for (const f of ['joiningDate', 'dob']) {
      if (changed(f) && data[f] && !/^\d{4}-\d{2}-\d{2}/.test(String(data[f]))) return `${f === 'dob' ? 'Date of birth' : 'Joining date'} is not a valid date.`;
    }
    if (changed('salaryStartDate') && data.salaryStartDate) {
      const sd = String(data.salaryStartDate).substring(0, 10);
      if (!/^\d{4}-\d{2}-\d{2}$/.test(sd) || Number.isNaN(Date.parse(`${sd}T00:00:00Z`))) return '"Salary from" is not a valid date.';
      const jd = String(data.joiningDate ?? opts.existing?.joiningDate ?? '').substring(0, 10);
      if (jd && sd < jd) return '"Salary from" cannot be before the joining date.';
    }
    return null;
  }

  const ALLOWED_STAFF_PORTAL_ROLES = [
    'SUPER_ADMIN',
    'SCHOOL_ADMIN',
    'PRINCIPAL',
    'TEACHER',
    'ACCOUNTANT',
    'HR_STAFF',
    'HOSTEL_WARDEN',
    'TRANSPORT_MANAGER',
    'ACADEMIC_COORDINATOR',
    'VICE_PRINCIPAL',
    'SUPPORT_STAFF',
  ];

  /**
   * Class Incharge rule: the class must exist and be ACTIVE, the section must be an active section of it,
   * and the teacher must teach that class (assigned class) or be qualified for it. A value that is already
   * saved on the record is left alone so older records can still be edited.
   */
  function validateClassIncharge(input: Record<string, any>, existing?: Record<string, any>): string | null {
    const raw = typeof input.classTeacherOf === 'string' ? input.classTeacherOf.trim() : '';
    if (!raw) return null;
    if (existing && String(existing.classTeacherOf || '').trim().toLowerCase() === raw.toLowerCase()) return null;
    const cut = raw.lastIndexOf('-');
    const className = (cut > 0 ? raw.slice(0, cut) : raw).trim();
    const section = (cut > 0 ? raw.slice(cut + 1) : '').trim().toUpperCase();
    const cls = classes.find((c) => c.name.toLowerCase() === className.toLowerCase() || c.id.toLowerCase() === className.toLowerCase());
    if (!cls || (cls.status || 'ACTIVE') === 'INACTIVE') return `Class Incharge: "${className}" is not an active class.`;
    const sectionNames = (Array.isArray(cls.detailedSections) && cls.detailedSections.length > 0
      ? cls.detailedSections.filter((d) => (d.status || 'ACTIVE') !== 'INACTIVE').map((d) => d.name)
      : cls.sections || []
    ).map((x) => String(x).trim().toUpperCase());
    if (!section || !sectionNames.includes(section)) return `Class Incharge: section ${section || '(none)'} is not an active section of ${cls.name}.`;
    const tp = input.teachingProfile || existing?.teachingProfile || {};
    const taught = new Set<string>(
      [
        tp.assignedClassId, tp.assignedClassName,
        ...(Array.isArray(input.assignedClasses) ? input.assignedClasses : existing?.assignedClasses || []).map((x: string) => String(x).split('-')[0]),
        ...(Array.isArray(input.qualifiedClasses) ? input.qualifiedClasses : existing?.qualifiedClasses || []),
      ].map((x) => String(x || '').trim().toLowerCase()).filter(Boolean)
    );
    if (!taught.has(cls.name.toLowerCase()) && !taught.has(cls.id.toLowerCase())) {
      return `Class Incharge: the teacher is not assigned or qualified to handle ${cls.name}.`;
    }
    return null;
  }

  app.post(
    ['/api/teachers', '/api/staff'],
    requireRole(['SUPER_ADMIN', 'SCHOOL_ADMIN', 'ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'HR_STAFF']),
    async (req: Request, res: Response) => {
    try {
      const actor = (req as any).currentUser as User;
      const fieldError = validateStaffFields(req.body || {}, { isCreate: true });
      if (fieldError) {
        return res.status(400).json({ success: false, error: fieldError });
      }
      const phoneTaken = staffPhoneTakenBy(req.body?.phone);
      if (phoneTaken) {
        return res.status(409).json({ success: false, error: phoneTaken, code: 'PHONE_IN_USE' });
      }
      const inchargeError = validateClassIncharge(req.body || {});
      if (inchargeError) {
        return res.status(400).json({ success: false, error: inchargeError });
      }

      // 1. Employee ID: generated when blank; a requested ID that is already taken is rejected (never silently renumbered).
      let employeeId = req.body.employeeId ? String(req.body.employeeId).trim() : '';
      if (!employeeId || employeeId.toUpperCase() === 'AUTO') {
        employeeId = getNextSequentialStaffEmployeeId();
      } else if (staff.some((s) => s.employeeId?.toLowerCase() === employeeId.toLowerCase()) || adminAccounts.some((a) => a.username?.toLowerCase() === employeeId.toLowerCase())) {
        return res.status(409).json({ success: false, error: `Employee ID ${employeeId} is already in use.`, code: 'EMPLOYEE_ID_IN_USE' });
      }
      if (req.body.id && staff.some((s) => s.id === String(req.body.id))) {
        return res.status(409).json({ success: false, error: 'This staff record already exists. Refresh the page to see it.', code: 'STAFF_EXISTS' });
      }

      // Sanitize Portal Role and Designation: Strictly 10 portal roles, no HEAD_OF_DEPARTMENT
      let targetRole = (req.body.portalRole || req.body.systemRole || req.body.role || 'TEACHER') as string;
      if (!ALLOWED_STAFF_PORTAL_ROLES.includes(targetRole)) {
        targetRole = 'TEACHER';
      }
      // Nobody may create an account with a role equal to or above their own (Super Admin excepted).
      const assignCheck = canAssignRole(rankRole(actor?.role), targetRole as UserRole);
      if (!assignCheck.allowed) {
        return res.status(403).json({ success: false, error: assignCheck.reason || 'You cannot assign this role.' });
      }
      let targetDesignation = req.body.designation ? String(req.body.designation).trim() : 'PGT Teacher';
      if (/head of department|\bhod\b/i.test(targetDesignation)) {
        targetDesignation = 'PGT Teacher';
      }

      // 2. Generate secure temporary password & hash
      const rawInitialPassword = req.body.initialPassword && String(req.body.initialPassword).trim().length >= 6
        ? String(req.body.initialPassword).trim()
        : generateSecureTemporaryPassword();
      const passwordHash = bcrypt.hashSync(rawInitialPassword, 10);

      const cleanBody: Record<string, any> = { ...req.body };
      if ('qualifiedClassSections' in cleanBody) {
        cleanBody.qualifiedClassSections = normalizeQualifiedClassSections(cleanBody.qualifiedClassSections, qualifiedClassNames(cleanBody));
      }
      for (const key of STAFF_WRITE_BLOCKED_FIELDS) delete cleanBody[key];
      // Salary and bank details are set only by payroll roles (same rule as editing a staff record).
      const creatorCanSetPay = isStaffPayrollTier(actor?.role) || ['SUPER_ADMIN', 'SCHOOL_ADMIN'].includes(rankRole(actor?.role));
      if (!creatorCanSetPay) {
        for (const key of [...STAFF_FINANCIAL_FIELDS, 'payrollInformation']) delete cleanBody[key];
      }
      const addedOn = getNowInAsiaKolkata().isoDate;
      cleanBody.salaryStartDate = cleanBody.salaryStartDate
        ? String(cleanBody.salaryStartDate).substring(0, 10)
        : defaultSalaryStartDate(cleanBody.joiningDate, addedOn);
      cleanBody.createdAt = new Date().toISOString();

      // Sanitize and ensure permanent photo URL and photoFileKey
      let photoFileKey = req.body.photoFileKey ? String(req.body.photoFileKey).trim().replace(/^\/+/, '') : undefined;
      let photo = req.body.photo ? String(req.body.photo).trim() : undefined;

      // Filter out transient client blob: or data: URIs
      if (photo && (photo.startsWith('blob:') || photo.startsWith('data:'))) {
        photo = undefined;
      }
      if (photoFileKey && (photoFileKey.startsWith('blob:') || photoFileKey.startsWith('data:'))) {
        photoFileKey = undefined;
      }

      // If photoFileKey exists, resolve permanent URL
      if (photoFileKey && (!photo || photo.startsWith('blob:'))) {
        photo = `/api/files/content?key=${encodeURIComponent(photoFileKey)}`;
      }
      if (!photoFileKey && photo && photo.includes('/api/files/content')) {
        const match = photo.match(/[?&]key=([^&]+)/);
        if (match && match[1]) {
          photoFileKey = decodeURIComponent(match[1]);
        }
      }

      const newStaff = {
        ...(migrateTeachingFields(cleanBody as any).staff as Partial<TeacherStaff>),
        id: req.body.id ? String(req.body.id) : `t-${Date.now()}`,
        employeeId,
        name: String(req.body.name).trim(),
        photo,
        photoFileKey,
        portalRole: targetRole as any,
        systemRole: targetRole as any,
        role: targetRole as any,
        designation: targetDesignation,
        passwordHash,
        status: req.body.status || 'ACTIVE',
        accountStatus: req.body.accountStatus || 'ACTIVE',
        // Support staff (cleaning, driver, guard…) get an ID and attendance record but never an app login.
        loginEnabled: isNoLoginStaffRole(targetRole) ? false : req.body.loginEnabled !== undefined ? req.body.loginEnabled : true,
      } as TeacherStaff;

      // Save to MongoDB first; only a stored record is reported as registered.
      if (mongoService.isConnected()) {
        const saved = await mongoService.insertStaff(newStaff);
        if (!saved) {
          return res.status(500).json({ success: false, error: 'Could not save the staff member. Please try again.' });
        }
      }

      // Save staff member to in-memory runtime array
      staff.unshift(newStaff);

      // Save complete staff profile to disk
      persistentStorage.saveStaffToDisk(staff);

      // Save the portal user account to MongoDB
      if (mongoService.isConnected()) {
        const resolvedAvatar = newStaff.photo || (newStaff.photoFileKey ? `/api/files/content?key=${encodeURIComponent(newStaff.photoFileKey)}` : '');
        const userAccount: any = {
          id: newStaff.id,
          name: newStaff.name,
          username: employeeId.toLowerCase(),
          employeeId: employeeId.toUpperCase(),
          email: newStaff.email ? newStaff.email.trim().toLowerCase() : '',
          phone: newStaff.phone ? normalizePhone(newStaff.phone) : '',
          role: (newStaff.systemRole || newStaff.role || 'TEACHER') as UserRole,
          userType: 'STAFF',
          status: 'ACTIVE',
          loginEnabled: !isNoLoginStaffRole(targetRole),
          failedLoginAttempts: 0,
          passwordHash: passwordHash,
          avatar: resolvedAvatar,
          mustChangePassword: true,
          createdAt: new Date().toISOString(),
        };
        await UserModel.updateOne(
          {
            $or: [
              { employeeId: employeeId.toUpperCase() },
              { id: newStaff.id },
              { id: `user-staff-${newStaff.id}` },
              { username: employeeId.toLowerCase() },
            ],
          },
          { $set: userAccount },
          { upsert: true }
        );
      }

      // 3. Email dispatch: If staff member has an email address, automatically send welcome credentials email
      const hasEmail = Boolean(newStaff.email && newStaff.email.trim()) && !isNoLoginStaffRole(targetRole);
      let emailStatus: 'SENT' | 'FAILED' | 'SKIPPED_NO_EMAIL' = 'SKIPPED_NO_EMAIL';
      let emailError: string | undefined = undefined;

      if (hasEmail) {
        const portalBaseUrl = resolveProductionFrontendUrl(req);
        const schoolName = schoolSettings.schoolName || 'CHANAKYA PUBLIC SCHOOL & COACHING CENTRE, SHEOHAR';

        try {
          const emailRes = await emailService.sendStaffWelcomeCredentialsEmail({
            to: newStaff.email!.trim(),
            staffName: newStaff.name,
            employeeId: newStaff.employeeId,
            portalUserId: newStaff.employeeId,
            roleName: newStaff.systemRole || newStaff.role || 'TEACHER',
            temporaryPassword: rawInitialPassword,
            portalUrl: portalBaseUrl,
            schoolName,
          });

          if (emailRes.success) {
            emailStatus = 'SENT';
          } else {
            emailStatus = 'FAILED';
            emailError = emailRes.error;
          }
        } catch (err: any) {
          emailStatus = 'FAILED';
          emailError = err?.message;
          console.warn('[Server] Error sending welcome credentials email:', err?.message);
        }
      }

      // Synchronize class teacher assignment with classes collection
      await syncTeacherClassAssignment(newStaff);

      logAudit(actor?.name || 'Administrator', (actor?.role as UserRole) || 'HR_STAFF', 'STAFF_ADDED', 'TeacherStaff', newStaff.id, `Added employee ${newStaff.name} with ID ${employeeId} (role ${targetRole})`);
      const publicStaff = sanitizeStaffRecord(newStaff, { includeFinancial: true });
      broadcastRealtimeEvent('TEACHER', 'CREATE', publicStaff, { description: `Added employee ${newStaff.name}` });
      broadcastRealtimeEvent('STAFF', 'CREATE', publicStaff, { description: `Added employee ${newStaff.name}` });

      let message = '';
      if (emailStatus === 'SENT') {
        message = `Staff registered successfully. Employee ID: ${employeeId}. The login details email was accepted by the email service for delivery to ${maskEmailAddress(newStaff.email || '')}.`;
      } else if (emailStatus === 'SKIPPED_NO_EMAIL') {
        message = `Staff registered successfully. Employee ID: ${employeeId}. No email was provided, so login credentials were not sent by email.`;
      } else {
        message = `Staff registered successfully, but the credential email could not be sent. Please retry sending the credentials from the staff profile.`;
      }

      res.status(201).json({
        success: true,
        staff: sanitizeStaffRecord(newStaff, { includeFinancial: isStaffPayrollTier(actor?.role) || rankRole(actor?.role) === 'SUPER_ADMIN' || rankRole(actor?.role) === 'SCHOOL_ADMIN' }),
        employeeId,
        portalUserId: employeeId,
        email: newStaff.email || null,
        emailStatus,
        emailError,
        message,
      });
    } catch (err: any) {
      console.error('[Server] Error adding staff:', err);
      res.status(500).json({ success: false, error: 'Could not save the staff member. Please try again.' });
    }
  });

  app.put(
    ['/api/teachers/:id', '/api/staff/:id'],
    requireRole(['SUPER_ADMIN', 'SCHOOL_ADMIN', 'ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'HR_STAFF']),
    async (req: Request, res: Response) => {
    const { id } = req.params;
    const index = staff.findIndex((s) => s.id === id);
    if (index === -1) {
      res.status(404).json({ error: 'Staff member not found' });
      return;
    }

    const currentStaff = staff[index];
    const actor = (req as any).currentUser as User;
    const actorRole = rankRole(actor?.role);
    const isSelf = isSameStaffPerson(actor, currentStaff);
    const targetRoleNow = currentStaffRole(currentStaff);

    // Role & Designation sanitization
    const payload: Record<string, any> = { ...req.body };
    for (const key of STAFF_WRITE_BLOCKED_FIELDS) delete payload[key];
    delete payload.id;
    if ('qualifiedClassSections' in payload) {
      // Sections are kept only for classes the teacher will be qualified for after this save.
      const nextQualified = qualifiedClassNames({ ...(currentStaff as any), ...payload });
      payload.qualifiedClassSections = normalizeQualifiedClassSections(payload.qualifiedClassSections, nextQualified);
    }
    const applySalaryToUnpaid = payload.applySalaryToUnpaid === true;
    delete payload.applySalaryToUnpaid;
    const inchargeErr = validateClassIncharge(payload, currentStaff as any);
    if (inchargeErr) {
      res.status(400).json({ success: false, error: inchargeErr });
      return;
    }
    if (payload.portalRole && ALLOWED_STAFF_PORTAL_ROLES.includes(payload.portalRole)) {
      payload.systemRole = payload.portalRole;
      payload.role = payload.portalRole;
    } else if (payload.systemRole && ALLOWED_STAFF_PORTAL_ROLES.includes(payload.systemRole)) {
      payload.portalRole = payload.systemRole;
      payload.role = payload.systemRole;
    } else {
      // Unknown role values are ignored rather than stored.
      delete payload.portalRole;
      delete payload.systemRole;
      delete payload.role;
    }
    if (payload.designation && /head of department|\bhod\b/i.test(payload.designation)) {
      payload.designation = 'PGT Teacher';
    }
    // Support staff never get an app login, whatever the form sends.
    if (isNoLoginStaffRole(payload.portalRole || currentStaff.portalRole || currentStaff.systemRole || currentStaff.role)) {
      payload.loginEnabled = false;
    }

    // Only payroll roles may change salary and bank details. Other roles never receive these fields, so
    // anything they send for them is a stale or default value and must not overwrite the real record.
    const canEditFinancial = isStaffPayrollTier(actor?.role) || ['SUPER_ADMIN', 'SCHOOL_ADMIN'].includes(actorRole);
    if (!canEditFinancial) {
      for (const key of [...STAFF_FINANCIAL_FIELDS, 'payrollInformation']) delete payload[key];
    }
    // Bank and tax details are plain text: clean them so a stray space or lower-case letter is not saved.
    for (const key of ['bankAccountNo', 'ifscCode', 'bankName', 'bankBranch', 'panNumber', 'uanNumber']) {
      if (typeof payload[key] === 'string') payload[key] = payload[key].trim().slice(0, 60);
    }
    if (typeof payload.ifscCode === 'string') payload.ifscCode = payload.ifscCode.toUpperCase();
    if (typeof payload.panNumber === 'string') payload.panNumber = payload.panNumber.toUpperCase();
    const bankValueChanged = (k: string) => payload[k] !== undefined && String(payload[k] || '') !== String((currentStaff as any)[k] || '');
    if (payload.panNumber && bankValueChanged('panNumber') && !/^[A-Z]{5}[0-9]{4}[A-Z]$/.test(payload.panNumber)) {
      return res.status(400).json({ success: false, error: 'PAN number is not valid (it looks like ABCDE1234F).' });
    }
    if (payload.ifscCode && bankValueChanged('ifscCode') && !/^[A-Z]{4}0[A-Z0-9]{6}$/.test(payload.ifscCode)) {
      return res.status(400).json({ success: false, error: 'IFSC code is not valid (it looks like SBIN0001234).' });
    }
    if (payload.uanNumber && bankValueChanged('uanNumber') && !/^\d{12}$/.test(payload.uanNumber)) {
      return res.status(400).json({ success: false, error: 'UAN must be 12 digits.' });
    }

    // An older form may still send Additional Subjects: fold them into Subject Expertise instead of storing a second list.
    if (payload.additionalSubjects !== undefined || payload.teachingProfile?.additionalSubjects !== undefined) {
      const base = Array.isArray(payload.subjectExpertise) ? payload.subjectExpertise : unifiedSubjectExpertise(currentStaff as any);
      const merged = uniqueNames([...base, ...(Array.isArray(payload.additionalSubjects) ? payload.additionalSubjects : []), ...(Array.isArray(payload.teachingProfile?.additionalSubjects) ? payload.teachingProfile.additionalSubjects : [])]);
      delete payload.additionalSubjects;
      payload.subjectExpertise = merged;
      payload.specializationSubjects = merged;
      if (payload.teachingProfile) {
        payload.teachingProfile = { ...payload.teachingProfile, subjectExpertise: merged };
        delete payload.teachingProfile.additionalSubjects;
      }
    }

    const fieldError = validateStaffFields(payload, { isCreate: false, existing: currentStaff });
    if (fieldError) {
      return res.status(400).json({ success: false, error: fieldError });
    }
    if (payload.phone !== undefined && normalizePhone(payload.phone) !== normalizePhone(currentStaff.phone)) {
      const phoneTaken = staffPhoneTakenBy(payload.phone, currentStaff.id);
      if (phoneTaken) return res.status(409).json({ success: false, error: phoneTaken, code: 'PHONE_IN_USE' });
    }

    // Security-sensitive changes: role, account status, portal access, login ID and email (credential channel).
    const newRole = (payload.systemRole || payload.portalRole) as UserRole | undefined;
    const roleChanging = !!newRole && newRole !== targetRoleNow;
    const statusChanging =
      (payload.status !== undefined && payload.status !== currentStaff.status) ||
      (payload.accountStatus !== undefined && payload.accountStatus !== currentStaff.accountStatus) ||
      (payload.loginEnabled !== undefined && payload.loginEnabled !== currentStaff.loginEnabled);
    const employeeIdChanging = payload.employeeId !== undefined && String(payload.employeeId).trim() !== String(currentStaff.employeeId || '');
    const emailChanging = payload.email !== undefined && String(payload.email || '').trim().toLowerCase() !== String(currentStaff.email || '').trim().toLowerCase();

    if (isSelf && (roleChanging || statusChanging || employeeIdChanging)) {
      return res.status(403).json({ success: false, error: 'You cannot change your own role, account status or employee ID.' });
    }
    if (!isSelf && (roleChanging || statusChanging || employeeIdChanging || emailChanging)) {
      const manageCheck = canManageUserAccount(actorRole, targetRoleNow);
      if (!manageCheck.allowed) {
        return res.status(403).json({ success: false, error: manageCheck.reason || 'You cannot change this account.' });
      }
    }
    if (roleChanging) {
      const assignCheck = canAssignRole(actorRole, newRole!);
      if (!assignCheck.allowed) {
        return res.status(403).json({ success: false, error: assignCheck.reason || 'You cannot assign this role.' });
      }
    }
    if (employeeIdChanging) {
      const nextEmp = String(payload.employeeId || '').trim();
      if (!nextEmp) {
        return res.status(400).json({ success: false, error: 'Employee ID cannot be empty.' });
      }
      if (staff.some((s) => s.id !== currentStaff.id && s.employeeId?.toLowerCase() === nextEmp.toLowerCase()) || adminAccounts.some((a) => a.username?.toLowerCase() === nextEmp.toLowerCase())) {
        return res.status(409).json({ success: false, error: `Employee ID ${nextEmp} is already in use.`, code: 'EMPLOYEE_ID_IN_USE' });
      }
      payload.employeeId = nextEmp;
    }

    // Photo & fileKey sanitization
    if (payload.photo && (payload.photo.startsWith('blob:') || payload.photo.startsWith('data:'))) {
      delete payload.photo;
    }
    if (payload.photoFileKey && (payload.photoFileKey.startsWith('blob:') || payload.photoFileKey.startsWith('data:'))) {
      delete payload.photoFileKey;
    }
    if (payload.photoFileKey && !payload.photo) {
      payload.photo = `/api/files/content?key=${encodeURIComponent(payload.photoFileKey)}`;
    }

    const previousRecord = staff[index];
    const updatedRecord = { ...staff[index], ...payload } as TeacherStaff;
    if (mongoService.isConnected()) {
      const saved = await mongoService.updateStaff(id, updatedRecord);
      if (!saved) {
        return res.status(500).json({ success: false, error: 'Could not save changes. Please try again.' });
      }
    }
    staff[index] = updatedRecord;
    persistentStorage.saveStaffToDisk(staff);

    // Synchronize staff details (UAN, name, employeeId, department, designation) with staffPayroll records
    let payrollUpdated = false;
    staffPayroll.forEach((rec) => {
      if (
        rec.staffId === id ||
        (rec.employeeId && staff[index].employeeId && rec.employeeId.toUpperCase() === staff[index].employeeId.toUpperCase())
      ) {
        if (staff[index].name && rec.staffName !== staff[index].name) {
          rec.staffName = staff[index].name;
          payrollUpdated = true;
        }
        if (staff[index].employeeId && rec.employeeId !== staff[index].employeeId) {
          rec.employeeId = staff[index].employeeId;
          payrollUpdated = true;
        }
        if (staff[index].uanNumber !== undefined && rec.uanNumber !== staff[index].uanNumber) {
          rec.uanNumber = staff[index].uanNumber;
          payrollUpdated = true;
        }
        if (staff[index].department && rec.department !== staff[index].department) {
          rec.department = staff[index].department;
          payrollUpdated = true;
        }
        if (staff[index].designation && rec.designation !== staff[index].designation) {
          rec.designation = staff[index].designation;
          payrollUpdated = true;
        }
      }
    });
    if (payrollUpdated) {
      persistentStorage.saveStaffPayrollToDisk(staffPayroll);
    }
    // Keep the login account (users collection) in step: login checks read status and loginEnabled from it.
    const accountBlocked =
      staff[index].loginEnabled === false ||
      BLOCKED_STAFF_ACCOUNT_STATUSES.includes(String(staff[index].accountStatus || '').toUpperCase()) ||
      BLOCKED_STAFF_ACCOUNT_STATUSES.includes(String(staff[index].status || '').toUpperCase());
    if (mongoService.isConnected()) {
      const avatarUrl = staff[index].photo || (staff[index].photoFileKey ? `/api/files/content?key=${encodeURIComponent(staff[index].photoFileKey)}` : '');
      const userUpdates: Record<string, any> = {
        name: staff[index].name,
        email: staff[index].email || '',
        phone: staff[index].phone || '',
        role: (staff[index].systemRole || staff[index].role || 'TEACHER') as UserRole,
        avatar: avatarUrl,
        status: accountBlocked ? 'INACTIVE' : 'ACTIVE',
        loginEnabled: !accountBlocked,
      };
      if (employeeIdChanging && staff[index].employeeId) {
        userUpdates.employeeId = staff[index].employeeId.toUpperCase();
        userUpdates.username = staff[index].employeeId.toLowerCase();
      }
      const userSaved = await mongoService.updateUser(id, userUpdates);
      if (!userSaved && (statusChanging || employeeIdChanging || roleChanging)) {
        console.warn(`[Staff] Login account for staff ${id} was not updated; access changes may not apply until it is.`);
      }
    }
    if (accountBlocked || roleChanging || employeeIdChanging) {
      revokeUserSessions(staff[index].id);
      if (previousRecord.employeeId) revokeUserSessions(previousRecord.employeeId);
    }
    // Synchronize class teacher assignment with classes collection
    await syncTeacherClassAssignment(staff[index]);

    // Salary change: record it, and (when asked) recalculate months already calculated but not yet paid.
    const salaryBefore = getConfiguredMonthlySalary(previousRecord);
    const salaryAfter = getConfiguredMonthlySalary(staff[index]);
    const salaryChangedNow = canEditFinancial && salaryAfter !== salaryBefore;
    let unpaidRecalculated = 0;
    if (salaryChangedNow && applySalaryToUnpaid && salaryAfter > 0) {
      const unpaidMonths = Array.from(new Set(
        staffPayroll
          .filter((p) => p.paymentStatus !== 'PAID' && (p.staffId === id || (p.employeeId && staff[index].employeeId && String(p.employeeId).toUpperCase() === String(staff[index].employeeId).toUpperCase())))
          .map((p) => p.payrollMonth || String(p.salaryPeriodStart || '').substring(0, 7))
          .filter((m): m is string => /^\d{4}-\d{2}$/.test(String(m)))
      ));
      const touched: StaffPayrollRecord[] = [];
      for (const m of unpaidMonths) {
        const out = await runAutomatedMonthlySalaryGeneration({
          targetYear: Number(m.slice(0, 4)),
          targetMonthIndex: Number(m.slice(5, 7)),
          force: true,
          onlyStaffId: id,
          generatedBy: actor?.name || actor?.id,
        });
        touched.push(...out.changedRecords);
      }
      unpaidRecalculated = touched.length;
      if (touched.length > 0) await persistPayrollRecords(touched);
    }

    const changeNotes = [
      salaryChangedNow ? `salary ₹${salaryBefore.toLocaleString('en-IN')} → ₹${salaryAfter.toLocaleString('en-IN')}${applySalaryToUnpaid ? ` (${unpaidRecalculated} unpaid month${unpaidRecalculated === 1 ? '' : 's'} recalculated)` : ''}` : '',
      roleChanging ? `role ${targetRoleNow} → ${newRole}` : '',
      statusChanging ? `access ${accountBlocked ? 'disabled' : 'enabled'}` : '',
      employeeIdChanging ? `employee ID ${previousRecord.employeeId} → ${staff[index].employeeId}` : '',
    ].filter(Boolean).join('; ');
    logAudit(actor?.name || 'Administrator', (actor?.role as UserRole) || 'HR_STAFF', 'STAFF_UPDATE', 'TeacherStaff', id, `Updated staff profile for ${staff[index].name}${changeNotes ? ` (${changeNotes})` : ''}`);
    const publicStaff = sanitizeStaffRecord(staff[index], { includeFinancial: true });
    broadcastRealtimeEvent('TEACHER', 'UPDATE', publicStaff, { description: `Updated staff profile for ${staff[index].name}` });
    broadcastRealtimeEvent('STAFF', 'UPDATE', publicStaff, { description: `Updated staff profile for ${staff[index].name}` });
    res.json(sanitizeStaffRecord(staff[index], { includeFinancial: isStaffPayrollTier(actor?.role) || ['SUPER_ADMIN', 'SCHOOL_ADMIN'].includes(actorRole) }));
  });

  app.delete(
    ['/api/teachers/:id', '/api/staff/:id'],
    requireRole(['SUPER_ADMIN', 'SCHOOL_ADMIN', 'ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'HR_STAFF']),
    async (req: Request, res: Response) => {
    const { id } = req.params;
    const target = staff.find((s) => s.id === id);
    if (!target) {
      res.status(404).json({ error: 'Staff member not found' });
      return;
    }

    const actor = (req as any).currentUser as User;
    const actorRole = rankRole(actor?.role);
    const targetRole = currentStaffRole(target);

    if (isSameStaffPerson(actor, target)) {
      return res.status(403).json({ success: false, error: 'You cannot delete your own staff record.' });
    }
    if (targetRole === 'SUPER_ADMIN') {
      return res.status(403).json({ success: false, error: 'Super Administrator accounts cannot be deleted.' });
    }
    const manageCheck = canManageUserAccount(actorRole, targetRole);
    if (!manageCheck.allowed) {
      return res.status(403).json({ success: false, error: manageCheck.reason || 'You cannot delete this account.' });
    }
    // Staff with salary payments or attendance are part of the payroll and attendance history; deleting
    // the profile would orphan those records. Such staff must be deactivated instead.
    const empUpper = String(target.employeeId || '').toUpperCase();
    const hasPaidSalary = staffPayroll.some((p) => (p.staffId === target.id || (!!empUpper && String(p.employeeId || '').toUpperCase() === empUpper)) && p.paymentStatus === 'PAID');
    const hasAttendance = staffAttendance.some((a) => a.staffId === target.id || (!!empUpper && String(a.employeeId || '').toUpperCase() === empUpper));
    if (hasPaidSalary || hasAttendance) {
      return res.status(409).json({
        success: false,
        code: 'STAFF_HAS_RECORDS',
        error: `${target.name} has ${[hasPaidSalary ? 'salary payments' : '', hasAttendance ? 'attendance' : ''].filter(Boolean).join(' and ')} on record and cannot be deleted. Set the status to Inactive instead.`,
      });
    }

    if (mongoService.isConnected()) {
      const removed = await mongoService.deleteStaff(id);
      if (!removed) {
        return res.status(500).json({ success: false, error: 'Could not delete the staff member. Please try again.' });
      }
      await mongoService.deleteUser(id);
    }
    staff = staff.filter((s) => s.id !== id);
    persistentStorage.saveStaffToDisk(staff);
    revokeUserSessions(target.id);
    if (target.employeeId) revokeUserSessions(target.employeeId);
    logAudit(actor?.name || 'Administrator', (actor?.role as UserRole) || 'HR_STAFF', 'STAFF_DELETE', 'TeacherStaff', id, `Removed staff member ${target.name} (${target.employeeId || 'no employee ID'})`);
    broadcastRealtimeEvent('TEACHER', 'DELETE', { id, name: target.name }, { description: `Removed staff member ${target.name}` });
    broadcastRealtimeEvent('STAFF', 'DELETE', { id, name: target.name }, { description: `Removed staff member ${target.name}` });
    res.json({ success: true, message: 'Staff member removed' });
  });

  // Classes, Sections, Subjects
  app.get('/api/classes', async (req: Request, res: Response) => {
    if (mongoService.isConnected()) {
      try {
        const dbClasses = await mongoService.getClasses();
        if (Array.isArray(dbClasses) && dbClasses.length > 0) {
          classes = dbClasses;
        }
      } catch (e) {}
    }
    const { status } = req.query;
    let filtered = [...classes];
    if (status) {
      filtered = filtered.filter((c) => (c.status || 'ACTIVE') === status);
    }
    filtered.sort((a, b) => (a.numericOrder ?? 0) - (b.numericOrder ?? 0));

    // Academic Structure Read-Only Scoping for TEACHER role
    const { user, session } = getAuthContext(req);
    if (session?.role === 'TEACHER' || user?.role === 'TEACHER') {
      const currentTeacher = findStaffForUser(user, session);
      if (!currentTeacher) {
        return res.json([]);
      }
      const assigned = getTeacherAssignedClassesAndSections(currentTeacher);
      const assignedClassIds = new Set(assigned.map((a) => a.classId.toLowerCase()));
      const assignedClassNames = new Set(assigned.map((a) => a.className.toLowerCase()));

      filtered = filtered
        .filter((c) => assignedClassIds.has(c.id.toLowerCase()) || assignedClassNames.has(c.name.toLowerCase()))
        .map((c) => {
          const matchAssignment = assigned.find(
            (a) => a.classId.toLowerCase() === c.id.toLowerCase() || a.className.toLowerCase() === c.name.toLowerCase()
          );
          const allowedSecs = new Set((matchAssignment?.sections || []).map((s) => s.toUpperCase()));
          return {
            ...c,
            sections: (c.sections || []).filter((s) => allowedSecs.has(s.toUpperCase())),
            detailedSections: Array.isArray(c.detailedSections)
              ? c.detailedSections.filter((ds) => allowedSecs.has(ds.name.toUpperCase()))
              : [],
          };
        });
    }

    res.json(filtered);
  });

  // Checks a class before it is saved: a name, no duplicate name, a Numeric Grade not used by another class
  // (sorting and promotion rely on it), and unique section names. Returns an error message or null.
  // `prev` (on edit): name / Numeric Grade are only checked when they change, so an older record that
  // already shares a number with another class can still get sections added.
  function validateClassServer(cls: any, excludeId?: string, prev?: any): string | null {
    const name = String(cls?.name || '').trim();
    if (!name) return 'Class name is required.';
    const others = classes.filter((c) => c.id !== excludeId);
    const nameChanged = !prev || String(prev.name || '').trim().toLowerCase() !== name.toLowerCase();
    const sameName = nameChanged && others.find((c) => String(c.name || '').trim().toLowerCase() === name.toLowerCase());
    if (sameName) return `A class named "${sameName.name}" already exists.`;
    const order = Number(cls.numericOrder);
    if (!Number.isFinite(order) || order < 0) return 'Numeric Grade must be 0 or more.';
    const orderChanged = !prev || Number(prev.numericOrder) !== order;
    const sameOrder = orderChanged && others.find((c) => Number(c.numericOrder) === order);
    if (sameOrder) {
      const nextFree = others.reduce((m, c) => Math.max(m, Number(c.numericOrder) || 0), 0) + 1;
      return `Numeric Grade ${order} is already used by ${sameOrder.name}. Use ${nextFree} (next free) or change ${sameOrder.name} first.`;
    }
    const secNames = (Array.isArray(cls.detailedSections) && cls.detailedSections.length
      ? cls.detailedSections.map((d: any) => d?.name)
      : cls.sections || []
    ).map((n: any) => String(n || '').trim().toUpperCase());
    if (secNames.some((n: string) => !n)) return 'Every section needs a name.';
    if (new Set(secNames).size !== secNames.length) return 'Two sections have the same name.';
    return null;
  }
  // Keeps sections (names) and detailedSections in step, uppercase.
  function normalizeClassSectionsServer(cls: any): void {
    if (Array.isArray(cls.detailedSections) && cls.detailedSections.length) {
      cls.detailedSections = cls.detailedSections.map((d: any) => ({ ...d, name: String(d.name || '').trim().toUpperCase() }));
      cls.sections = cls.detailedSections.map((d: any) => d.name);
    } else {
      const names = (Array.isArray(cls.sections) && cls.sections.length ? cls.sections : ['A']).map((n: any) => String(n).trim().toUpperCase());
      cls.sections = names;
      cls.detailedSections = names.map((n: string, i: number) => ({
        id: `sec-${cls.id}-${n.toLowerCase()}-${Date.now()}-${i}`,
        name: n,
        maxCapacity: Number(cls.maxCapacity) || 40,
        status: 'ACTIVE',
      }));
    }
  }

  app.post(
    '/api/classes',
    requireRole(['SUPER_ADMIN', 'SCHOOL_ADMIN', 'ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'ACADEMIC_COORDINATOR']),
    async (req: Request, res: Response) => {
      try {
        const newClass = {
          ...req.body,
          id: req.body.id || `c-${Date.now()}`,
          name: String(req.body.name || '').trim(),
          sections: req.body.sections || ['A'],
          numericOrder:
            req.body.numericOrder !== undefined && req.body.numericOrder !== null && req.body.numericOrder !== ''
              ? Number(req.body.numericOrder)
              : classes.reduce((m, c) => Math.max(m, Number(c.numericOrder) || 0), 0) + 1,
          status: req.body.status || 'ACTIVE',
        };
        if (classes.some((c) => c.id === newClass.id)) {
          return res.status(409).json({ success: false, error: 'This class already exists. Refresh the page.' });
        }
        const invalid = validateClassServer(newClass);
        if (invalid) return res.status(409).json({ success: false, error: invalid });
        normalizeClassSectionsServer(newClass);
        classes.push(newClass);
        classes.sort((a, b) => (a.numericOrder ?? 0) - (b.numericOrder ?? 0));
        await persistentStorage.saveClasses(classes);
        if (mongoService.isConnected()) {
          await mongoService.saveAllClasses(classes);
        }
        broadcastRealtimeEvent('CLASS', 'CREATE', newClass, {
          classId: newClass.id,
          description: `Created class ${newClass.name}`,
        });
        res.status(201).json(newClass);
      } catch (err: any) {
        res.status(500).json({ success: false, error: err?.message || 'Failed to create class' });
      }
    }
  );

  app.get('/api/classes/:id', async (req: Request, res: Response) => {
    try {
      const { id } = req.params;
      let target = classes.find((c) => c.id === id || String((c as any)._id) === id || c.name === id);
      if (!target && mongoService.isConnected()) {
        const dbClasses = await mongoService.getClasses();
        if (Array.isArray(dbClasses)) {
          classes = dbClasses;
          target = classes.find((c) => c.id === id || String((c as any)._id) === id || c.name === id);
        }
      }
      if (!target) {
        return res.status(404).json({ success: false, error: 'Class not found' });
      }

      // Academic Structure Read-Only Scoping & Authorization for TEACHER role
      const { user, session } = getAuthContext(req);
      if (session?.role === 'TEACHER' || user?.role === 'TEACHER') {
        const currentTeacher = findStaffForUser(user, session);
        if (!currentTeacher) {
          return res.status(403).json({ success: false, error: 'Forbidden: Teacher profile not found.' });
        }
        const assigned = getTeacherAssignedClassesAndSections(currentTeacher);
        const matchAssignment = assigned.find(
          (a) => a.classId.toLowerCase() === target!.id.toLowerCase() || a.className.toLowerCase() === target!.name.toLowerCase()
        );
        if (!matchAssignment) {
          return res.status(403).json({ success: false, error: 'Forbidden: You are not authorized to view this class.' });
        }
        const allowedSecs = new Set((matchAssignment.sections || []).map((s) => s.toUpperCase()));
        return res.json({
          ...target,
          sections: (target.sections || []).filter((s) => allowedSecs.has(s.toUpperCase())),
          detailedSections: Array.isArray(target.detailedSections)
            ? target.detailedSections.filter((ds) => allowedSecs.has(ds.name.toUpperCase()))
            : [],
        });
      }

      return res.json(target);
    } catch (err: any) {
      return res.status(500).json({ success: false, error: err?.message || 'Failed to fetch class' });
    }
  });

  app.put(
    ['/api/classes/:id', '/api/class/:id'],
    requireRole(['SUPER_ADMIN', 'SCHOOL_ADMIN', 'ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'ACADEMIC_COORDINATOR']),
    async (req: Request, res: Response) => {
      try {
        const { id } = req.params;
        let idx = classes.findIndex((c) => c.id === id || String((c as any)._id) === id || c.name === id);
        if (idx === -1 && mongoService.isConnected()) {
          const dbClasses = await mongoService.getClasses();
          if (Array.isArray(dbClasses) && dbClasses.length > 0) {
            classes = dbClasses;
            idx = classes.findIndex((c) => c.id === id || String((c as any)._id) === id || c.name === id);
          }
        }
        if (idx !== -1) {
          const { _id: _ignoredId, ...incoming } = req.body || {};
          const merged: any = { ...classes[idx], ...incoming, id: classes[idx].id };
          if (merged.name !== undefined) merged.name = String(merged.name).trim();
          if (merged.numericOrder !== undefined) merged.numericOrder = Number(merged.numericOrder);
          const invalid = validateClassServer(merged, classes[idx].id, classes[idx]);
          if (invalid) return res.status(409).json({ success: false, error: invalid });
          normalizeClassSectionsServer(merged);
          classes[idx] = merged;
          classes.sort((a, b) => (a.numericOrder ?? 0) - (b.numericOrder ?? 0));
          idx = classes.findIndex((c) => c.id === merged.id);
          await persistentStorage.saveClasses(classes);
          if (mongoService.isConnected()) {
            await mongoService.saveAllClasses(classes);
            try {
              const db = (mongoService as any).db;
              if (db) {
                const { _id, ...cleanDoc } = classes[idx] as any;
                await db.collection('classes').updateOne(
                  { $or: [{ id: classes[idx].id }, { id }] },
                  { $set: cleanDoc },
                  { upsert: false }
                );
              }
            } catch (e) {}
          }
          persistentStorage.saveClassesToDisk(classes);
          broadcastRealtimeEvent('CLASS', 'UPDATE', classes[idx], {
            classId: id,
            description: `Updated class ${classes[idx].name} (Status: ${classes[idx].status || 'ACTIVE'})`,
          });
          return res.json(classes[idx]);
        }
        res.status(404).json({ success: false, error: 'Class not found' });
      } catch (err: any) {
        res.status(500).json({ success: false, error: err?.message || 'Failed to update class' });
      }
    }
  );

  app.delete(
    '/api/classes/:id',
    requireRole(['SUPER_ADMIN', 'SCHOOL_ADMIN', 'ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'ACADEMIC_COORDINATOR']),
    async (req: Request, res: Response) => {
      try {
        const { id } = req.params;
        let targetClass = classes.find((c) => c.id === id);
        if (!targetClass) {
          try {
            const dbDoc = await ClassModel.findOne({ $or: [{ id }, { name: id }] }).lean();
            if (dbDoc) {
              const { _id, __v, ...rest } = dbDoc as any;
              targetClass = rest as AcademicClass;
            }
          } catch {}
        }

        if (!targetClass) {
          return res.status(404).json({ success: false, error: 'Class not found' });
        }

        const targetId = targetClass.id;
        const targetName = targetClass.name;

        // 1. Dependency Check: enrolled students (in-memory + database)
        const enrolledStudents = students.filter(
          (s) => s.classId === targetId || s.className === targetName
        );

        const { reassignToClassId, force } = req.body || {};

        if (enrolledStudents.length > 0) {
          if (reassignToClassId) {
            const destClass =
              classes.find((c) => c.id === reassignToClassId) ||
              (await ClassModel.findOne({ id: reassignToClassId }).lean());
            if (!destClass) {
              return res.status(400).json({
                success: false,
                error: 'Destination class for student reassignment not found.',
              });
            }
            const defaultSec =
              (destClass.detailedSections && destClass.detailedSections[0]?.name) ||
              destClass.sections?.[0] ||
              'A';

            enrolledStudents.forEach((s) => {
              s.classId = destClass.id;
              s.className = destClass.name;
              s.section = defaultSec;
            });

            await StudentModel.updateMany(
              { $or: [{ classId: targetId }, { className: targetName }] },
              { $set: { classId: destClass.id, className: destClass.name, section: defaultSec } }
            );
            if (mongoService.isConnected()) {
              await mongoService.saveAllStudents(students);
            }
            persistentStorage.saveStudentsToDisk(students);
            broadcastRealtimeEvent(
              'STUDENT',
              'UPDATE',
              { classId: destClass.id },
              { description: `Reassigned ${enrolledStudents.length} students to ${destClass.name}` }
            );
          } else if (force) {
            enrolledStudents.forEach((s) => {
              s.classId = '';
              s.className = 'Unassigned';
              s.section = '';
            });

            await StudentModel.updateMany(
              { $or: [{ classId: targetId }, { className: targetName }] },
              { $set: { classId: '', className: 'Unassigned', section: '' } }
            );
            if (mongoService.isConnected()) {
              await mongoService.saveAllStudents(students);
            }
            persistentStorage.saveStudentsToDisk(students);
            broadcastRealtimeEvent(
              'STUDENT',
              'UPDATE',
              { classId: targetId },
              { description: `Unassigned ${enrolledStudents.length} students from deleted class ${targetName}` }
            );
          } else {
            return res.status(400).json({
              success: false,
              error: `Cannot delete class "${targetName}" because ${enrolledStudents.length} student(s) are currently enrolled. Please choose to reassign or unassign students before deleting.`,
            });
          }
        }

        // 2. Remove class from in-memory array
        classes = classes.filter((c) => c.id !== targetId);

        // 3. Permanently remove from MongoDB
        await ClassModel.deleteMany({ $or: [{ id: targetId }, { name: targetId }] });
        await persistentStorage.deleteClass(targetId);
        if (mongoService.isConnected()) {
          await mongoService.deleteClass(targetId);
          await mongoService.saveAllClasses(classes);
        }
        await persistentStorage.saveClasses(classes);

        // 4. Safely remove related assignments/homework from data model and MongoDB
        homework = homework.filter((h) => h.classId !== targetId);
        await HomeworkModel.deleteMany({ classId: targetId });
        if (mongoService.isConnected()) {
          await mongoService.saveAllHomework(homework);
        }
        persistentStorage.saveHomeworkToDisk(homework);

        // 5. Remove timetable slots for this class
        timetable = timetable.filter((t) => t.classId !== targetId);
        await TimetableSlotModel.deleteMany({ classId: targetId });
        if (mongoService.isConnected()) {
          await mongoService.saveAllTimetable(timetable);
        }
        persistentStorage.saveTimetableToDisk(timetable);
        broadcastRealtimeEvent('TIMETABLE', 'UPDATE', { classId: targetId });

        // 6. Clean up subject classIds
        let subjectsChanged = false;
        subjects.forEach((sub) => {
          if (Array.isArray(sub.classIds) && sub.classIds.includes(targetId)) {
            sub.classIds = sub.classIds.filter((cid) => cid !== targetId);
            subjectsChanged = true;
          }
        });
        if (subjectsChanged) {
          await SubjectModel.updateMany(
            { classIds: targetId },
            { $pull: { classIds: targetId } }
          );
          if (mongoService.isConnected()) {
            await mongoService.saveAllSubjects(subjects);
          }
          persistentStorage.saveSubjectsToDisk(subjects);
          broadcastRealtimeEvent('SUBJECT', 'UPDATE', { classId: targetId });
        }

        // 7. Clean up teacher assignedClasses
        let staffChanged = false;
        staff.forEach((st) => {
          if (Array.isArray(st.assignedClasses)) {
            const originalLen = st.assignedClasses.length;
            st.assignedClasses = st.assignedClasses.filter((ac) => !ac.startsWith(targetName));
            if (st.assignedClasses.length !== originalLen) {
              staffChanged = true;
            }
          }
        });
        if (staffChanged) {
          if (mongoService.isConnected()) {
            await mongoService.saveAllStaff(staff);
          }
          persistentStorage.saveStaffToDisk(staff);
          broadcastRealtimeEvent('TEACHER', 'UPDATE', {});
        }

        // 8. Broadcast realtime deletion event and audit
        broadcastRealtimeEvent('CLASS', 'DELETE', { id: targetId, name: targetName }, { classId: targetId, description: `Deleted class ${targetName}` });
        try {
          await AuditLogModel.create({
            action: 'CLASS_DELETED',
            entityType: 'AcademicClass',
            entityId: targetId,
            details: `Permanently deleted class ${targetName}`,
            performedBy: (req as any).currentUser?.name || (req as any).currentUser?.username || 'Admin',
            timestamp: new Date().toISOString(),
          });
        } catch {}

        return res.json({ success: true, message: `Class ${targetName} permanently deleted.` });
      } catch (err: any) {
        console.error('[Server] Error deleting class:', err);
        return res.status(500).json({ success: false, error: err?.message || 'Internal server error deleting class' });
      }
    }
  );

  // Explicit Class Section Management Endpoints (Administrative Only)
