  const SUBJECT_ADMIN_ROLES = ['SUPER_ADMIN', 'SCHOOL_ADMIN', 'ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'ACADEMIC_COORDINATOR'];

  /** Returns a message when the subject payload is not acceptable (null = fine). */
  const validateSubjectPayload = (body: any, selfId?: string): string | null => {
    const name = String(body?.name ?? '').trim();
    const code = String(body?.code ?? '').trim();
    if (!name) return 'Subject name is required.';
    if (!code) return 'Subject code is required.';
    const maxMarks = Number(body?.maxMarks ?? 100);
    const passMarks = Number(body?.passMarks ?? 33);
    if (!(maxMarks > 0)) return 'Maximum marks must be greater than 0.';
    if (!(passMarks >= 0) || passMarks > maxMarks) return 'Pass marks must be between 0 and maximum marks.';
    if (body?.theoryMarks !== undefined && body?.practicalMarks !== undefined && Number(body.theoryMarks) + Number(body.practicalMarks) !== maxMarks) {
      return 'Theory marks plus practical marks must equal maximum marks.';
    }
    const session = body?.academicSession;
    const clash = subjects.find(
      (s) => s.id !== selfId && String(s.code || '').trim().toLowerCase() === code.toLowerCase() && (!session || !s.academicSession || s.academicSession === session)
    );
    if (clash) return `Subject code ${code.toUpperCase()} is already used by ${clash.name}.`;
    return null;
  };

  /** Where a subject is referenced by saved records; a non-empty result blocks deletion. */
  const getSubjectUsage = (id: string, name: string) => {
    const sameName = (v?: string) => !!v && v.trim().toLowerCase() === name.trim().toLowerCase();
    const usage: Record<string, number> = {
      'exam marks': examMarks.filter((m) => m.subjectId === id).length,
      'exam schedules': exams.reduce((n, e) => n + (Array.isArray(e.schedule) ? e.schedule.filter((p) => p.subjectId === id).length : 0), 0),
      'timetable slots': timetable.filter((t) => t.subjectId === id || sameName(t.subjectName)).length,
      homework: homework.filter((h: any) => h.subjectId === id || sameName(h.subjectName)).length,
    };
    return Object.entries(usage).filter(([, n]) => n > 0);
  };

  app.post('/api/subjects', requireRole(SUBJECT_ADMIN_ROLES), (req: Request, res: Response) => {
    const problem = validateSubjectPayload(req.body);
    if (problem) return res.status(400).json({ success: false, error: problem });
    const newSub = {
      ...req.body,
      name: String(req.body.name).trim(),
      code: String(req.body.code).trim().toUpperCase(),
      id: req.body.id || `s-${Date.now()}`,
    };
    if (subjects.some((s) => s.id === newSub.id)) return res.status(409).json({ success: false, error: 'A subject with this id already exists.' });
    subjects.push(newSub);
    persistentStorage.saveSubjectsToDisk(subjects);
    broadcastRealtimeEvent('SUBJECT', 'CREATE', newSub, { description: `Added subject ${newSub.name}` });
    res.status(201).json(newSub);
  });

  app.put('/api/subjects/:id', requireRole(SUBJECT_ADMIN_ROLES), (req: Request, res: Response) => {
    const { id } = req.params;
    const idx = subjects.findIndex((s) => s.id === id);
    if (idx === -1) return res.status(404).json({ success: false, error: 'Subject not found' });
    const merged = { ...subjects[idx], ...req.body, id };
    const problem = validateSubjectPayload(merged, id);
    if (problem) return res.status(400).json({ success: false, error: problem });
    subjects[idx] = { ...merged, name: String(merged.name).trim(), code: String(merged.code).trim().toUpperCase() };
    persistentStorage.saveSubjectsToDisk(subjects);
    broadcastRealtimeEvent('SUBJECT', 'UPDATE', subjects[idx], { description: `Updated subject ${subjects[idx].name}` });
    return res.json(subjects[idx]);
  });

  app.delete('/api/subjects/:id', requireRole(SUBJECT_ADMIN_ROLES), async (req: Request, res: Response) => {
    const { id } = req.params;
    const targetSubject = subjects.find((s) => s.id === id);
    if (!targetSubject) return res.status(404).json({ success: false, error: 'Subject not found' });
    const used = getSubjectUsage(id, targetSubject.name);
    if (used.length > 0) {
      return res.status(409).json({
        success: false,
        error: `${targetSubject.name} is used by ${used.map(([k, n]) => `${n} ${k}`).join(', ')} and cannot be deleted. Mark it Inactive instead.`,
      });
    }
    subjects = subjects.filter((s) => s.id !== id);
    await persistentStorage.deleteSubject(id);
    persistentStorage.saveSubjectsToDisk(subjects);
    broadcastRealtimeEvent('SUBJECT', 'DELETE', { id }, { description: `Deleted subject ${targetSubject.name}` });
    res.json({ success: true, message: `Subject ${id} deleted` });
  });

