  /**
   * Records an approve / reject decision on a staff leave. Approval marks every
   * working day of the leave as LEAVE in the staff attendance register (a day the
   * person already worked stays as worked), which payroll then reads.
   */
  async function applyStaffLeaveDecision(leave: StaffLeave, status: 'APPROVED' | 'REJECTED' | 'PENDING' | '', decidedBy: string, remarks?: string) {
    if (status) leave.status = status;
    if (status === 'APPROVED' || status === 'REJECTED') leave.approvedBy = decidedBy;
    leave.approvedAt = new Date().toISOString().split('T')[0];
    if (remarks !== undefined) leave.remarks = remarks;

    if (status === 'APPROVED') {
      const targetStaff = staff.find((s) => s.id === leave.staffId || s.employeeId === leave.employeeId);
      const newStaffAtts: StaffAttendanceRecord[] = [];
      const leaveDates = leaveWorkingDates(
        leave.startDate,
        leave.endDate,
        holidays.filter((h) => !h.academicSession || h.academicSession === (schoolSettings.currentAcademicSession || '2026-2027')),
        schoolSettings.workingDays
      );
      for (const curDateStr of leaveDates) {
        const existingIdx = staffAttendance.findIndex(
          (a) => (a.staffId === leave.staffId || a.employeeId === leave.employeeId) && a.date === curDateStr
        );
        if (existingIdx !== -1 && ['PRESENT', 'LATE', 'HALF_DAY'].includes(String(staffAttendance[existingIdx].status))) continue;
        const attRec: StaffAttendanceRecord = {
          id: existingIdx !== -1 ? staffAttendance[existingIdx].id : `sa-${Date.now()}-${Math.random().toString(36).substring(7)}`,
          date: curDateStr,
          staffId: leave.staffId,
          staffName: leave.staffName,
          employeeId: leave.employeeId,
          department: targetStaff?.department || 'ACADEMICS',
          status: 'LEAVE',
          remarks: `Approved Leave: ${leave.leaveType} (${leave.reason})`,
          markedBy: decidedBy,
          academicSession: schoolSettings.currentAcademicSession || '2026-2027',
        };
        if (existingIdx !== -1) staffAttendance[existingIdx] = attRec;
        else staffAttendance.push(attRec);
        newStaffAtts.push(attRec);
      }
      if (newStaffAtts.length) {
        await persistentStorage.saveStaffAttendance(newStaffAtts);
        broadcastRealtimeEvent('STAFF_ATTENDANCE', 'UPDATE', newStaffAtts, {
          description: `Marked approved leave for ${leave.staffName} from ${leave.startDate} to ${leave.endDate}`,
        });
      }
    }
  }

  // Staff Leaves Management
  app.get('/api/staff-leaves', (req: Request, res: Response) => {
    const { user, session } = getAuthContext(req);
    if (!session) {
      return res.status(401).json({ error: 'Unauthorized: Authentication required.' });
    }
    const { staffId, status } = req.query;
    let result = [...staffLeaves];

    if (!isStaffAdminTier(session.role)) {
      const currentTeacher = findStaffForUser(user, session);
      if (!currentTeacher) {
        return res.status(403).json({ error: 'Forbidden: Teacher profile not found.' });
      }
      if (staffId && staffId !== currentTeacher.id && staffId !== currentTeacher.employeeId) {
        return res.status(403).json({ error: 'Forbidden: Teachers can only view their own leave requests.' });
      }
      result = result.filter(
        (l) => l.staffId === currentTeacher.id || l.employeeId === currentTeacher.employeeId
      );
    } else if (staffId) {
      result = result.filter((l) => l.staffId === staffId || l.employeeId === staffId);
    }

    if (status) result = result.filter((l) => l.status === status);
    res.json(result);
  });

  app.post('/api/staff-leaves', async (req: Request, res: Response) => {
    const { user, session } = getAuthContext(req);
    const leaveData = req.body;

    if (!session) {
      return res.status(401).json({ success: false, error: 'Unauthorized: Authentication required.' });
    }

    if (!leaveData.startDate || !leaveData.endDate) {
      return res.status(400).json({ success: false, error: 'startDate and endDate are required.' });
    }

    let targetStaff = staff.find((s) => s.id === leaveData.staffId || s.employeeId === leaveData.employeeId);

    // Staff outside the leave-approval roles may apply ONLY for their own leave.
    // Approvers may record leave for any staff member (and approve it at once).
    const STAFF_LEAVE_APPROVERS = ['SUPER_ADMIN', 'SCHOOL_ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'ADMIN', 'HR_STAFF'];
    const isLeaveApprover = STAFF_LEAVE_APPROVERS.includes(session.role);
    if (!isLeaveApprover) {
      const currentTeacher = findStaffForUser(user, session);
      if (!currentTeacher) {
        return res.status(403).json({ success: false, error: 'Forbidden: Teacher profile not found.' });
      }
      const matchesId = !leaveData.staffId || leaveData.staffId === currentTeacher.id || leaveData.staffId === currentTeacher.employeeId;
      const matchesEmp = !leaveData.employeeId || leaveData.employeeId.toLowerCase() === currentTeacher.employeeId.toLowerCase();
      if (!matchesId && !matchesEmp) {
        return res.status(403).json({ success: false, error: 'Forbidden: You can only apply for your own leave.' });
      }
      targetStaff = currentTeacher;
    }

    if (!targetStaff) {
      return res.status(404).json({ success: false, error: 'Staff member not found.' });
    }

    const STAFF_LEAVE_TYPE_LIST = ['CASUAL', 'SICK', 'MATERNITY', 'EARNED', 'DUTY', 'OTHER', 'UNPAID', 'LWP'];
    const requestedType = String(leaveData.leaveType || 'CASUAL').toUpperCase();
    const workingLeaveDates = leaveWorkingDates(
      String(leaveData.startDate),
      String(leaveData.endDate),
      holidays.filter((h) => !h.academicSession || h.academicSession === (schoolSettings.currentAcademicSession || '2026-2027')),
      schoolSettings.workingDays
    );
    const leaveInvalid = validateLeaveInput({ ...leaveData, reason: leaveData.reason || 'Personal leave request' }, workingLeaveDates.length);
    if (leaveInvalid) {
      return res.status(400).json({ success: false, error: leaveInvalid });
    }
    const overlapping = staffLeaves.find(
      (l) => l.id !== leaveData.id &&
        (l.staffId === targetStaff!.id || l.employeeId === targetStaff!.employeeId) &&
        ['PENDING', 'APPROVED'].includes(l.status) &&
        !(l.endDate < leaveData.startDate || l.startDate > leaveData.endDate)
    );
    if (overlapping) {
      return res.status(409).json({ success: false, error: `A ${overlapping.status.toLowerCase()} leave already covers ${overlapping.startDate} – ${overlapping.endDate}.` });
    }

    const newLeave: StaffLeave = {
      id: leaveData.id || `sl-${Date.now()}-${Math.random().toString(36).substring(7)}`,
      staffId: targetStaff.id,
      staffName: targetStaff.name,
      employeeId: targetStaff.employeeId,
      leaveType: (STAFF_LEAVE_TYPE_LIST.includes(requestedType) ? requestedType : 'CASUAL') as any,
      startDate: leaveData.startDate,
      endDate: leaveData.endDate,
      daysCount: workingLeaveDates.length,
      reason: leaveData.reason || 'Personal leave request',
      status: 'PENDING',
      appliedAt: leaveData.appliedAt || new Date().toISOString().split('T')[0],
      approvedBy: undefined,
      approvedAt: undefined,
      remarks: leaveData.remarks || '',
      document: leaveData.document || leaveData.documentFileKey || undefined,
      documentName: leaveData.documentName || undefined,
    };

    const existingIdx = staffLeaves.findIndex((l) => l.id === newLeave.id);
    if (existingIdx !== -1) {
      staffLeaves[existingIdx] = newLeave;
    } else {
      staffLeaves.unshift(newLeave);
    }

    if (isLeaveApprover && String(leaveData.status || '').toUpperCase() === 'APPROVED') {
      // Administration recorded the leave directly: approve it and mark attendance now.
      await applyStaffLeaveDecision(newLeave, 'APPROVED', user?.name || 'Administration', leaveData.remarks || 'Added by administration');
    }

    await persistentStorage.saveStaffLeaves(staffLeaves);
    logAudit(
      user?.name || newLeave.staffName,
      session.role as UserRole,
      'STAFF_LEAVE_APPLIED',
      'StaffLeave',
      newLeave.id,
      `${newLeave.staffName} applied for ${newLeave.leaveType} leave (${newLeave.daysCount} days)`
    );
    broadcastRealtimeEvent('STAFF_LEAVE', 'CREATE', newLeave, {
      description: `Leave application by ${newLeave.staffName} (${newLeave.daysCount} days)`,
    });
    res.status(201).json({ success: true, leave: newLeave });
  });

  app.put(['/api/staff-leaves/:id', '/api/staff-leaves/:id/status'], async (req: Request, res: Response) => {
    const { user, session } = getAuthContext(req);
    const { id } = req.params;
    const { status, approvedBy, remarks } = req.body;

    if (!session) {
      return res.status(401).json({ success: false, error: 'Unauthorized: Authentication required.' });
    }

    // Strictly authorize leave approval
    const LEAVE_APPROVAL_ROLES = ['SUPER_ADMIN', 'SCHOOL_ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL', 'ADMIN', 'HR_STAFF'];
    if (!LEAVE_APPROVAL_ROLES.includes(session.role)) {
      return res.status(403).json({
        success: false,
        error: 'Forbidden: Teachers cannot approve or reject leave requests. Only administrators and principal are authorized.',
      });
    }

    const leave = staffLeaves.find((l) => l.id === id);
    if (!leave) {
      return res.status(404).json({ success: false, error: 'Staff leave record not found.' });
    }
    const nextStatus = String(status || '').toUpperCase();
    if (nextStatus && !['APPROVED', 'REJECTED', 'PENDING'].includes(nextStatus)) {
      return res.status(400).json({ success: false, error: 'Status must be APPROVED or REJECTED.' });
    }

    await applyStaffLeaveDecision(leave, nextStatus as any, approvedBy || user?.name || 'Principal', remarks);

    await persistentStorage.saveStaffLeaves(staffLeaves);
    logAudit(
      user?.name || 'Administrator',
      session.role as UserRole,
      'STAFF_LEAVE_STATUS_UPDATED',
      'StaffLeave',
      leave.id,
      `Leave application for ${leave.staffName} was ${leave.status}`
    );
    broadcastRealtimeEvent('STAFF_LEAVE', 'UPDATE', leave, {
      description: `Leave application for ${leave.staffName} is ${leave.status}`,
    });
    res.json({ success: true, leave });
  });

