  /**
   * The storage key behind a saved image value: "school/…" as is, "/api/files/content?key=…" (any host)
   * decoded, "https://host/school/…" → "school/…". Other addresses (e.g. an external photo) → ''.
   */
  function storageKeyOf(v: unknown): string {
    const raw = typeof v === 'string' ? v.trim() : '';
    if (!raw) return '';
    const q = /\/api\/files\/content\?(?:[^#]*&)?key=([^&#]+)/.exec(raw);
    if (q) {
      try {
        return decodeURIComponent(q[1]).replace(/^\/+/, '');
      } catch {
        return q[1].replace(/^\/+/, '');
      }
    }
    const hosted = /^https?:\/\/[^/]+\/(school\/[^?#]+)$/i.exec(raw);
    if (hosted) return hosted[1];
    if (/^https?:|^data:|^blob:/i.test(raw)) return '';
    return raw.replace(/^\/+/, '');
  }
  /**
   * Deletes the old stored file only when an edit really replaced it. Before, an edit that sent the same
   * photo as "/api/files/content?key=…" instead of the bare key looked like a new photo and the
   * current file was deleted (gallery photos disappeared after editing only the title).
   */
  async function deleteReplacedFile(oldValue: unknown, newValue: unknown): Promise<void> {
    const oldKey = storageKeyOf(oldValue);
    const newRaw = typeof newValue === 'string' ? newValue.trim() : '';
    if (!oldKey || !newRaw) return;
    if (storageKeyOf(newRaw) === oldKey) return;
    await persistentStorage.deleteFile(oldKey).catch(() => {});
  }

